window.__Q=window.__Q||{};window.__Q["tcm/7/A1"]=[{"q":"大肠内细菌可合成","o":["维生素D","维生素B复合物和维生素K","维生素B12","维生素E","维生素C"],"a":1,"e":"大肠内细菌能利用肠内较简单的物质合成维生素B复合物和维生素K，供人体吸收，以补充食物摄入的不足；对蛋白质的分解则称腐败，产物经肠壁吸收后由肝脏解毒。"},{"q":"在实验中用单个电脉冲刺激心肌，逐渐增大刺激强度，心肌的反应是","o":["完全强直收缩","不完全强直收缩","收缩强度也随之增大","收缩强度先增大后减小","全或无反应"],"a":4,"e":"心肌细胞间以闰盘低电阻连接，兴奋一旦产生便迅速扩布至全部心肌细胞，故收缩呈“全或无”；刺激强度只决定能否达到阈电位，不改变收缩幅度。"},{"q":"引起缩胆囊素释放作用最强的物质是","o":["盐酸","脂酸钠","蛋白质分解产物","葡萄糖","高渗溶液"],"a":2,"e":"引起缩胆囊素释放的因素由强至弱为蛋白质分解产物、脂酸钠、盐酸、脂肪，糖类无刺激作用；盐酸才是刺激促胰液素释放的最强因素，二者不可混淆。"},{"q":"单根神经纤维动作电位中，正后电位出现在","o":["阈电位之后","超射之后","锋电位之后","负后电位之后","恢复到静息电位之后"],"a":3,"e":"动作电位的后电位分为负后电位（后去极化）与正后电位（后超极化）两部分，正后电位出现在负后电位之后，表现为膜电位超过静息电位的超极化状态。"},{"q":"下列物质进入肾小管后，既不被分泌又不被重吸收的是","o":["酚红","氨基酸","菊粉","葡萄糖","氯化钠"],"a":2,"e":"菊粉可经肾小球自由滤过，而肾小管和集合管既不重吸收也不分泌，其清除率恰等于肾小球滤过率，是测定GFR的理想标志物；酚红、葡萄糖、氨基酸、氯化钠均被肾小管处理。"},{"q":"糖皮质激素对各系统功能的影响，下列哪一项描述是正确的","o":["使淋巴细胞数量增加","减少淋巴细胞与嗜酸性粒细胞的破坏","使嗜酸性粒细胞数量增加","降低中枢神经系统兴奋性","促进消化液的分泌"],"a":4,"e":"糖皮质激素可促进胃酸和胃蛋白酶原的分泌，即促进消化液的分泌；同时使淋巴细胞和嗜酸性粒细胞减少、提高中枢神经系统的兴奋性。"},{"q":"肺气肿患者的肺弹性回缩力降低，主要导致哪项指标增加","o":["时间肺活量","肺活量","功能残气量和潮气量","潮气量","功能残气量"],"a":4,"e":"肺气肿时肺弹性成分大量破坏、回缩力减小，功能余气量（余气量与补呼气量之和）增多，患者表现为呼气困难。"},{"q":"下列关于呕吐的叙述，正确的是","o":["呕吐中枢位于下丘脑","感受器仅位于消化道内","主要为小肠逆蠕动动所致","仅有胃肌收缩","对机体有利有害"],"a":4,"e":"呕吐由延髓呕吐中枢调控，感受器分布于消化道、前庭器官和化学感受区等多处，是胃肠逆蠕动与腹肌、膈肌协同收缩的结果，既有排出有害物质之利，也有丢失消化液之害。"},{"q":"交感神经系统不具有下列哪一特点","o":["节前纤维短，节后纤维长","支配几乎所有脏器","紧张性活动","刺激节前纤维时反应比较局限","在应急反应中活动明显加强"],"a":3,"e":"交感神经节前纤维短、节后纤维长，分布广泛且有紧张性活动，应急时活动明显加强；一个节前神经元与多个节后神经元换元，辐散程度高，故刺激节前纤维时反应弥散而不局限。"},{"q":"红细胞的变形能力取决于红细胞的","o":["体积","表面积","数量","比重","表面积与体积之比"],"a":4,"e":"双凹圆碟形使红细胞具有较大的表面积与体积之比，受外力时易于变形；遗传性球形红细胞增多症患者该比值降低，变形能力减弱。"},{"q":"下列凝血因子中，稳定性最低的是","o":["因子Ⅴ","因子Ⅶ","因子Ⅹ","因子Ⅺ","因子Ⅻ"],"a":0,"e":"因子Ⅴ又称前加速素、易变因子，在体外最不稳定，易自发失活，储存血中首先减少；因子Ⅶ、Ⅹ、Ⅺ、Ⅻ相对稳定。"},{"q":"机体对刺激发生反应的能力或特性称为","o":["稳态","兴奋性","兴奋","反应","收缩性"],"a":1,"e":"兴奋性指活组织细胞接受刺激产生反应的能力或特性，对可兴奋细胞而言即接受刺激后产生动作电位的能力，是生命活动的基本特征之一。"},{"q":"刺激支配唾液腺的副交感神经，引起唾液分泌的特点是","o":["量多、固体成分少的唾液","量少、固体成分少的唾液","量少、固体成分多的唾液","量多、固体成分多的唾液","唾液量基本不变"],"a":0,"e":"副交感神经兴奋时唾液腺分泌量多而固体成分少的稀薄唾液，以适应进食与消化；交感神经兴奋则引起量少而固体成分多的黏稠唾液。"},{"q":"心迷走节后纤维末梢释放的递质是","o":["脑啡肽","一氧化氮","乙酰胆碱","肾上腺素","去甲肾上腺素"],"a":2,"e":"心迷走神经节后纤维末梢释放乙酰胆碱，作用于心肌细胞膜M受体，产生负性变力、负性变时和负性变传导效应。"},{"q":"排尿反射的初级中枢位于","o":["大脑皮层","脊髓","延髓","下丘脑","脑桥"],"a":1,"e":"排尿反射在脊髓水平即能完成，故初级中枢位于骶髓；正常情况下该反射受脑的高级中枢控制，可有意识地抑制或加强。"},{"q":"关于三大营养物质在体内代谢的叙述，下列哪一项不正确","o":["机体所需能量的50%～70%由糖提供","只有将能量转移至ATP，才能被组织活动所利用","人体在不做外功的情况下，所消耗的能量全部转化为热能","能源物质在体内氧化释放的能量50%以上转化为热能","蛋白质在体内氧化和体外燃烧时所产生的能量相等"],"a":4,"e":"蛋白质在体内氧化不彻底，终产物尿素等仍含能量，故生物热价小于物理热价，二者不相等；糖和脂肪在体内外氧化的终产物相同，热价一致。"},{"q":"与骨骼肌细胞比较，心室肌细胞的动作电位具有的特征是","o":["去极化速度快","动作电位较大的幅度","复极化时间短暂","动作电位时间持续较长","去极化速度慢"],"a":3,"e":"心室肌细胞动作电位存在平台期，复极极为缓慢，时程可达300毫秒左右，显著长于骨骼肌的数毫秒。"},{"q":"下述关于EPSP产生过程的叙述，错误的是","o":["突触前膜超极化","Ca2+经突触前膜进入突触小体","突触小泡释放兴奋性递质并与后膜受体结合","突触后膜对Na+、K+特别是Na+通透性增强","Na+内流突触后膜去极化产生EPSP"],"a":0,"e":"EPSP产生时突触前膜是去极化而非超极化，去极化使电压门控钙通道开放、Ca2+内流触发递质释放，递质再使后膜对Na+通透性增大而产生去极化。"},{"q":"脑电图对于以下哪种疾病的诊断有重要辅助作用","o":["癫痫","精神分裂症","高血压","糖尿病","智力低下"],"a":0,"e":"癫痫患者脑电图上可出现棘波、尖波、棘慢综合波等特征性改变，故脑电图对该病诊断有重要辅助价值。"},{"q":"关于某成年女性患者的呼吸功能检查结果，下列哪一项不正常","o":["呼吸频率16次/分","潮气量500ml","肺活量2500ml","时间肺活量第1秒为70%，第2秒为85%，第3秒为94%","每分通气量为8L"],"a":3,"e":"正常成人第1秒用力呼气量约占用力肺活量的83%，该患者仅70%，提示通气功能异常；呼吸频率16次/分、潮气量500ml、肺活量2500ml及每分通气量8L均在正常范围。"},{"q":"人工呼吸的原理是人为地造成","o":["肺内压与胸内压的压力差","肺内压与大气压的压力差","腹内压与大气压的压力差","胸内压与大气压的压力差","肺内压与腹内压的压力差"],"a":1,"e":"肺通气依靠肺内压与大气压之间的压力差推动气体进出肺，人工呼吸即用人为方法建立这一压力差。"},{"q":"心肌组织中，兴奋传导速度最慢的是","o":["房室束","房室交界","心室肌","结间束","希氏束"],"a":1,"e":"房室交界（结区）细胞体积小、缝隙连接少，兴奋传导速度最慢，形成房室延搁，使心室在心房收缩完毕后才开始收缩。"},{"q":"肾素是由下列哪种细胞分泌的","o":["球旁细胞","肾小管近端小管上皮细胞","肾血管内皮细胞","集合管上皮细胞","致密斑上皮细胞"],"a":0,"e":"肾素由肾小球球旁器中的球旁细胞合成、储存和释放，属蛋白水解酶，可催化血浆中的血管紧张素原转变为血管紧张素Ⅰ。"},{"q":"下列关于大肠内细菌作用的叙述，正确的是","o":["使糖和脂肪腐败","使蛋白质发酵","分解纤维素","合成维生素B和K","使氨基酸转化为二氧化碳"],"a":3,"e":"大肠内细菌对糖和脂肪的分解称发酵，对蛋白质的分解称腐败，并能利用肠内简单物质合成维生素B复合物和维生素K供人体吸收。"},{"q":"形成中枢延搁现象的原因主要是突触传递过程中","o":["神经递质在胞体的合成","神经递质沿轴浆的运输","神经递质的释放、扩散和对突触后膜的作用","神经递质的失活","突触后电位的总和"],"a":2,"e":"兴奋经突触传递需经历递质释放、经突触间隙扩散并与后膜受体结合等环节，耗时较长，形成中枢延搁。"},{"q":"关于胎盘产生的激素的描述，下列哪一项是错误的","o":["人绒毛膜促性腺激素与人绒毛膜生长素都是糖蛋白激素","人绒毛膜促性腺激素的生理功能与黄体生成素相似","人绒毛膜生长素有促生长作用，促进胎儿摄取营养","雌三醇的主要前身物质来自母体的胆固醇","孕激素的生理作用是维持子宫内膜，抑制T细胞，防止母体排斥胎儿"],"a":3,"e":"雌三醇的生成需胎儿肾上腺分泌的脱氢异雄酮硫酸盐先在胎儿肝内羟化、再经胎盘转化，其前身物质并非母体胆固醇，故该说法错误。"},{"q":"窦房结的兴奋由心房到达心室，表现在心电图上的相应部分是","o":["P-P间期","P-R间期","Q-T间期","S-T段","R-R间期"],"a":1,"e":"P-R间期指P波起点至QRS波起点之间的时程，代表兴奋由窦房结经心房、房室交界和房室束到达心室所需的时间。"},{"q":"肺泡表面活性物质缺乏，将使","o":["肺顺应性增高","肺弹性阻力增高","肺非弹性阻力增高","大肺泡内压大于小肺泡内压","肺水肿减轻"],"a":1,"e":"肺泡表面活性物质减少使肺泡表面张力增大，肺弹性阻力增高、顺应性降低，患者表现为吸气困难，易发生肺不张和肺水肿。"},{"q":"下列关于体温调节过程的叙述，不正确的是","o":["温度信息多途径输入","整合中枢在下丘脑","以PO/AH为中心","传出信息多途径输出","与调定点无关"],"a":4,"e":"体温调节遵循调定点学说：温度信息多途径输入，以PO/AH为中心整合，传出信息多途径输出，均围绕调定点进行比较调节。"},{"q":"心室肌细胞动作电位4期恢复细胞内外钠钾离子正常浓度梯度依靠","o":["载体易化扩散","单纯扩散","通道易化扩散","离子泵主动转运","继发性主动转运"],"a":3,"e":"动作电位期间进入细胞的Na+、Ca2+和流出细胞的K+，需经膜上钠泵等离子泵逆浓度梯度主动转运，才能恢复4期细胞内外的正常离子分布。"},{"q":"安静状态下，动-静脉血氧含量差最大的器官是","o":["皮肤","骨骼肌","心脏","肾脏","肝脏"],"a":2,"e":"心肌耗氧量大、摄氧率高，安静时冠状动脉血中氧含量已明显降低，故动-静脉血氧含量差在心脏最大。"},{"q":"抑制胰岛素分泌的激素是","o":["胰高血糖素","生长抑素","生长激素","皮质醇","甲状腺激素"],"a":1,"e":"胰岛δ细胞分泌的生长抑素经旁分泌抑制β细胞分泌胰岛素；胰高血糖素、生长激素、皮质醇和甲状腺激素均促进胰岛素分泌。"},{"q":"脑组织消耗的能量，主要来自下列哪种物质","o":["氨基酸","胆固醇","蛋白质","甘油","葡萄糖"],"a":4,"e":"脑组织代谢旺盛又几乎无糖原储备，主要依靠血糖持续供给葡萄糖进行有氧氧化供能，对缺氧和低血糖极为敏感。"},{"q":"实验测得某物质血浆清除率是150ml/min，表明","o":["该物质可被肾小管分泌","该物质可不被肾小管分泌","该物质分泌量等于重吸收量","该物质分泌量等于肾小球滤过量","该物质血浆清除率等于肾小球滤过率"],"a":0,"e":"该物质清除率150ml/min高于肾小球滤过率（约125ml/min），表明肾小管必定能分泌该物质，但不能排除同时存在重吸收。"},{"q":"防御反应区主要位于","o":["延髓","脊髓","脑桥","下丘脑","低位脑干"],"a":3,"e":"防御反应区主要位于下丘脑近中线两旁的腹内侧区，电刺激清醒动物该区可诱发防御反应。"},{"q":"下列关于体温的正常生理变动的描述，哪项是正确的","o":["新生儿体温最稳定","午后1～6时体温最低","通常成年女性体温低于成年男性","肌肉活动可导致体温升高","老年人体温偏高"],"a":3,"e":"运动时肌肉活动增强、代谢产热增加，体温随之升高；新生儿体温调节能力差，成年女性体温略高于男性，清晨2～6时最低。"},{"q":"对细胞膜跨膜物质转运机制的研究属于","o":["器官、系统水平","局部水平","整体水平","细胞、分子水平","组织水平"],"a":3,"e":"跨膜物质转运涉及膜蛋白的构象改变和分子机制，研究其具体过程属于细胞和分子水平的研究范畴。"},{"q":"下丘脑是较高级的","o":["交感神经中枢","副交感神经中枢","内脏活动调节中枢","躯体运动中枢","交感和副交感神经中枢"],"a":2,"e":"下丘脑通过调控体温、水平衡、内分泌、情绪活动及生物节律等间接影响内脏活动，是调节内脏活动的较高级中枢。"},{"q":"体温调定点的部位在","o":["下丘脑","下丘脑后部","视前区-下丘脑前部","脑干网状结构","大脑皮层"],"a":2,"e":"视前区-下丘脑前部（PO/AH）热敏神经元集中，是体温调节的基本中枢，也是调定点所在部位。"},{"q":"Rh血型系统的抗体是","o":["IgA","IgD","IgE","IgG","IgM"],"a":3,"e":"Rh系统的抗体主要为IgG，分子小可通过胎盘；ABO血型的天然抗体多属IgM，分子量大不能通过胎盘。"},{"q":"血管肌源性调节属于心血管活动的","o":["神经调节","体液调节","自身调节","负反馈调节","正反馈调节"],"a":2,"e":"肌源性调节指血管平滑肌受牵张刺激后自身紧张性活动增强、血管收缩，属于不依赖神经和体液因素的自身调节。"},{"q":"小剂量使用肾上腺素可致","o":["心动周期缩短","心肌收缩力减弱","心输出量降低","外周阻力明显降低","外周阻力明显增加"],"a":0,"e":"小剂量肾上腺素以兴奋β受体为主，使心率加快、心肌收缩力增强、心输出量增加，心动周期相应缩短。"},{"q":"呼吸气体交换的动力是","o":["温度","气体分压差","气体溶解度","气体的分子量","扩散面积"],"a":1,"e":"气体扩散的动力是两区域间的分压差，分压差既决定扩散速率，也决定扩散方向，是气体交换的关键因素。"},{"q":"Rh阳性是指红细胞膜上含有","o":["A抗原","B抗原","C抗原","D抗原","E抗原"],"a":3,"e":"红细胞膜上含D抗原者为Rh阳性，缺乏D抗原者为Rh阴性；D抗原抗原性最强，临床意义最重要。"},{"q":"正常生理情况下，骨骼肌的收缩形式一般为","o":["全程的等长收缩","全程的等张收缩","单收缩","不完全强直收缩","完全强直收缩"],"a":4,"e":"正常体内骨骼肌接受运动神经连续的高频冲动，后一收缩叠加在前一收缩的收缩期上，形成完全强直收缩。"},{"q":"以下关于生物电现象的叙述，正确的是","o":["在静息状态下，Na＋、K＋通道处于关闭状态","细胞接受刺激开始去极化时，就有Na＋通道大量开放","膜电位在去极化达阈电位时，Na＋通道大量开放","Na＋通道关闭，出现动作电位的复极相","刺激可引起动作电位的爆发"],"a":2,"e":"膜去极化达阈电位时电压门控钠通道大量开放，Na+内流与去极化形成正反馈而爆发动作电位；静息时并非所有钠、钾通道都处于关闭状态。"},{"q":"传入侧支性抑制又称交互抑制，有关其活动过程和意义的正确叙述是","o":["可以不需要中间神经元的参与","主要的结构是轴-轴式突触","抑制性中间神经元兴奋性降低","有助于协调相互拮抗中枢的活动","有利于及时终止中枢内神经元的活动"],"a":3,"e":"传入侧支抑制通过抑制性中间神经元使拮抗肌的运动神经元受抑，保证伸肌与屈肌活动协调，意义在于协调相互拮抗中枢的活动。"},{"q":"cAMP作为第二信使，它的主要作用是激活","o":["G蛋白","腺苷酸环化酶","蛋白激酶A","蛋白激酶C","磷酸二酯酶"],"a":2,"e":"cAMP作为第二信使主要激活蛋白激酶A，使底物蛋白磷酸化而产生调节效应；腺苷酸环化酶是其生成酶。"},{"q":"肠期胃液的分泌主要是通过十二指肠释放哪种胃肠激素实现的","o":["缩胆囊素","促胰液素","促胃液素","生长抑素","肠抑胃肽"],"a":2,"e":"食物进入小肠后刺激黏膜释放促胃液素，经血液循环作用于胃腺引起肠期胃液分泌，此期分泌量少、酸度低、消化力弱。"},{"q":"治疗“水中毒”应补充下列哪种物质","o":["皮质醇","醛固酮","血管升压素","褪黑素","胰岛素"],"a":0,"e":"糖皮质激素可抑制抗利尿激素分泌、增加肾小球滤过率并减少肾小管对水的重吸收，促进多余水分排出，故可用于水中毒的治疗。"},{"q":"去睾丸后，血中促卵泡激素浓度增加的原因是以下哪一项","o":["睾酮对腺垂体分泌促卵泡激素有负反馈作用","甲基睾酮对促卵泡激素分泌有负反馈作用","孕烯醇酮对促卵泡激素分泌有负反馈作用","抑制素对促卵泡激素分泌有负反馈作用","雄激素结合球蛋白的负反馈作用"],"a":3,"e":"睾丸支持细胞分泌的抑制素选择性抑制腺垂体FSH的分泌；去睾丸后抑制素减少，负反馈解除，血中FSH升高。"},{"q":"在动物实验中，电刺激家兔膈下迷走神经时，不会出现下列哪种情况","o":["小肠平滑肌收缩","胃平滑肌收缩","肛门外括约肌舒张","促胰液素分泌增多","胆汁分泌增多"],"a":2,"e":"肛门外括约肌由阴部神经这一躯体神经支配，迷走神经不支配该肌；刺激膈下迷走神经可增强胃肠运动和消化腺分泌。"},{"q":"代谢水平对心脏血流量的调节属于","o":["神经调节","体液调节","自身调节","正反馈调节","负反馈调节"],"a":2,"e":"心脏血流量随代谢水平升高而增多，属局部代谢产物介导的代谢性自身调节，不依赖神经和体液因素。"},{"q":"消化道平滑肌的自动节律性主要依赖于下列哪一项作用","o":["交感神经的支配","平滑肌本身的特性","迷走神经的支配","食物的刺激作用","壁内神经丛的作用"],"a":1,"e":"消化道平滑肌静息电位不稳定，可周期性产生慢波，其自动节律性源于平滑肌细胞本身的这一电生理特性。"},{"q":"临床上，当胆瘘患者胆汁大量流失至体外时，其胆汁分泌与正常人相比较会显著减少，主要原因是","o":["合成胆盐的原料减少","胆盐的肠肝循环减少","促胃液素分泌减少","促胰液素分泌减少","缩胆囊素分泌减少"],"a":1,"e":"胆盐随胆汁排入小肠后绝大部分在回肠被重吸收，经门静脉回肝并刺激肝细胞分泌胆汁；胆瘘时胆盐大量丢失、肠肝循环中断，故胆汁分泌显著减少。"},{"q":"心动周期中，心脏瓣膜的活动，下述哪项是错误的","o":["房室瓣关，动脉瓣开","房室瓣开，动脉瓣关","房室瓣、动脉瓣都开","房室瓣、动脉瓣都关","压力差控制瓣膜开关"],"a":2,"e":"房室瓣与动脉瓣不可能同时开放，否则血液无法单向流动；等容收缩期和等容舒张期两瓣均关闭，射血期动脉瓣开、充盈期房室瓣开。"},{"q":"某患者在胃大部分切除后出现巨幼红细胞性贫血的原因是对哪项物质吸收障碍","o":["蛋白质","叶酸","维生素B12","脂肪","铁"],"a":2,"e":"胃壁细胞分泌的内因子与维生素B12结合后促其在回肠末端吸收，胃大部切除后内因子缺乏，维生素B12吸收障碍而致巨幼细胞贫血。"},{"q":"妊娠期内不排卵是由于下列哪些激素的作用","o":["雌激素","缩宫素","雌激素与孕激素","催乳素","促性腺激素释放激素"],"a":2,"e":"妊娠期血中高浓度的孕激素与雌激素共同负反馈抑制腺垂体FSH和LH的分泌，卵泡发育和排卵均受抑制，故不发生二次受孕。"},{"q":"O2在血液中的运输形式以氧合血红蛋白为主，1g血红蛋白大约可结合1、34ml的O2。某人的血红蛋白浓度为140g/L，该人血中的血红蛋白氧容量(ml/L)大约接近于下列哪一数值","o":["100","140","180","220","260"],"a":2,"e":"血红蛋白氧容量等于Hb浓度与1.34ml/g的乘积，140g/L×1.34≈188ml/L，最接近180。"},{"q":"临床上对严重肺气肿患者不宜以吸入纯氧来改善缺氧的原因是","o":["避免高氧对呼吸中枢的直接抑制作用","高氧对中枢化学感受器无刺激作用","反而引起CO2对中枢化学感受器的刺激减弱","维持低氧对外周化学感受器的刺激作用","维持高CO2对中枢的兴奋作用"],"a":3,"e":"严重肺气肿患者长期CO2潴留使中枢化学感受器产生适应，低氧对外周化学感受器的刺激成为驱动呼吸的主要因素，吸入纯氧可解除该刺激而致呼吸抑制。"},{"q":"与反馈相比，前馈控制的特点是","o":["反应滞后","产生波动","无预见性","适应性差","快速生效"],"a":4,"e":"前馈控制利用前馈信号在效应出现偏差之前即启动调节，反应迅速、快速生效，但判断失误时也可引起波动。"},{"q":"下列生理过程需要细胞本身耗能的是","o":["O2通过呼吸膜","动作电位复极化过程中K+外流","小肠黏膜上皮细胞吸收葡萄糖","集合管对水的重吸收","心室肌细胞动作电位2期的Ca2+内流"],"a":2,"e":"小肠黏膜上皮细胞吸收葡萄糖经Na+-葡萄糖同向转运体，属继发性主动转运，能量来自钠泵建立的Na+浓度梯度，需细胞耗能。"},{"q":"关于肺泡表面活性物质的描述，错误的是","o":["维持肺泡的扩张状态","由肺泡I型细胞所分泌","降低肺泡表面张力","稳定肺泡容积","使肺的顺应性增加"],"a":1,"e":"肺表面活性物质由肺泡Ⅱ型上皮细胞合成和分泌，可降低肺泡表面张力、稳定肺泡容积、防止肺不张和肺水肿。"},{"q":"血浆胶体渗透压降低时可引起","o":["组织液减少","组织液增加","红细胞萎缩","红细胞膨胀和破裂","尿量减少"],"a":1,"e":"血浆胶体渗透压是限制组织液生成的主要力量，其降低使有效胶体渗透压下降、有效滤过压增大，组织液生成增多。"},{"q":"交感缩血管神经节后纤维末梢释放的递质主要与下列哪一种受体结合","o":["M受体","N受体","α受体","β1受体","β2受体"],"a":2,"e":"交感缩血管神经节后纤维末梢释放去甲肾上腺素，主要与血管平滑肌α受体结合，引起血管收缩。"},{"q":"单纯扩散和易化扩散的共同点是","o":["需要ATP供能","借助于通道蛋白的帮助","借助于载体蛋白的帮助","顺浓度差转运","转运脂溶性物质"],"a":3,"e":"单纯扩散与易化扩散均属被动转运，都顺浓度梯度和电位梯度进行、不耗能；区别在于易化扩散需借助膜蛋白。"},{"q":"呋塞米产生利尿作用的部位是","o":["近端小管","髓袢升支细段","髓袢升支粗段","远曲小管","集合管"],"a":2,"e":"呋塞米抑制髓袢升支粗段顶端膜的Na+-K+-2Cl-共转运体，减少NaCl重吸收，降低髓质间液高渗而产生利尿作用。"},{"q":"在对血氧饱和度与血液PO2关系的描述中，P50是指","o":["使Hb氧饱和度达到50%的PO2","PO2为50mmHg时的氧饱和度","PCO2为50mmHg时的氧饱和度","PO2为正常值的50%时的氧饱和度","使Hb的氧容量达到正常值50%时的PO2"],"a":0,"e":"P50是使Hb氧饱和度达到50%时的PO2，正常约26.5mmHg，其增大表示Hb对O2的亲和力降低。"},{"q":"有关K+的分泌，下列说法不正确的是","o":["多吃多排","少吃少排","不吃也排","不能进食的患者，应防止发生低血钾","不吃不排"],"a":4,"e":"肾对钾的排出特点是多吃多排、少吃少排、不吃也排，故不能进食的患者仍应补钾，防止发生低血钾。"},{"q":"可作为心室舒张期开始的标志的心音是","o":["第一心音","第二心音","第三心音","第四心音","二尖瓣关闭音"],"a":1,"e":"第二心音由主动脉瓣和肺动脉瓣关闭引起，标志心室舒张期的开始，在胸骨右、左两旁第二肋间听诊最清楚。"},{"q":"当长期不能进食或能量消耗过大时，维持生理活动必要的能源物质是","o":["葡萄糖","脂肪酸","甘油三酯","蛋白质","乳酸"],"a":3,"e":"长期不能进食或能量消耗过大时，机体依靠蛋白质分解产生的氨基酸供能，以维持基本的生理功能活动。"},{"q":"临床上，气管插管或全身麻醉时可辅助使用肌肉松弛剂，如N型胆碱受体的阻断剂筒箭毒等，此类药物作用机制主要是抑制骨骼肌细胞哪一生理过程","o":["G蛋白偶联受体介导的信号转导","酪氨酸激酶受体介导的信号转导","酪氨酸激酶结合型受体介导的信号转导","离子通道型受体介导的信号转导","鸟苷酸环化酶受体介导的信号转导"],"a":3,"e":"筒箭毒等N型胆碱受体阻断剂阻断终板膜上的N2型乙酰胆碱受体阳离子通道，属离子通道型受体介导的信号转导。"},{"q":"下列哪一项是糖皮质激素对代谢的作用","o":["促进葡萄糖的利用，促进蛋白质分解","促进葡萄糖的利用，抑制蛋白质分解","抑制葡萄糖的利用，促进蛋白质分解","促进葡萄糖的利用，促进蛋白质合成","抑制葡萄糖的利用，抑制蛋白质分解"],"a":2,"e":"糖皮质激素抑制外周组织对葡萄糖的利用、加速肝糖异生使血糖升高，同时促进肝外组织蛋白质分解。"},{"q":"下列物质中，通过离子通道型受体进行信号转导的是","o":["谷氨酸","心房钠尿肽","生长激素","表皮生长因子","甲状腺激素"],"a":0,"e":"谷氨酸作用于NMDA、AMPA等促离子型受体，属离子通道型受体介导的信号转导；心房钠尿肽、生长激素等则经其他受体途径。"},{"q":"所有平滑肌都具有的是","o":["自律性","传导性","交感神经和副交感神经支配","三联管结构","紧张性收缩"],"a":4,"e":"各类平滑肌均具有紧张性收缩，可对抗重力、维持器官形态；自律性和交感和副交感双重支配并非所有平滑肌共有。"},{"q":"安静时心室肌细胞膜对K+通透性较高主要是由于","o":["IK通道开放","IK1通道开放","Ito通道开放","If通道开放","INa通道开放"],"a":1,"e":"心室肌细胞安静时膜对K+通透性高，主要因IK1通道开放、K+外流形成静息电位；IK1具有内向整流特性。"},{"q":"每分通气量和肺泡通气量之差为","o":["无效腔气量×呼吸频率","潮气量×呼吸频率","余气量×呼吸频率","功能余气量×呼吸频率","补吸气量×呼吸频率"],"a":0,"e":"每分通气量为潮气量与呼吸频率之积，肺泡通气量为（潮气量-无效腔气量）×呼吸频率，两者之差即无效腔气量×呼吸频率。"},{"q":"成人在清醒、安静并闭目时出现","o":["α波","β波","δ波","θ波","α波阻断"],"a":0,"e":"成人清醒、安静并闭目时枕叶以α波为主，睁眼或接受其他刺激时α波消失而呈现β波，称α阻断。"},{"q":"长期服用广谱抗生素，导致出血倾向可选用","o":["肝素","叶酸","维生素B1","维生素K","尿激酶"],"a":3,"e":"广谱抗生素抑制肠道细菌使维生素K合成减少，依赖维生素K的凝血因子Ⅱ、Ⅶ、Ⅸ、Ⅹ活化障碍而出现出血倾向。"},{"q":"刺激引起兴奋的基本条件是使跨膜电位达到","o":["局部电位","阈电位","锋电位","后电位","动作电位"],"a":1,"e":"刺激引起兴奋的基本条件是使膜去极化达到阈电位，从而触发电压门控钠通道大量开放，产生动作电位。"},{"q":"血浆中的碳酸氢盐主要在红细胞内生成，其主要原因是","o":["红细胞含丰富Hb","红细胞内含有丰富的碳酸酐酶","血浆蛋白可以抑制CO2与水的反应","CO2易于通过红细胞膜","红细胞膜上有HCO3--Cl-载体"],"a":1,"e":"红细胞内碳酸酐酶浓度高，催化CO2与水生成H2CO3并解离为H+和HCO3-，故血浆中的碳酸氢盐主要在红细胞内生成。"},{"q":"胆盐对下列哪种物质的消化具有重要意义","o":["淀粉","蛋白质","脂肪","多肽","胆固醇"],"a":2,"e":"胆盐作为乳化剂降低脂肪表面张力，使脂肪乳化成微滴，增加胰脂肪酶的作用面积，促进脂肪的消化和吸收。"},{"q":"外科手术中常用温热盐水纱布压迫止血，关于其生理机制的叙述错误的是","o":["纱布是异物，可激活因子Ⅻ","可促进红细胞凝集","凝血过程是酶促反应，适当加温可使凝血反应加速","纱布是异物，可激活血小板","压迫可使局部小血管收缩，促进凝血"],"a":1,"e":"温热盐水纱布压迫止血靠压迫使小血管收缩、异物激活因子Ⅻ和血小板、加温加速酶促凝血反应；红细胞凝集是抗原抗体反应，与止血无关。"},{"q":"关于胰岛素降低血糖的作用，下列哪一项是错误的","o":["促进组织细胞摄取葡萄糖","增强糖原的合成","抑制糖原的分解","增加糖异生","促进葡萄糖转变为脂肪酸"],"a":3,"e":"胰岛素通过促进糖原合成、抑制糖原分解、抑制糖异生和促进葡萄糖转变为脂肪酸来降低血糖，故“增加糖异生”错误。"},{"q":"交感神经节后纤维释放的递质是","o":["ACh和NE","NE","5-HT","ACh","NE和5-HT"],"a":0,"e":"多数交感节后纤维释放去甲肾上腺素，支配汗腺和骨骼肌血管的交感节后纤维释放乙酰胆碱，故为ACh和NE。"},{"q":"在肾小球滤过中阻碍带电荷的蛋白通过滤过膜最主要的结构是","o":["肾小球毛细血管内皮","毛细血管内皮下基膜","肾小囊脏层足细胞","足细胞足突间裂隙膜","肾小球毛细血管口径"],"a":1,"e":"滤过膜三层均带负电荷，其中毛细血管内皮下基膜孔隙小且富含带负电糖蛋白，是阻碍带电荷蛋白质通过的主要结构。"},{"q":"收缩压是下列哪个时期的大动脉血压","o":["等容收缩期","快速射血期","等容舒张期","房缩期","减慢射血期"],"a":1,"e":"收缩压是心室快速射血期主动脉内压力所达到的最高值，此期射出的血量约占总射血量的2/3。"},{"q":"细胞内外液渗透压的平衡主要依赖于下列哪一物质的移动来维持","o":["Na+","K+","CI-","葡萄糖","水"],"a":4,"e":"细胞内外液渗透压的平衡依靠水自由跨膜移动来维持，水顺渗透压梯度移动直至两侧渗透压相等。"},{"q":"下列关于气体在血液中运输的叙述，错误的是","o":["血中O2和CO2都有物理溶解和化学结合两种形式","O2的结合形式是氧合血红蛋白","O2与血红蛋白结合快、可逆，需要酶催化","CO2主要以HCO3-形式运输","CO2与血红蛋白的氨基结合不需酶的催化"],"a":2,"e":"O2与Hb结合是氧合而非氧化，迅速、可逆且不需酶催化；CO2生成碳酸氢盐才需碳酸酐酶催化，二者不可混淆。"},{"q":"感受器就如实验中用到的换能器那样，最终可以将不同形式的刺激能量转变为电信号，其换能过程是","o":["刺激→静息电位减小→动作电位","刺激→超极化电位→动作电位","刺激→静息电位减小→局部去极化","刺激→感受器电位或发生器电位→动作电位","刺激→去极化电位→局部兴奋"],"a":3,"e":"感受器换能时先把各种刺激能量转变为感受器电位或发生器电位，再触发传入神经纤维产生动作电位。"},{"q":"下列哪一项可使肾小球滤过率增加","o":["肾小球毛细血管血压增高","血浆胶体渗透压增高","肾小囊内压升高","肾小球毛细血管血压降低","血浆晶体渗透压升高"],"a":0,"e":"肾小球毛细血管血压是促进超滤液生成的力量，其升高使有效滤过压增大、GFR增加；胶体渗透压和囊内压升高则使GFR减少。"},{"q":"家兔麻醉后行膀胱插管，观察影响尿生成的因素。这种实验方法属于","o":["慢性在体实验","慢性离体实验","混合性实验","急性在体实验","急性离体实验"],"a":3,"e":"动物麻醉后行膀胱插管观察尿生成，属在麻醉状态下对完整动物进行的观察，为急性在体实验。"},{"q":"下列属于胰液成分的是","o":["肠激酶","内因子","糜蛋白酶原","胆固醇","胆色素"],"a":2,"e":"胰液含胰蛋白酶原、糜蛋白酶原、羧基肽酶原等；肠激酶来自肠液，内因子来自胃壁细胞，胆固醇和胆色素属胆汁成分。"},{"q":"下列哪种情况，是呼吸商降低的主要因素","o":["酸中毒","碱中毒","肺过度通气","糖转变为脂肪","剧烈运动"],"a":1,"e":"碱中毒时呼吸受抑制、CO2排出减少，测得的CO2产生量与耗O2量之比下降，故呼吸商降低；糖转变为脂肪则使呼吸商升高。"},{"q":"幼儿排便反射常发生在进餐后，这种情况下引起结肠收缩的原因是","o":["胃-回肠反射","胃-结肠反射","迷走-迷走反射","内在神经丛局部反射","肠-胃反射"],"a":1,"e":"食物入胃后经十二指肠-结肠反射（胃-结肠反射）使结肠集团蠕动增强，常在进食后尤其是早餐后引起便意。"},{"q":"某肾盂结石患者出现尿量明显减少，其原因是","o":["肾小球毛细血管血压增高","肾小囊胶体渗透压增高","血浆胶体渗透压增高","血浆晶体渗透压升高","肾小囊内压升高"],"a":4,"e":"肾盂结石阻塞使小管液排出受阻，逆行性压力升高致肾小囊内压升高，有效滤过压和肾小球滤过率降低，尿量减少。"},{"q":"一天中血液生长激素分泌的最高水平出现在","o":["清晨","中午","傍晚","进食后","夜间"],"a":4,"e":"生长激素呈脉冲式分泌，在NREM睡眠期分泌明显增多，故一天中血液生长激素水平最高出现在夜间。"},{"q":"测定清除率的意义不包括","o":["反映肾对不同物质的清除能力","反映肾对各种物质的重吸收","反映肾对各种物质的分泌","清除率是检测肾功能的重要方法之一","反映肾对各种物质滤过率"],"a":4,"e":"清除率可反映肾对不同物质的排泄能力及重吸收、分泌情况，是检测肾功能的重要方法，但不能反映各种物质的滤过率。"},{"q":"牵张刺激可以引起以下哪种肌肉收缩","o":["子宫","虹膜肌","主动脉","输精管","竖毛肌"],"a":0,"e":"牵张刺激可诱发子宫平滑肌收缩，妊娠末期子宫在牵拉及缩宫素作用下收缩更强；虹膜肌、竖毛肌等不由牵张刺激直接引起收缩。"},{"q":"有髓神经纤维的传导特点是","o":["单向传导","传导速度慢","衰减性传导","跳跃式传导","离子跨膜运动总数多、耗能多"],"a":3,"e":"有髓神经纤维的髓鞘具绝缘性，只在郎飞结处产生动作电位，兴奋逐个郎飞结跳跃传导，速度快、离子跨膜数少而耗能少。"},{"q":"肺有效通气量是指","o":["潮气量","肺活量","时间肺活量","肺泡通气量","肺总容量"],"a":3,"e":"肺泡通气量指每分钟吸入肺泡的新鲜空气量，是真正有效的气体交换量，等于（潮气量-无效腔气量）×呼吸频率。"},{"q":"脊髓前角γ-运动神经元的功能主要是","o":["抑制α-运动神经元的活动","直接兴奋α-运动神经元","提高肌梭的敏感性","发动肌牵张反射","抑制肌牵张反射"],"a":2,"e":"γ-运动神经元支配梭内肌纤维，其兴奋使肌梭感受装置张力增加，从而提高肌梭对牵拉刺激的敏感性。"},{"q":"优势半球指的是下列哪项特征占优势的一侧半球","o":["重量","运动功能","感觉功能","语言活动功能","皮层沟回数"],"a":3,"e":"语言活动中枢主要位于左侧大脑皮层，故左侧半球称语言优势半球，优势半球指语言活动功能占优势的一侧。"},{"q":"胃酸的生理作用不包括下列哪一项","o":["杀死进入胃内的细菌","进入小肠后促进胰液和胆汁的分泌","促进维生素B12的吸收","促进钙和铁的吸收","激活胃蛋白酶原，并为胃蛋白酶提供适宜环境"],"a":2,"e":"维生素B12的吸收需胃壁细胞分泌的内因子介导，与胃酸无关；胃酸可杀菌、激活胃蛋白酶原、促进钙铁吸收并刺激胰液和胆汁分泌。"},{"q":"肺泡与肺毛细血管血液之间的气体交换所通过的组织结构是","o":["呼吸膜","肺泡膜","肺泡上皮和毛细血管内皮","肺泡上皮，毛细血管内皮，内皮基膜","肺泡上皮，上皮基膜，毛细血管内皮基膜，毛细血管内皮"],"a":0,"e":"肺泡与肺毛细血管血液之间进行气体交换所通过的结构称呼吸膜，由肺泡表面液层、肺泡上皮、基膜、间质、毛细血管基膜及内皮构成。"},{"q":"下列哪种因素会导致血中儿茶酚胺类激素浓度升高","o":["血糖升高","恐惧、焦虑和剧痛","慢波睡眠期","血压升高","机体清醒安静"],"a":1,"e":"恐惧、焦虑和剧痛等紧急情况经传入通路兴奋交感神经和肾上腺髓质，使血中肾上腺素和去甲肾上腺素浓度升高。"},{"q":"衡量人眼调节能力大小的指标是","o":["瞳孔大小","角膜厚度","房水压力","远点","近点"],"a":4,"e":"近点是眼作最大调节时能看清物体的最近距离，近点越近表明晶状体弹性越好、眼的调节能力越强，故为衡量调节能力的指标。"},{"q":"左心室和右心室相同的是","o":["心室内压","心肌收缩力","心输出量","心脏做功量","心室肌厚度"],"a":2,"e":"左、右心室串联于同一循环通路，每分钟射出的血量基本相等，即心输出量相同；两心室压力、做功量和肌壁厚度则明显不同。"},{"q":"下列选项中，能使血液中的促红细胞生成素含量增加的生理性刺激因素是","o":["缺氧","CO2潴留","雌激素","肾脏疾患","酸中毒"],"a":0,"e":"组织缺氧是促进肾产生EPO的生理性刺激，贫血、缺氧或肾血流量减少均可使血浆促红细胞生成素含量增加。"},{"q":"舞蹈病的病变部位在","o":["黑质","纹状体","脑干网状结构","中脑上、下丘之间","小脑后叶"],"a":1,"e":"舞蹈病的主要病变部位在纹状体（新纹状体），表现为不自主的舞蹈样动作；帕金森病的病变部位在黑质。"},{"q":"在心动周期中，心室内压最高的时期是","o":["等容收缩期末","快速射血期末","减慢射血期末","快速充盈期末","减慢充盈期末"],"a":1,"e":"快速射血期心室肌强烈收缩，心室内压升至峰值，故为心动周期中心室内压最高的时期；减慢射血期室内压已开始下降。"},{"q":"下列哪一种因素促进胃的排空","o":["扩张十二指肠","十二指肠内渗透压升高","十二指肠内的脂肪浓度升高","十二指肠内的酸刺激","胃内食物的机械和化学刺激"],"a":4,"e":"胃内食物的机械扩张和化学刺激经迷走-迷走反射、壁内神经丛局部反射及促胃液素释放促进胃运动；十二指肠内的酸、脂肪和高渗液则抑制排空。"},{"q":"与非自律细胞相比，自律细胞生物电活动主要特征是","o":["0期去极速度快","4期膜电位不稳定，自动去极","1期复极速度慢","3期复极速度慢","2期复极速度慢"],"a":1,"e":"自律细胞4期膜电位不稳定，可自动去极化达阈电位而自动产生兴奋，这是与非自律细胞生物电活动的主要区别。"},{"q":"可作为有机磷中毒解救的药物是","o":["阿托品","鱼精蛋白","普萘洛尔","筒箭毒碱","酚妥拉明"],"a":0,"e":"有机磷农药抑制胆碱酯酶使ACh蓄积，阿托品阻断M受体可缓解其毒蕈碱样症状，是常用的解救药物。"},{"q":"临床上，外科医生不轻易切除小肠，特别是十二指肠和空肠上段，即使切除也不能超过50%，其主要原因是","o":["小肠回盲括约肌的功能","小肠具有分节运动","小肠是食物消化和吸收的重要部位","小肠内胰液的化学性消化","十二指肠腺和肠腺是重要的消化腺"],"a":2,"e":"小肠是食物消化和吸收的主要部位，糖类、蛋白质和脂肪的消化产物大部分在十二指肠和空肠被吸收，切除过多将导致严重营养障碍。"},{"q":"在动物实验中，对动物进行假饲后，引起胃液分泌的特点是","o":["量大、酸度高、消化力弱","量大、酸度低、消化力强","量大，酸度高、消化力强","量少、酸度低、消化力弱","量少、酸度高、消化力强"],"a":2,"e":"假饲引起头期胃液分泌，其特点是分泌量大、酸度高、胃蛋白酶原含量高即消化力强，且受食欲影响明显。"},{"q":"慢性肾病时出现组织水肿的主要原因是","o":["毛细血管血压增高","血浆胶体渗透压降低","组织液静水压降低","组织液胶体渗透压增高","血浆晶体渗透压降低"],"a":1,"e":"慢性肾病时大量血浆蛋白从尿中丢失，血浆胶体渗透压降低，有效滤过压增大，组织液生成增多而出现水肿。"},{"q":"与肾近端小管重吸收葡萄糖关系密切的转运过程是","o":["Na+的主动重吸收","K+的主动重吸收","H+的分泌","Cl-的被动重吸收","氨基酸的重吸收"],"a":0,"e":"近端小管重吸收葡萄糖依靠管腔膜上的Na+-葡萄糖同向转运体，动力来自钠泵活动建立的Na+浓度梯度，故与Na+的主动重吸收密切相关。"},{"q":"一个肌钙蛋白亚单位TnC亚单位可结合的钙离子数是","o":["2","3","4","5","6"],"a":2,"e":"每分子TnC可结合4个Ca2+，胞质Ca2+浓度升高时与TnC结合，引起肌钙蛋白构象改变而触发肌丝滑行。"},{"q":"非弹性阻力主要成分是","o":["气道阻力","肺泡表面张力","黏滞阻力","肺回缩力","惯性阻力"],"a":0,"e":"非弹性阻力包括惯性阻力、黏滞阻力和气道阻力，平静呼吸时前两者很小，气道阻力占非弹性阻力的80%～90%。"},{"q":"通常所说的血型是指","o":["红细胞膜上特异性受体类型","血浆中特异性凝集素类型","血浆中特异性凝集原类型","红细胞膜上特异性凝集原类型","红细胞膜上特异性凝集素类型"],"a":3,"e":"血型通常指红细胞膜上特异性抗原即凝集原的类型，由遗传决定；凝集素是血浆中与之反应的抗体。"},{"q":"膜内外Na+和K+浓度梯度的维持是由于","o":["膜在安静时对K+通透性大","膜在兴奋时对Na+通透性大","Na+和K+易化扩散的结果","膜上Na+-K+泵的作用","细胞膜上载体的作用"],"a":3,"e":"Na+-K+泵每分解一分子ATP可将3个Na+泵出胞外、2个K+泵入胞内，从而维持膜内外Na+和K+的浓度梯度。"},{"q":"心室肌的后负荷为","o":["心房压力","快速射血期心室内压","减慢射血期心室内压","等容收缩期初心室内压","大动脉血压"],"a":4,"e":"心室收缩时必须克服大动脉血压才能将血液射入动脉，故大动脉血压是心室收缩的后负荷。"},{"q":"心交感神经节前纤维起源于","o":["星状神经节","脊髓中间外侧柱","延髓疑核","延髓背核","延髓孤束核"],"a":1,"e":"心交感神经节前神经元胞体位于第1～5胸段脊髓中间外侧柱，其节前纤维在星状神经节和颈交感神经节内换元。"},{"q":"胸膜腔内压等于","o":["大气压+跨肺压","大气压+肺回缩力","大气压-肺回缩力","胸内压+跨胸壁压","大气压-肺内压"],"a":2,"e":"胸膜腔内压等于肺内压与肺弹性回缩压的代数和，平静呼吸时肺内压等于大气压，故为大气压减肺回缩力。"},{"q":"传导速度最慢的神经纤维是","o":["C类纤维","B类纤维","Aα纤维","Aγ纤维","Aβ纤维"],"a":0,"e":"神经纤维的传导速度与直径和髓鞘有关，C类纤维无髓鞘且直径最细，故传导速度最慢；A类纤维有髓鞘而传导最快。"},{"q":"下列关于机体运动时血压升高，心输出量增加的原因描述，哪一项是错误的","o":["交感神经兴奋","心肌收缩力增强","前负荷增加","后负荷增加","回心血量增加"],"a":3,"e":"运动时交感神经兴奋、心肌收缩力增强、回心血量增加使前负荷增大，心输出量增加、血压升高；后负荷增加不利于射血，不是心输出量增加的原因。"},{"q":"当血浆蛋白含量显著减少时，可引起","o":["血浆胶体渗透压明显升高","组织液生成减少","组织水肿","淋巴液回流减少","血浆晶体渗透压降低"],"a":2,"e":"血浆蛋白显著减少使血浆胶体渗透压降低，有效胶体渗透压下降、有效滤过压增大，组织液生成增多而致组织水肿。"},{"q":"在心动周期中，心室充盈主要依靠","o":["地心引力的作用","骨骼肌挤压和静脉瓣的共同作用","心房收缩的作用","心室舒张的负压抽吸作用","胸膜腔内负压的作用"],"a":3,"e":"心室舒张时室内压迅速下降形成负压，对心房和大静脉内的血液产生抽吸作用，是心室充盈的主要动力。"},{"q":"血液凝固的发生是由于","o":["纤维蛋白溶解","凝血酶的激活","纤维蛋白原变为纤维蛋白","凝血因子Ⅷ的激活","血小板聚集与红细胞叠连"],"a":2,"e":"血液凝固的本质是凝血因子按一定顺序相继激活生成凝血酶，使可溶的纤维蛋白原转变为不溶的纤维蛋白多聚体。"},{"q":"下列因素中，不能引起心输出量增加的是","o":["焦虑","运动","贫血","妊娠","代谢性酸中毒"],"a":4,"e":"焦虑、运动、贫血和妊娠均可使心输出量增加；代谢性酸中毒时心肌收缩力受抑、外周血管扩张，心输出量减少。"},{"q":"人体功能活动的整合调控机制是","o":["神经调节","体液调节","自身调节","免疫调节","以上均正确"],"a":4,"e":"人体功能活动由神经调节、体液调节和自身调节共同整合调控，三者相互配合以维持内环境的稳态。"},{"q":"机体发生酸中毒时，有关血钾变化描述正确的是","o":["降低","升高","不变","先降低后升高","先升高后降低"],"a":1,"e":"酸中毒时肾小管上皮细胞泌H+增加，Na+-H+交换增强而Na+-K+交换受抑，钾排出减少；加之H+进入细胞与K+交换，使血钾升高。"},{"q":"小肠蠕动的特点是","o":["速度较快，约5cm/s","回肠蠕动的速度大于十二指肠","通常只进行一段短距离","空腹时无蠕动波","有赖于外来神经支配"],"a":2,"e":"小肠蠕动速度慢，通常只将食糜推进一段短距离即停止；传播快而远的称蠕动冲，可将食糜推送至小肠末端。"},{"q":"食物或食物残渣在消化道内停留时间最长的部位是","o":["胃","十二指肠","空肠和回肠","结肠","直肠"],"a":3,"e":"食物残渣在结肠内停留十余小时，水分被吸收并经细菌发酵、腐败后形成粪便，故结肠是停留时间最长的部位。"},{"q":"正常人动脉血液中血红蛋白的氧饱和度约为","o":["100%","97%","87%","77%","67%"],"a":1,"e":"正常动脉血PO2约100mmHg时，Hb氧饱和度约为97%～98%，静脉血PO2为40mmHg时约为75%。"},{"q":"浦肯野细胞不具有的生理特性是","o":["兴奋性","自律性","传导性","收缩性","有效不应期长"],"a":3,"e":"浦肯野细胞属自律细胞，具有兴奋性、自律性和传导性，但无收缩性；其动作电位时程长，有效不应期也长。"},{"q":"安静时膜电位处于内负外正的状态，称为","o":["极化","去极化","复极化","超极化","反极化"],"a":0,"e":"静息时细胞膜两侧存在内负外正的不均匀电荷分布状态，称为极化，是静息电位的表现形式。"},{"q":"调节远曲小管和集合管对水重吸收的激素是","o":["抗利尿激素","醛固酮","肾上腺素","心房钠尿肽","缓激肽"],"a":0,"e":"抗利尿激素作用于集合管主细胞，增加水通道AQP2的表达和转位，提高对水的通透性，促进水的重吸收。"},{"q":"颈动脉窦和主动脉弓压力感受性反射的生理意义是","o":["降低动脉血压","升高动脉血压","减弱心血管活动","加强心血管活动","维持动脉血压相对恒定"],"a":4,"e":"压力感受性反射属典型的负反馈调节，能在血压突然变动时缓冲其波动，维持动脉血压的相对恒定。"},{"q":"健康成年男性在安静状态下的心输出量约为","o":["2～3L/min","4、5～6L/min","10～15L/min","20～25L/min","30～35L/min"],"a":1,"e":"健康成年男性在安静状态下的心输出量约为4.5～6.0L/min，女性的心输出量比同体重男性低10%左右。"},{"q":"窦房结细胞动作电位0期去极化是由于","o":["Na+电导增加","Na+电导降低","Ca2+电导增加","Ca2+电导降低","K+电导增加"],"a":2,"e":"窦房结P细胞0期去极化由L型钙通道开放、Ca2+内流引起，属慢反应动作电位，可被钙通道阻滞剂阻断。"},{"q":"在体内，主要用于供能的营养物质是","o":["糖与脂肪","糖与蛋白质","脂肪与蛋白质","脂肪与核酸","糖、脂肪与蛋白质"],"a":0,"e":"糖和脂肪是体内主要的供能物质，蛋白质主要在长期不能进食等特殊情况下分解供能，故主要用于供能的是糖与脂肪。"},{"q":"健康成年男性静息状态下，心输出量约为","o":["2～3L/min","4、5～6L/min","6、5～8L/min","7、5～9L/min","9～10L/min"],"a":1,"e":"以心率75次/分、搏出量70ml计，心输出量约5L/min；健康成年男性安静时心输出量为4.5～6.0L/min。"},{"q":"胃的容受性舒张是通过下列哪种途径实现的","o":["交感神经释放的去甲肾上腺素","迷走神经释放的乙酰胆碱","迷走神经释放的肽类物质或一氧化氮","壁内神经释放的生长抑素","肠-胃反射"],"a":2,"e":"胃的容受性舒张通过迷走-迷走反射实现，其传出纤维属抑制性肽能纤维，末梢释放VIP和NO使胃壁平滑肌舒张。"},{"q":"决定肺换气和组织换气方向的主要因素是","o":["气体分压差","气体分子量大小","呼吸膜的通透性","气体溶解度","扩散系数"],"a":0,"e":"分压差是气体扩散的动力，既决定扩散速率也决定扩散方向，故肺换气和组织换气的方向主要由气体分压差决定。"},{"q":"损伤动物下丘脑外侧区可引致","o":["动物拒食","动物多食","动物饮水增多","动物饮水减少","动物拒食和饮水减少"],"a":4,"e":"下丘脑外侧区存在摄食中枢，毁损后动物拒食；该区还参与饮水调节，损伤后饮水也减少。"},{"q":"迷走神经兴奋引起胰液分泌的特点是","o":["碳酸氢盐和酶的含量丰富","水分和碳酸氢盐的含量少，酶的含量丰富","水分多，碳酸氢盐和酶的含量也丰富","碳酸氢盐多，水分和酶的含量少","水分和碳酸氢盐的含量多，酶的含量少"],"a":1,"e":"迷走神经主要作用于胰腺腺泡细胞，故其兴奋引起水和碳酸氢盐含量少、酶含量丰富的胰液；促胰液素则使水和碳酸氢盐大量分泌。"},{"q":"临床上作胆囊造影时，为检查胆囊的收缩功能，让受试者进食油煎荷包蛋是为了促进","o":["胆盐的合成","胆固醇的合成","迷走神经的兴奋","缩胆囊素的分泌","促胃液素的分泌"],"a":3,"e":"油煎荷包蛋富含脂肪，进入十二指肠后刺激黏膜释放缩胆囊素，引起胆囊强烈收缩、排出胆汁，便于观察胆囊的收缩功能。"},{"q":"下列关于蒸发散热的叙述，不正确的是","o":["以蒸发水分的形式散热","与发汗有关","与不感蒸发有关","蒸发1g水可带走2、43kJ的热量","与气温、湿度无关"],"a":4,"e":"蒸发散热以水分汽化的形式散发热量，包括不感蒸发和出汗，1g水蒸发可带走2.43kJ热量，并明显受环境气温、湿度和风速的影响。"},{"q":"关于睾酮的作用描述，下列哪一项是不正确的","o":["刺激男性生殖器官的生长发育和性征的出现","维持生精","维持和提高性欲","促进红细胞生成","促进水钠排出"],"a":4,"e":"睾酮促进肾小管对Na+和水的重吸收，使水钠潴留，而非促进水钠排出；它还能刺激男性生殖器官发育、维持生精和性欲，并促进红细胞生成。"},{"q":"下列关于甲状腺的描述，哪一项是错误的","o":["是人体最大的内分泌腺体","主要分泌甲状腺激素","激素贮存在甲状腺腺上皮内","甲状腺激素包括T3和T4","甲状腺激素能显著影响基础代谢率"],"a":2,"e":"甲状腺激素以甲状腺胶质形式大量储存于细胞外的甲状腺滤泡腔，是唯一能将激素大量储存于细胞外的内分泌腺，而非储存于腺上皮细胞内。"},{"q":"血小板磷脂酶A2激活后可产生的物质是","o":["血小板活化因子","ADP","TXA2","cAMP","组胺"],"a":2,"e":"血小板激活时磷脂酶A2裂解膜磷脂，游离出花生四烯酸，经环氧合酶及血栓烷合成酶作用生成TXA2，后者强烈聚集血小板并收缩血管。"},{"q":"下列哪种原因会引起便意","o":["横结肠粪便积聚","降结肠粪便积聚","乙状结肠粪便积聚","粪便进入直肠","粪便刺激肛门"],"a":3,"e":"粪便进入直肠后扩张直肠壁感受器，冲动传至骶段初级排便中枢并上传大脑皮层引起便意，正常人的直肠内通常没有粪便。"},{"q":"脊髓灰质炎患者发生肢体肌肉萎缩的主要原因是","o":["病毒的直接侵害","患肢肌肉血供减少","失去神经的营养性作用","患肢长期废用","脊髓失去高位中枢的控制"],"a":2,"e":"前角运动神经元变性死亡后，所支配肌肉失去神经的营养性作用，糖原合成减慢、蛋白分解加速而逐渐萎缩，并非病毒直接侵害或长期废用所致。"},{"q":"心室肌细胞动作电位各时期跨膜电位变化不包括","o":["1期复极化","2期平台期","0期去极化","3期复极化","4期自动去极化"],"a":4,"e":"4期自动去极化是窦房结等自律细胞特有的自动节律活动，心室肌工作细胞的动作电位只有0、1、2、3期，不存在4期自动去极化。"},{"q":"关于唾液的生理作用，下列哪项是错误的","o":["可湿润与溶解食物，使食物便于吞咽，并引起味觉。","可清除口腔中的食物残渣","可对蛋白质初步分解","可冲淡、中和、清除进入口腔的有害物质","可把淀粉分解为麦芽糖"],"a":2,"e":"唾液含唾液淀粉酶，可把淀粉分解为麦芽糖，但不含蛋白酶，不能对蛋白质进行初步分解；蛋白质的初步分解始于胃蛋白酶。"},{"q":"阿司匹林具有抗血小板聚集作用，是因为阿司匹林可抑制血小板的","o":["磷脂酶A2","环加氧酶","血栓烷合酶","前列环素合酶","过氧化物酶"],"a":1,"e":"阿司匹林抑制环氧合酶，减少花生四烯酸转化为TXA2，从而抑制血小板聚集；磷脂酶A2和血栓烷合酶不是其作用靶点。"},{"q":"心房肌的电生理特性是","o":["有自律性，无传导性","有传导性，无自律性，传导速度较慢","有传导性，有自律性，自律性较高","有传导性，有自律性，自律性较低","有传导性，无自律性，传导速度较快"],"a":1,"e":"心房肌属工作细胞，无自律性，但能传导兴奋，因细胞直径小、缝隙连接少，传导速度较心室肌和浦肯野纤维慢。"},{"q":"内脏痛与皮肤痛比较，主要特点是","o":["刺痛，定位明确","钝痛，定位不精确","对切割刺激敏感","对牵拉不敏感","常伴轻微的情绪反应"],"a":1,"e":"内脏痛由牵拉、痉挛、缺血或炎症引起，定位不准确，呈钝痛和慢痛，对切割烧灼不敏感而对牵拉敏感，常伴明显的情绪和自主神经反应。"},{"q":"在自动控制系统中，从受控部分发出到达控制部分的信息称为","o":["偏差信息","干扰信息","控制信息","反馈信息","自控信息"],"a":3,"e":"受控部分发出、反过来影响控制部分活动的信息称为反馈信息，如体温升高后温度感受器回输至体温调节中枢的信号。"},{"q":"兴奋在中枢的传播比在外周神经纤维上复杂，可表现为","o":["传播速度慢","在单位时间内传播距离远","在每个神经元之间的传播方式都不同","在传播过程中都会经过几十个突触","传播机制是电-机械-化学-电模式"],"a":0,"e":"兴奋在中枢须经多次化学突触接替，每个突触都产生延搁，故传播速度慢于相同长度神经纤维上的传导，还表现为单向、易疲劳和易总和。"},{"q":"迷走神经传出纤维上的神经冲动可看作","o":["反馈信息","控制信息","受控系统","控制系统","干扰信息"],"a":1,"e":"迷走神经传出纤维把中枢整合后下达的指令传至效应器，属控制部分发出的控制信息；由效应器回输的信号才是反馈信息。"},{"q":"细胞的胞质内不含致密体的组织是","o":["心室肌","子宫平滑肌","睫状肌","输精管平滑肌","主动脉平滑肌"],"a":0,"e":"致密体是平滑肌细胞内的细肌丝附着结构，心室肌为横纹肌，以Z线固定细肌丝，胞质内不含致密体。"},{"q":"临床上常用t-PA应用于心肌梗死、脑梗死等血栓性疾病，该类药物治疗的生理机制是","o":["激活血液中的抗凝血酶Ⅲ，发挥抗凝作用","激活血液中纤溶酶原激活物","刺激肥大细胞产生肝素，发挥抗凝作用","刺激肝脏合成蛋白质C，灭活凝血因子，发挥抗凝作用","激活纤溶酶原，使纤维蛋白发生降解"],"a":4,"e":"t-PA与纤维蛋白结合后激活纤溶酶原生成纤溶酶，使纤维蛋白降解而溶解血栓，属纤溶系统的激活，并非抗凝作用。"},{"q":"下列哪一项不是生长激素的作用","o":["抑制组织细胞利用葡萄糖","促进蛋白质的合成","促进脑的发育","促进软骨生长","促进脂肪分解"],"a":2,"e":"促进脑发育是甲状腺激素的作用，胚胎期TH促进神经元增殖分化、突触形成和髓鞘生成；生长激素主要促进骨骼生长和蛋白质合成。"},{"q":"以下关于钠泵生理作用的叙述，错误的是","o":["逆浓度差将进入细胞内的Na+移出膜外","顺浓度差使细胞膜外的K+转入膜内","使细胞超极化","建立离子势能储备","是神经、肌肉等组织具有兴奋性的基础"],"a":1,"e":"钠泵每分解一分子ATP逆浓度差将3个Na+移出胞外、2个K+移入胞内，K+是逆浓度梯度进入细胞，并非顺浓度差。"},{"q":"下列关于小肠运动调节的叙述，正确的是","o":["交感神经兴奋，肠运动加强","副交感神经兴奋，肠运动减弱","肌间神经丛起主要作用","对扩张刺激不敏感","对化学刺激不敏感"],"a":2,"e":"小肠运动主要受肌间神经丛调节，食糜的机械和化学刺激可通过局部反射使运动加强；交感兴奋抑制肠运动，副交感兴奋则加强。"},{"q":"红细胞比容是指红细胞","o":["与血清容积之比","与血浆容积之比","在血液中所占容积百分比","在血液中所占重量百分比","与血浆所占重量之比"],"a":2,"e":"红细胞比容指红细胞在血液中所占的容积百分比，正常男性40%～50%、女性37%～48%，可反映血液中红细胞的相对浓度。"},{"q":"后负荷突然增加会引起","o":["心室肌缩短程度增加","心室肌缩短速度加快","搏功减少","射血速度加快","心室内剩余血量增加"],"a":4,"e":"后负荷增大时等容收缩期延长、射血期缩短，射血速度减慢、搏出量减少，射血后心室内剩余血量因而增加。"},{"q":"心交感神经节后纤维末梢释放的递质主要与下列哪一种受体结合","o":["M受体","N受体","α受体","β1受体","β2受体"],"a":3,"e":"心交感神经节后纤维释放去甲肾上腺素，与心肌细胞膜β1受体结合，产生正性变力、变时和变传导作用，可被美托洛尔阻断。"},{"q":"下列关于舒血管神经的叙述，正确的是","o":["体内血管主要接受舒血管神经的支配","副交感舒血管神经主要支配骨骼肌血管","对循环系统的总外周阻力影响较大","主要调节所支配器官的血流量","始终存在紧张性活动"],"a":3,"e":"舒血管神经纤维只支配少数器官，兴奋时引起所支配器官血管舒张、局部血流量增加，对总外周阻力影响很小，也无持续紧张性活动。"},{"q":"关于肺通气阻力的描述，错误的是","o":["肺通气阻力来自弹性和非弹性阻力","弹性阻力来自肺组织和胸廓","非弹性阻力主要来自呼吸道气流的摩擦","同样压力下，弹性阻力大则表示顺应性亦大","肺的顺应性过分减小或过分增大，对呼吸均不利"],"a":3,"e":"弹性阻力与顺应性呈反变关系，同样压力下弹性阻力大则顺应性小；肺顺应性过大见于肺气肿，过小见于肺纤维化，均不利于通气。"},{"q":"深呼气末较平静呼气末","o":["肺内压绝对值不变","肺内压绝对值增加","胸内压绝对值不变","胸内压绝对值增加","肺内压绝对值减小"],"a":0,"e":"平静呼气末和深呼气末气流均已停止，肺内压都等于大气压，故绝对值不变；深呼气末胸膜腔内负压的绝对值增大。"},{"q":"中枢内兴奋传递时必须通过的结构是","o":["轴突","树突","神经纤维","突触","胞体"],"a":3,"e":"中枢内神经元之间以化学突触相接，兴奋必须经突触传递才能由一个神经元传给下一个，轴突、树突和胞体本身不能完成递质介导的传递。"},{"q":"血液进出心腔按方向流动取决于","o":["重力作用","心室肌收缩","心房心室依次收缩","压力差与瓣膜开启","心房收缩"],"a":3,"e":"血液进出心腔取决于心房与心室之间的压力差以及瓣膜随压力差而启闭，瓣膜保证血液单向流动，心房收缩只是充盈的辅助。"},{"q":"下列选项中，不属于血浆蛋白组成成分的是","o":["白蛋白","α1球蛋白","β球蛋白","γ球蛋白","纤维蛋白"],"a":4,"e":"血浆蛋白包括白蛋白、球蛋白和纤维蛋白原，纤维蛋白是纤维蛋白原在凝血酶作用下转变而成的不溶性产物，不属于血浆蛋白。"},{"q":"以下关于抑制素的描述，哪一项是错误的","o":["由睾丸支持细胞分泌","是含氮类激素","对促卵泡激素分泌有很强的抑制作用","对黄体生成素分泌有很强的抑制作用","由两个亚单位组成"],"a":3,"e":"抑制素由睾丸支持细胞分泌，是含两个亚单位的糖蛋白，选择性抑制腺垂体FSH分泌，对LH分泌无明显抑制作用。"},{"q":"下列凝血因子不属于蛋白质的是","o":["因子Ⅰ","因子Ⅱ","因子Ⅲ","因子Ⅳ","因子Ⅴ"],"a":3,"e":"凝血因子中唯有FⅣ是Ca2+，其余包括FⅠ、FⅡ、FⅢ、FⅤ等均为蛋白质，故FⅣ不属于蛋白质。"},{"q":"下列关于消化道平滑肌基本电节律的叙述，哪一项是错误的","o":["在消化道平滑肌不收缩的情况下，也可记录到基本电节律","其波幅和频率与平滑肌组织在消化道中所处的位置无关","起源于纵行肌和环形肌层之间的Cajal间质细胞","其产生可能是肌源性的","是动作电位产生的基础"],"a":1,"e":"消化道不同部位平滑肌的慢波频率和波幅不同，胃约3次/分、十二指肠约12次/分，故其频率和波幅与所在部位密切相关。"},{"q":"在急慢性肾小球肾炎时，出现蛋白尿是由于","o":["肾小球滤过率增加","滤过膜通透性降低","滤过膜的唾液（涎）蛋白减少","小管液溶质浓度增高","肾小球血浆流量增多"],"a":2,"e":"滤过膜各层含带负电荷的唾液蛋白，限制带负电的白蛋白滤过；肾炎时负电荷减少或消失，白蛋白得以滤过而出现蛋白尿。"},{"q":"有些人饮用牛奶后出现腹胀、腹痛、腹泻、排气增加，原因是由于缺乏","o":["蛋白酶","纤维素酶","乳糖酶","淀粉酶","脂肪酶"],"a":2,"e":"乳糖酶缺乏时乳糖不能被水解吸收，进入结肠被细菌发酵产气并提高肠腔渗透压，引起腹胀、腹痛、腹泻和排气增多。"},{"q":"浦肯野细胞动作电位2期内向电流电化学驱动力是","o":["Na+浓度差势能","K+浓度差势能","Ca2+浓度差势能","K+平衡电位势能","Ca2+平衡电位势能"],"a":2,"e":"浦肯野细胞2期内向电流由L型钙通道介导，其电化学驱动力等于膜电位与Ca2+平衡电位之差，来源于跨膜Ca2+浓度差势能。"},{"q":"下列生理活动中，属于负反馈调节的是","o":["减压反射","排尿反射","血液凝固","分娩","射乳反射"],"a":0,"e":"减压反射、体温调节等使受控变量向原活动相反的方向变化，属负反馈；排尿、分娩、血液凝固和射乳反射均为正反馈。"},{"q":"迷走神经兴奋时，下列说法错误的是","o":["胃平滑肌收缩","肠道平滑肌收缩","胰液分泌增加","胃液分泌增加","胃肠道括约肌收缩"],"a":4,"e":"迷走神经兴奋使胃肠平滑肌收缩、腺体分泌增加，同时使胃肠道括约肌舒张；括约肌收缩是交感神经兴奋的效应。"},{"q":"在动物实验中，将脂肪注入动物的十二指肠会引起","o":["肠胃反射，导致胃排空加速","胰液分泌增加","胆汁分泌减少","胃液分泌增加","小肠液分泌减少"],"a":1,"e":"脂肪进入十二指肠刺激小肠黏膜释放缩胆囊素，后者促进胰液分泌和胆囊收缩；脂肪不促进胃液分泌，也不加速胃排空。"},{"q":"肺通气的原动力来自","o":["肺的舒缩运动","肺的弹性回缩","呼吸肌的舒缩","胸内负压的周期性变化","肺内压与胸内压之差"],"a":2,"e":"呼吸肌的收缩舒张引起胸廓节律性扩大缩小，是肺通气的原动力；肺泡与大气间的压力差只是直接动力，肺本身不能主动舒缩。"},{"q":"关于使静脉回心血量增加的因素，叙述错误的是","o":["深吸气","体力活动加强","心肌收缩力增强","体位从卧位变成立位","循环系统平均充盈压升高"],"a":3,"e":"由卧位转为立位时，低垂部位静脉跨壁压增大而扩张，可多容纳约500ml血液，回心血量减少，故不是增加回心血量的因素。"},{"q":"肾小管中对水易通透而对Na+不易通透的部位是","o":["髓袢升支细段","髓袢升支粗段","髓袢降支细段","髓袢降支粗段","远曲小管"],"a":2,"e":"髓袢降支细段上皮含AQP1，对水高度通透而对NaCl相对不通透，小管液自上而下渗透压逐渐升高；升支细段和粗段则对水不通透。"},{"q":"皮肤触压觉的传入神经纤维属于","o":["Aα纤维","Aβ纤维","Aγ纤维","B类纤维","C类纤维"],"a":1,"e":"触-压觉由Aβ纤维传入，其纤维粗大、有髓鞘、传导速度快；Aδ和C类纤维主要传导痛觉和温度觉，C类纤维最细、传导最慢。"},{"q":"下列关于快波睡眠时相的描述中，哪一项是错误的","o":["快波睡眠又称为异相睡眠","骨骼肌反射运动和肌紧张进一步减弱","各种感觉功能进一步减退","可观察到血压升高和心率加快，呼吸加快","快波睡眠每晚只出现一次"],"a":4,"e":"整夜睡眠中快波睡眠与慢波睡眠交替出现4～6次，每次持续约20～30分钟，主要出现在睡眠后期，并非每晚只出现一次。"},{"q":"平滑肌收缩过程中胞内钙离子的主要来源是","o":["细胞外钙离子内流","肌质网内钙离子释放","肌质网膜上钙泵的转运","肌钙蛋白与大量钙离子解离","与钙调蛋白结合的钙离子解离释放"],"a":0,"e":"平滑肌肌质网不发达，收缩时胞质Ca2+主要经膜上L型钙通道由细胞外内流提供，故对细胞外Ca2+依赖明显。"},{"q":"作为感受器官，人的耳属于","o":["听觉、位置觉和平衡觉器官","听觉和平衡觉器官","听觉器官","位置觉器官","平衡觉器官"],"a":0,"e":"耳包括外耳、中耳和内耳，内耳前庭器官感受位置觉和平衡觉，耳蜗完成听觉感受，故耳兼有三种感觉功能。"},{"q":"在折光异常情况中，视远物和视近物都需要眼进行调节的是","o":["老视","近视","远视","散光","近视和散光"],"a":2,"e":"远视眼无论看远物还是看近物都需调节以增加折光力，故易发生调节疲劳；近视只在看近物时调节，老视仅看近物需调节。"},{"q":"从器官和系统水平研究的生命活动是","o":["食物在胃肠内消化与吸收","神经细胞的生物电活动","航天环境对机体功能的影响","心肌细胞的收缩机制","神经骨骼肌接头的兴奋传递"],"a":0,"e":"食物在胃肠内的消化与吸收属于以器官和系统为单位的功能研究；神经细胞生物电、心肌收缩和接头传递均属细胞和分子水平。"},{"q":"分娩前没有乳汁分泌，其原因是","o":["缺乏缩宫素","催乳素浓度过低","催乳素受体不足","血中雌孕激素浓度过高","血中雌孕激素浓度过低"],"a":3,"e":"妊娠期血中雌激素和孕激素浓度很高，抑制PRL的泌乳作用，故乳腺虽已具备泌乳能力却不泌乳；分娩后雌孕激素骤降，PRL始动泌乳。"},{"q":"体液调节的特点包括","o":["迅速","精确","持久","短暂","起作用快"],"a":2,"e":"体液调节通过血液或组织液运送化学物质，作用缓慢、持久而范围广，与神经调节的迅速、短暂、精确形成对比。"},{"q":"当细胞外Ca2+浓度降低时，心肌收缩的变化为","o":["收缩降低","舒张减慢","收缩增强","舒张增快","传导增快"],"a":0,"e":"心肌兴奋-收缩耦联依赖细胞外Ca2+内流触发肌质网释放Ca2+，细胞外Ca2+浓度降低时钙致钙释放减弱，心肌收缩力下降。"},{"q":"神经纤维动作电位的上升支是由于","o":["K+内流","K+外流","Na+内流","Na+外流","Cl-外流"],"a":2,"e":"神经纤维动作电位上升支由电压门控钠通道开放、Na+顺电化学梯度快速内流形成；K+外流则与复极化有关。"},{"q":"小肠上皮细胞吸收速度最快的糖是","o":["果糖","甘露糖","半乳糖","木糖","核糖"],"a":2,"e":"己糖吸收快于戊糖，己糖中以半乳糖和葡萄糖最快，果糖次之，甘露糖最慢；半乳糖经SGLT-1与Na+耦联行继发性主动转运。"},{"q":"关于心电图的叙述，不正确的是","o":["反映心肌机械收缩过程","P波反映兴奋在心房传导过程中电位变化","QRS波反映兴奋在心室传导中电位变化","T波反映心室肌复极过程中的电位变化","P-R间期代表窦房结的兴奋由心房到达心室所需的时间"],"a":0,"e":"心电图记录的是整个心脏兴奋的产生、传播和恢复过程中的生物电变化，与心肌的机械收缩活动无直接关系。"},{"q":"高血钙时导致慢反应细胞传导性增高的原因","o":["膜对Ca2+的通透性增大","膜对Na+的通透性增大","膜对K+的通透性增大","0期去极加快加强","Ca2+通道复活加快"],"a":3,"e":"细胞外Ca2+升高使慢反应细胞0期Ca2+内流加快、去极化速度和幅度增大，局部电流增强，传导性因而增高。"},{"q":"静脉注射大剂量的去甲肾上腺素引起尿量减少的主要原因是","o":["肾小囊内压升高","滤过膜通透性降低","肾小球滤过面积减少","血浆胶体渗透压升高","肾小球毛细血管血压降低"],"a":4,"e":"大剂量去甲肾上腺素使肾入球小动脉强烈收缩，肾小球毛细血管血压明显下降，有效滤过压降低，尿量减少。"},{"q":"在突触传递过程中，突触前膜去极化可促使","o":["Na+内流","K+外流","Mg2+内流","Ca2+内流","Cl-内流"],"a":3,"e":"突触前膜去极化达一定程度时电压门控钙通道开放，Ca2+内流，触发突触囊泡出胞而释放递质。"},{"q":"临床上治疗消化道疾病，服用阿托品以后，会出现口干现象。下列哪一项是其产生的原因","o":["使唾液分泌非条件反射不能完成","使唾液分泌的条件反射消失","引起唾液腺功能暂时消失","阻断唾液腺N受体，唾液分泌减少","阻断唾液腺M受体，唾液分泌减少"],"a":4,"e":"阿托品阻断唾液腺细胞膜上的M受体，使副交感神经的促分泌作用不能实现，唾液分泌减少而出现口干。"},{"q":"O型血的红细胞膜上有","o":["A抗原","B抗原","O抗原","H抗原","E抗原"],"a":3,"e":"O型红细胞不含A、B抗原，但保留H抗原；H抗原由前驱物质经岩藻糖基转移酶作用生成，是A、B抗原合成的前体物质。"},{"q":"听觉感受器位于","o":["椭圆囊","半规管","基底膜","球囊","鼓膜"],"a":2,"e":"听觉感受器为螺旋器，位于耳蜗基底膜上，由内、外毛细胞及支持细胞组成，盖膜覆于其上。"},{"q":"影响正常人收缩压最主要的因素是","o":["循环血量","每搏输出量","心率","外周阻力","大动脉弹性"],"a":1,"e":"每搏输出量主要影响收缩压，搏出量增加时收缩压明显升高、舒张压升高较少，脉压增大，故收缩压高低主要反映搏出量多少。"},{"q":"Hb氧饱和度的大小主要取决于血液中的","o":["PO2","PN2","PCO2","Hb含量","pH值"],"a":0,"e":"Hb氧饱和度取决于血液PO2，二者关系呈氧解离曲线；PCO2、pH和温度通过影响Hb构型使曲线移位，并非决定因素。"},{"q":"骨骼肌产生强直收缩的刺激条件是","o":["足够强度和持续时间的单刺激","足够强度的单刺激","足够强度和时间变化率的单刺激","间隔大于单收缩收缩期的连续阈刺激","间隔小于单收缩收缩期的连续阈刺激"],"a":4,"e":"连续阈刺激的间隔小于单收缩的收缩期时，后一收缩叠加在前一收缩的收缩期上，形成完全强直收缩。"},{"q":"胆碱能Ｍ型受体的阻断剂是","o":["阿托品","普萘洛尔","酚妥拉明","河豚毒素","筒箭毒"],"a":0,"e":"阿托品是M型胆碱能受体的拮抗剂；普萘洛尔阻断β受体，酚妥拉明阻断α受体，筒箭毒阻断N2受体，河豚毒素阻断钠通道。"},{"q":"下列哪一个不是神经纤维兴奋传导的特征","o":["双向传导","绝缘性","易疲劳","结构完整","功能完整"],"a":2,"e":"神经纤维传导兴奋具有完整性、双向性、绝缘性和相对不疲劳性，能长时间连续传导，易疲劳是化学突触传递的特征。"},{"q":"窦房结细胞最大复极电位的绝对值变小，是由于它的细胞膜对下列哪种离子的电导降低","o":["K+","Na+","Cl-","Ca2+","Ca2+和Na+"],"a":0,"e":"最大复极电位主要由IK外流形成，K+电导降低使复极不充分，最大复极电位绝对值变小，与阈电位差距缩短而自律性升高。"},{"q":"对心室肌细胞有效不应期特征的叙述，错误的是","o":["此期可产生局部兴奋","阈上刺激能引起动作电位","相当于心室收缩期+舒张早期","此期持续时间较长","此期等于绝对不应期+局部反应期"],"a":1,"e":"有效不应期内钠通道处于失活状态，任何强度的阈上刺激都不能引起新的动作电位，只能产生局部反应，故该叙述错误。"},{"q":"内源性凝血过程一般开始于","o":["组织细胞释放因子Ⅲ","血小板聚集","接触激活因子Ⅻ","Ca2＋的参与","因子X的激活"],"a":2,"e":"内源性凝血途径因血液与带负电荷的异物表面接触而启动，首先激活FⅫ为FⅫa，参与的凝血因子全部来自血液。"},{"q":"睡眠的产生是由于","o":["脑干网状结构上行抑制系统的作用","脑干网状结构上行激动系统的作用","下丘脑的情绪反应中枢兴奋","迷走-胰岛素系统兴奋","小脑皮质兴奋引起"],"a":0,"e":"延髓网状结构上行抑制系统活动增强时对皮层产生抑制性影响，使机体进入睡眠；上行激动系统兴奋则维持觉醒。"},{"q":"神经冲动抵达末梢时，引起递质释放主要依赖于下列哪种离子的作用","o":["Na+","Cl-","Mg2+","Ca2+","K+"],"a":3,"e":"神经冲动到达末梢使前膜去极化，电压门控钙通道开放，Ca2+内流触发囊泡出胞，递质释放量主要取决于进入末梢的Ca2+量。"},{"q":"以下关于可兴奋细胞动作电位的描述，正确的是","o":["动作电位是细胞受刺激时出现的快速而不可逆的电位变化","在动作电位的去极相，膜电位由内正外负变为内负外正","动作电位的大小不随刺激强度和传导距离而改变","动作电位的传导距离随刺激强度的大小而改变","不同的细胞，动作电位的幅度都相同"],"a":2,"e":"动作电位具有全或无特性，其幅度由钠通道性状和离子驱动力决定，不随刺激强度增强或传导距离延长而改变。"},{"q":"由于眼球前后径过长而导致的近视，为了使远处来自物体的平行光线能聚焦到视网膜上，可配戴合适度数的","o":["凸透镜","凹透镜","平面透镜","圆柱形透镜","棱镜"],"a":1,"e":"轴性近视因眼球前后径过长，平行光线聚焦于视网膜前方，需配戴凹透镜使光线适度发散后再入眼，方能聚焦于视网膜。"},{"q":"下列有关血浆清除率的描述正确的是","o":["相对于单位时间被肾完全清除了某物质的血浆毫升数","清除血浆中一定量某物质的能力","清除一定量体液的能力","将一定容积血浆中某物质完全清除掉的能力","将血浆中某物质清除到终尿中的能力"],"a":0,"e":"清除率指两肾每分钟能将多少毫升血浆中所含的某物质完全清除，是推算值，用以反映肾对该物质的排泄能力。"},{"q":"CO2在血液中运输的主要形式是","o":["物理溶解","形成碳酸","形成碳氧血红蛋白","形成氨基甲酰血红蛋白","形成碳酸氢盐"],"a":4,"e":"CO2在血液中约88%以碳酸氢盐形式运输，在红细胞内碳酸酐酶催化下生成H2CO3并解离为H+和HCO3-，其余为氨基甲酰血红蛋白和物理溶解。"},{"q":"通气/血流比值异常，所致肺泡与血液间气体交换不足，常表现为","o":["缺O2明显，CO2潴留不明显","缺O2不明显，CO2潴留明显","缺O2和CO2潴留都不明显","缺O2和CO2潴留不会出现","只表现为CO2潴留"],"a":0,"e":"VA/Q增大或减小都妨碍气体有效交换，因动静脉血PO2差远大于PCO2差，加之氧解离曲线的特点，缺O2比CO2潴留更显著。"},{"q":"下列哪种物质不属于第二信使","o":["cAMP","DG","IP3","cGMP","AC"],"a":4,"e":"腺苷酸环化酶是催化ATP生成cAMP的效应器酶，本身不是第二信使；cAMP、DG、IP3和cGMP才是第二信使。"},{"q":"下列关于胃液分泌的描述哪一项是错误的","o":["主细胞分泌胃蛋白酶原","主细胞分泌内因子","壁细胞分泌盐酸","幽门腺和贲门腺分泌黏液","黏液细胞分泌黏液"],"a":1,"e":"内因子由胃壁细胞分泌，与维生素B12结合后促进其在回肠吸收；主细胞分泌胃蛋白酶原，壁细胞分泌盐酸。"},{"q":"心室肌细胞的有效不应期的长短主要取决于","o":["动作电位0期去极速度","动作电位1期复极速度","动作电位2期复极速度","动作电位3期复极速度","动作电位4期复极速度"],"a":2,"e":"有效不应期相当于动作电位的0、1、2期及3期前半，平台期越长不应期越长，故其长短主要取决于2期复极速度。"},{"q":"影响毛细血管前括约肌舒缩活动的主要因素是","o":["交感舒血管神经纤维末梢释放的乙酰胆碱","副交感神经末梢释放的乙酰胆碱","肾上腺髓质释放的肾上腺素","局部代谢产物增多","交感神经末梢释放去甲肾上腺素"],"a":3,"e":"毛细血管前括约肌的神经分布极少，其舒缩主要受局部代谢产物和低氧调节，代谢产物积聚使其舒张、毛细血管开放。"},{"q":"以下哪项因素可以抑制胰岛素的分泌","o":["交感神经兴奋","血中氨基酸及脂肪酸增加","胃肠激素","迷走神经兴奋","血糖升高"],"a":0,"e":"交感神经兴奋释放去甲肾上腺素，主要经β细胞膜α受体抑制胰岛素分泌；血糖升高、氨基酸和脂肪酸增多、胃肠激素及迷走兴奋均促进分泌。"},{"q":"下列关于神经纤维动作电位的描述，正确的是","o":["刺激强度小于阈值时，出现低幅度的动作电位","刺激强度达到阈值时，再增加刺激强度，则动作电位的幅度随之增大","动作电位一旦产生，可沿细胞膜作电紧张传播","动作电位的大小随着传导距离的增加而变小","不同可兴奋细胞动作电位的幅度和持续时间可以不一样"],"a":4,"e":"不同可兴奋细胞动作电位的幅度和持续时间不同，如神经细胞约1毫秒、心室肌约300毫秒；其幅度不随刺激强度改变。"},{"q":"正常心电图中代表心室肌复极是","o":["P波","QRS波","T波","S-T段","P-R间期"],"a":2,"e":"T波反映心室肌快速复极化即3期的电位变化，QRS波群代表心室去极化，P波代表心房去极化。"},{"q":"引起神经细胞兴奋的阈电位是指细胞膜","o":["对Ca2+通透性突然增大时的临界膜电位值","对K+通透性突然减小时的临界膜电位值","对K+通透性突然增大时的临界膜电位值","对Na+通透性突然增大时的临界膜电位值","对Na+通透性突然减小时的临界膜电位值"],"a":3,"e":"阈电位是使膜上钠通道大量开放、Na+内流与去极化形成正反馈的临界膜电位，即膜对Na+通透性突然增大的临界值。"},{"q":"细胞内能使底物蛋白质磷酸化的酶是","o":["磷酸二酯酶","腺苷酸环化酶","蛋白激酶A","鸟苷酸环化酶","磷脂酶C"],"a":2,"e":"蛋白激酶A是cAMP依赖性蛋白激酶，可把ATP的磷酸基团转移到底物蛋白质上使其磷酸化；腺苷酸环化酶和鸟苷酸环化酶则催化生成第二信使。"},{"q":"关于Cl-在近端小管重吸收的描述正确的是","o":["大部分在前半段被重吸收","与HCO3-重吸收竞争转运体","主要在前半段主动重吸收","可通过细胞旁途径被动重吸收","不存在跨细胞途径重吸收"],"a":3,"e":"近端小管后半段因Na+、葡萄糖等被重吸收而使小管液带正电，Cl-顺电位梯度经细胞旁途径被动重吸收，并非主动转运。"},{"q":"下列哪种物质对胃酸的分泌没有促进作用","o":["乙酰胆碱","糖皮质激素","组胺","生长抑素","促胃液素"],"a":3,"e":"生长抑素由胃δ细胞分泌，抑制G细胞释放促胃液素并抑制组胺释放，从而抑制胃酸分泌；ACh、组胺和促胃液素均促进胃酸分泌。"},{"q":"降钙素的主要作用是","o":["升高血钙和血磷","降低血钙和血磷","降低血钙、升高血磷","升高血钙、降低血磷","主要参与正常血钙的调节"],"a":1,"e":"降钙素作用于骨和肾，抑制破骨细胞活动、促进成骨并增强肾脏排出钙磷，使血钙和血磷均降低，与甲状旁腺激素作用相反。"},{"q":"将动物的外周化学感受器完全切除后","o":["动脉血PCO2升高10%，不能使呼吸发生明显变化","动脉血pH值升高，不能使呼吸发生明显变化","肌肉运动时呼吸不会加强","缺氧可通过中枢化学感受器使呼吸加强","该动物对低氧环境的适应能力显著降低"],"a":4,"e":"外周化学感受器是感知低氧的主要部位，切除后机体对低氧的通气代偿反应丧失，对低氧环境的适应能力显著降低。"},{"q":"肿瘤压迫导致局部组织水肿的原因是","o":["血浆胶体渗透压降低","组织液静水压降低","毛细血管壁通透性增加","毛细血管血压增高","淋巴和（或）静脉回流受阻"],"a":4,"e":"肿瘤压迫使淋巴管或静脉回流受阻，含蛋白质的组织液在组织间隙积聚，形成淋巴水肿或静脉性水肿。"},{"q":"肾小管中对Cl-是主动重吸收的部位是","o":["近曲小管","髓袢升支粗段","髓袢升支细段","髓袢降支粗段","髓袢降支细段"],"a":1,"e":"髓袢升支粗段顶端膜NKCC2主动重吸收Na+、K+和Cl-，Cl-再经基底侧膜氯通道进入组织间液，是Cl-主动重吸收的主要部位。"},{"q":"水分子快速通过细胞膜主要依靠","o":["单纯扩散","水通道","载体蛋白","非门控离子通道","水泵"],"a":1,"e":"水分子虽能以单纯扩散方式通过脂质双层，但速度很慢，快速跨膜主要依靠水通道蛋白，其转运速率极高。"},{"q":"异相睡眠的主要特点有","o":["脑电波呈现同步化慢波","血压下降","心率减慢","做梦","生长激素分泌明显升高"],"a":3,"e":"异相睡眠脑电呈去同步化快波，伴眼球快速阵发性运动，此时被唤醒者多诉正在做梦；生长激素分泌减少，血压和心率升高。"},{"q":"给家兔静脉注射一定量乳酸引起呼吸加强主要是通过","o":["刺激中枢化学感受器","刺激外周化学感受器","抑制呼吸中枢","刺激呼吸中枢","刺激中枢和外周化学感受器"],"a":1,"e":"乳酸使血液H+浓度升高，H+不易通过血-脑屏障，主要通过刺激外周化学感受器反射性加强呼吸。"},{"q":"凝血酶原酶复合物的组成是","o":["FⅢ-FⅦ-Ca2+-PL","FⅩ-FⅤ-Ca2+-PL","FⅡ-FⅩ-Ca2+-PL","FⅨ-FⅦ-Ca2+-PL","FⅤ-FⅧ-Ca2+-PL"],"a":1,"e":"内源性和外源性途径生成的FⅩa在Ca2+存在下与FⅤa结合于血小板膜磷脂表面，形成FⅩa-FⅤa-Ca2+-磷脂复合物即凝血酶原酶复合物。"},{"q":"眼折光系统的组成结构是","o":["角膜、房水、晶状体和视网膜","角膜、晶状体、玻璃体和视网膜","角膜、房水、视网膜和玻璃体","角膜、房水、晶状体和玻璃体","角膜、晶状体、玻璃体和睫状体"],"a":3,"e":"眼的折光系统由角膜、房水、晶状体和玻璃体四种折光体及其界面构成，入眼光线的折射主要发生在角膜前表面。"},{"q":"原尿在肾脏被重吸收的比率约为","o":["65%","85%","89%","95%","99%"],"a":4,"e":"肾小球每日滤过原尿约180L，而终尿仅约1.5L，故约99%的原尿在肾小管和集合管被重吸收。"},{"q":"甲状腺激素的生理功能不包括下列哪一项","o":["促进能量代谢","影响物质代谢","促进生长发育","提高中枢神经系统兴奋性","抑制心血管活动"],"a":4,"e":"甲状腺激素提高心肌对儿茶酚胺的敏感性，使心率加快、心肌收缩力增强、心输出量增加，故抑制心血管活动不是其作用。"},{"q":"引起醛固酮分泌减少的主要因素是","o":["循环血量减少","血液中K+浓度升高","血液中K+浓度降低","血浆晶体渗透压降低","血浆晶体渗透压升高"],"a":2,"e":"血K+浓度降低或血Na+浓度升高时醛固酮分泌减少；血K+升高、血Na+降低和循环血量减少均刺激其分泌，且对血K+变化更敏感。"},{"q":"尿液的稀释主要发生在下列哪个部位","o":["髓袢升支细段","髓袢降支粗段","髓袢升支粗段","髓袢降支细段","远曲小管"],"a":4,"e":"远曲小管对水不通透，在ADH缺乏时仍继续重吸收NaCl而水不被重吸收，小管液渗透压进一步降低，尿液因而被稀释。"},{"q":"血中激素浓度极低，但生理作用却非常显著，其原因是","o":["激素的半衰期非常长","激素的特异性很高","激素分泌的持续时间非常长","细胞内存在高效能的生物放大系统","激素在体内降解速度慢"],"a":3,"e":"激素与受体结合后经逐级酶促反应放大信号，如1mol肾上腺素可生成10⁸mol葡萄糖，故血中浓度极低而生理效应显著。"},{"q":"如果在高原上吸入气PO2大于60mmHg，Hb氧饱和度水平可为","o":["40%～60%","60%～70%","70%～80%","80%～90%","90%以上"],"a":4,"e":"氧解离曲线在PO2 60～100mmHg段较平坦，PO2降至60mmHg时Hb氧饱和度仍约90%，只要不低于60mmHg即可维持在90%以上。"},{"q":"与组织液的生成与回流无关的因素包括","o":["毛细血管血压","毛细血管血压壁通透性","血浆晶体渗透压","血浆胶体渗透压","组织液静水压"],"a":2,"e":"组织液的生成取决于毛细血管血压、血浆胶体渗透压、组织液静水压和淋巴回流；血浆晶体渗透压主要调节细胞内外水的分布，与其无关。"},{"q":"中性粒细胞的主要功能是","o":["产生抗体","吞噬细菌","参与止血","释放组胺","参与蠕虫反应"],"a":1,"e":"中性粒细胞是血液中主要的吞噬细胞，变形游走和吞噬活性均强，能迅速渗出至炎症区域吞噬并杀灭细菌。"},{"q":"安静时，细胞膜外正内负的稳定状态称为","o":["极化","超极化","反极化","复极化","去极化"],"a":0,"e":"静息时膜两侧内负外正的不均匀电荷分布状态称为极化；负值增大为超极化，负值减小为去极化。"},{"q":"发汗的基本中枢位于","o":["脊髓","延髓","中脑","下丘脑","大脑皮质"],"a":3,"e":"控制温热性发汗的中枢位于下丘脑体温调节中枢，经交感胆碱能纤维支配全身小汗腺；精神性出汗的中枢在大脑皮层运动区。"},{"q":"外周阻力和心率不变而每搏输出量增多时，动脉血压的变化主要是","o":["收缩压升高，脉压增大","舒张压升高，脉压变小","收缩压降低，舒张压升高","收缩压升高，舒张压降低","收缩压升高，脉压不变"],"a":0,"e":"外周阻力和心率不变时，搏出量增多使收缩期射入主动脉的血量增加，收缩压明显升高、舒张压升高较少，脉压增大。"},{"q":"腹下神经兴奋时，将引起","o":["膀胱逼尿肌收缩","膀胱逼尿肌舒张","尿道内括约肌舒张","尿道外括约肌收缩","尿道外括约肌舒张"],"a":1,"e":"腹下神经为交感神经，末梢释放去甲肾上腺素，作用于β受体使膀胱逼尿肌舒张、作用于α受体使内括约肌收缩，利于储尿。"},{"q":"下列生理过程与K+的跨膜扩散无关的是","o":["快反应细胞动作电位的3期复极化","慢反应细胞动作电位的0期去极化","快反应细胞的静息电位","快反应细胞动作电位的1期复极化","慢反应细胞动作电位的4期自动去极化"],"a":1,"e":"慢反应细胞0期去极化由L型钙通道介导的Ca2+内流形成，与K+跨膜扩散无关；静息电位、1期和3期复极及4期自动去极化均有K+电流参与。"},{"q":"下列哪种活动不是机体的排泄作用","o":["肠道排出食物残渣","结肠与直肠排出胆色素","呼吸道排出CO2","皮肤分泌的汗液","肾脏排出的尿液"],"a":0,"e":"排泄指机体把代谢终产物、多余物质和异物排出体外；食物残渣未被吸收，经大肠排出属排遗而非排泄。"},{"q":"平滑肌细胞中钙离子-钙调蛋白复合物的作用位点存在于","o":["致密体","肌钙蛋白与大量Ca2+解离","肌动蛋白","原肌球蛋白","肌球蛋白"],"a":4,"e":"平滑肌无肌钙蛋白，Ca2+与钙调蛋白结合后激活肌球蛋白轻链激酶，使肌球蛋白轻链磷酸化而触发收缩，故作用位点在肌球蛋白。"},{"q":"对于M型受体的叙述，错误的是","o":["属于胆碱能受体","其阻断剂为阿托品","能与毒蕈碱发生特异性结合","存在于副交感神经节后纤维支配的效应器细胞膜上","存在于神经肌肉接头后膜上"],"a":4,"e":"M受体存在于副交感节后纤维支配的效应器细胞膜上，能与毒蕈碱特异性结合并被阿托品阻断；神经肌肉接头后膜上的是N2受体。"},{"q":"骨髓中自我复制能力最强的细胞是","o":["造血干细胞","定向组细胞","前体细胞","网织红细胞","淋巴细胞"],"a":0,"e":"造血干细胞具有对称性和非对称性有丝分裂能力，可自我更新并保持数量稳定；造血祖细胞已失去自我更新能力。"},{"q":"引起红细胞沉降率减慢的因素是","o":["红细胞叠连增多","血浆胆固醇含量增多","血浆白蛋白含量增多","血浆球蛋白含量增多","血浆纤维蛋白原含量增多"],"a":2,"e":"血浆白蛋白带负电荷，可抑制红细胞叠连，使沉降率减慢；纤维蛋白原、球蛋白和胆固醇增多则促进叠连，使血沉加快。"},{"q":"体循环和肺循环相比，基本相同的是","o":["心脏做功量","心输出量","动脉血压","动脉血含氧量","外周阻力"],"a":1,"e":"左、右心室的心输出量基本相等，这是体循环与肺循环串联的必然结果；两循环的动脉血压、外周阻力和心脏做功量相差悬殊。"},{"q":"造成呼出气中CO2含量低于肺泡气的原因是","o":["潮气量","无效腔中的新鲜空气","肺泡气中的新鲜空气","补吸气量中的新鲜空气","残气量中的新鲜空气"],"a":1,"e":"呼出气是解剖无效腔内吸入的新鲜空气与肺泡气的混合气体，混入的新鲜空气使其CO2含量低于肺泡气。"},{"q":"在心动周期中，房室瓣开放始于","o":["等容舒张期末","快速充盈期末","减慢充盈期末","心房收缩期初","心房收缩期末"],"a":0,"e":"等容舒张期室内压持续下降，降至低于房内压时房室瓣开放，血液冲入心室，心室充盈期由此开始。"},{"q":"下丘脑室旁核主要分泌下列哪种激素","o":["催乳素","缩宫素","生长激素","黄体生成素","促卵泡激素"],"a":1,"e":"室旁核和视上核的神经元合成缩宫素和血管升压素，经轴突运至神经垂体贮存，需要时释放入血。"},{"q":"胰岛素对血糖水平的调节通过以下哪种分泌方式进行","o":["自分泌","远距分泌","旁分泌","神经分泌","外分泌"],"a":1,"e":"胰岛素经血液运输至全身靶细胞调节血糖，属远距分泌；胰岛α细胞分泌胰高血糖素刺激β细胞则属旁分泌。"},{"q":"能使机体功能状态保持相对稳定的是","o":["非自动控制系统","负反馈控制系统","正反馈控制系统","前馈控制系统","混合调节系统"],"a":1,"e":"负反馈使受控部分的活动向与原活动相反的方向改变，把血糖、血压、渗透压等变量维持在调定点水平，是维持稳态的主要方式。"},{"q":"心肌收缩能力的增强可通过下列哪一途径实现","o":["增加参与收缩的肌纤维数目","增加肌小节的初长度","增加兴奋时肌浆内Ca2+浓度","心肌发生完全强直收缩","降低主动脉的血压水平"],"a":2,"e":"心肌收缩能力取决于兴奋时胞质Ca2+浓度及肌钙蛋白对Ca2+的敏感性，增加Ca2+内流和钙致钙释放可增强收缩；心肌不能发生强直收缩。"},{"q":"α受体的阻断剂是","o":["阿托品","普萘洛尔","筒箭毒","河豚毒素","酚妥拉明"],"a":4,"e":"酚妥拉明非选择性地阻断α受体；阿托品阻断M受体，普萘洛尔阻断β受体，筒箭毒阻断N2受体，河豚毒素阻断钠通道。"},{"q":"在动物实验中，按压家兔双侧颈动脉窦可引起","o":["心率加快","心肌收缩力减弱","外周血管收缩","心交感神经活动增强","心迷走神经活动减弱"],"a":1,"e":"按压颈动脉窦使压力感受器受到的牵张刺激增强，减压反射加强，心迷走紧张增强、心交感紧张减弱，心肌收缩力减弱、心率减慢。"},{"q":"心动周期中，主动脉压最高见于","o":["心房收缩期末","等容收缩期末","快速射血期末","减慢射血期末","等容舒张期末"],"a":2,"e":"快速射血期心室射入主动脉的血量最多、流速最快，主动脉压急剧升高，在快速射血期末达到最高值。"},{"q":"钙通道阻断剂维拉帕米对浦肯野细胞动作电位的影响是","o":["0期除极幅度降低","0期除极速度减慢","1期复极时程缩短","2期复极时程缩短","3期复极时程缩短"],"a":3,"e":"维拉帕米阻断L型钙通道，减少2期Ca2+内流，使平台期缩短，故浦肯野细胞动作电位的2期复极时程缩短。"},{"q":"脑电波的形成机制是大量皮层神经元发生","o":["动作电位","诱发电位","兴奋性突触后电位","抑制性突触后电位","突触后电位同步总和"],"a":4,"e":"脑电波由大量皮层锥体细胞同步发生的突触后电位经总和后形成，单个神经元的突触后电位不足以引起皮层表面电位改变。"},{"q":"交感和副交感神经节前纤维释放的递质是","o":["肾上腺素","去甲肾上腺素","乙酰胆碱","肾上腺素和去甲肾上腺素","乙酰胆碱和去甲肾上腺素"],"a":2,"e":"交感和副交感神经的节前纤维均释放乙酰胆碱，作用于节后神经元的N1受体；节后纤维才分别为去甲肾上腺素和乙酰胆碱。"},{"q":"中医学在古代生理学阶段作出卓越贡献的著作是","o":["本草纲目","黄帝内经","金匮要略","伤寒杂病论","千金要方"],"a":1,"e":"《黄帝内经》是我国第一部医学典籍，对脏腑功能有较详细记载，是古代生理学阶段的重要贡献。"},{"q":"体温调节中枢在","o":["下丘脑","中脑","延髓","脊髓","大脑皮质"],"a":0,"e":"脑分段横断实验表明，只要下丘脑及其以下结构完整，动物仍能维持体温相对稳定；视前区-下丘脑前部是体温调节的基本中枢。"},{"q":"窦房结能成为心脏正常起搏点的原因是","o":["4期自动去极速度慢","阈电位与最大复极电位差距大","0期去极速度低","自律性高","动作电位无明显平台期"],"a":3,"e":"窦房结P细胞的自律性最高，约100次/分，高于房室结和浦肯野细胞，并通过抢先占领和超速驱动压抑控制潜在起搏点。"},{"q":"调节毛细血管前括约肌舒缩活动的主要因素是","o":["交感神经末梢释放去甲肾上腺素","交感副交感神经末梢释放乙酰胆碱","血管紧张素","组织的局部代谢产物","肾上腺髓质释放的肾上腺素"],"a":3,"e":"毛细血管前括约肌受神经支配极少，其舒缩主要由局部代谢产物和低氧状态调控，属典型的代谢性自身调节。"},{"q":"下列能够促进胆汁分泌的因素是","o":["血管活性肠肽","生长抑素","促胰液素","抑胃肽","神经降压素"],"a":2,"e":"促胰液素促进胆管上皮分泌大量水和HCO3-，使胆汁分泌量增加；促胃液素也有刺激作用，生长抑素和抑胃肽则抑制。"},{"q":"安静时微循环中真毛细血管网的状态是","o":["经常关闭","经常开放","持续关闭","持续开放","交替开放"],"a":4,"e":"安静时同一器官内不同部位的真毛细血管轮流开放，同一毛细血管也交替开放和关闭，由毛细血管前括约肌控制。"},{"q":"下列关于吞咽的叙述，错误的是","o":["是一个复杂的反射活动","可分为口腔期、咽期和食管期","是一个条件反射的过程","可以随意发动","吞咽时软腭上升，咽喉壁向前突出"],"a":2,"e":"吞咽是使食团由口腔经咽、食管入胃的复杂反射，分为口腔期、咽期和食管期，其启动可随意控制，全过程属非条件反射。"},{"q":"在氧分压较低的高原上，呼吸将代偿性增强，这主要依赖于下列何种感受器对呼吸中枢的兴奋作用","o":["颈动脉窦压力感受器","颈动脉体化学感受器","主动脉弓压力感受器","主动脉体化学感受器","延髓化学感受器"],"a":1,"e":"低氧主要刺激外周化学感受器，其中颈动脉体对低氧的敏感性高于主动脉体，是高原低氧时驱动呼吸增强的主要感受器。"},{"q":"孕激素的作用不包括下列哪一项","o":["使子宫内膜产生分泌期变化为受精卵着床做准备","抑制子宫平滑肌收缩","促进乳腺腺泡发育","抑制能量代谢过程使体温降低","使血管和消化道平滑肌紧张性降低"],"a":3,"e":"孕激素增强能量代谢并提高体温调定点，使基础体温升高0.2～0.5℃，而非抑制能量代谢使体温降低。"},{"q":"下列哪种细胞合成雄激素结合蛋白","o":["生精细胞","支持细胞","基底细胞","睾丸内皮细胞","间质细胞"],"a":1,"e":"支持细胞在FSH作用下合成和分泌雄激素结合蛋白，与睾酮结合维持曲细精管内高浓度的雄激素，有利于生精。"},{"q":"关于局部兴奋的特征，叙述错误的是","o":["电位大小随刺激强度而改变","可总和","无不应期","有全或无现象","衰减性传导"],"a":3,"e":"局部电位呈等级性，幅度随刺激强度改变，可衰减性传导、无不应期并能总和；全或无现象是动作电位的特征。"},{"q":"下列关于心肌与骨骼肌的不同的描述，哪项是正确的","o":["只有心肌是由肌小节组成的","只有骨骼肌的收缩机制可用滑行理论解释","从心肌的长度-曲线关系中，看不出最适初长","骨骼肌的收缩是有等级性的，而心肌的收缩是“全或无”的","只有骨骼肌有粗、细两种肌丝"],"a":3,"e":"骨骼肌靠增减参与收缩的肌纤维数目调节收缩强度而呈等级性；心肌细胞以闰盘相连，兴奋一旦产生全部心肌细胞参与收缩，呈全或无。"},{"q":"房室交界区传导减慢可致","o":["P波增宽","QRS波群增宽","T波增宽","P-R间期延长","ST段延长"],"a":3,"e":"P-R间期代表兴奋经心房、房室交界和房室束到达心室所需的时间，房室交界传导减慢时该间期延长，常见于房室传导阻滞。"},{"q":"在动物中脑四叠体间横断脑干时，呼吸的变化是","o":["呼吸节律基本正常","呈节律性喘息式呼吸","出现深而慢的呼吸","出现长吸式呼吸","呼吸停止"],"a":0,"e":"在中脑与脑桥之间横断脑干，呼吸节律无明显变化；在脑桥中部横断则呼吸变慢变深，在延髓与脑桥之间横断出现喘息样呼吸。"},{"q":"副交感神经节前纤维释放的递质是","o":["ACh","NE","5-HT","ACh和NE","NE和5-HT"],"a":0,"e":"交感和副交感神经的节前纤维末梢均释放ACh，作用于节后神经元的N1受体；副交感节后纤维也释放ACh。"},{"q":"下列关于甲状腺激素代谢的描述，哪一项是正确的","o":["T4代谢比T3快","T4主要在肝内代谢","T4代谢后可转变为T3","T4在外周组织代谢较少","T4与T3不能在肾脏代谢"],"a":2,"e":"T4在外周组织脱碘酶作用下可转变为T3和rT3，外周血中80%的T3来源于T4脱碘。T3生物活性最强，代谢比T4快。"},{"q":"房-室延搁的生理意义是","o":["使心房、心室不会同时收缩","使心室肌有效不应期延长","增强心肌收缩力","使心室肌不会产生完全强直收缩","降低心肌的收缩力"],"a":0,"e":"房室延搁使兴奋经房室结传导缓慢，保证心房收缩完毕后心室才收缩，有利于心室充盈和射血。"},{"q":"血小板减少导致皮肤出现自发性出血斑点的主要原因是","o":["血小板不能聚集成团","血小板不能释放足够的血管活性物质","不能修复和保持血管内皮细胞完整性","血凝块回缩障碍","血小板黏附减少"],"a":2,"e":"血小板可黏附于受损内皮下组织并释放活性物质，维持血管壁完整性；血小板减少时毛细血管脆性增高，出现自发性出血斑点。"},{"q":"关于胃液分泌的叙述，下列哪项是错误的","o":["壁细胞分泌盐酸","幽门腺分泌黏液","主细胞分泌胃蛋白酶","壁细胞分泌内因子","黏液细胞分泌糖蛋白"],"a":2,"e":"主细胞分泌胃蛋白酶原，而非胃蛋白酶；胃蛋白酶原需经盐酸激活后才转变为胃蛋白酶。壁细胞分泌盐酸和内因子，黏液细胞分泌糖蛋白。"},{"q":"比较各种体液中蛋白质浓度，正确的是","o":["细胞内液>组织液>血浆","细胞内液>血浆>组织液","血浆>组织液>细胞内液","血浆>细胞内液>组织液","血浆=细胞内液>组织液"],"a":1,"e":"血浆含大量蛋白质，组织液中蛋白质很少，细胞内液蛋白质含量高于组织液，故蛋白质浓度为血浆>细胞内液>组织液。"},{"q":"下列关于心肺感受器引起的心血管反射的叙述，正确的是","o":["感受器只接受心或血管壁的机械牵张","感受器不接受化学物质的刺激","心室血容量降低可引起该反射活动","可引起血压下降","可引起心交感紧张性加强"],"a":3,"e":"心房壁容量感受器受牵张兴奋后，经迷走神经传入引起交感抑制、迷走兴奋，使心率减慢、心输出量减少、外周阻力降低，血压下降。"},{"q":"完成一个反射所涉及的五个部位中，最易出现疲劳的是","o":["效应器","反射中枢","感受器","传入神经","传出神经"],"a":1,"e":"反射中枢的兴奋传播需经多次化学突触接替，递质耗竭使中枢传播相对容易发生疲劳，故反射中枢最易疲劳。"},{"q":"骨骼肌终板膜上的受体是","o":["α受体","β1受体","Ｎ2受体","Ｎ1受体","Ｍ受体"],"a":2,"e":"骨骼肌终板膜上的乙酰胆碱受体为N2型（肌肉型烟碱受体），属配体门控阳离子通道，激活后以Na+内流为主引起肌细胞兴奋。"},{"q":"正常成年男性的血细胞在血液中所占的容积百分比是","o":["20%～30%","30%～40%","40%～50%","60%～65%","70%～80%"],"a":2,"e":"血细胞比容指血细胞在血液中所占的容积百分比，正常成年男性为40%～50%，女性为37%～48%。白细胞和血小板仅占0.15%～1%，故该值主要反映红细胞相对浓度。"},{"q":"在壁细胞完全缺乏的人，下列哪种情况不会发生","o":["消化蛋白质能力降低","维生素B12吸收减少","胃蛋白酶激活降低或消失","肠道细菌生长加速","碳酸氢盐分泌减少"],"a":0,"e":"壁细胞分泌盐酸和内因子，内因子促进回肠维生素B12吸收，盐酸激活胃蛋白酶原并维持胃内低pH杀菌。壁细胞缺乏时胃蛋白酶激活障碍、维生素B12吸收减少、杀菌力下降致肠道细菌增多；蛋白质消化主要靠胰液，故消化蛋白质能力降低不会发生。"},{"q":"在寒冷环境中，机体不会出现下列哪项反应","o":["交感神经紧张性增高","皮肤小动脉收缩","皮肤血流量降低","皮下动-静脉吻合支开放增多","皮肤温度升高"],"a":4,"e":"寒冷环境中交感神经紧张性增强，皮肤小动脉收缩、血流量减少、皮肤温度降低以减少散热，动-静脉吻合支开放增多见于炎热环境。皮肤温度升高是散热反应，不会在寒冷中出现。"},{"q":"球-管平衡的生理意义是","o":["尿量不会因肾小球滤过率的增减出现大幅度变动","维持肾小球滤过率恒定","维持肾髓质高渗梯度","保证肾小管重吸收的正常进行","保证肾小管分泌的正常进行"],"a":0,"e":"球-管平衡指肾小球滤过率增减时近端小管对Na+和水的重吸收百分率基本不变，其生理意义在于保持尿量和尿Na+相对稳定，避免尿量随滤过率波动而大幅变动。"},{"q":"O2分压最高的部位是","o":["动脉血","静脉血","组织细胞","毛细血管","肺泡气"],"a":4,"e":"肺泡气PO2约102mmHg，高于动脉血97～100mmHg、混合静脉血40mmHg和组织30mmHg。O2依分压差由肺泡向血液净扩散，故肺泡气氧分压最高。"},{"q":"关于能量代谢的描述，错误的是","o":["肌肉活动能显著提高产热量","环境温度低于20℃时，代谢增加","精神紧张可致机体产热量显著增加","平静思考问题时，脑组织产热量明显升高","在睡眠和在活跃的精神状态下，脑中葡萄糖代谢明显不同"],"a":3,"e":"平静思考问题时产热量增加一般不超过4%，脑组织产热量无明显升高；精神紧张时能量代谢率可增高10%以上，肌肉活动显著增加产热，环境温度低于20℃时代谢增强。"},{"q":"怀孕期间胎盘大量分泌的雌激素主要是下列哪一种","o":["雌酮","孕酮","β-雌二醇","雌三醇","绒毛膜促性腺激素"],"a":3,"e":"人类胎盘分泌的雌激素主要是雌三醇，其生成需胎儿肾上腺皮质与胎盘共同参与，妊娠末期可增至非孕妇女的1000倍，尿雌三醇水平可反映胎盘功能。"},{"q":"肾维持体内水平衡主要通过下列哪项调节活动实现","o":["肾小球滤过量","近曲小管与髓袢的重吸收水量","远曲小管和集合管的重吸收水量","肾小管的分泌功能","集合管的分泌功能"],"a":2,"e":"远曲小管和集合管对Na+、Cl-和水的重吸收受抗利尿激素和醛固酮等调节，可根据机体水盐平衡状况改变重吸收量，是肾维持水平衡的主要调节部位。"},{"q":"脑桥呼吸调整中枢的主要功能是","o":["限制吸气相的时间","接受迷走神经传入的信息","激活延髓呼吸中枢","形成基本的呼吸节律","抑制吸气切断机制的活动"],"a":0,"e":"呼吸调整中枢位于脑桥上部PBKF核，主要含呼气神经元，作用是限制吸气、促使吸气向呼气转换，从而限制吸气相的时间。切断脑桥上部后吸气延长出现长吸式呼吸，即因失去该限制作用。"},{"q":"对于凝血、抗凝及纤维蛋白溶解的叙述，错误的是","o":["外源性凝血激活途径完全不依靠血浆内的凝血因子","Ca2＋是血液凝固过程不可缺少的离子","许多凝血因子是在肝脏合成的","小血管内已形成的凝血块还可逐渐溶解","纤维蛋白降解产物一般不能再凝固"],"a":0,"e":"外源性凝血途径由血管外组织释放的FⅢ启动，但仍需血浆中的FⅦ、FⅩ、FⅤ、FⅡ等凝血因子参与，并非完全不依靠血浆凝血因子。Ca²⁺为凝血过程必需的辅因子，凝血因子多在肝合成，纤维蛋白降解产物可抑制凝血。"},{"q":"甲状旁腺过度增生或形成腺瘤时会出现下列哪项变化","o":["血磷升高","血钙降低","血钙升高","血钙降低、血磷升高","血钙升高、血磷降低"],"a":4,"e":"甲状旁腺增生或腺瘤使PTH分泌过多，PTH促进肾远曲小管和集合管重吸收钙、抑制近端和远端小管重吸收磷，总效应为升高血钙、降低血磷。故表现为血钙升高、血磷降低。"},{"q":"属于类固醇激素的是","o":["甲状腺素","甲状旁腺素","胰岛素","氢化可的松","生长激素"],"a":3,"e":"氢化可的松即皮质醇，属肾上腺皮质激素，为类固醇激素。甲状腺素、甲状旁腺素、胰岛素和生长激素均为蛋白质或氨基酸衍生物类激素。"},{"q":"在随意运动期间，腱器官提供给中枢神经系统的信息是","o":["肌肉长度的变化","运动的速度","肌肉血液供应情况","肌肉张力的变化","肌肉内的温度变化"],"a":3,"e":"腱器官是感受肌肉张力的感受器，其传入冲动反映肌肉张力的变化，反射效应为抑制牵张反射。肌梭才感受肌肉长度、运动速度和方向的变化。"},{"q":"膜受体的化学本质是","o":["糖类","脂类","蛋白质","核糖核酸","胺类"],"a":2,"e":"膜受体是带有糖链的跨膜蛋白质分子，其化学本质为蛋白质。视紫红质的视蛋白即属G蛋白耦联受体，为典型膜受体蛋白。"},{"q":"心室肌细胞的有效不应期较长，一直要延续到","o":["心室舒张早期","舒张晚期","收缩期开始","整个收缩期","整个舒张期"],"a":0,"e":"心肌细胞有效不应期特别长，相当于整个收缩期和舒张早期，故一直延续到心室舒张早期。此期内任何强度刺激均不能引起兴奋收缩，使心肌不发生完全强直收缩。"},{"q":"维持机体稳态的重要途径是","o":["正反馈调节","负反馈调节","前馈调节","免疫调节","适应性凋节"],"a":1,"e":"负反馈调节使受控部分活动向原活动相反方向改变，将活动恢复到调定点水平，是维持内环境稳态的主要途径，体内绝大多数控制系统属负反馈控制系统。正反馈则使活动不断增强，偏离稳态。"},{"q":"对肾单位的描述不正确的是","o":["是肾脏的基本功能单位","与集合管共同完成肾脏的泌尿功能","可分为皮质肾单位和近髓肾单位","近髓肾单位多于皮质肾单位","近髓肾单位与尿液浓缩和稀释关系大"],"a":3,"e":"皮质肾单位占肾单位总数的85%～90%，近髓肾单位仅占10%～15%，故近髓肾单位多于皮质肾单位的说法错误。肾单位是肾脏的基本功能单位，分皮质和近髓两类，与集合管共同完成泌尿功能。"},{"q":"输血时下列哪一种血型的人最不易找到合适的给血者","o":["O型，Rh阳性","A型，Rh阳性","B型，Rh阳性","AB型，Rh阳性","O型，Rh阴性"],"a":4,"e":"O型血红细胞不含A、B抗原，血清含抗A、抗B抗体，Rh阴性者又缺乏RhD抗原，只能接受O型Rh阴性血，故最难找到合适供血者。Rh阴性者接受Rh阳性血后第二次输血可发生溶血反应。"},{"q":"交感神经节对冠脉循环的影响是","o":["直接引起冠脉舒张","间接引起冠脉收缩","间接引起血流量减少","间接引起血流量增多","导致心肌代谢水平降低"],"a":3,"e":"交感神经兴奋通过增强心肌代谢、代谢产物引起冠脉舒张，间接使冠脉血流量增多。冠脉主要受心肌代谢水平调控，交感神经的直接作用是收缩冠脉。"},{"q":"在机体的排泄途径中，排出的物质种类最多，数量最大的部位是","o":["呼吸道","消化道","肾脏","皮肤汗腺","泪腺"],"a":2,"e":"肾脏是机体最重要的排泄器官，通过尿的生成和排出，排出代谢终产物、过剩物质和异物，排泄物质种类最多、数量最大，并调节水、电解质和酸碱平衡。"},{"q":"受交感和副交感神经双重支配的是","o":["皮肤血管","多数汗腺","皮肤竖毛肌","膀胱逼尿肌","肾上腺髓质"],"a":3,"e":"膀胱逼尿肌和内括约肌受副交感和交感神经双重支配：副交感使逼尿肌收缩、内括约肌舒张促进排尿，交感使逼尿肌松弛、内括约肌收缩。皮肤血管和汗腺主要受交感神经支配。"},{"q":"在缺铁性贫血的实验室检查中，哪项指标最能说明体内储备的铁缺乏","o":["血清铁降低","血清铁蛋白降低","总铁结合力增加","小细胞低色素","转铁蛋白降低"],"a":1,"e":"血清铁蛋白是反映体内储存铁最敏感的指标，其降低最能说明储备铁缺乏。血清铁降低、总铁结合力增加和小细胞低色素为缺铁性贫血的表现，但特异性不及铁蛋白。"},{"q":"自律细胞产生自动节律性兴奋的基础是","o":["4期自动去极化","0期去极化","1期快速复极化","2期缓慢复极化","3期缓慢复极化"],"a":0,"e":"自律细胞以4期自动去极化为特征，是产生自动节律性兴奋的基础。4期自动去极化速度是决定和影响自律性最重要的因素，速度越快自律性越高。"},{"q":"实现胃容受性舒张的途径是","o":["迷走神经","交感神经","壁内神经丛","抑胃肽","促胰液素"],"a":0,"e":"胃容受性舒张通过迷走-迷走反射实现，其迷走神经传出纤维属抑制性纤维，节后纤维释放VIP和NO使胃底、胃体平滑肌舒张。切断迷走神经后该反射消失。"},{"q":"调节降钙素分泌最主要的因素是","o":["血钙浓度","胰高血糖素","缩胆囊素","进食刺激","促胃液素"],"a":0,"e":"血钙浓度是调节降钙素分泌最主要的因素，血钙升高时CT分泌增多，两者共同维持血钙稳态。促胃液素等胃肠激素虽可刺激CT分泌，但属次要因素。"},{"q":"“谈虎色变”是由于","o":["副交感神经兴奋所致","交感神经兴奋所致","第一信号系统的活动所致","第二信号系统的活动所致","非条件反射活动所致"],"a":3,"e":"“谈虎色变”是借助语言、文字等抽象信号形成的条件反射，属第二信号系统活动。第一信号系统是对具体刺激的反应。"},{"q":"窦房结细胞的起搏活动是由于","o":["K+递减性外流","K+递减性内流","K+递减性外流+Na+内流","K+递减性内流+Na+内流","K+递减性外流+Na+内流+Ca2+内流"],"a":4,"e":"窦房结P细胞4期自动去极化由K+外流递减、If通道介导的Na+内流及T型钙通道Ca2+内流共同形成，故起搏活动为三者共同参与。"},{"q":"汗液与血浆成分相比较，正确的是","o":["脂类浓度相等","尿素氮浓度高于血浆","葡萄糖浓度高于血浆","氯化钠浓度低于血浆","氯化钠浓度高于血浆"],"a":3,"e":"汗液为低渗液，汗腺导管重吸收Na+、Cl-而水相对保留，故氯化钠浓度低于血浆。尿素氮、葡萄糖浓度均不高于血浆。"},{"q":"关于糖皮质激素和肾上腺素关系的描述，下列哪一项正确","o":["糖皮质激素促进肾上腺素的合成","糖皮质激素促进肾上腺素的释放","肾上腺素抑制糖皮质激素的合成","肾上腺素抑制糖皮质激素的释放","两者之间没有联系"],"a":0,"e":"糖皮质激素可促进肾上腺髓质嗜铬细胞中苯乙醇胺氮位甲基移位酶（PNMT）的合成，从而促进肾上腺素合成。糖皮质激素并不直接促进其释放。"},{"q":"大脑皮质体表感觉代表区的投射规律是","o":["身体一侧的感觉投射到同侧皮层","下肢代表区在皮层感觉区的底部","中央后回是体表感觉的主要代表区，称第一感觉区","代表区大小与感觉精细程度无关","第一感觉区产生的感觉定位不明确，性质不清晰"],"a":2,"e":"中央后回（3-1-2区）是第一感觉区，为体表感觉的主要代表区。其投射为交叉、倒置（头面部正立），代表区大小与感觉精细程度成正比。"},{"q":"受精的过程不包括下列哪一项","o":["精子通过宫颈、宫体和输卵管","精子进入卵巢","精子获能","顶体反应","精子与卵子融合为合子"],"a":1,"e":"受精包括精子经宫颈、宫腔、输卵管运行至壶腹部、精子获能、顶体反应及精卵融合形成合子。精子不进入卵巢，受精在输卵管壶腹部完成。"},{"q":"关于胰岛素分泌的神经调节，下列描述错误的是哪一项","o":["胰岛受迷走神经与交感神经支配","迷走神经可通过M受体促进胰岛素的分泌","迷走神经可通过刺激胃肠激素释放促进胰岛素分泌","交感神经可通过α受体抑制胰岛素的分泌","交感神经可通过刺激胃肠激素释放抑制胰岛素分泌"],"a":4,"e":"交感神经兴奋释放去甲肾上腺素，主要经β细胞α受体抑制胰岛素分泌，并非通过刺激胃肠激素释放来抑制。迷走神经则经M受体及胃肠激素促进分泌。"},{"q":"大脑皮质体表感觉区中第二感觉区的结构或功能特点是","o":["位于中央后回与岛叶之间","倒置安排","接受双侧投射","不接受痛觉传入信息","感觉定位明确"],"a":2,"e":"第二感觉区接受双侧投射，即一侧皮层代表区与双侧感觉传入有关。第一感觉区位于中央后回，呈倒置安排且定位明确；第二感觉区还接受痛觉传入，定位不明确。"},{"q":"心交感神经活动加强，可引起","o":["心率减慢、传导加速、心肌收缩力减弱","心率加快、传导加速、心肌收缩力减弱","心率减慢、传导减慢、心肌收缩力加强","心率减慢、传导加速、心肌收缩力加强","心率加快、传导加速、心肌收缩力加强"],"a":4,"e":"心交感神经节后纤维释放去甲肾上腺素，作用于心肌β1受体，产生正性变力、正性变时和正性变传导作用，即心率加快、传导加速、心肌收缩力加强。"},{"q":"夜盲症患者，夜晚看不清物体的主要原因是","o":["视蛋白增多","视紫蓝质缺乏","视黄醛增多","视紫红质缺乏","视紫红质过多"],"a":3,"e":"视紫红质由视蛋白和11-顺视黄醛组成，是视杆细胞感受弱光的基础。维生素A摄入不足使视黄醛补充减少，视紫红质合成不足，暗视觉受损而致夜盲症。"},{"q":"关于HCO3-在近端小管重吸收的描述正确的是","o":["与H+的分泌无关","重吸收率约为35%","滞后于Cl-的重吸收","以CO2的形式重吸收","管腔膜对HCO3-的通透性好"],"a":3,"e":"近端小管重吸收HCO3-时，H+经Na+-H+交换分泌入小管液与HCO3-结合成H2CO3，再解离为CO2和水，CO2扩散入细胞，故以CO2形式重吸收。约80%的HCO3-在近端小管重吸收，且优先于Cl-。"},{"q":"对于血小板的聚集起重要作用的物质是","o":["纤维蛋白原","凝血酶","钙离子","ADP与TXA2","钠离子"],"a":3,"e":"ADP与TXA2均可促进血小板聚集，TXA2还有缩血管作用。阿司匹林抑制环氧合酶减少TXA2生成而抗血小板聚集；PGI2作用相反，抑制聚集并舒张血管。"},{"q":"关于糖皮质激素对物质代谢的作用，下列哪一项正确","o":["能对抗胰岛素对血糖的作用","能抑制糖异生，降低血糖","促进肝外组织蛋白质的合成","促进脂肪合成","糖皮质激素分泌过多可致低血糖"],"a":0,"e":"糖皮质激素促进肝糖异生、减少外周组织摄取利用葡萄糖，使血糖升高，具有对抗胰岛素的作用。其还促进肝外蛋白质分解、脂肪重新分布，分泌过多可致血糖升高。"},{"q":"血氧饱和度是指","o":["血氧容量占血氧含量的百分比","血氧含量占血氧容量的百分比","溶解氧量占血氧容量的百分比","溶解氧量占血氧含量的百分比","氧合Hb占Hb总量的百分比"],"a":1,"e":"血氧饱和度指血氧含量与血氧容量的百分比，即Hb氧含量与Hb氧容量的百分比。健康成人动脉血PO2为100mmHg时约为97.5%，静脉血PO2为40mmHg时约为75%。"},{"q":"下列造成心室肌传导阻滞的因素中，错误的是","o":["心肌细胞0期除极速度明显减慢","心肌不应期延长","快钠通道失活","静息电位的绝对值稍增大","动作电位幅度减小"],"a":3,"e":"静息电位绝对值稍增大时，钠通道不易开放，兴奋性降低而非传导阻滞；传导阻滞主要因0期除极速度减慢、动作电位幅度减小、快钠通道失活及不应期延长所致。"},{"q":"下列关于胆汁的描述，正确的是","o":["消化期时只有胆囊胆汁排入小肠","非消化期无胆汁分泌","胆汁中不含脂肪消化酶","胆汁中与消化和吸收有关的成分是胆固醇","胆盐可促进蛋白质的消化和吸收"],"a":2,"e":"胆汁是唯一不含消化酶的消化液，故不含脂肪消化酶。胆汁中与消化吸收有关的主要成分是胆盐，其乳化脂肪促进脂肪消化吸收，而非胆固醇；非消化期肝细胞仍持续分泌胆汁并储存于胆囊。"},{"q":"7次跨膜受体是指","o":["酪氨酸激酶受体","酪氨酸激酶结合型受体","鸟苷酸环化酶受体","G蛋白耦联受体","离子通道型受体"],"a":3,"e":"G蛋白耦联受体的肽链反复跨膜7次，故称7次跨膜受体。酪氨酸激酶受体、鸟苷酸环化酶受体均为单次跨膜，离子通道型受体不属此列。"},{"q":"下列关于食管下括约肌的叙述，正确的是","o":["由环形肌极度增厚形成","食管蠕动波到达时舒张","由骨骼肌构成","由三层平滑肌构成","主要受激素调节"],"a":1,"e":"食管蠕动波到达食管下括约肌时，经迷走神经抑制性纤维释放VIP和NO使其舒张，食团得以通过。该括约肌由平滑肌构成，受神经和体液双重调节，并非环形肌极度增厚形成。"},{"q":"士的宁与破伤风毒素可引起骨骼肌痉挛，其原因是破坏了闰绍细胞功能从而阻断","o":["传入侧支性抑制","回返性抑制","去极化抑制","周围性抑制","突触前抑制"],"a":1,"e":"脊髓前角运动神经元经轴突侧支兴奋闰绍细胞，后者释放甘氨酸抑制该神经元自身，属回返性抑制。士的宁阻断甘氨酸受体、破伤风毒素阻断甘氨酸释放，均使此抑制解除而致痉挛。"},{"q":"平静呼吸过程中胸内压的变化是","o":["吸气时小于大气压，呼气时大于大气压","吸气、呼气时均小于大气压，吸气、呼气末均等于大气压","吸气、呼气时及吸气末、呼气末均小于大气压","吸气时大于大气压，呼气时小于大气压","呼气时比吸气时胸内压更低"],"a":2,"e":"平静呼吸时胸膜腔内压始终低于大气压，吸气末约-6mmHg、呼气末约-2.5mmHg，故吸气、呼气过程及吸气末、呼气末均小于大气压。"},{"q":"心电图P-R间期延长，表示","o":["心房肥大","心房内传导速度减慢","房室交界区传导速度减慢","心室内传导速度减慢","心室肥大"],"a":2,"e":"PR间期代表兴奋经心房、房室交界和房室束到达心室的时间，其延长反映房室交界区传导速度减慢，常见于房室传导阻滞。"},{"q":"脑电图的主要波形，按频率由高到低依次排列为","o":["α-β-θ-δ","β-α-θ-δ","α-β-δ-θ","β-α-δ-θ","δ-θ-β-α"],"a":1,"e":"脑电波频率由高到低为β波（14～30Hz）、α波（8～13Hz）、θ波（4～7Hz）、δ波（0.5～3Hz）。"},{"q":"下列细胞中，吞噬能力最强的是","o":["单核巨噬细胞","中性粒细胞","嗜酸性粒细胞","嗜碱性粒细胞","淋巴细胞"],"a":0,"e":"巨噬细胞体积大、溶酶体丰富，比中性粒细胞有更强的吞噬能力，可吞噬更多、更大的细菌和颗粒，是吞噬能力最强的细胞。"},{"q":"快适应感觉器，即最容易发生适应的感受器是","o":["伤害性感受器","触觉感受器","肺牵张感受器","肌梭","颈动脉窦感受器"],"a":1,"e":"皮肤触觉感受器如环层小体、迈斯纳小体属于快适应感受器，受刺激后仅在短时间内发放传入冲动，随后频率迅速降低甚至消失。痛觉感受器属慢适应感受器，不易发生适应。"},{"q":"从实验大鼠体内取一段小肠，放置于适宜的环境当中，观察到小肠平滑肌仍然进行节律性的收缩和舒张。这种特性属于下列哪一项","o":["有自动节律性","传导性好","有较强的收缩性","兴奋性比较高","伸展性良好"],"a":0,"e":"离体小肠平滑肌在适宜环境中仍能自动进行节律性收缩和舒张，即具有自动节律性。该特性由平滑肌中的起步细胞自发产生节律性兴奋并引发整块平滑肌活动所致。"},{"q":"支配骨骼肌的躯体运动神经释放的递质为","o":["肾上腺素","去甲肾上腺素","儿茶酚胺","多巴胺","乙酰胆碱"],"a":4,"e":"躯体运动神经末梢释放乙酰胆碱，作用于骨骼肌终板膜上的N2型乙酰胆碱能受体阳离子通道，引起终板电位。去甲肾上腺素为多数交感节后纤维释放的递质。"},{"q":"当血钾浓度轻度升高时，心肌的兴奋性将","o":["增大","减小","不变","先增大后减小","先减小后增大"],"a":0,"e":"细胞外K+浓度轻度升高时，膜电位轻度去极化，与阈电位水平靠近，心肌兴奋性升高。仅当血钾明显升高致钠通道失活时兴奋性才降低。"},{"q":"当全身小动脉狭窄时，此时动脉血压的主要表现为","o":["收缩压增高","收缩压降低","收缩压、舒张压均增高，但以舒张压明显","收缩压、舒张压均增高，但以收缩压明显","舒张压降低、收缩压增高"],"a":2,"e":"全身小动脉狭窄使外周阻力增大，舒张期血液外流减慢致舒张压明显升高，收缩压亦升高但幅度较小，故脉压减小。外周阻力以影响舒张压为主。"},{"q":"直接给机体活动提供能量的物质是","o":["磷酸肌酸","ADP","ATP","环磷酸腺苷","葡萄糖"],"a":2,"e":"组织细胞进行各种功能活动所利用的能量由ATP水解直接提供，ATP既是直接供能物质又是能量储存的重要形式。磷酸肌酸是ATP的储存库，葡萄糖须经氧化分解生成ATP才能供能。"},{"q":"下列哪项属于小肠的运动形式","o":["袋状往返运动","容受性舒张","集团蠕动","多袋推进运动","分节运动"],"a":4,"e":"分节运动是小肠特有的运动形式，以环形肌为主的节律性收缩和舒张交替进行，使食糜与消化液充分混合并增加与黏膜接触。袋状往返运动、集团蠕动、多袋推进运动属大肠运动，容受性舒张属胃的运动。"},{"q":"关于促肾上腺皮质激素分泌的调节，下列哪一项正确","o":["受促甲状腺激素释放激素的调节","受糖皮质激素的负反馈调节","受肾上腺素的负反馈调节","受促甲状腺激素的调节","与睡眠无关"],"a":1,"e":"下丘脑CRH促进腺垂体释放ACTH，ACTH促进肾上腺皮质分泌糖皮质激素，糖皮质激素对下丘脑和腺垂体起负反馈调节。ACTH的分泌受CRH调节而非TRH或肾上腺素调节。"},{"q":"当脊髓前角α-运动神经元的传出冲动增加时，可引起","o":["γ-运动神经元的传出冲动增加","梭内肌收缩","肌梭的敏感性增强","梭外肌收缩","梭内肌与梭外肌同时收缩"],"a":3,"e":"α-运动神经元兴奋时其传出冲动直接引起所支配的梭外肌收缩。γ-运动神经元兴奋才引起梭内肌收缩并增强肌梭敏感性，故梭外肌收缩是α传出冲动增加的直接效应。"},{"q":"下列关于前列腺素的描述，哪一项是错误的","o":["前列腺素的前体为花生四烯酸","前列腺素半衰期短，在体内代谢极快","前列腺素属于循环激素，能对全身功能进行调节","前列腺素来源于细胞膜磷脂","前列腺素主要在肺和肝灭活"],"a":2,"e":"前列腺素在局部产生并作用于邻近细胞，主要在肺和肝灭活，半衰期短，属局部激素而非循环激素。其前体为花生四烯酸，来源于细胞膜磷脂。"},{"q":"慢适应感受器的生理意义是","o":["有利于发现高频刺激","有利于感受所有刺激","有利于对某些功能状态进行长期持续的监测","有利于感受新的刺激","有利于机体对新事物的变化作出反应"],"a":2,"e":"慢适应感受器在刺激持续作用时传入冲动频率仅轻微下降并长期维持，有利于对姿势、血压等功能状态进行持久恒定的调节。快适应感受器才有利于发现新刺激。"},{"q":"心动周期中，主动脉压最低见于","o":["等容舒张期末","快速充盈期末","减慢充盈期末","心房收缩期末","等容收缩期末"],"a":4,"e":"等容收缩期室内压急剧升高，当超过主动脉压时半月瓣开放，故主动脉压最低点出现在半月瓣开放前的等容收缩期末。"},{"q":"神经调节的基本方式是","o":["适应","反射","反应","正反馈调节","负反馈调节"],"a":1,"e":"反射是神经调节的基本方式，其结构基础为反射弧。神经调节通过神经反射活动调节机体功能，具有反应迅速、持续时间短、调节精确的特点。"},{"q":"骨骼肌收缩完成后，回收胞内钙离子的钙泵位于","o":["横管","高尔基体膜","肌膜","肌质网膜","线粒体膜"],"a":3,"e":"骨骼肌舒张时胞质Ca2+回收依靠肌质网膜上的钙泵（SERCA）完成，该过程耗能。质膜钙泵分布于肌膜，并非骨骼肌舒张时回收Ca2+的主要部位。"},{"q":"心肌不会产生强直收缩的原因是","o":["心脏是机能上的合胞体","心肌呈“全或无”收缩","心肌的有效不应期特别长","心肌肌浆网不发达，Ca2+贮存少","心肌肌浆网发达，Ca2+贮存多"],"a":2,"e":"心肌细胞有效不应期特别长，相当于整个收缩期和舒张早期，此期内不能再接受刺激产生兴奋和收缩，故心肌不发生完全强直收缩。"},{"q":"心室肌细胞动作电位平台期形成机制主要是下列哪些离子跨膜流动的综合结果","o":["Na+内流，K+外流","Na+内流，Cl-外流","Na+内流，Cl-内流","Ca2+内流，K+外流","K+内流，Na+外流"],"a":3,"e":"心室肌细胞平台期由Ca2+内流与K+外流在时间上几乎相等、相互平衡所致，使膜电位维持于零附近。"},{"q":"可引起氧解离曲线右移的因素是","o":["血液中PCO2增高","血液中PCO2降低","血液中pH值增高","血液中PO2增高","血液中2,3-二磷酸甘油酸减少"],"a":0,"e":"PCO2升高时Hb对O2的亲和力降低，P50增大，氧解离曲线右移。pH升高使曲线左移，2,3-DPG减少亦使曲线左移。"},{"q":"血液中绝大多数的凝血因子合成部位是","o":["脾","肝","肾","骨髓","肺"],"a":1,"e":"除FⅢ外多数凝血因子在肝内合成，FⅡ、FⅦ、FⅨ、FⅩ的生成还需维生素K参与。肝病时可因凝血因子缺乏致凝血时间延长。"},{"q":"在中脑上、下丘之间切断脑干的动物将出现","o":["肢体麻痹","去大脑僵直","脊休克","腱反射加强","动作不精细"],"a":1,"e":"在中脑上、下丘之间切断脑干，中断皮层与脑干网状结构的联系，抑制区活动减弱、易化区占优势，出现去大脑僵直。"},{"q":"神经肌肉接头处的递质是","o":["肾上腺素","去甲肾上腺素","多巴胺","乙酰胆碱","5-羟色胺"],"a":3,"e":"骨骼肌神经肌肉接头由运动神经末梢释放乙酰胆碱，作用于终板膜N2型ACh受体阳离子通道产生终板电位。去甲肾上腺素为多数交感节后纤维递质。"},{"q":"心室肌细胞与浦肯野细胞动作电位的主要区别在于","o":["1期复极化的速度","平台期复极化的机制","3期复极化的机制","4期自动去极化的有无","0期复极化的速度"],"a":3,"e":"心室肌细胞无4期自动去极化，浦肯野细胞具有4期自动去极化而具自律性，这是两者动作电位的主要区别。"},{"q":"第一心音的出现标志着","o":["心室收缩开始","心室舒张开始","心房收缩开始","心房舒张开始","心室射血开始"],"a":0,"e":"第一心音由房室瓣突然关闭引起心室血液和室壁振动产生，标志心室收缩的开始，在心尖搏动处听诊最清楚。"},{"q":"关于经典化学性突触传递的叙述，正确的是","o":["双向传递","不易疲劳","有突触延搁现象","突触后电位不能总和","直接引起突触后膜产生动作电位"],"a":2,"e":"化学突触传递存在中枢延搁，即兴奋通过一个化学突触至少需0.5毫秒。化学突触传递为单向、易疲劳，突触后电位可总和。"},{"q":"细胞一次兴奋后，兴奋性最低的是","o":["绝对不应期","相对不应期","超常期","低常期","局部反应期"],"a":0,"e":"绝对不应期内细胞的兴奋性为零，任何强度刺激均不能引起新的动作电位，是兴奋后兴奋性最低的时期。"},{"q":"关于心肌生物电活动的叙述，正确的是","o":["迷走神经兴奋引起心房肌细胞去极化","交感神经兴奋引起心室肌细胞超极化","细胞外高钠可引起心肌细胞超极化","细胞外高钾可引起心肌细胞去极化","细胞外低钠可引起心肌细胞去极化"],"a":3,"e":"细胞外高钾使膜内外钾浓度差减小，静息电位绝对值减小，即发生去极化。迷走神经兴奋通过乙酰胆碱使心房肌细胞超极化而非去极化。"},{"q":"维生素D3代谢障碍时会出现下列哪些变化","o":["血磷升高","血钙降低","血钙升高","血钙降低、血磷升高","血钙升高、血磷降低"],"a":1,"e":"维生素D3经羟化后促进小肠和肾对钙的吸收，其代谢障碍时钙吸收减少，血钙降低。血磷变化并非其直接特征。"},{"q":"在细胞膜的物质转运中，Na+跨膜转运的方式是","o":["单纯扩散和易化扩散","单纯扩散和主动转运","易化扩散和主动转运","易化扩散和入胞","单纯扩散，易化扩散和主动转运"],"a":2,"e":"Na+顺电化学梯度经通道蛋白跨膜属易化扩散，逆浓度梯度经钠泵转运属主动转运。Na+不通过单纯扩散或入胞方式跨膜。"},{"q":"胆汁中有利胆作用的成分是","o":["胆盐","胆固醇","卵磷脂","胆色素","黏蛋白"],"a":0,"e":"胆盐经肠肝循环返回肝脏后有刺激肝胆汁分泌的作用，称为利胆作用。胆固醇、卵磷脂、胆色素均无此作用。"},{"q":"在心动周期中，房室瓣关闭始于","o":["快速充盈期末","减慢充盈期末","心房收缩期末","等容收缩期末","快速射血期末"],"a":2,"e":"心房收缩期末心室开始收缩，室内压超过房内压，房室瓣关闭。等容收缩期即始于房室瓣关闭而半月瓣尚未开放。"},{"q":"引起组织细胞产生动作电位的单一刺激必须是","o":["物理刺激","化学刺激","电刺激","阈刺激或阈上刺激","生物刺激"],"a":3,"e":"能使细胞产生动作电位的有效刺激为阈刺激或阈上刺激，与刺激性质无关。阈下刺激只能引起局部电位。"},{"q":"在突触传递中，突触后神经元上局部反应发生总和的情况是","o":["EPSP和IPSP都可发生总和","IPSP发生时间总和","EPSP发生时间总和","IPSP发生空间总和","EPSP发生空间总和"],"a":0,"e":"EPSP和IPSP均可发生时间总和与空间总和，同性质叠加、异性质抵消。总合后去极化达阈电位即爆发动作电位。"},{"q":"参与G蛋白耦联信号转导过程的信号蛋白不包括","o":["G蛋白","G蛋白效应器","酪氨酸激酶","第二信使","蛋白激酶"],"a":2,"e":"G蛋白耦联信号转导通路包括G蛋白、G蛋白效应器、第二信使和蛋白激酶。酪氨酸激酶是酪氨酸激酶型受体的胞内结构域成分，不参与该通路。"},{"q":"下列关于唾液分泌调节的描述，正确的是","o":["仅受神经调节","仅受体液调节","条件反射和体液调节同时存在","非条件反射和体液因素同时存在","仅受自身调节"],"a":0,"e":"唾液腺仅受神经调节，进食时引起的反射性唾液分泌是神经调节的典型例子。唾液分泌通过条件反射和非条件反射实现，不存在体液调节途径。"},{"q":"以下属于多个单位平滑肌的是","o":["消化道","虹膜肌","输尿管","子宫","小血管"],"a":1,"e":"多个单位平滑肌主要包括睫状肌、虹膜肌、竖毛肌以及气道和大血管平滑肌，其肌细胞间几乎无缝隙连接，以单个肌细胞为单位活动。消化道、输尿管、子宫属单个单位平滑肌。"},{"q":"维持肾髓质高渗梯度的主要结构是","o":["小叶间动脉","弓形动脉","弓形静脉","网状小血管","直小血管"],"a":4,"e":"直小血管的逆流交换作用使NaCl和尿素滞留于髓质间液而不被血流带走，从而维持肾髓质高渗梯度。该维持能力呈流量依赖，血流量增加会使渗透梯度下降。"},{"q":"关于终板电位的叙述正确的是","o":["是去极化电位","终板电位的大小与ACh的释放量无关","终板电位是由Ca2+内流产生的","有不应期","是全或无的"],"a":0,"e":"终板电位是ACh与终板膜受体结合后引起的去极化电位，其大小与ACh释放量有关，呈等级性而非全或无，无不应期。它由Na+内流产生，而非Ca2+内流。"},{"q":"有关女子基础体温的描述，哪一项是错误的","o":["随雌激素水平波动而变化","随孕激素及其代谢产物的变化而波动","在排卵前短暂降低","排卵后升高0、5℃左右","基础体温改变可作为判定排卵期的标志之一"],"a":0,"e":"基础体温随孕激素水平波动，排卵后孕激素升高使基础体温升高0.2～0.5℃，排卵前短暂降低，双相变化可判断排卵。基础体温不随雌激素水平波动而变化。"},{"q":"安静状态下，紧张性活动起主导作用的神经纤维是","o":["心交感神经","心迷走神经","交感舒血管神经","副交感舒血管神经","脊髓背根舒血管纤维"],"a":1,"e":"安静状态下心迷走神经紧张性活动占优势，对心脏起抑制作用，切断心迷走神经后心率加快。心交感与心迷走紧张相互拮抗，共同调节心脏活动。"},{"q":"关于肺顺应性的叙述，错误的是","o":["与非弹性阻力呈正变关系","容易扩张的肺，顺应性大","可用单位压力引起的容积变化来衡量","表示在外力作用下肺的可扩展性","与弹性阻力呈反变关系"],"a":0,"e":"肺顺应性是弹性阻力的倒数，两者呈反变关系；顺应性大表示肺易扩张。非弹性阻力属动态阻力，与顺应性无正变关系。"},{"q":"慢性肺心病病人体内长时间低O2和CO2潴留，这种病人呼吸中枢兴奋性的维持主要依靠","o":["高CO2刺激外周化学感受器","高CO2刺激中枢化学感受器","缺O2刺激外周化学感受器","缺O2刺激中枢化学感受器","缺O2直接刺激呼吸中枢"],"a":2,"e":"长时间CO2潴留使中枢化学感受器对CO2刺激发生适应，而外周化学感受器对低O2刺激适应很慢，故低O2刺激外周化学感受器成为驱动慢性肺心病患者呼吸的主要因素。"},{"q":"副交感神经系统兴奋所引起的机体变化不包括","o":["支气管平滑肌舒张","心跳减慢","促进胃肠运动","促进消化液分泌","促进胰岛素分泌"],"a":0,"e":"副交感神经末梢释放ACh作用于气道平滑肌M受体，使支气管平滑肌收缩、气道阻力增加，故支气管平滑肌舒张不属于其兴奋效应。副交感兴奋使心率减慢、胃肠运动增强、消化液分泌增多并促进胰岛素分泌。"},{"q":"原尿和血浆相比较，在成分上不同的是","o":["K+含量","蛋白质含量","葡萄糖含量","Na+含量","酸碱物质含量"],"a":1,"e":"原尿是血浆经肾小球滤过膜滤过形成的，大分子蛋白质不能滤过，故原尿中蛋白质含量极微，与血浆明显不同。两者K+、葡萄糖、Na+及酸碱物质含量基本一致。"},{"q":"血浆晶体渗透压降低时可引起","o":["组织液减少","组织液增加","红细胞萎缩","红细胞膨胀和破裂","尿量减少"],"a":3,"e":"血浆晶体渗透压降低时，水向红细胞内转移，红细胞膨胀甚至破裂。晶体渗透压主要维持细胞内外水平衡，其降低使组织液生成增多而非减少，尿量增多而非减少。"},{"q":"心肌细胞分为快反应细胞和慢反应细胞的主要依据是","o":["0期去极化的速率","平台期的长短","动作电位复极化的速度","4期自动去极化快慢","3期自动复极化速度"],"a":0,"e":"快反应细胞0期去极化由快钠通道介导，慢反应细胞0期由慢钙通道介导，故0期去极化速率是区分二者的主要依据。0期去极化速度和幅度也是决定心肌传导速度最重要的因素。"},{"q":"血管损伤后止血栓能正确定位于损伤部位有赖于血小板的哪项特征","o":["黏附","聚集","收缩","吸附","释放"],"a":0,"e":"血小板黏附需GPⅠb/Ⅸ/Ⅴ复合物、内皮下胶原和vWF参与，通过黏附识别损伤部位，使止血栓正确定位于损伤处。聚集是血小板彼此黏着，不负责定位。"},{"q":"心肌等长调节主要是改变了下列哪一因素","o":["心室舒张末期压力","心肌收缩能力","肌小节长度","主动脉血压","心力储备"],"a":1,"e":"心肌收缩能力是不依赖前负荷和后负荷而改变心肌力学活动的内在特性，通过改变心肌收缩能力调节泵血功能称为等长调节。前负荷改变肌小节长度，后负荷主要影响射血阻力。"},{"q":"根据神经纤维兴奋传导速度对其进行的分类中，自主神经节前纤维属于哪一类","o":["Ａα","Ａβ","Ａγ","B","Ｃ"],"a":3,"e":"自主神经节前纤维为有髓鞘的B类纤维，传导速度3～15m/s。A类为有髓鞘的躯体传入和传出纤维，C类为无髓鞘纤维。"},{"q":"维持躯体姿势的最基本反射是","o":["翻正反射","肌紧张","腱反射","屈肌反射","交叉伸反射"],"a":1,"e":"肌紧张是缓慢持续牵拉肌腱时发生的牵张反射，为多突触反射，是维持身体姿势最基本的反射活动，也是随意运动的基础。腱反射为单突触反射，翻正反射和交叉伸反射属复杂姿势反射。"},{"q":"下列叙述中，哪一项是条件反射的特点","o":["先天遗传而获得","后天训练而建立","种族共有的反射","是一种初级的神经活动","反射弧固定不变"],"a":1,"e":"条件反射是在非条件反射基础上通过后天学习和训练形成的反射，其类型和数量无定数，可建立也能消退。先天遗传、种族共有、反射弧固定均属非条件反射的特征。"},{"q":"关于用力呼吸的描述，错误的是","o":["吸气时有辅助吸气肌参加活动","呼气和吸气都是主动的","呼气时有胸锁乳突肌参加收缩","用力呼吸使潮气量加大","用力呼吸时，肺内压变动程度增大"],"a":2,"e":"胸锁乳突肌和斜角肌是辅助吸气肌，只在用力吸气时收缩，用力呼气时收缩的是腹肌等呼气肌。用力呼吸时吸气与呼气均为主动过程，潮气量加大，肺内压变动幅度增大。"},{"q":"关于微终板电位的叙述，正确的是","o":["表现“全或无”特性","有不应期","是个别囊泡的自发释放在终板膜上引起的微小的电变化","是大量囊泡的自发释放在终板膜上引起的较大的电变化","是神经末梢单个动作电位引起的终板膜上的电变化"],"a":2,"e":"微终板电位是静息时单个囊泡自发释放ACh引起的终板膜微弱去极化，频率约1次/s。它属局部电位，无全或无特性和不应期；一次动作电位引发约125个囊泡释放产生的是终板电位。"},{"q":"机体各种功能活动释放的能量中，最终不能转化为热能的是","o":["心脏泵血并推动血液流动","细胞合成各种功能蛋白质","兴奋在神经纤维上传导","肌肉收缩对外界物质做功","内、外分泌腺体的活动"],"a":3,"e":"肌肉收缩对外界物体做功时，部分能量转化为机械外功，其余仍转为热能。心脏泵血、神经传导、腺体分泌及蛋白质合成所利用的能量最终均转变为热能。"},{"q":"心室功能曲线反映下列哪种关系","o":["心率和心输出量","心率和搏功","搏功和心室充盈压","搏功和心输出量","心室充盈压和心率"],"a":2,"e":"心室功能曲线以心室舒张期末压力（心室充盈压）为横坐标、每搏功或搏出量为纵坐标绘制，反映前负荷与心肌收缩力的关系。"},{"q":"下列关于激素的生理作用描述，哪一项不正确","o":["调节新陈代谢、维持内环境稳态","促进细胞的增殖与分化","影响神经系统的发育和功能","促进生殖器官的发育成熟","营养作用"],"a":4,"e":"激素的生理作用包括调节新陈代谢、促进细胞增殖分化、影响神经系统发育和功能、促进生殖器官发育成熟。营养作用属于胃肠激素和神经的作用范畴，不是激素的普遍生理作用。"},{"q":"肾脏近端小管进行重吸收的特点是","o":["重吸收的物质种类少","各种物质的重吸收量少","受到体液因素调节","主要受神经因素调节","小管液与上皮细胞内液保持等渗"],"a":4,"e":"近端小管对水和溶质按比例重吸收，属等渗性重吸收，小管液保持等渗。其重吸收物质种类多、量大，且不受神经和体液因素调节。"},{"q":"糖皮质激素的作用是下列哪一项","o":["抑制糖原分解","使血糖浓度升高","使肾脏排水能力降低","促进黏蛋白合成","使红细胞数量减少"],"a":1,"e":"糖皮质激素促进糖异生、减少外周组织对葡萄糖的利用，使血糖浓度升高。它还能促进黏蛋白合成、使红细胞增多，并增加肾排水能力。"},{"q":"儿茶酚胺可调节心肌生物电活动，对其作用机制描述正确的是","o":["加强浦肯野细胞4期内向电流If","复极化2期Ca2+内流减慢","慢反应细胞0期Ca2+内流减慢","窦房结细胞4期自动去极速度加快","快反应细胞动作电位上升速度减慢"],"a":3,"e":"儿茶酚胺通过β受体使窦房结P细胞T型钙通道开放概率增加，4期Ca2+内流增加，自动去极化速度加快，自律性升高。"},{"q":"在下列关于肌紧张的描述中，错误的是","o":["屈肌的肌紧张表现明显","主要的生理意义是维持站立姿势","肌紧张的反射中枢在脊髓","肌紧张的感受器是肌梭","脑干网状结构中有肌紧张的易化区"],"a":0,"e":"肌紧张是缓慢持续牵拉肌腱时发生的牵张反射，效应器以慢肌纤维为主，表现为受牵拉肌肉持续轻度收缩，屈肌与伸肌均存在，并非屈肌表现明显。"},{"q":"下列关于曲张体的叙述，错误的是","o":["为神经与效应器发生联系的部位","内含贮存递质的小泡","只存在于肾上腺素能神经末梢","为神经末梢的结节状装置","为非定向突触"],"a":2,"e":"曲张体是神经末梢的结节状膨大，内含贮存递质的小泡，通过非定向突触与效应器联系；肾上腺素能纤维和胆碱能纤维末梢均可存在曲张体。"},{"q":"与葡萄糖耦联转运的离子是","o":["Na+","K+","C1-","Ca2+","Fe2+"],"a":0,"e":"肠黏膜刷状缘的SGLT-1与2个Na+和1分子葡萄糖结合，属继发性主动转运；近端小管葡萄糖重吸收同样由Na+-葡萄糖耦联转运体完成。"},{"q":"在动物实验中，暂时夹闭家兔一侧颈总动脉可引起","o":["心率减慢","心肌收缩力减弱","外周血管收缩","心交感神经活动减弱","心迷走神经活动增强"],"a":2,"e":"夹闭颈总动脉使颈动脉窦压力感受器传入减少，压力感受性反射减弱，交感神经活动增强，外周血管收缩、心率加快、血压升高。"},{"q":"下列能引起胰液分泌减少的因素是","o":["胃酸","蛋白质分解产物","促胃液素","促胰液素","胰多肽"],"a":4,"e":"胰多肽属抑制性胃肠激素，可抑制胰液分泌；胃酸、蛋白质分解产物、促胃液素和促胰液素均促进胰液分泌。"},{"q":"下列关于甲状腺激素合成的描述，哪一项是错误的","o":["合成甲状腺激素的原料是碘和甲状腺球蛋白","T4的数量多于T3","甲状腺激素有结合型和游离型两种运输形式","甲状腺腺泡上皮摄碘的过程是被动转运","抑制甲状腺过氧化酶可抑制甲状腺激素的合成"],"a":3,"e":"甲状腺滤泡上皮细胞聚碘是逆电-化学梯度的主动转运，细胞内I-浓度约为血浆30倍，故摄碘并非被动转运。"},{"q":"判断组织兴奋性高低最常用的简便指标是","o":["阈电位","时值","阈强度","强度-时间变化率","刺激的频率"],"a":2,"e":"阈强度是引起组织产生反应的最小刺激强度，阈值越小兴奋性越高，故常用阈强度衡量组织兴奋性高低。"},{"q":"具有“全或无”特征的电信号是","o":["终板电位","感受器电位","兴奋性突触后电位","抑制性突触后电位","动作电位"],"a":4,"e":"动作电位具有“全或无”特征，其幅度由钠通道性状和Na+驱动力决定，不随刺激强度改变。终板电位、感受器电位及突触后电位均属局部电位，呈等级性，可总和。"},{"q":"最能反映血液中红细胞数量相对值的是","o":["血液比重","血液黏滞性","血细胞比容","血液渗透压","血红蛋白含量"],"a":2,"e":"血细胞比容指血细胞占血液容积的百分比，因白细胞和血小板仅占0.15%～1%，故可反映红细胞相对浓度。血液比重和黏滞度还受血浆蛋白等因素影响。"},{"q":"胃大部分切除的患者出现贫血的主要原因是","o":["壁细胞减少","黏液减少","维生素B12吸收减少","碳酸氢盐减少","胃蛋白酶活性减弱"],"a":2,"e":"壁细胞分泌内因子，胃大部切除后内因子不足，维生素B12在回肠吸收障碍，导致巨幼细胞贫血。内因子-维生素B12复合物保护维生素B12并促其吸收。"},{"q":"以下哪项不属于细胞膜蛋白质的功能","o":["作为转运蛋白参与物质转运","作为离子通道参与物质转运","作为抗原决定簇","参与信息传递","作为ATP酶，分解ATP"],"a":2,"e":"细胞膜蛋白可作转运蛋白、离子通道、受体及酶参与物质转运、信息传递和ATP分解。抗原决定簇由膜上糖蛋白或糖脂的寡糖链构成，属糖类功能。"},{"q":"下列有关同一细胞兴奋传导的叙述，哪项是错误的","o":["动作电位可沿细胞膜传导到整个细胞","传导方式是通过产生局部电流刺激未兴奋部位，使之也出现动作电位","在有髓纤维是跳跃传导","有髓纤维传导动作电位的速度比无髓纤维快","动作电位的幅度随传导距离增加而减小"],"a":4,"e":"动作电位在同一细胞传导是膜依次产生动作电位的过程，其幅度不随传导距离衰减，呈“全或无”。有髓纤维经郎飞结跳跃传导，速度较无髓纤维快。"},{"q":"神经中枢内有抑制活动，其中突触后抑制的形成是由于","o":["突触前膜释放的神经递质减少","抑制一个兴奋性中间神经元","兴奋一个抑制性中间神经元","中间神经元末梢释放的递质减少","突触后膜产生的EPSP减小"],"a":2,"e":"突触后抑制由抑制性中间神经元兴奋、末梢释放抑制性递质引起，使突触后膜Cl-通道开放产生IPSP。传入侧支抑制和回返性抑制均属此类。"},{"q":"室性期前收缩之后出现代偿间歇的原因是","o":["窦房结的兴奋延迟发放","窦房结的兴奋少发放一次","室性期前收缩有效不应期特别长","窦房结的兴奋落在期前收缩的有效不应期内","窦房结的兴奋提前发放"],"a":3,"e":"期前收缩有自身有效不应期，紧接其后的窦房结兴奋若落在该不应期内则不能引起心室兴奋，出现脱失，形成代偿间歇。"},{"q":"大脑皮质的本体感觉代表区位于","o":["第二感觉区","颞叶皮质","运动辅助区","中央前回","中央后回"],"a":3,"e":"本体感觉的皮层代表区即运动区，位于中央前回（4区），接受本体感觉冲动并调控躯体运动。中央后回为第一感觉区。"},{"q":"在细胞膜脂质成分中，几乎全部分布在膜的内侧并与第二信使DC和IP3的产生有关的是","o":["磷脂酰胆碱","鞘酯","磷脂酰乙醇胺","磷脂酰丝氨酸","磷脂酰肌醇"],"a":4,"e":"磷脂酰肌醇含量虽少，但主要分布于膜内侧，是IP3和二酰甘油的供体，参与跨膜信号转导。磷脂酰胆碱则主要分布于膜外层。"},{"q":"微循环中与体温调节有关的关键组成部分是","o":["后微动脉","通血毛细血管","毛细血管前括约肌","真毛细血管","动-静脉吻合支"],"a":4,"e":"动-静脉吻合支管壁较厚、血流快、无物质交换功能，属非营养通路，其开放与关闭参与体温调节。真毛细血管是物质交换的主要场所。"},{"q":"快反应自律细胞是","o":["心房肌细胞","窦房结细胞","心室肌细胞","浦肯野氏细胞","房室结细胞"],"a":3,"e":"浦肯野细胞兴奋时产生快反应动作电位，且具有4期自动去极化，属快反应自律细胞。窦房结、房室结细胞为慢反应自律细胞。"},{"q":"鼓膜温度可用来检测脑内温度，其数值最接近下列哪个部位的温度","o":["大脑","小脑","中脑","下丘脑","延髓"],"a":3,"e":"鼓膜温度与下丘脑温度十分接近，可反映脑组织温度，故临床用鼓膜温度代表体核温度。"},{"q":"纤维蛋白降解产物的主要作用是","o":["促进凝血酶的活性","防止血小板的激活","对抗血液凝固","促进纤维蛋白单体聚合","抑制纤维蛋白溶解"],"a":2,"e":"纤维蛋白降解产物通常不再发生凝固，其中部分小肽还具有抗凝血作用，故其作用是抗凝血。纤溶酶才是降解纤维蛋白的蛋白酶。"},{"q":"影响神经系统发育的最重要的激素是","o":["糖皮质激素","生长激素","盐皮质激素","肾上腺素","甲状腺激素"],"a":4,"e":"甲状腺激素广泛调节机体生长发育和新陈代谢，是影响神经系统发育最重要的激素，胚胎期缺乏可致呆小症。生长激素主要促进躯体生长。"},{"q":"用直流电刺激神经干，通电时的兴奋是发生在","o":["阴极下方","阳极下方","阴极下方或阳极下方均可","阴极或阳极之间","阴极或阳极以外的地方"],"a":0,"e":"负电极下方细胞膜产生去极化电紧张电位，使膜电位接近阈电位，故通电时兴奋发生在阴极下方；阳极下方为超极化。"},{"q":"关于雄激素的描述，下列哪一项是正确的","o":["是含氮类激素","以双氢睾酮分泌量最多","游离的雄激素不能发挥生物学作用","主要在肾脏灭活","是雌二醇前体"],"a":4,"e":"雄激素在芳香化酶作用下可转变为雌二醇，故为雌二醇前体。睾酮是分泌量最多的雄激素，并非双氢睾酮。"},{"q":"一次大量饮清水后，尿量增多的主要原因是","o":["血压升高","血浆胶体渗透压降低","肾小球毛细血管血压升高","血浆晶体渗透压降低","循环血量增加"],"a":3,"e":"大量饮清水使血浆晶体渗透压降低，抑制抗利尿激素释放，集合管对水重吸收减少，尿量增多。血浆胶体渗透压降低并非水利尿的机制。"},{"q":"在脊髓作为反射中枢的反射活动中，不包括","o":["屈肌反射","腱反射","血管张力反射","排尿反射","翻正反射"],"a":4,"e":"翻正反射由脑干参与完成，不属于以脊髓为中枢的反射。屈肌反射、腱反射、血管张力反射和排尿反射的基本中枢均在脊髓。"},{"q":"下列关于胰岛素的描述，哪项是错误的","o":["促进糖原合成","促进糖的贮存和利用，使血糖降低","促进脂肪和蛋白质的分解和利用","是维持正常代谢和生长所不可缺少的重要激素之一","缺乏时血糖升高，可形成糖尿病"],"a":2,"e":"胰岛素促进脂肪和蛋白质的合成与储存，抑制其分解，故该描述错误。胰岛素促进糖原合成、加速葡萄糖利用而降低血糖，缺乏时血糖升高可致糖尿病。"},{"q":"十二指肠内容物返流入胃对黏膜屏障有破坏作用的物质是","o":["碳酸氢盐","高渗溶液","胆汁酸","黏蛋白","氨基酸"],"a":2,"e":"胆汁酸为脂溶性物质，反流入胃可破坏胃黏膜屏障。碳酸氢盐和黏蛋白对黏膜有保护作用。"},{"q":"对长期大量用糖皮质激素治疗疾病的患者，下列哪一项分析不正确","o":["患者可表现出向心性肥胖","患者血液皮质激素水平较高","患者血液中促肾上腺皮质激素水平较高","患者肾上腺皮质束状带萎缩","所治的疾病痊愈后不应突然停药"],"a":2,"e":"长期大量应用糖皮质激素通过负反馈抑制腺垂体，使促肾上腺皮质激素分泌减少，血中水平降低而非升高。同时肾上腺皮质束状带萎缩，故不可突然停药。"},{"q":"下述关于超速压抑的描述，不正确的是","o":["高频起搏点驱使低频起搏点跟随低频率起搏点搏动","频率差别越大，抑制效应越强","窦房结停搏后，首先由受压抑程度较小的房室交界起搏","窦房结对心室的控制中断后，可出现一段时间的心室停搏","为避免撤去超速抑制时诱发的心脏停搏，中断人工起搏器时应逐步减慢其驱动频率"],"a":0,"e":"超速驱动阻抑是高频起搏点驱动并抑制低频起搏点，使其跟随高频节律搏动，而非跟随低频起搏点。频率差值越大抑制越强，驱动中断后可出现一段时间停搏。"},{"q":"关于Rh血型的下列叙述，正确的是","o":["汉族人群中Rh阴性率为90%","抗Rh抗体是不完全抗体","血浆抗Rh因子为天然抗体","Rh阴性者的血液不可输给Rh阳性者","红细胞表面没有D抗原者为Rh阳性"],"a":1,"e":"抗Rh抗体为免疫性不完全抗体，需经Rh阳性红细胞免疫后产生。汉族人群Rh阴性率约1%，血清中无天然抗Rh抗体，红细胞无D抗原者为Rh阴性。"},{"q":"下列关于缺O2对呼吸影响的叙述，正确的是","o":["直接兴奋延髓呼吸中枢","直接兴奋脑桥呼吸中枢","严重缺O2时呼吸加深加快","轻度缺O2时呼吸加深加快","对呼吸有抑制作用"],"a":3,"e":"轻度缺O2通过兴奋外周化学感受器反射性使呼吸加深加快。低O2对呼吸中枢的直接作用是抑制，严重缺O2时反射效应不足以克服抑制，呼吸减弱。"},{"q":"中枢化学感受器最敏感的刺激物是","o":["血液中的[H+]","脑脊液中的[H+]","血液中的[CO2]","脑脊液中的[CO2]","脑脊液中［O2］"],"a":1,"e":"脑脊液中的H+是中枢化学感受器最有效的刺激物，其敏感性约为外周化学感受器的25倍。血液中H+不易通过血-脑屏障，对中枢化学感受器的直接作用不大；CO2需先转变为H+才能起作用。"},{"q":"不影响心肌细胞自律性的因素是","o":["最大复极电位","阈电位","有效不应期","4期自动去极速度","最大复极电位与阈电位差距"],"a":2,"e":"心肌细胞自律性取决于4期自动去极速度、最大复极电位与阈电位的差距，有效不应期不影响自律性。有效不应期反映兴奋后兴奋性的周期性变化，与自动去极无关。"},{"q":"下列关于应激反应的描述，哪一项是正确的","o":["促肾上腺皮质激素浓度降低","糖皮质激素浓度降低","儿茶酚胺含量降低","对有害刺激的抵抗力提高","是一种特异性反应"],"a":3,"e":"应激反应是机体受到有害刺激时以交感-肾上腺髓质和下丘脑-垂体-肾上腺皮质轴活动增强为主的非特异性反应，可提高对有害刺激的耐受力和抵抗力。应激时促肾上腺皮质激素、糖皮质激素和儿茶酚胺均升高。"},{"q":"决定细胞在单位时间内能够产生兴奋的最多次数是","o":["绝对不应期","相对不应期","超常期","恢复期","低常期"],"a":0,"e":"绝对不应期内细胞对任何强度刺激均不能产生新的兴奋，故单位时间内产生兴奋的最多次数取决于绝对不应期的长短。神经细胞绝对不应期约2ms，动作电位最大频率不超过每秒500次。"},{"q":"安静时，散发热量最多的方式是","o":["辐射","传导","对流","蒸发","加温吸入气体"],"a":0,"e":"安静状态下环境温度低于皮肤温度时，大部分体热以辐射方式发散，裸体处于21℃环境中约60%的热量经辐射散发。蒸发仅在环境温度等于或高于皮肤温度时成为唯一有效的散热方式。"},{"q":"盆神经兴奋时，将引起","o":["膀胱逼尿肌收缩","膀胱逼尿肌舒张","尿道内括约肌收缩","尿道外括约肌收缩","尿道外括约肌舒张"],"a":0,"e":"盆神经为副交感神经，其节后纤维释放乙酰胆碱，激活膀胱逼尿肌M受体，使逼尿肌收缩、尿道内括约肌舒张，促进排尿。交感神经才使逼尿肌松弛、内括约肌收缩。"},{"q":"影响正常人舒张压的主要因素是","o":["大动脉弹性","心输出量","阻力血管的口径","血液的黏滞性","血管长度"],"a":2,"e":"舒张压主要反映外周阻力，而外周阻力取决于阻力血管（小动脉和微动脉）的口径，故阻力血管口径是影响正常人舒张压的主要因素。大动脉弹性主要影响脉压。"},{"q":"机体缺氧、PCO2升高，以及使用麻醉剂等药物的情况下，神经中枢内最易受到影响的功能是","o":["神经元兴奋","神经冲动传导","神经胶质细胞绝缘作用","突触传递","血管壁扩散距离"],"a":3,"e":"突触间隙与细胞外液相通，缺氧、CO2分压升高、麻醉剂及某些药物等内环境理化因素变化最易影响化学突触传递。神经冲动传导在神经纤维上相对不易受这些因素影响。"},{"q":"进行腹式呼吸的吸气时，下述哪块肌肉收缩为主","o":["肋间外肌","腹直肌","肋间内肌","膈肌","斜角肌"],"a":3,"e":"腹式呼吸以膈肌舒缩活动为主，膈肌收缩使腹腔器官位移、腹部起伏，故吸气时以膈肌收缩为主。肋间外肌是胸式呼吸的主要吸气肌。"},{"q":"引起促胰液素释放的因素由强至弱的排列顺序为","o":["脂酸钠、蛋白质分解产物、盐酸","蛋白质分解产物、脂酸钠、盐酸","盐酸、脂酸钠、蛋白质分解产物","盐酸、蛋白质分解产物、脂酸钠","蛋白质分解产物、盐酸、脂酸钠"],"a":3,"e":"盐酸是刺激促胰液素释放的最强因素，其次为蛋白质分解产物和脂酸钠，糖类几乎无刺激作用。故由强至弱为盐酸、蛋白质分解产物、脂酸钠。"},{"q":"下列关于IPSP产生过程的叙述，错误的是","o":["突触前膜去极化，Ca2+进入突触前膜内","K+内流突触后膜去极化产生IPSP","释放抑制性递质","突触后膜对Cl-、K+通透性增强","囊泡与前膜融合破裂"],"a":1,"e":"IPSP是突触后膜超极化电位，由Cl-内流和K+外流引起，而非K+内流去极化。抑制性递质释放后使突触后膜对Cl-、K+通透性增强，产生超极化。"},{"q":"记录神经纤维动作电位时，加入选择性离子通道阻断剂河鲀毒素，会出现什么结果","o":["静息电位变小","静息电位变大","去极相不出现","超射不出现","以上都不正确"],"a":2,"e":"河鲀毒素特异性阻断电压门控钠通道，使Na+内流消失，动作电位的快速去极相不能产生。静息电位主要由K+平衡电位决定，不受影响。"},{"q":"下列可以使氧解离曲线左移的是","o":["血液PCO2降低","血液H+浓度升高","温度升高","血液PCO2升高","红细胞中2,3-DPG浓度升高"],"a":0,"e":"血液PCO2降低或pH升高时，Hb对O2亲和力增大，氧解离曲线左移。PCO2升高、H+浓度升高、温度升高及2,3-DPG增多均使曲线右移。"},{"q":"乙酰胆碱通过增加心肌细胞膜上通道的通透性而影响心肌细胞的电活动，不能引起下列哪种生理变化","o":["阈电位绝对值增大","动作电位时程缩短","静息电位绝对值增大","窦房结细胞4期自动去极速度减慢","膜对钾离子的通透性增加"],"a":0,"e":"乙酰胆碱增加心肌细胞膜对K+的通透性，使静息电位或最大复极电位绝对值增大、窦房结4期自动去极减慢、动作电位时程缩短。阈电位水平并不因此改变。"},{"q":"下列哪个是人体内最大、最复杂的内分泌器官","o":["甲状腺","肾上腺","消化道","卵巢","下丘脑"],"a":2,"e":"消化道黏膜层内存在40多种内分泌细胞，总数远超其他内分泌器官，故消化道是体内最大、最复杂的内分泌器官。"},{"q":"空腹时，大肠最常见的运动形式是","o":["集团蠕动","分节运动","紧张性收缩","袋状往返运动","多袋推进运动"],"a":3,"e":"袋状往返运动由环行肌无规律收缩引起，是空腹和安静时最常见的大肠运动形式，使内容物短距离往返位移而不向前推进。"},{"q":"心交感与心迷走神经节前纤维末梢释放的递质是","o":["乙酰胆碱","去甲肾上腺素","肾上腺素","多巴胺","5-羟色胺"],"a":0,"e":"心交感与心迷走神经的节前纤维均属自主神经节前纤维，末梢释放乙酰胆碱作用于节后神经元N1受体。去甲肾上腺素为心交感节后纤维释放的递质。"},{"q":"决定心室肌细胞0期去极速度的因素是","o":["Na+通道开放速度","Na+通道失活的速度","Na+通道复活速度","Na+-K+泵活性","Na+-Ca2+泵活性"],"a":0,"e":"快反应细胞0期去极由钠通道快速开放、Na+内流形成，钠通道开放速度决定0期最大去极化速度。钠通道复活速度影响期后兴奋性恢复，而非0期去极速度。"},{"q":"肺的弹性回缩力见于","o":["吸气初","呼气初","呼气末","吸气末","整个呼吸过程中"],"a":4,"e":"肺始终处于扩张状态，肺弹性回缩力一直存在，是吸气的阻力、呼气的动力，故整个呼吸过程中均存在。"},{"q":"轻触眼角膜引起眨眼动作，该调节方式属于","o":["神经反射","神经体液调节","激素远距分泌","旁分泌","自身调节"],"a":0,"e":"轻触角膜引起眨眼属神经反射，为神经系统参与下通过反射活动完成的调节，反应迅速、精确。该过程无体液因素参与。"},{"q":"高血压患者与正常人相比，下列指标明显增高的是","o":["每搏输出量","心输出量","心脏做功量","心指数","射血分数"],"a":2,"e":"动脉血压升高时射血阻力增大，心肌须加强收缩才能维持搏出量，心脏做功量必定增加。此时每搏输出量、心输出量、射血分数可无明显变化。"},{"q":"在牵张反射活动中，肌梭的传入神经纤维有","o":["Ⅲ和Ⅳ类纤维","Ⅰa和Ⅱ类纤维","Ⅰa和Ⅰb纤维","Ⅰ和Ⅱ类纤维","Ⅱ和Ⅲ类纤维"],"a":1,"e":"肌梭的传入神经纤维为Ⅰa和Ⅱ类纤维，Ⅰa类纤维传入冲动引起支配同一肌肉的α运动神经元兴奋，形成牵张反射。Ⅰb类纤维来自腱器官。"},{"q":"有关静息电位的叙述，哪项是错误的","o":["由K+外流所致，相当于K+的平衡电位","膜内电位较膜外为负","各种细胞的静息电位数值是不相同的","是指细胞安静时膜内外两侧的电位差","由Na+外流所致，相当于Na+的平衡电位"],"a":4,"e":"静息电位主要由K+外流形成，接近K+平衡电位；Na+内流部分抵消K+外流，使实测值略低于K+平衡电位。Na+内流而非外流，故E项错误。"},{"q":"下列关于肾素-血管紧张素系统（RAS）功能的叙述，正确的是","o":["仅对血压进行调节","主要实现对动脉血压的短期调节","仅存在全身性的体液调节作用","失血可导致该系统活动抑制","功能异常与高血压的发病有关"],"a":4,"e":"RAS不仅调节血压，还参与水盐平衡及组织重构，功能异常与高血压发病密切相关。失血时RAS活动增强，且其作用并非仅限于短期调节血压。"},{"q":"细肌丝组成中含量最高的蛋白类型是","o":["肌动蛋白","原肌球蛋白","肌球蛋白","肌钙蛋白","肌纤蛋白"],"a":0,"e":"细肌丝中肌动蛋白、原肌球蛋白和肌钙蛋白的比例为7∶1∶1，肌动蛋白含量最高，并聚合为双螺旋构成细肌丝主干。肌球蛋白是粗肌丝的组成蛋白。"},{"q":"由下丘脑视上核和室旁核合成的缩血管物质是","o":["血管紧张素","血管升压素","内皮素","去甲肾上腺素","5-羟色胺"],"a":1,"e":"血管升压素由下丘脑视上核和室旁核神经元合成，经下丘脑-垂体束运至神经垂体储存并释放，属缩血管物质。血管紧张素Ⅱ虽可收缩血管，但并非由视上核和室旁核合成。"},{"q":"为心室肌细胞动作电位4期逆浓度梯度外运提供能量的是","o":["Cl-泵","Ca2+泵","Na+泵","浓度梯度","K+泵"],"a":2,"e":"心室肌细胞4期通过钠泵逆浓度梯度将Na+外运、K+内运，维持跨膜离子梯度，其活动需ATP供能。钠泵建立的Na+梯度是继发性主动转运的基础。"},{"q":"切断动物双侧迷走神经后会出现","o":["呼吸频率加快","呼气幅度减小","吸气相缩短","呼气相延长","呼吸频率减慢，幅度增大"],"a":4,"e":"切断双侧迷走神经后，肺牵张反射的传入中断，吸气向呼气的转换减慢，故吸气延长加深，呼吸变得深而慢，即频率减慢、幅度增大。"},{"q":"下列关于唾液分泌调节的叙述，正确的是","o":["神经调节只有非条件反射","交感神经兴奋时分泌减少","唾液分泌中枢位于丘脑","使用阿托品后，分泌减少","睡眠时分泌减少"],"a":3,"e":"唾液分泌受副交感神经促进，其递质作用于M受体；阿托品阻断M受体，故唾液分泌减少。交感神经兴奋时唾液腺分泌少量黏稠唾液，并非单纯减少。"},{"q":"用于分析比较不同身材个体心功能的常用指标是","o":["每分输出量","心指数","射血分数","心脏作功量","心力储备"],"a":1,"e":"心输出量与体表面积成正比，以单位体表面积计算的心输出量即心指数，可用于比较身材不同个体的心功能。每分输出量随身材大小而异，不宜直接比较。"},{"q":"正常情况下不能经肾小球滤过的物质是","o":["Na+、Cl-、HCO3-等电解质","血浆白蛋白","葡萄糖","氨基酸","甘露醇"],"a":1,"e":"血浆白蛋白有效半径约3.6nm且带负电荷，受滤过膜孔径和负电荷屏障阻挡，正常时很难滤过。电解质、葡萄糖、氨基酸和甘露醇均可自由滤过。"},{"q":"呼吸过程中肺内压的变化是","o":["吸气时大于大气压，呼气时小于大气压","吸气、呼气时均小于大气压","吸气时小于大气压，呼气时大于大气压","吸气及呼气时均大于大气压","吸气末等于大气压，呼气时小于大气压"],"a":2,"e":"吸气时肺容积增大、肺内压降低至低于大气压，气体入肺；呼气时肺容积减小、肺内压升高至高于大气压，气体出肺。吸气末和呼气末肺内压均与大气压相等。"},{"q":"下列关于大动脉硬化导致心血管系统变化的叙述，错误的是","o":["收缩压升高","舒张压降低","脉压增大","大动脉顺应性下降","脉搏波传播速度减慢"],"a":4,"e":"大动脉硬化使管壁可扩张性降低，脉搏波传播速度加快，故“脉搏波传播速度减慢”错误。硬化使顺应性下降、收缩压升高、舒张压降低、脉压增大。"},{"q":"下列关于神经纤维兴奋传导特征的叙述，错误的是","o":["双向传导","绝缘性","兴奋节律不改变","总和","对内环境敏感"],"a":3,"e":"神经纤维兴奋传导具有完整性、双向性、绝缘性和相对不疲劳性，不包括总和。总和是突触传递和反射中枢兴奋传递的特征。"},{"q":"刺激阈值指的是","o":["用最小刺激强度，刚刚引起组织兴奋的最短作用时间","保持一定的刺激强度不变，能引起组织兴奋的最适作用时间","保持一定的刺激时间和强度-时间变化率不变，引起组织发生兴奋的最小刺激强度","刺激时间不限，能引起组织兴奋的最适刺激强度","刺激时间不限，能引起组织最大兴奋的最小刺激强度"],"a":2,"e":"阈强度指固定刺激时间和强度-时间变化率时，能引起组织兴奋的最小刺激强度，是衡量兴奋性的指标。"},{"q":"自主神经节前纤维释放的递质是","o":["ACh和NE","NE","5-HT","ACh","NE和5-HT"],"a":3,"e":"自主神经节前纤维末梢释放ACh，作用于节后神经元N1受体；节后纤维才释放NE或ACh。"},{"q":"心迷走节后纤维末梢释放的递质主要与下列哪一种受体结合","o":["M受体","N受体","α受体","β1受体","β2受体"],"a":0,"e":"心迷走神经节后纤维释放ACh，作用于心肌细胞膜M型胆碱能受体，产生负性变力、变时和变传导作用。"},{"q":"下列疾病中，能够使肺通气/血流比值增高最明显的是","o":["肺纤维化形成","肺水肿","支气管哮喘发作","肺栓塞","肺癌"],"a":3,"e":"肺栓塞使肺血流减少，VA/Q比值明显增高。肺纤维化、肺水肿使扩散距离增加或面积减小，哮喘致通气不足使比值降低。"},{"q":"心室肌细胞动作电位的时程主要取决于","o":["Na+内流的速度","Cl-内流的速度","Ca2+内流的速度","K+外流的速度","Na+外流的速度"],"a":2,"e":"心室肌动作电位平台期由Ca2+内流与K+外流共同形成，时程主要取决于Ca2+内流速度，钙通道阻断可使时程缩短。"},{"q":"心室等容收缩期瓣膜的状态是","o":["房室瓣开放，动脉瓣关闭","房室瓣关闭，动脉瓣关闭","房室瓣关闭，动脉瓣开放","房室瓣开放，动脉瓣开放","房室瓣、动脉瓣间无规律开关"],"a":1,"e":"等容收缩期室内压高于房内压使房室瓣关闭，又低于主动脉压使半月瓣关闭，心室容积不变。"},{"q":"动作电位的“全或无”特性是指同一细胞动作电位的幅度","o":["不受细胞外K+浓度的影响","不受细胞外Na+浓度的影响","与刺激强度和传导距离无关","与静息电位无关","与Na+通道的状态无关"],"a":2,"e":"动作电位的“全或无”指刺激一旦达到阈值，其幅度即达该细胞最大值，不随刺激强度增强而增大；传导过程中幅度也不衰减。其幅度由钠通道性状和Na+驱动力决定，与原始刺激强度无关。"},{"q":"调节心血管活动的最基本中枢是","o":["脊髓","延髓","脑桥","下丘脑","大脑皮层"],"a":1,"e":"延髓是调节心血管活动最基本的中枢，保持延髓及以下中枢完整即可维持接近正常的血压和心血管反射。延髓因整合循环、呼吸等基本生命活动而被称为“生命中枢”。"},{"q":"成年人生长激素分泌过多，将导致下列哪种疾病发生","o":["地方性甲状腺肿","单纯性甲状腺肿","侏儒症","巨人症","肢端肥大症"],"a":4,"e":"成年后骨骺已闭合，长骨不再加长，GH分泌过多使肢端短骨、颅骨及软组织异常生长，表现为手足粗大、鼻大唇厚、下颌突出，称肢端肥大症。幼年GH过多才引起巨人症。"},{"q":"纯胃液是无色的酸性液体，下列有关其pH值的描述正确的是","o":["0、9～1、5","2、5～3、0","3、5～4、5","5、0","6、5～7、5"],"a":0,"e":"纯净胃液为无色酸性液体，pH为0.9～1.5，主要成分有盐酸、胃蛋白酶原、黏液和内因子。胰液为碱性液体，pH 7.8～8.4，与胃液不同。"},{"q":"微循环中真毛细血管的主要作用是","o":["调节外周阻力","调节体温","引流淋巴液","实现血液与组织液之间的物质交换","促进血液回流"],"a":3,"e":"真毛细血管壁薄、通透性大、血流缓慢，是血液与组织液进行物质交换的主要场所，又称营养通路。扩散是血液与组织液间物质交换最重要的方式。"},{"q":"下述形成心室肌细胞动作电位的离子基础，错误的是","o":["0期主要是Na+内流","1期主要是Cl-外流","2期主要是Ca2+内流","3期主要是K+外流","4期有K+内流"],"a":1,"e":"心室肌细胞1期快速复极主要由瞬时外向K+流（Ito）引起，而非Cl-外流。0期由Na+内流形成，2期由Ca2+内流与K+外流共同形成，3期由K+外流形成。"},{"q":"交感神经节前纤维释放的递质是","o":["ACh","NE","5-HT","ACh和NE","NE和5-HT"],"a":0,"e":"交感神经节前纤维末梢释放的递质为ACh，作用于节后神经元N1受体；节后纤维才释放NE。ACh和NE分别为节前、节后纤维的递质。"},{"q":"红细胞沉降率的快慢主要取决于红细胞的","o":["体积","表面积","数量","比重","叠连"],"a":4,"e":"红细胞沉降率快慢主要取决于红细胞是否发生叠连，叠连后总表面积与总体积之比减小，摩擦力减小而沉降加快。决定叠连的因素在于血浆成分变化，而非红细胞本身。"},{"q":"下列关于窦房结细胞Ca2+通道的叙述中，错误的是","o":["是电压门控性通道","选择性高，只允许Ca2+通透","激活的阈电位水平为-40mV","参与窦房结细胞4期自动去极化","激活、失活以及再复活的时间均比Na+通道长"],"a":1,"e":"窦房结细胞Ca2+通道属电压门控通道，激活阈电位约-40mV，参与4期自动去极化，其激活、失活及复活均比Na+通道慢。该通道对Ca2+有选择性但并非只允许Ca2+通透，故“选择性高，只允许Ca2+通透”错误。"},{"q":"控制呼吸基本节律的神经元位于","o":["脊髓前角","延髓","中脑","脑桥背外侧部","下丘脑"],"a":1,"e":"延髓是产生最基本呼吸节律的部位，在延髓与脑桥之间横切仍出现喘息样呼吸，提示延髓为喘息中枢。呼吸节律主要产生于延髓前包钦格复合体。"},{"q":"下列哪种物质在胃排空的速度最慢","o":["糖、蛋白和脂肪的混合物","糖与蛋白的混合物","脂肪","蛋白质","糖"],"a":2,"e":"三大营养物质中糖类排空最快，蛋白质次之，脂肪最慢，脂肪可刺激促胰液素、抑胃肽释放并抑制胃运动，延缓胃排空。"},{"q":"细胞膜上不衰减形式传播的电活动是","o":["动作电位","静息电位","终板电位","感受器电位","局部电位"],"a":0,"e":"动作电位产生后可沿细胞膜不衰减地传遍整个细胞，其幅度和波形在传播过程中保持不变。局部电位、终板电位和感受器电位均呈等级性、可衰减。"},{"q":"在突触传递中，当突触前神经元受到较高频率刺激时，引起突触后神经发放冲动减少的原因是","o":["突触前神经元出现适应","突触前神经产生的兴奋减少","突触后神经出现适应","神经递质与受体结合能力减弱","突触前神经元末梢的神经递质耗竭"],"a":4,"e":"高频长时间连续刺激突触前神经元时，突触前末梢递质释放逐渐耗竭，使突触后神经元放电频率降低，即突触传递容易发生疲劳。"},{"q":"关于正常尿液的产生，描述正确的是","o":["每昼夜的尿量为2000～3000ml","尿液的渗透压高于血浆渗透压","尿液的pH值与饮食情况无关","尿液可检出少量葡萄糖","尿液中不能检出蛋白质和红细胞"],"a":4,"e":"正常尿液中不含蛋白质和红细胞，因肾小球滤过膜屏障作用使大分子蛋白质和血细胞不能滤过。正常尿量约1000～2000ml/24h，尿液渗透压可高于或低于血浆，pH随饮食变化。"},{"q":"兴奋性突触后电位与抑制性突触后电位的共同特征是","o":["突触前膜释放的递质性质一样","突触后膜均去极化","突触前膜均去极化","突触后膜对离子通透性一样","产生的突触后电位的最终效应一样"],"a":2,"e":"无论兴奋性还是抑制性突触传递，突触前神经元兴奋传至末梢均使突触前膜去极化，触发Ca2+内流和递质释放。EPSP使突触后膜去极化，IPSP使突触后膜超极化，两者递质和离子通透性不同。"},{"q":"心室肌细胞的静息电位相当于","o":["EK","ENa","ECa","Ecl","EK及ENa的中间值"],"a":0,"e":"静息时细胞膜对K+的通透性明显大于对Na+的通透性，静息电位主要由K+外流形成，故心室肌细胞静息电位接近EK。"},{"q":"下列关于肾上腺皮质分泌激素的描述，哪一项是错误的","o":["肾上腺皮质分泌的激素是维持生命所必需的","球状带分泌醛固酮","束状带分泌皮质醇","网状带分泌性激素","合成肾上腺皮质激素的原料是磷脂"],"a":4,"e":"肾上腺皮质激素的合成原料是胆固醇，约80%来自血液低密度脂蛋白，少量由乙酸合成，并非磷脂。肾上腺皮质激素为维持生命所必需，球状带分泌醛固酮、束状带分泌皮质醇、网状带分泌性激素。"},{"q":"下列关于消化器官神经支配的叙述，正确的是","o":["交感神经节后纤维释放乙酰胆碱","所有副交感神经节后纤维均释放乙酰胆碱","去除外来神经后，内在神经仍能完成局部反射","外来神经对内在神经无调节作用","内在神经丛均存在于黏膜下和平滑肌间"],"a":2,"e":"去除外来神经后，内在神经丛仍可独立调节胃肠运动、分泌、血流量及水电解质转运，完成局部反射。交感神经节后纤维释放去甲肾上腺素；内在神经丛包括黏膜下丛和肌间神经丛。"},{"q":"细胞膜外表面的糖链","o":["可以作为离子通道","可以作为膜受体参与跨膜信号转导","可以作为离子泵","可以作为细胞特异性识别标志","能分解ATP"],"a":3,"e":"细胞膜外表面的糖链由寡糖链构成，可作为细胞特异性识别标志，如ABO血型抗原即由红细胞表面糖链决定。离子通道、离子泵和参与信号转导的膜受体均为膜蛋白。"},{"q":"第二心音的产生主要由于","o":["房室瓣开放","房室瓣关闭","动脉瓣开放","动脉瓣关闭","乳头肌及腱索的振动"],"a":3,"e":"第二心音主要因主动脉瓣和肺动脉瓣关闭，血流冲击大动脉根部引起振动而产生，标志心室舒张期开始。房室瓣关闭产生第一心音。"},{"q":"静息心指数等于","o":["每搏输出量/心室舒张末期容积","心输出量/体表面积","每搏输出量/体表面积","心室舒张末期容积/体表面积","每分功/体表面积"],"a":1,"e":"以单位体表面积计算的心输出量称为心指数，安静空腹时测定的为静息心指数，正常约3.0～3.5L/(min·m²)。心输出量等于心率与搏出量的乘积。"},{"q":"心迷走神经活动加强，可引起","o":["心率减慢、传导加速、心肌收缩力减弱","心率加快、传导加速、心肌收缩力减弱","心率减慢、传导减慢、心肌收缩力减弱","心率减慢、传导加速、心肌收缩力加强","心率加快、传导加速、心肌收缩力加强"],"a":2,"e":"心迷走神经节后纤维释放ACh作用于心肌M受体，引起负性变力、负性变时和负性变传导，即心率减慢、传导减慢、心肌收缩力减弱。心交感神经兴奋才使心率加快、传导加速、收缩力增强。"},{"q":"ACh与突触后膜受体结合产生效应后，清除的主要方式是","o":["被突触前膜重新摄取","被胆碱酯酶分解","随血流到达肾脏排出","随血流带到肝脏破坏","被单胺氧化酶分解"],"a":1,"e":"ACh与突触后膜受体结合产生效应后，主要被附着于突触后膜的乙酰胆碱酯酶迅速水解为胆碱和乙酸而清除。去甲肾上腺素才主要经突触前膜重摄取和单胺氧化酶降解。"},{"q":"主动脉在维持舒张压中起重要作用，主要是因为主动脉","o":["血管口径大","管壁厚","对血液的摩擦阻力小","血流速度快","管壁具有可扩张性和弹性"],"a":4,"e":"主动脉属弹性储器血管，管壁富含弹性纤维，具有可扩张性和弹性，心室舒张时弹性回缩推动血液继续流向外周，从而维持舒张压。老年人动脉硬化使弹性储器作用减弱，脉压加大。"},{"q":"下列哪种情况可抑制促胃液素释放","o":["迷走神经兴奋","胃内pH值高于6","胃内pH值低于1、5","胃内肽浓度升高","扩张胃窦"],"a":2,"e":"胃窦内pH降至1.2～1.5时，HCl可直接抑制G细胞释放促胃液素，并刺激δ细胞分泌生长抑素间接抑制其释放，故胃酸分泌受抑。迷走神经兴奋经GRP促进促胃液素释放。"},{"q":"交感神经紧张时，尿量减少的主要原因是","o":["循环血量减少","血浆胶体渗透压升高","肾小球滤过膜通透性降低","肾小球毛细血管血压降低","肾小囊内压升高"],"a":3,"e":"肾交感神经兴奋释放去甲肾上腺素，使入球小动脉收缩比出球小动脉更明显，肾小球毛细血管血压下降，有效滤过压降低，GFR减少而尿量减少。"},{"q":"皮肤快痛发生时，表现出来的特点是","o":["定位不确准","持续时间较长","是一种刺痛","疼痛发生较慢","由C类纤维传导"],"a":2,"e":"快痛由Aδ有髓纤维传导，表现为尖锐、定位明确的“刺痛”，发生快、消失快，一般不伴明显情绪改变。C类纤维传导的是定位不准确的慢痛。"},{"q":"在1mmHg分压差下，每分钟通过呼吸膜扩散的某种气体的毫升数称为该气体的","o":["肺扩散能力","肺扩散容量","呼吸膜通透性","肺扩散指数","肺通气/血流比值"],"a":1,"e":"肺扩散容量指气体在单位分压差（1mmHg）作用下每分钟通过呼吸膜扩散的毫升数，反映呼吸膜的扩散能力。"},{"q":"IPSP发生时，突触后膜电位的状态是","o":["超射","去极化","反极化","超极化","复极化"],"a":3,"e":"IPSP是突触传递在突触后膜引起的超极化电位，其机制为抑制性递质使后膜氯通道开放、Cl⁻内流，使膜电位远离阈电位。"},{"q":"下列关于肺循环的叙述，正确的是","o":["血流阻力大","肺循环压力高","血容量波动小","血流量仅受神经调节","低氧可使肺部血管收缩"],"a":4,"e":"急性或慢性低氧均使肺循环血管收缩、血流阻力增大，与体循环低氧引起血管舒张相反，其意义是将血流转移至通气良好的肺泡区域。"},{"q":"动物见到食物就引起唾液分泌，这属于","o":["非条件反射","非自动控制","负反馈控制","正反馈控制","前馈控制"],"a":4,"e":"前馈控制是利用前馈信号构成的开环控制系统，使调节具有预见性；动物见到食物即引起唾液分泌，是为进食提前准备，属前馈控制。"},{"q":"单根神经纤维受到刺激而兴奋，当它的兴奋性处于低常期时，相当于其动作电位的","o":["阈电位","去极相","超射时期","负后电位","正后电位"],"a":4,"e":"动作电位后兴奋性依次经历绝对不应期、相对不应期、超常期和低常期，低常期相当于正后电位阶段，此时膜电位超极化，兴奋性低于正常。"},{"q":"O2与CO2的扩散系数相比较","o":["前者大，因为O2可与血红蛋白结合","前者小，因为O2的溶解度低","前者大，因为O2分压梯度大","前者小，因为O2的相对分子质量小","基本相同"],"a":1,"e":"正确答案是前者小，因为O2的溶解度低。CO2在血浆中的溶解度约为O2的24倍，故CO2的扩散系数约为O2的20倍，O2扩散系数较小。"},{"q":"合成血红蛋白的基本原料是","o":["蛋白质和铁","蛋白质和铜","蛋白质和锌","蛋白质和钙","蛋白质和磷"],"a":0,"e":"正确答案是蛋白质和铁。蛋白质和铁是合成血红蛋白的重要原料，叶酸和维生素B12为红细胞成熟所必需。"},{"q":"关于精子的运行，下列哪一项描述是正确的","o":["精液呈酸性","精子的运行只依靠自身的运动","排卵期宫颈黏液稀薄有利于精子运行","接近卵子的精子可达2～5×108个","孕酮有利于精子运行"],"a":2,"e":"正确答案是排卵期宫颈黏液稀薄有利于精子运行。排卵前雌激素使宫颈黏液清亮、稀薄，有利于精子穿行；孕激素则使黏液变黏稠而阻止精子通过。"},{"q":"生命活动的基本特征不包括下列哪一项","o":["新陈代谢","生殖","兴奋性","适应性","生长发育"],"a":4,"e":"正确答案是生长发育。生命活动的基本特征包括新陈代谢、生殖、兴奋性和适应性，生长发育不属于基本生命活动特征。"},{"q":"滤过分数是指","o":["肾小球滤过率/肾血浆流量","肾血浆流量/肾血流量","肾血流量/肾血浆流量","肾小球滤过率/肾血流量","肾血流量/心输出量"],"a":0,"e":"正确答案是肾小球滤过率/肾血浆流量。滤过分数为肾小球滤过率与肾血浆流量的比值，正常约19%，表示约1/5血浆经肾小球滤过。"},{"q":"霍尔丹(Haldane)效应是指","o":["O2与Hb的结合可促使CO2的结合","CO2与Hb的结合可促使氧的结合","O2与Hb的解离可促使CO2的释放","CO2与Hb的结合可促使氧的释放","O2与Hb的结合可促使CO2的释放"],"a":4,"e":"正确答案是O2与Hb的结合可促使CO2的释放。Hb与O2结合可促进CO2释放，释放O2后的去氧Hb则易与CO2结合，此即霍尔丹效应。"},{"q":"激烈运动时，骨骼肌能量代谢的主要途径是","o":["葡萄糖的有氧氧化","葡萄糖的无氧酵解","脂肪酸代谢","氨基酸代谢","蛋白质代谢"],"a":1,"e":"正确答案是葡萄糖的无氧酵解。剧烈运动时摄氧速度暂时不及骨骼肌耗氧量而出现氧债，骨骼肌通过葡萄糖无氧氧化生成乳酸供能。"},{"q":"人的心率超过180次/分时心输出量减少的主要原因是","o":["心室充盈不足","心室射血无力","射血分数减少","心力储备不足","等容舒张期变短"],"a":0,"e":"正确答案是心室充盈不足。心率超过160～180次/分时心室舒张期明显缩短，充盈量明显减少，搏出量减少致心输出量下降。"},{"q":"临床上用简便方法测定能量代谢时，必须取得哪项数据","o":["呼吸商","非蛋白呼吸商","食物的氧热价","身高和体重","单位时间内的耗O2量"],"a":4,"e":"正确答案是单位时间内的耗O2量。间接测热法依据安静状态下的耗氧量和CO2产生量推算能源物质消耗量及产热量，临床简便测定只需测单位时间耗O2量，再乘以氧热价即得产热量。"},{"q":"柠檬酸钠的抗凝血机制是","o":["激活了纤维蛋白溶解系统","破坏血浆中凝血酶原激活物","增加了血浆中Na＋","去掉了血浆中的纤维蛋白原","与血浆中的Ca2＋结合形成可溶性络合物"],"a":4,"e":"正确答案是与血浆中的Ca2＋结合形成可溶性络合物。柠檬酸钠通过络合血浆Ca2＋，使依赖Ca2＋的凝血过程受阻而抗凝。"},{"q":"下列凝血因子中，需要维生素K参与其合成的是","o":["因子Ⅰ、因子Ⅲ、因子Ⅷ、因子Ⅻ","因子Ⅱ、因子Ⅶ、因子Ⅸ、因子Ⅹ","因子Ⅲ、因子Ⅴ、因子Ⅶ、因子Ⅺ","因子Ⅲ、因子Ⅷ、因子Ⅹ、因子Ⅺ","因子Ⅴ、因子Ⅷ、因子Ⅸ、因子Ⅺ"],"a":1,"e":"正确答案是因子Ⅱ、Ⅶ、Ⅸ、Ⅹ。这四种凝血因子在肝内合成需维生素K参与，故称依赖维生素K的凝血因子，其分子含γ-羧基谷氨酸，与Ca2＋结合后参与凝血。"},{"q":"关于细胞膜流动性的叙述，错误的是","o":["细胞膜流动性的高低与温度有关","出胞过程有赖于细胞膜的流动性","膜脂质中胆固醇含量越高，膜流动性越低","膜蛋白含量越高，膜流动性越低","膜脂质中饱和脂肪酸越多，膜的流动性越高"],"a":4,"e":"正确答案是膜脂质中饱和脂肪酸越多，膜的流动性越高。饱和脂肪酸碳链不含双键，排列紧密，含量越多膜流动性越低；胆固醇增多及温度降低均使流动性下降，出胞依赖膜的流动性。"},{"q":"下述关于神经末梢释放外周递质的叙述，错误的是","o":["全部交感神经节后纤维均释放NE","交感神经节前纤维释放ACh","副交感神经节前纤维释放ACh","全部副交感神经节后纤维均释放ACh","躯体运动神经纤维释放ACh"],"a":0,"e":"正确答案是全部交感神经节后纤维均释放NE。多数交感节后纤维释放去甲肾上腺素，但支配汗腺的交感节后纤维释放ACh，故“全部”表述错误。"},{"q":"当一伸肌被过度牵拉时张力会突然降低，其原因是","o":["疲劳","负反馈","回返性抑制","腱器官兴奋","肌梭敏感性降低"],"a":3,"e":"正确答案是腱器官兴奋。肌肉被过度牵拉时张力增大，腱器官兴奋引起反牵张反射，抑制牵张反射使张力突然降低，从而防止肌肉拉伤。"},{"q":"胰岛素分泌调节中，最重要的因素是","o":["血中游离脂肪酸","血糖浓度","神经调节","胰岛素自身调节","肾上腺素"],"a":1,"e":"正确答案是血糖浓度。胰岛β细胞对血糖变化十分敏感，血糖水平是调节胰岛素分泌的最重要因素，血糖升高使胰岛素分泌明显增加。"},{"q":"下列关于甲状旁腺激素的描述，错误的是哪一项","o":["其分泌主要受血浆中Ca2+浓度的调节","直接刺激破骨细胞的溶骨","主要增加小肠黏膜对Ca2+的吸收","直接刺激肾脏远曲小管重吸收Ca2+","主要作用是升高血钙、降低血磷"],"a":2,"e":"正确答案是主要增加小肠黏膜对Ca2＋的吸收。甲状旁腺激素促进肾小管重吸收Ca2＋并增强破骨细胞溶骨，使血钙升高、血磷降低；小肠Ca2＋吸收主要经维生素D3促进，而非PTH直接作用。"},{"q":"呼吸是指","o":["呼气和吸气合称","气体进出肺的过程","机体与外界环境之间进行气体交换的过程","肺泡与血液之间进行气体交换过程","呼吸运动"],"a":2,"e":"呼吸是机体与外界环境之间的气体交换过程，包括外呼吸、气体运输和内呼吸三个环节。呼气和吸气仅为肺通气过程，肺泡与血液之间的气体交换属于肺换气。"},{"q":"自律性最高的细胞是","o":["窦房结细胞","心房肌细胞","房室交界细胞","浦肯野细胞","心室肌细胞"],"a":0,"e":"窦房结P细胞的自律性最高，约100次/分，是心脏的正常起搏点；房室结约50次/分，末梢浦肯野细胞约25次/分。"},{"q":"排便反射的初级中枢位于","o":["脊髓腰骶段","脑桥","脊髓胸段","中脑","延髓"],"a":0,"e":"排便反射的初级中枢位于脊髓腰骶段，冲动经盆神经和腹下神经传入，并受大脑皮层控制。"},{"q":"内呼吸是指","o":["肺泡与肺毛细血管血液之间的气体交换","组织细胞与毛细血管血液之间的气体交换","细胞器之间的气体交换","线粒体膜内外的气体交换","细胞内的生物氧化过程"],"a":1,"e":"内呼吸指组织细胞与组织毛细血管血液之间的气体交换及细胞内氧化代谢；肺泡与肺毛细血管血液之间的气体交换为肺换气。"},{"q":"正常人安静时通气/血液比值为","o":["0、64","0、84","0、94","1、0","2、0"],"a":1,"e":"健康成人安静时每分钟肺泡通气量与肺血流量的比值VA/Q约为0.84，此时肺换气效率最高。"},{"q":"震颤麻痹的产生主要是由于","o":["纹状体的多巴胺递质系统功能异常","黑质的多巴胺递质系统功能受损","红核的神经递质释放量异常","下丘脑的调节功能异常","边缘系统的调节功能异常"],"a":1,"e":"帕金森病由黑质多巴胺能神经元退行性变所致，多巴胺系统受损使直接通路活动减弱、间接通路活动增强，出现运动减少和动作缓慢。"},{"q":"下列哪项不属于小脑的功能","o":["调节内脏活动","维持身体平衡","维持姿势","协调随意运动","调节肌紧张"],"a":0,"e":"小脑的功能是维持身体平衡、调节肌紧张和协调随意运动；调节内脏活动由自主神经及中枢各级内脏调节中枢完成。"},{"q":"下列哪一类神经纤维属C类神经纤维","o":["初级肌梭传入纤维","皮肤温觉传入纤维","交感神经节前纤维","交感神经节后纤维","皮肤的触-压觉传入纤维"],"a":3,"e":"交感神经节后纤维属无髓鞘的C类神经纤维，其轴突由非成髓鞘施万细胞包裹形成Remak束。"},{"q":"在寒冷环境中，机体主要依靠下列哪种方式来增加产热量","o":["肝脏代谢加强","脑代谢增强","战栗产热","食物特殊动力效应","骨骼肌运动产热"],"a":2,"e":"寒冷环境中机体主要依靠战栗产热和非战栗产热增加产热，其中战栗产热由骨骼肌屈肌和伸肌同时发生不随意节律性收缩完成，可使代谢率增加4～5倍。肝脏代谢加强并非寒冷环境下的主要产热方式。"},{"q":"下面关于A型血的叙述，正确的是","o":["红细胞膜上有A凝集原","血浆中有抗A凝集素","红细胞膜上有抗A凝集素","血浆中有A凝集原","红细胞膜上有B凝集原"],"a":0,"e":"A型血红细胞膜上含A凝集原，血清中含抗B凝集素。凝集素是血浆中的抗体，不存在于红细胞膜上；A凝集原位于红细胞膜而非血浆中。"},{"q":"制备坐骨神经-腓肠肌标本后，如果将腓肠肌浸泡在加入筒箭毒的任氏液中，再刺激坐骨神经。请问腓肠肌的变化是","o":["收缩强度不变","强直收缩","没有反应","收缩加强","收缩减弱"],"a":2,"e":"筒箭毒阻断神经-肌接头处终板膜上的N2受体，使神经冲动不能引起腓肠肌兴奋收缩，故刺激坐骨神经后肌肉无反应。"},{"q":"红细胞所需的能量主要来自","o":["葡萄糖的有氧氧化","糖异生","糖原分解","糖酵解","脂肪酸氧化"],"a":3,"e":"成熟红细胞无线粒体，不能进行有氧氧化，糖酵解是其获得能量的唯一途径，所产ATP用于维持钠泵活动和细胞形态。"},{"q":"使内环境理化性质保持相对恒定的调节方式属于","o":["神经调节","体液调节","自身调节","免疫调节","负反馈调节"],"a":4,"e":"负反馈调节使受控部分活动向原先活动相反方向改变，将活动恢复到调定点水平，是维持内环境理化性质相对恒定的主要调节方式。"},{"q":"红细胞在血管外破坏的主要场所是","o":["肾、肝","脾、骨髓","肾、脾","胸腺、骨髓","胸腺、肝"],"a":1,"e":"衰老红细胞变形能力减退、脆性增高，难以通过微小孔隙，易滞留于脾、肝和骨髓中被巨噬细胞吞噬，此即血管外破坏，脾为主要场所。"},{"q":"下列情况中，能够使肺通气/血流比值减少最明显的是","o":["人体处于直立位时的肺尖","肺水肿","支气管哮喘发作","肺栓塞","肺癌"],"a":2,"e":"支气管哮喘发作时气道平滑肌收缩、气道阻力增大，肺泡通气量明显减少，而肺血流未相应减少，故通气/血流比值减小最明显。肺栓塞时血流减少使比值增大。"},{"q":"肾小管中不能主动重吸收Na+的部位是","o":["近曲小管","髓袢细段","髓袢升支粗段","远曲小管","集合管"],"a":1,"e":"髓袢细段对NaCl可通透，NaCl顺浓度差被动重吸收，不进行主动转运；近端小管、升支粗段、远曲小管和集合管均能主动重吸收Na+。"},{"q":"逆行性遗忘症的机制可能是","o":["第一级记忆发生扰乱","第二级记忆发生扰乱","第三级记忆发生扰乱","第一级记忆至第二级记忆过程发生扰乱","海马环路的损害"],"a":1,"e":"逆行性遗忘症的发生机制与记忆巩固和提取异常有关，即第二级记忆发生扰乱。顺行性遗忘症则是信息不能从第一级记忆转入第二级记忆所致。"},{"q":"集合管上皮细胞向管腔内分泌NH3的过程是属于","o":["易化扩散","单纯扩散","出胞","原发性主动转运","继发性主动转运"],"a":1,"e":"NH3为脂溶性分子，可顺浓度梯度以单纯扩散方式进入小管腔。单纯扩散无须载体和代谢耗能，脂溶性物质经此方式跨膜转运。"},{"q":"脊髓前角α-运动神经元被称为躯体骨骼肌运动反射的","o":["效应器","运动单位","最后公路","感受器","传出途径"],"a":2,"e":"α运动神经元接受传入信息后发出冲动到达所支配的梭外肌纤维，是躯体运动反射的最后公路。运动单位指一个α运动神经元及其支配的全部肌纤维。"},{"q":"机体内各种感觉传入纤维在第二级神经元换元后，唯一不投射到丘脑的感觉是","o":["嗅觉","听觉","视觉","本体感觉","痛觉"],"a":0,"e":"丘脑是各种感觉（嗅觉除外）传入的重要中继站。嗅觉传入纤维不经丘脑换元，直接投射到大脑皮层嗅觉区。"},{"q":"上消化道出血诱发肝性脑病的主要机制是","o":["失血性休克","肠道细菌作用下产氨增加","脑组织缺血缺氧","水、电解质紊乱","血脑屏障破坏"],"a":1,"e":"上消化道出血后，血液蛋白质在肠道细菌作用下分解产氨增多，氨经吸收进入血循环，是诱发肝性脑病的主要机制。"},{"q":"人体功能调节方式中处于主导地位的是","o":["神经调节","体液调节","自身调节","全身调节","免疫调节"],"a":0,"e":"神经调节通过神经反射活动调节生理功能，是人体生理功能调节中最重要的调节形式，处于主导地位。体液调节作用缓慢而持久、范围广，但较原始。"},{"q":"血浆中葡萄糖进入红细胞内的过程是属于","o":["单纯扩散","载体介导的易化扩散","通道介导的易化扩散","继发性主动转运","入胞"],"a":1,"e":"葡萄糖为水溶性小分子，在载体蛋白介导下顺浓度梯度进入红细胞，属经载体易化扩散，具有结构特异性、饱和现象和竞争性抑制。"},{"q":"关于影响肺换气的因素，叙述错误的是","o":["气体扩散速率与呼吸膜厚度成反比","扩散速率与呼吸膜面积成正比","通气/血流比值增大有利于换气","通气/血流比值减小不利于换气","扩散速率与气体分压差成正比"],"a":2,"e":"通气/血流比值增大意味着部分肺泡通气未能与血流充分交换，相当于肺泡无效腔增大，反而不利于换气。气体扩散速率与呼吸膜厚度成反比、与面积和分压差成正比。"},{"q":"关于哺乳类动物的心脏，下列描述不正确的是","o":["细胞外K+浓度增加，引起细胞膜去极化","细胞外K+浓度增加，引起细胞膜钾电导增加","低血钾时，心室肌动作电位时程缩短","细胞外K+浓度增加时，心室肌动作电位幅度增加","细胞外高钙可对抗高血钾"],"a":2,"e":"低血钾时心室肌动作电位时程延长而非缩短，故该描述不正确。细胞外K+浓度增加使膜内外K+浓度差减小，静息电位减小（去极化），同时钾电导增加；高钙可对抗高血钾的膜效应。"},{"q":"交感缩血管神经节后纤维末梢释放的递质是","o":["5-羟色胺","血管紧张素Ⅱ","乙酰胆碱","肾上腺素","去甲肾上腺素"],"a":4,"e":"交感缩血管神经节后纤维释放的递质为去甲肾上腺素，与血管平滑肌α受体结合较强，引起血管收缩。乙酰胆碱是副交感及交感舒血管纤维的递质。"},{"q":"可以反映肺通气过程中的阻力的指标是","o":["潮气量","功能残气量","肺活量","补吸气量","时间肺活量"],"a":4,"e":"时间肺活量（用力呼气量）反映单位时间内呼出的气量，能充分反映肺组织弹性状态和气道通畅程度，即通气阻力。肺活量测定不限制呼气时间，气道狭窄者仍可正常。"},{"q":"全血的密度主要取决于","o":["红细胞的数量","渗透压的高低","白细胞的数量","血浆蛋白的数量","血小板的数量"],"a":0,"e":"全血密度主要取决于红细胞数量，红细胞约占血细胞总数的99%，是血液中数量最多的血细胞。血浆密度则主要取决于血浆蛋白。"},{"q":"心室肌细胞绝对不应期的产生是由于","o":["Na+通道处于激活状态","Na+通道处于备用状态","Ca2+通道处于激活状态","Ca2+通道处于失活状态","Na+通道处于失活状态"],"a":4,"e":"心室肌细胞0期去极化的Na+通道在绝对不应期处于失活状态，不能对传来的冲动发生反应，是不应期产生的内在原因。"},{"q":"与骨骼肌收缩相比，平滑肌收缩","o":["横桥激活的机制不同","都具有自律性","不需要胞质内Ca2+浓度升高","没有粗肌丝的滑行","横桥周期更短"],"a":0,"e":"平滑肌收缩的触发因子同为Ca2+，但胞质Ca2+浓度调控存在电-机械耦联和药物-机械耦联两条途径，故横桥激活机制与骨骼肌不同。平滑肌无自律性，收缩同样依赖粗肌丝滑行。"},{"q":"正常条件下，终尿量约占肾小球滤过量的","o":["30%","20%","10%","5%","1%"],"a":4,"e":"正常成人肾小球滤过率约125ml/min，终尿量约1ml/min，仅占滤过量的1%，99%的滤液被肾小管和集合管重吸收。"},{"q":"关于铁的吸收，下列叙述正确的是","o":["食物中铁80%以上被吸收","吸收主要在回肠","高铁比亚铁易吸收","胃酸缺乏不利于吸收","铁离子与铁蛋白结合后由肠腔进人肠上皮细胞"],"a":3,"e":"铁的吸收主要在十二指肠和空肠，胃酸使铁保持二价亚铁状态而利于吸收，胃酸缺乏时铁吸收减少。食物铁仅约10%被吸收，亚铁较高铁易吸收。"},{"q":"催化肾小管分泌H+的酶是","o":["羟化酶","脱羧酶","过氧化物酶","磷酸化酶","碳酸酐酶"],"a":4,"e":"碳酸酐酶催化CO2与H2O生成H2CO3并解离出H+，是肾小管上皮细胞分泌H+的关键酶。酸中毒时该酶活性增高，生成更多H+加速Na+-H+交换。"},{"q":"儿童佝偻病主要是缺乏下列哪种物质","o":["铁","锌","镁","钙","铜"],"a":3,"e":"维生素D和钙缺乏使骨骺端生长板和骨基质不能正常钙化，导致营养性佝偻病。钙是骨盐沉积的直接原料，缺乏时骨钙化障碍。"},{"q":"下列关于心室肌细胞快钠通道特征的描述，哪一项是不正确的","o":["激活快","复活快","对钠离子具有高度选择性","电压依从性","可被Mn2+阻断"],"a":4,"e":"心室肌快钠通道可被河鲀毒素阻断，其对TTX敏感性仅为神经和骨骼肌钠通道的1/100～1/1000。该通道具有激活快、复活快、对Na+高度选择性及电压依从性。"},{"q":"脑内多巴胺能神经元主要位于","o":["脑桥蓝斑","中脑黑质","低位脑干","纹状体","低位脑干中缝核"],"a":1,"e":"多巴胺能神经元胞体主要集中在中脑黑质，构成黑质-纹状体等通路。蓝斑核为去甲肾上腺素能，中缝核为5-羟色胺能。"},{"q":"血液中H+浓度升高加强呼吸运动的主要作用途径是","o":["刺激外周化学感受器","刺激中枢化学感受器","直接刺激延髓呼吸中枢","刺激脑桥呼吸调整中枢","直接刺激脊髓呼吸中枢"],"a":0,"e":"H+不易通过血-脑屏障，血液中H+升高主要刺激外周化学感受器反射性加强呼吸。中枢化学感受器对H+敏感但主要感受脑脊液中H+。"},{"q":"肺总容量等于","o":["潮气量+肺活量","潮气量+功能残气量","功能残气量+肺活量","残气量+补吸气量","残气量+肺活量"],"a":4,"e":"肺总容量为肺活量与残气量之和，即肺所能容纳的最大气体量。肺活量仅含潮气量、补吸气量和补呼气量，不含残气量。"},{"q":"二氧化碳分压由高到低的顺序一般是","o":["呼出气，肺泡气，组织细胞，静脉血","静脉血，呼出气，肺泡气，组织细胞","肺泡气，静脉血，组织细胞，呼出气","组织细胞，静脉血，肺泡气，呼出气","呼出气，组织细胞，静脉血，肺泡气"],"a":3,"e":"CO2分压以组织细胞最高（约50mmHg），静脉血次之（46mmHg），肺泡气再次（40mmHg），呼出气最低。CO2由组织向血液、肺泡顺分压差扩散。"},{"q":"以下关于心室肌相对不应期的描述，不正确的是","o":["膜内电位为-60mV～80mV","Na+通道部分复活","刺激阈值高于正常","本期内产生的动作电位时程较长","兴奋传导速度较慢"],"a":3,"e":"相对不应期膜电位约-60～-80mV，Na+通道部分复活，阈值高于正常，兴奋传导速度较慢。此期产生的动作电位时程与正常相同，并不延长。"},{"q":"正常人耳声音频率的最敏感范围是","o":["1000～10000Hz","5000～10000Hz","1000～3000Hz","100～20000Hz","20～20000Hz"],"a":2,"e":"人耳最敏感的声波频率为1000～3000Hz，恰与人类语言频率范围一致。20～20000Hz是人耳的听阈范围，并非最敏感范围。"},{"q":"近端小管的重吸收率始终占肾小球滤过率的比例为","o":["50%","55%","60%","65%","80%"],"a":3,"e":"近端小管对Na+和水的重吸收率始终占肾小球滤过率的65%～70%，称为定比重吸收，即球-管平衡。"},{"q":"骨骼肌收缩过程中胞内钙离子的主要来源是","o":["细胞外钙离子内流","肌钙蛋白与大量钙离子解离","与钙调蛋白结合的钙离子解离释放","肌质网内钙离子释放","肌质网膜上钙泵的转运"],"a":3,"e":"骨骼肌兴奋-收缩耦联中，肌膜去极化经L型钙通道变构触发肌质网RyR1开放，Ca2+主要来自肌质网释放。心肌则不同，细胞外Ca2+内流触发肌质网释放，即钙致钙释放。"},{"q":"下列可促进胰液分泌的因素是","o":["迷走神经兴奋","降钙素基因相关肽","生长抑素","支配胰的内脏大神经","胆盐"],"a":0,"e":"迷走神经兴奋作用于胰腺腺泡细胞，引起酶含量丰富而水和碳酸氢盐少的胰液分泌。内脏大神经对胰液分泌影响不明显，促胰液素才主要促进水和HCO3-分泌。"},{"q":"神经中枢内兴奋传递的活动中，发生后发放现象的神经元联系方式主要是","o":["辐散式联系","聚合式联系","环式联系","单线式联系","链锁式联系"],"a":2,"e":"环式联系中后一级神经元经侧支回返联系前一级神经元形成闭合环路，刺激停止后传出通路仍继续发放冲动，即后发放。"},{"q":"右心衰竭时组织液生成增加导致水肿，主要原因是","o":["毛细血管血压增高","血浆胶体渗透压降低","组织液静水压降低","组织液胶体渗透压增高","血浆晶体渗透压降低"],"a":0,"e":"右心衰竭使体循环静脉压升高、静脉回流受阻，毛细血管有效流体静压增高，组织液生成增多而致全身性水肿。"},{"q":"判断组织兴奋性高低最常用的指标是","o":["刺激频率","刺激强度","动作电位","阈电位","阈强度"],"a":4,"e":"阈强度是引起活组织细胞产生反应的最小刺激强度，阈值越小兴奋性越高，故常用阈强度衡量组织兴奋性高低。"},{"q":"神经细胞兴奋时，首先产生扩布性动作电位的部位是","o":["胞体","树突","轴突始段","轴突","轴突末梢"],"a":2,"e":"多数神经元轴突始段电压门控钠通道密度大、阈电位低，兴奋时首先在该部位爆发扩布性动作电位，再沿轴突传向末梢并逆向传至胞体。"},{"q":"关于神经纤维静息电位的形成机制，下述哪项是错误的","o":["细胞外的K+浓度小于细胞内的K+浓度","细胞膜对Na+有点通透性","细胞膜主要对K+有通透性","加大细胞外的K+浓度，会使静息电位绝对值加大","细胞内Na+浓度低于细胞外Na+浓度"],"a":3,"e":"静息电位主要由K+外流形成，细胞外K+浓度升高使K+平衡电位减小，静息电位绝对值减小而非加大。静息时膜主要对K+有通透性，对Na+仅有少量通透性。"},{"q":"下列哪个部位不存在中枢温度感受器","o":["PO/AH","小脑","中脑","下丘脑","下丘脑后部"],"a":1,"e":"中枢温度感受器分布于下丘脑、脑干网状结构和脊髓等部位，包括热敏神经元和冷敏神经元，小脑不属于其分布部位。"},{"q":"启动外源性凝血途径的物质是","o":["因子Ⅲ","因子Ⅻ","PF3","Ca2＋","凝血酶原"],"a":0,"e":"外源性凝血途径由组织因子（因子Ⅲ）启动，组织因子与FⅦa结合成复合物后激活FⅩ。因子Ⅻ是内源性凝血途径的启动因子。"},{"q":"关于神经纤维的静息电位，下述哪项是错误的","o":["它是膜外为正、膜内为负的电位","接近于钾离子的平衡电位","在不同的细胞，其大小可以不同","它是个稳定的电位","相当于钠离子的平衡电位"],"a":4,"e":"静息时膜主要对K+有通透性，静息电位接近K+平衡电位，而与Na+平衡电位相差较远。静息电位表现为膜外正、膜内负，不同细胞其数值不同。"},{"q":"在突触前易化的形成过程中，其主要结构或机制是","o":["与突触前抑制的结构基础完全不同，没有轴-轴式突触","中间神经元释放5-HT，使突触前膜产生高频率动作电位","有更多的Ca2+进入突触前轴突末梢","突触前膜释放神经递质减少","突触后膜产生的EPSP数量增多"],"a":2,"e":"突触前易化时突触前末梢动作电位时程延长，Ca2+通道开放时间延长，进入末梢的Ca2+增多，递质释放增加，使突触后EPSP增大。"},{"q":"Hb实际结合的氧量主要决定于动脉血的","o":["pH值","PCO2","2,3-DPG的浓度","PO2","Hb浓度"],"a":3,"e":"Hb氧含量指100ml血液中Hb实际结合的O2量，取决于Hb浓度与Hb氧饱和度，而Hb氧饱和度主要受PO2影响，故实际结合氧量主要决定于动脉血PO2。"},{"q":"神经垂体释放的激素有","o":["催乳素与生长激素","缩宫素与催乳素","抗利尿激素与缩宫素","抗利尿激素与促黑激素","催乳素与血管升压素"],"a":2,"e":"神经垂体释放抗利尿激素（血管升压素）和缩宫素，二者由下丘脑视上核和室旁核合成后运输至神经垂体贮存释放。催乳素和生长激素由腺垂体分泌。"},{"q":"低氧对呼吸的兴奋作用是通过","o":["直接兴奋延髓吸气神经元","直接兴奋呼吸中枢","直接兴奋脑桥呼吸调整中枢","刺激中枢化学感受器而兴奋呼吸中枢","刺激外周化学感受器而实现的反射性效应"],"a":4,"e":"低O2对呼吸的兴奋作用完全依赖外周化学感受器，切断其传入神经后该效应消失；低O2对呼吸中枢的直接作用是抑制。"},{"q":"自主神经节后纤维释放的主要递质是","o":["ACh和NE","NE","5-HT","ACh","NE和5-HT"],"a":0,"e":"自主神经节后纤维的递质为ACh和NE：副交感神经及交感舒血管纤维释放ACh，多数交感节后纤维释放NE。5-HT不是自主神经节后纤维的主要递质。"},{"q":"健康成年人在强体力劳动时，心输出量约可达到","o":["5～6L/min","30L/min","60L/min","120L/min","150L/min"],"a":1,"e":"健康成年人安静时心输出量约5L/min，剧烈运动时可增至25～30L/min，为安静时的5～6倍，体现心力储备。5～6L/min为安静时水平。"},{"q":"下丘脑在内脏调节中的作用不包括","o":["摄食","水平衡","生物节律","内分泌","排便反射"],"a":4,"e":"排便反射的基本中枢在脊髓骶段，下丘脑主要参与摄食、水平衡、生物节律和内分泌等的调节。"},{"q":"在一定血压范围内，肾血流量能保持相对稳定主要靠","o":["神经调节","体液调节","免疫调节","自身调节","多种调节"],"a":3,"e":"当动脉血压在70～180mmHg范围内波动时，肾血流量通过自身调节保持相对稳定，使肾小球滤过率不致大幅波动。"},{"q":"肝素抗凝血的主要机制是","o":["抑制凝血酶原的激活","增强抗凝血酶Ⅲ与凝血酶的亲和力","促进纤维蛋白吸附凝血酶","抑制因子X的激活","去除血浆中游离的Ca2＋"],"a":1,"e":"肝素本身抗凝作用弱，主要通过增强抗凝血酶Ⅲ灭活凝血酶及FⅩa等而间接发挥强大抗凝作用。"},{"q":"下列关于激素作用的特征的描述，哪一项正确","o":["很多激素都可以影响全身，所以没有特异性","激素浓度很低，但有高效放大作用","激素的生理功能是相互独立的","胰岛素和糖皮质激素是相互拮抗的激素","胰岛素和糖皮质激素是相互协同的激素"],"a":1,"e":"激素在血中浓度很低（pmol/L～nmol/L），但经受体后信号逐级放大产生高效生物效应，即高效作用特征。"},{"q":"主要在回肠吸收的物质是","o":["果糖","甘油","氨基酸","维生素B12","内因子"],"a":3,"e":"维生素B12与内因子结合后，在回肠远端经特异受体介导被吸收，是唯一在回肠吸收的维生素。"},{"q":"关于球旁细胞的描述错误的是","o":["系入球小动脉管壁的特殊分化细胞","能感受血浆Na+浓度的变化","能释放肾素","受交感神经的支配","在醛固酮的分泌调节中起重要作用"],"a":1,"e":"球旁细胞是入球小动脉壁的特殊分化细胞，能感受牵张刺激并释放肾素，受交感神经支配，参与醛固酮分泌调节；感受血浆Na+浓度变化的是致密斑。"},{"q":"关于单突触反射的特点，正确的是","o":["神经中枢内很多见","参与的中枢范围很广","需要多个突触活动","反射效应产生较慢","反射时短"],"a":4,"e":"单突触反射在中枢只经一次突触传递，突触延搁短，故反射时短。教材测算膝反射中枢延搁仅0.6～0.9毫秒，只够一次化学突触传递所需时间。"},{"q":"人体感受外界环境温度降低刺激的主要感受器是","o":["中枢冷敏神经元","皮肤热感受器","皮肤冷感受器","中枢热敏神经元","外周温度感受器"],"a":2,"e":"皮肤冷感受器是感受外界温度降低的主要感受器，其数量为热感受器的5～11倍，对冷刺激更敏感。皮肤温度降至30℃以下时冷感受器放电增加，冷觉增强。"},{"q":"下列物质都能引起尿量增多，其中通过渗透性利尿机制实现的是","o":["心房钠尿肽","生理盐水","呋塞米","甘露醇","缓激肽"],"a":3,"e":"甘露醇可经肾小球自由滤过而不被肾小管重吸收，使小管液溶质浓度升高、水重吸收减少，产生渗透性利尿。呋塞米通过抑制髓袢升支粗段NaCl重吸收利尿，并非渗透性机制。"},{"q":"ABO血型系统的天然抗体是","o":["IgA","IgD","IgM","IgE","IgG"],"a":2,"e":"ABO血型系统的天然抗体多属IgM，分子量大，不能通过胎盘。免疫性抗体属IgG，分子量小，能通过胎盘进入胎儿体内。"},{"q":"人体功能活动的神经调节特点是","o":["反应速度慢","作用广泛而持久","调节敏感性差","迅速、准确和短暂","调节有局限性"],"a":3,"e":"神经调节通过神经反射实现，具有反应迅速、持续时间短、调节精确的特点。体液调节则作用缓慢、广泛而持久。"},{"q":"促进某些生理过程逐步加强直至完成是依靠体内的","o":["非自动控制系统","负反馈控制系统","正反馈控制系统","前馈控制系统","神经和内分泌系统"],"a":2,"e":"正反馈时受控部分的活动向原先活动相同的方向改变，使系统活动越来越强，促使某些生理过程逐步加强直至完成，如分娩、排尿。负反馈则维持系统稳态。"},{"q":"机体对抗蠕虫幼体感染的主要防御机制是","o":["中性粒细胞","嗜酸性粒细胞","嗜碱性粒细胞","单核巨噬细胞","淋巴细胞"],"a":1,"e":"嗜酸性粒细胞是机体对抗蠕虫幼体感染的主要防御机制，在IgG、IgE和补体C3调理下黏着于幼虫，释放MBP等损伤虫体。中性粒细胞主要参与急性化脓性感染防御。"},{"q":"将成束粗肌丝固定在一起的结构称为","o":["Z线","M线","肌钙蛋白","原肌球蛋白","H带"],"a":1,"e":"粗肌丝肌球蛋白杆状部集合成主干，尾端朝向M线排列，M线将成束粗肌丝固定在一起。Z线是细肌丝的附着结构，相邻两Z线间为肌节。"},{"q":"酸性食糜进入小肠引起大量胰液分泌的主要机制是","o":["小肠黏膜释放促胃液素","小肠黏膜释放促胰液素","小肠黏膜释放缩胆囊素","迷走神经兴奋","交感神经兴奋"],"a":1,"e":"酸性食糜进入小肠后刺激小肠黏膜S细胞释放促胰液素，促胰液素主要促进胰液分泌。盐酸是刺激促胰液素释放的最强因素，糖类几乎无刺激作用。"},{"q":"在肺水肿、肺充血等病理情况下，呼吸浅快的主要原因是激发了","o":["中枢化学感受器的活动","加压反射","肺牵张反射","外周化学感受器的活动","大脑皮质的活动"],"a":2,"e":"肺顺应性降低时肺扩张对气道的牵张刺激增强，激发肺牵张反射，使呼吸变浅变快。肺充血、肺水肿时肺组织顺应性下降，故出现浅快呼吸。"},{"q":"肌梭感受器的适宜刺激是","o":["梭外肌收缩","梭外肌松弛","梭外肌受牵拉","梭内肌紧张性降低","梭内肌受压迫"],"a":2,"e":"肌梭与梭外肌纤维呈并联关系，当梭外肌受牵拉时肌梭随之被牵拉而兴奋，故其适宜刺激是梭外肌受牵拉。肌梭是长度感受器，感受肌肉长度的变化。"},{"q":"下列关于中心静脉压的叙述，错误的是","o":["指右心房和胸腔大静脉的血压","可反映心脏射血功能和回心血量的关系","中心静脉压比外周静脉压稍高","可作为临床输液量和速度的参考指标","心脏射血功能下降或输液过多可使中心静脉压升高"],"a":2,"e":"中心静脉压是右心房和胸腔大静脉内的血压，正常仅4～12cmH2O，低于外周静脉压，其高低取决于心脏射血能力与静脉回心血量的关系。"},{"q":"夏天大量出汗，引起尿量减少的主要原因是","o":["血压降低","血浆胶体渗透压升高","肾小球毛细血管血压升高","血浆晶体渗透压升高","循环血量增多"],"a":3,"e":"大量出汗使机体失水多于失钠，血浆晶体渗透压升高，刺激渗透压感受器使抗利尿激素释放增多，集合管重吸收水增加，尿量减少。"},{"q":"脊髓前角中参与协调运动的闰绍细胞，其轴突末梢释放的神经递质是","o":["5-羟色胺","甘氨酸","多巴胺","乙酰胆碱","γ-氨基丁酸"],"a":1,"e":"闰绍细胞是脊髓前角抑制性中间神经元，其轴突末梢释放甘氨酸，经回返性抑制终止α运动神经元活动。破伤风毒素阻断闰绍细胞释放甘氨酸可致惊厥。"},{"q":"给家兔吸入气中增加一定量N2后观察到呼吸运动加强，主要原因是","o":["刺激中枢化学感受器","刺激外周化学感受器","抑制呼吸中枢","刺激呼吸中枢","刺激中枢和外周化学感受器"],"a":1,"e":"吸入气中增加N2使氧分压降低，低氧主要刺激外周化学感受器（颈动脉体、主动脉体），反射性使呼吸加深加快。中枢化学感受器对低氧不敏感。"},{"q":"一个突触囊泡中神经递质释放进入突触间隙，所引发的兴奋性突触后电位属于","o":["动作电位","局部电位","静息电位","阈电位","负后电位"],"a":1,"e":"单个囊泡释放的递质量引起的兴奋性突触后电位幅度小，不能向远距离传播，属局部电位，可经总和达到阈电位后引发动作电位。"},{"q":"兴奋性突触后电位在突触后膜上发生的电位变化为","o":["极化","超极化","后电位","复极化","去极化"],"a":4,"e":"兴奋性突触后电位是突触后膜发生的去极化电位，由兴奋性递质使Na+内流为主引起。教材明确将EPSP定义为突触后膜的去极化。"},{"q":"下列哪种情况尿量不会增加","o":["尿崩症","糖尿病","静脉注射甘露醇","肾血浆流量增加","交感神经兴奋"],"a":4,"e":"交感神经兴奋使肾血管收缩、肾血浆流量减少，并促进肾小管重吸收，尿量减少。尿崩症、糖尿病、甘露醇及肾血浆流量增加均使尿量增多。"},{"q":"华法林在体内可以具有抗凝作用，其生理机制是","o":["可使血管内皮光滑，延缓血液凝固","可去除血浆中的Ca2+","可加强抗凝血酶Ⅲ的抗凝作用","可抑制因子Ⅱ、因子Ⅶ、因子Ⅸ、因子Ⅹ等维生素K依赖性凝血因子的合成","可加强肝素的抗凝作用"],"a":3,"e":"华法林抑制维生素K依赖性凝血因子FⅡ、FⅦ、FⅨ、FⅩ的合成，在体内发挥抗凝作用。这些因子的γ-羧基谷氨酸生成需维生素K参与。"},{"q":"近端小管重吸收Na+对下列哪组物质的重吸收有促进作用","o":["K+、Cl-","H2O、Cl-、HCO3-","H+、K+","H2O、H+、K+","H+、HCO3-"],"a":1,"e":"近端小管重吸收Na+造成小管液渗透压降低、细胞间液渗透压升高，促进水重吸收，并伴随Cl-和HCO3-的重吸收。HCO3-以CO2形式优先重吸收。"},{"q":"下列关于大肠功能的叙述，正确的是","o":["大肠可吸收氨基酸","大肠液有保护肠黏膜、润滑粪便的作用","大肠内的细菌可合成维生素A和D","大肠液的消化酶可分解脂肪","大肠是人体消化和吸收的主要场所"],"a":1,"e":"大肠液富含黏液蛋白，起保护肠黏膜和润滑粪便的作用。大肠细菌可合成维生素K和B族，而非A和D；大肠不是消化吸收的主要场所。"},{"q":"下列哪一项是胃蛋白酶作用的最适宜pH值","o":["0、5～1、0","1、8～3、5","5、0～6、0","6、1～7、0","8、0～9、0"],"a":1,"e":"胃蛋白酶只有在酸性环境中才能发挥作用，其最适pH为1.8～3.5，pH超过5.0时完全失活。"},{"q":"心肌异长自身调节通过改变下列哪一项实现","o":["肌小节初长度","肌钙蛋白活性","肌浆游离Ca2+浓度","心肌收缩能力","横桥ATP酶活性"],"a":0,"e":"心肌异长自身调节是通过改变心肌初长度即肌小节初长度来改变收缩力的。前负荷决定心室舒张期末容积，进而影响初长度。"},{"q":"人的基本生命中枢位于","o":["脑桥","延髓","下丘脑","丘脑","中脑"],"a":1,"e":"延髓是调节心血管活动最基本的中枢，循环、呼吸等基本生命现象的反射调节在延髓水平已基本完成，故称“生命中枢”。"},{"q":"当神经冲动到达运动神经末梢时，可引起接头前膜的","o":["K+通道开放","Ca2+通道开放","Na+通道开放","Cl-通道开放","Cl-通道关闭"],"a":1,"e":"神经冲动传至运动神经末梢使接头前膜去极化，膜上电压门控Ca2+通道开放，Ca2+内流触发ACh囊泡出胞。细胞外Ca2+浓度改变可明显影响兴奋传递，故为Ca2+通道开放。"},{"q":"可反映肺在外力作用下的可扩张性的是","o":["黏滞阻力","气道阻力","肺扩散容量","肺顺应性","通气血流比值"],"a":3,"e":"肺顺应性指肺在外力作用下的可扩张性，用单位跨肺压变化引起的肺容积变化表示。顺应性大则肺弹性阻力小，平静呼吸时位于曲线斜率最大处，呼吸省力。"},{"q":"肌牵张反射使","o":["同一关节的协同肌发生抑制","受牵拉的肌肉发生收缩","同一关节的拮抗肌发生兴奋","其他关节的肌肉也同时发生收缩","伸肌和屈肌都收缩"],"a":1,"e":"牵张反射指有完整神经支配的骨骼肌受外力牵拉时，被牵拉的同一肌肉发生收缩。其感受器为肌梭，腱反射为单突触反射，肌紧张属缓慢持续牵拉引起的牵张反射。"},{"q":"脊髓闰绍细胞轴突末梢释放的递质是","o":["５－羟色胺","谷氨酸","γ－氨基丁酸","甘氨酸","多巴胺"],"a":3,"e":"脊髓闰绍细胞参与回返性抑制，其轴突末梢释放的抑制性递质是甘氨酸。破伤风毒素阻断闰绍细胞释放甘氨酸，士的宁则阻断甘氨酸受体，二者均可致惊厥。"},{"q":"关于心室肌相对不应期的描述，不正确的是","o":["膜内电位为-60mV至-80mV水平","Na+通道大部分已复活","引起期前兴奋所需的刺激阈值高于正常","此期内产生的动作电位时程较长","引起期前兴奋所需的刺激阈值低于正常"],"a":4,"e":"相对不应期膜电位为-60mV至-80mV，Na+通道大部分已复活，兴奋性仍低于正常，引起期前兴奋所需阈上刺激阈值高于正常。此期产生的动作电位时程较短，故“阈值低于正常”不正确。"},{"q":"尿崩症的患者，排出大量低渗尿的始发因素是","o":["下丘脑病变","血管升压素分泌增多","醛固酮分泌增多","远曲小管和集合管上皮细胞V1受体缺乏","垂体病变"],"a":0,"e":"中枢性尿崩症由下丘脑-神经垂体病变使血管升压素合成和释放减少，集合管对水重吸收障碍，排出大量低渗尿。始发因素为下丘脑病变，外源性ADH治疗有效。"},{"q":"心迷走神经节前纤维起源于","o":["脊髓中间外侧柱","脊髓灰质前角","延髓疑核和背核","延髓孤束核","心内神经节"],"a":2,"e":"心迷走神经属副交感神经，其节前神经元胞体位于延髓的迷走神经疑核和背核，节前纤维行走于迷走神经干中，在心脏内神经节换元后支配心脏。"},{"q":"不属于红细胞生理特性和功能的是","o":["可塑变形性","悬浮稳定性","趋化性","渗透脆性","运输氧气和二氧化碳"],"a":2,"e":"红细胞具有可塑变形性、悬浮稳定性和渗透脆性，并运输O2和CO2。趋化性是白细胞朝向化学物质定向运动的特性，不属于红细胞的生理特性。"},{"q":"在实验中，需要运用较强的阈上刺激才可使得心室肌再次兴奋，发生在以下哪一时期","o":["绝对不应期","有效不应期","超常期","局部反应期","相对不应期"],"a":4,"e":"相对不应期时心肌兴奋性已从零恢复但低于正常，需阈上刺激才能引起新的动作电位。绝对不应期与有效不应期兴奋性为零，任何刺激均不能再次兴奋。"},{"q":"下列关于胆盐肠肝循环的叙述，正确的是","o":["胆盐在空肠末端被吸收","每次重吸收约7%","由肝静脉返回肝脏","每次进餐后可循环5～6次","返回的胆盐对肝胆汁分泌有促进作用"],"a":4,"e":"胆盐经回肠黏膜吸收入血，由门静脉返回肝脏，返回的胆盐可刺激肝细胞分泌胆汁，即胆盐的利胆作用。胆盐在回肠末端吸收，每次约95%被重吸收，进餐后可循环2～3次。"},{"q":"对肺牵张反射的叙述，错误的是","o":["是由肺扩张或缩小引起的反射","又称黑–伯反射","在人体平静呼吸时不起重要作用","支气管壁内存在牵张感受器","是调节人体呼吸运动的主要反射"],"a":4,"e":"肺牵张反射包括肺扩张反射和肺萎陷反射，感受器位于支气管和细支气管平滑肌内，平静呼吸时一般不参与呼吸调节，不是调节呼吸运动的主要反射。"},{"q":"丘脑特异投射系统的功能特点是","o":["调节内脏功能","引起特定感觉并激发大脑皮质发出神经冲动","改变大脑皮质兴奋状态","维持机体觉醒状态","协调随意运动"],"a":1,"e":"丘脑特异投射系统点对点投射至大脑皮层特定区域，引起特定感觉，并激发大脑皮层发出传出冲动。维持和改变皮层兴奋状态是非特异投射系统的功能。"},{"q":"关于ABO血型系统遗传规律的叙述，正确的是","o":["A型血和B型血的父母，只能生下来A型血或B型血的孩子","A型血和A型血的父母，只能生下来A型血或O型血的孩子","B型血和B型血的父母，只能生下来B型血的孩子","AB型血和O型血的父母，只能生下来AB型血或O型血的孩子","AB型血和A型血的父母，只能生下来A型血或B型血的孩子"],"a":1,"e":"A型血基因型可为AA或AO，两A型父母可生下O型（OO）子女，故子女血型为A型或O型。AB型与O型父母所生子女为A型或B型，不可能为AB型或O型。"},{"q":"下列关于胰液的叙述，正确的是","o":["每日分泌量约5L","pH为6、8～7、2","在一定范围内，HCO3-浓度与分泌速率成正变关系","无机盐主要由腺泡细胞分泌","胰酶主要由小导管细胞分泌"],"a":2,"e":"胰液中HCO3-由小导管细胞分泌，其浓度随分泌速率增加而升高，最高可达140mmol/L。胰酶由腺泡细胞分泌，每日胰液量约1～2L。"},{"q":"心动周期是指","o":["心脏机械活动周期","心脏生物电活动周期","心音活动周期","心率变化周期","室内压变化周期"],"a":0,"e":"心动周期是心脏一次收缩和舒张构成的机械活动周期，通常指心室的活动周期，其长短与心率成反变关系。"},{"q":"全血的黏滞性主要取决于","o":["血浆蛋白含量","红细胞数量","白细胞数量","红细胞的叠连","NaCl的浓度"],"a":1,"e":"全血的黏滞性主要取决于红细胞数量，红细胞越多黏滞性越大。血浆黏滞性主要取决于血浆蛋白含量。"},{"q":"内环境稳态是指","o":["细胞内液中各种理化因素保持相对稳定","细胞外液中各种理化性质保持相对稳定","细胞内外液中各种理化性质保持相对稳定","血液中各种理化性质保持相对稳定","体液中各种理化性质保持相对稳定"],"a":1,"e":"内环境稳态指细胞外液（血浆和组织间液）的理化性质相对恒定。教材明确内环境即细胞外液，其温度、酸碱度、渗透压及成分保持相对稳定是机体自由独立生存的首要条件。"},{"q":"在浦肯野细胞的人工浸浴液中加入河鲀毒素后给予刺激，强度足够强，作用时间足够长，其动作电位的变化是","o":["产生的动作电位不变","仍然有去极化现象产生，且去极速度变慢","没有动作电位产生","去极化的速度较快","是由于K+内流引起的"],"a":1,"e":"河鲀毒素阻断钠通道，浦肯野细胞0期去极化由快钠流介导，故去极化仍可发生但速度减慢、幅度降低。浦肯野细胞0期去极速率本可达200～800V/s，钠通道阻滞后去极变慢。"},{"q":"盆神经受到损伤时，排尿反射的障碍主要表现为","o":["少尿","多尿","尿失禁","尿潴留","尿频"],"a":3,"e":"盆神经是排尿反射的传出神经，受损后逼尿肌不能收缩，膀胱松弛扩张，大量尿液滞留，表现为尿潴留。尿失禁见于高位脊髓受损而骶部反射弧完好时。"},{"q":"促黑激素的产生部位是","o":["下丘脑促垂体区","下丘脑视上核","下丘脑室旁核","腺垂体","神经垂体"],"a":3,"e":"促黑激素（MSH）由腺垂体中间部细胞分泌，与ACTH等共同来自阿黑皮素原前体。下丘脑视上核、室旁核主要分泌血管升压素和缩宫素。"},{"q":"能够减慢心率，使心电图P-R间期延长的药物可能是","o":["阿托品","普萘洛尔","肾上腺素","去甲肾上腺素","酚妥拉明"],"a":1,"e":"普萘洛尔阻断β受体，减慢心率并减慢房室传导，使PR间期延长。阿托品阻断M受体加快心率，肾上腺素、去甲肾上腺素加快心率，酚妥拉明阻断α受体。"},{"q":"下列关于类固醇激素作用机制的描述，哪一项是错误的","o":["启动DNA转录，促进mRNA形成","诱导新蛋白质生成","直接作用于细胞膜受体","减少新蛋白质的生成","调节基因表达"],"a":2,"e":"类固醇激素为亲脂性，可穿越细胞膜与胞内受体结合，启动DNA转录、促进mRNA形成并诱导新蛋白质生成，从而调节基因表达。直接作用于细胞膜受体的是肽类激素和儿茶酚胺。"},{"q":"第二心音的出现标志着","o":["心室收缩开始","心室舒张开始","心房收缩开始","心房舒张开始","心室射血开始"],"a":1,"e":"第二心音由主动脉瓣和肺动脉瓣关闭引起，标志着心室舒张期的开始。第一心音由房室瓣关闭引起，标志心室收缩开始。"},{"q":"关于顺应性的叙述，错误的是","o":["弹性阻力小，顺应性大","弹性阻力大，顺应性小","不易扩展的组织顺应性大","易扩展的组织顺应性大","肺泡表面活性物质使肺顺应性增加"],"a":2,"e":"顺应性指弹性组织在外力作用下发生变形的难易程度，与弹性阻力成反比：易扩展者顺应性大，不易扩展者顺应性小。肺表面活性物质降低表面张力，使肺顺应性增加。"},{"q":"终尿中的K+主要是由下列哪段肾小管分泌","o":["近端小管","髓袢降支细段","髓袢降支粗段","髓袢升支粗段","远端小管"],"a":4,"e":"K+的排出量主要取决于远端小管和集合管上皮细胞K+的分泌量，该处K+顺化学梯度经钾通道进入小管液，形成终尿中的K+。近端小管以重吸收为主，髓袢各段不是K+分泌的主要部位。"},{"q":"房-室延搁产生的部位在","o":["房室束","结间束","房室交界","窦房结","希氏束"],"a":2,"e":"房室交界（结区）细胞体积小、缝隙连接少，传导速度最慢，兴奋在此延搁约0.1秒，称房-室延搁。房室束及希氏束传导速度快，不是延搁部位。"},{"q":"胆汁中与消化有关的成分是","o":["胆盐","胆色素","胆固醇","脂肪酸","碳酸氢盐"],"a":0,"e":"胆汁中最重要的成分是胆盐，作为乳化剂降低脂肪表面张力，促进脂肪的消化和吸收。胆色素决定胆汁颜色，胆固醇需溶入微胶粒，均非消化相关的主要成分。"},{"q":"血清与血浆的主要区别在于血清中缺乏","o":["纤维蛋白原","纤维蛋白","凝血因子","血小板","Ca2+"],"a":0,"e":"血液凝固过程中纤维蛋白原转变为纤维蛋白并被消耗，故血清与血浆的主要区别是血清中缺乏纤维蛋白原。血清仍含Ca2+，也含凝血过程中血小板释放的物质。"},{"q":"支配汗腺的交感神经节后纤维释放","o":["血管活性肠肽","三磷酸腺苷","去甲肾上腺素","乙酰胆碱","5-羟色胺"],"a":3,"e":"支配汗腺的交感神经节后纤维释放乙酰胆碱，作用于汗腺M受体。多数交感节后纤维释放去甲肾上腺素，汗腺为显著例外。"},{"q":"在日常生活中，看到或听到酸梅时，唾液分泌会增多。其产生机制是","o":["条件反射","非条件反射","体液调节","自身调节","条件反射和非条件反射"],"a":0,"e":"看到或听到酸梅引起唾液分泌，是食物的形状、颜色、气味及言语等信号刺激建立的条件反射。非条件反射由食物直接刺激口腔黏膜引起。"},{"q":"红细胞渗透脆性指的是","o":["红细胞对高渗盐溶液的抵抗力","红细胞在低渗盐溶液中膨胀破裂的特性","红细胞在生理盐溶液中破裂的特性","红细胞耐受机械撞击的能力","红细胞相互撞击破裂的特性"],"a":1,"e":"红细胞在低渗盐溶液中发生膨胀破裂的特性称红细胞渗透脆性，简称脆性。衰老红细胞对低渗盐溶液抵抗力低，即脆性高。"},{"q":"正常眼看6米以外的物体时，在视网膜上形成","o":["小而倒置的虚像","倒置的虚像","小而倒置的实像","倒置的实像","直立的实像"],"a":2,"e":"6米以外物体发出的平行光线经眼折光系统折射后，在视网膜上形成倒置的实像，且物像缩小。安静状态下后主焦点恰位于视网膜。"},{"q":"CO中毒引起的缺氧比Hb减少(贫血)所致的缺氧更严重，这是因为","o":["动脉血PO2降低","血氧容量降低","血氧含量降低","HbO2的O2释放量减少","氧解离曲线右移"],"a":3,"e":"CO中毒时Hb与O2亲和力显著增高，氧解离曲线左移，HbO2在组织中不易释放O2，故组织缺氧比单纯Hb减少更严重。贫血时血氧容量降低，但残存Hb的释氧能力正常。"},{"q":"在心动周期中，下列哪一时期的心室内压最低","o":["等容舒张期末","快速充盈期末","减慢充盈期末","心房收缩期末","等容收缩期末"],"a":1,"e":"快速充盈期心室肌快速舒张，室内压明显降低甚至成为负压，是心动周期中心室内压最低的时期。此期血液因抽吸作用快速流入心室，约占心室总充盈量的2/3。"},{"q":"左心室的搏功比右心室的大，其主要原因是","o":["每搏输出量不同","左、右心室容积不同","体循环和肺循环的血流速度不同","体循环和肺循环的平均动脉压不同","体循环和肺循环的血流途径长短不同"],"a":3,"e":"搏功等于每搏输出量与射血期压力差的乘积。左右心室每搏输出量相等，但体循环平均动脉压远高于肺循环，故左心室搏功大于右心室。"},{"q":"下列受体中，属于门控通道型的有","o":["M受体","N受体","β1受体","α受体","β2受体"],"a":1,"e":"N受体属促离子型受体，即递质门控通道，激活后开放阳离子通道产生N样作用。M受体、α受体和β受体均属G蛋白耦联受体。"},{"q":"尿液流经尿道刺激感受器，使膀胱逼尿肌收缩增强，直至排完尿液是","o":["自身调节","负反馈调节","正反馈调节","神经-体液调节","体液调节"],"a":2,"e":"尿液刺激后尿道感受器，反射性加强排尿中枢活动，使逼尿肌收缩进一步增强，直至尿液排尽，属正反馈调节。正反馈打破原先平衡状态，使系统活动越来越强。"},{"q":"正常情况下，心脏正常的节律来自","o":["窦房结","房室结","希氏束","浦肯野纤维","左右束支"],"a":0,"e":"窦房结P细胞自律性最高，约100次/分，是心脏正常起搏点，由窦房结起搏形成窦性节律。其他自律组织自律性较低，正常情况下仅起兴奋传导作用。"},{"q":"红细胞表面积与体积之比下降可引起红细胞","o":["变形性增强","渗透脆性增大","悬浮稳定性增强","对低渗盐溶液的抵抗力增强","运输氧气的能力增加"],"a":1,"e":"红细胞表面积与体积之比下降时，其变形能力减弱、渗透脆性增大，在低渗盐溶液中更易膨胀破裂。遗传性球形红细胞增多症即因球形红细胞表面积与体积之比降低而脆性变大。"},{"q":"严重丝虫病导致下肢水肿的原因是","o":["血浆胶体渗透压降低","组织液静水压降低","毛细血管通透性增加","毛细血管血压增高","淋巴和（或）静脉回流受阻"],"a":4,"e":"丝虫病或恶性肿瘤淋巴转移可堵塞淋巴管，使淋巴回流受阻，含蛋白质的淋巴液在组织间隙积聚形成淋巴水肿。静脉压升高才是有效流体静压增高的主要成因。"},{"q":"下列糖皮质激素分泌调节的描述中，哪一项是正确的","o":["受神经垂体调节","促肾上腺皮质激素是调节糖皮质激素合成和释放的最重要因素","糖皮质激素的基础分泌不受促肾上腺皮质激素影响","呈现日节律波动，午夜最高，觉醒起床前最低","促肾上腺皮质激素抑制束状带生长"],"a":1,"e":"促肾上腺皮质激素是调节糖皮质激素合成和释放的最重要因素，ACTH促进肾上腺皮质束状带分泌糖皮质激素。糖皮质激素基础分泌也依赖ACTH，且呈日节律波动，觉醒起床前最高、午夜最低。"},{"q":"中性粒细胞吞噬细菌的跨膜物质转运方式属于","o":["易化扩散","继发性主动转运","入胞","原发性主动转运","出胞"],"a":2,"e":"中性粒细胞以伪足包裹细菌形成吞噬泡进入胞内，属于入胞中的吞噬。吞噬仅发生于巨噬细胞和中性粒细胞等特殊细胞，是团块或颗粒形式进入细胞的过程。"},{"q":"下列哪项是甲状腺激素在体内贮存的特点","o":["贮存于细胞外","贮存量不是很大","主要贮存形式是T3、T4","没有贮存的甲状腺激素，需要时合成","主要贮存形式是一碘酪氨酸和二碘酪氨酸"],"a":0,"e":"甲状腺激素以甲状腺胶质形式大量储存于细胞外的甲状腺滤泡腔，甲状腺是唯一能将激素大量储存于细胞外的内分泌腺。储存形式为甲状腺球蛋白上的碘化酪氨酸残基，而非游离T3、T4。"},{"q":"在中脑上、下叠体之间切断脑干的动物，出现四肢伸直、头尾昂起、脊柱挺硬，表现出抗重力肌的肌紧张加强，称为去大脑僵直。其原因是脑干网状结构","o":["抑制区活动增强","易化区活动增强","组织受到破坏","组织受到刺激","出现抑制解除"],"a":1,"e":"切断中脑上、下丘后中断了皮层、纹状体与脑干网状结构的联系，抑制区活动减弱、易化区活动占优势，导致抗重力肌肌紧张增强。经典去大脑僵直属于γ僵直。"},{"q":"去甲肾上腺素释放后在突触间隙被清除的主要方式是","o":["酶促降解","突触前末梢重摄取","进入突触后细胞","胶质细胞摄取","进入细胞外液被带走"],"a":1,"e":"去甲肾上腺素释放后主要被突触前末梢重摄取而清除，三环类抗抑郁药即通过抑制该重摄取发挥作用。乙酰胆碱才是被突触后膜乙酰胆碱酯酶迅速水解清除。"},{"q":"下列能增强肾脏对尿液浓缩稀释的因素是","o":["血中葡萄糖浓度升高","血中血管升压素浓度升高","血中醛固酮浓度升高","血中血管紧张素浓度升高","血中肾素浓度升高"],"a":1,"e":"血管升压素增加内髓部集合管对尿素的通透性并提高集合管对水的通透性，有助于髓质间液高渗形成和水的重吸收，增强肾浓缩稀释能力。醛固酮主要调节Na+、K+排出。"},{"q":"小管液中尿素浓度最高的部位是","o":["近端小管","远端小管","髓袢升支","髓袢降支","内髓部集合管"],"a":4,"e":"内髓部集合管对水重吸收使小管液中尿素浓度不断升高，并经UT-A1/UT-A3扩散至内髓部组织间液参与尿素再循环，故该处尿素浓度最高。"},{"q":"下列物质中，不易通过红细胞膜的是","o":["O2和CO2","尿素","H2O","HCO3-","K+和Na+"],"a":4,"e":"K+和Na+为带电离子，不能自由通过脂质双分子层，需经离子通道或泵转运。O2、CO2、尿素、H2O及HCO3-均可经膜或载体较快通过红细胞膜。"},{"q":"后负荷增大引起肌肉缩短速度减小的原因是","o":["改变初长度","改变最适初长度","横桥周期延长","横桥数目增加","ATP酶活性增加"],"a":2,"e":"后负荷增大时横桥头部摆动速度减慢、横桥周期延长，使每瞬间处于张力状态的横桥数增多，故收缩张力增大而缩短速度减小。张力-速度关系曲线即由此机制形成。"},{"q":"关于等长收缩的叙述，正确的是","o":["收缩过程中不消耗能量","肌节长度明显缩短","没有发生对外做功","多发生在与肢体运动有关的肌肉中","肌肉张力保持不变"],"a":2,"e":"等长收缩时肌肉张力增至最大而长度不变，未发生肌肉缩短，因而不对外做功。等张收缩才表现为张力不变而肌肉缩短。"},{"q":"小儿麻痹症遗留的肢体肌肉萎缩主要是由于","o":["脊髓血液供应不足","神经肌接头部位的兴奋传递功能降低","失去了运动神经对肌肉的营养作用","高位中枢的抑制作用加强","高位中枢对脊髓的易化作用减弱"],"a":2,"e":"脊髓前角运动神经元变性死亡后，肌肉失去神经末梢释放营养因子的营养性作用，糖原合成减慢、蛋白分解加速而逐渐萎缩。此属神经的营养性作用而非功能性作用。"},{"q":"人体造血的主要原料是","o":["铁和维生素B12","维生素B12和叶酸","蛋白质和钙","蛋白质和铁","铁、蛋白质和维生素B6"],"a":3,"e":"蛋白质和铁是合成血红蛋白的重要原料，为红细胞生成的基本物质；叶酸和维生素B12参与红细胞成熟，并非主要原料。"},{"q":"下列关于促胃液素作用的描述，错误的是","o":["促进盐酸大量分泌","抑制肝胆汁分泌","促进胃黏膜生长","促进胃的运动","促进小肠液的分泌"],"a":1,"e":"促胃液素可经血液循环作用于肝细胞引起肝胆汁分泌，并刺激胃酸分泌、促进胃黏膜生长和胃运动，故“抑制肝胆汁分泌”描述错误。"},{"q":"关于睾丸功能的描述，下列哪项是错误的","o":["具有产生精子与雄激素的双重作用","精原细胞产生精子","支持细胞对精子起营养作用","间质细胞产生睾酮","睾丸生精功能与内分泌功能互不影响"],"a":4,"e":"睾丸兼具生精与内分泌功能，且两者相互影响：雄激素维持生精，生精细胞与支持细胞参与调节激素分泌，故“互不影响”错误。"},{"q":"动物实验中，可使家兔呼吸停止的操作是","o":["在延髓和脊髓之间横断","在脑桥上、中部横断","在中脑和脑桥之间横断","切除大脑皮层","在延髓和脑桥之间横断"],"a":0,"e":"呼吸节律起源于低位脑干，在延髓与脊髓之间横断后，呼吸肌失去延髓呼吸中枢的驱动，呼吸运动立即停止。延髓为产生基本呼吸节律的部位。"},{"q":"能引起血液凝固延缓或停止的因素是","o":["将血液收置在表面粗糙的玻璃管中","将血液的温度由20℃升高到37℃","在血液中加入肝素","在血液中加入少许生理盐水","在血中加入纱布块"],"a":2,"e":"肝素是体内重要的抗凝物质，可增强抗凝血酶Ⅲ活性而抑制凝血，故加入肝素使血液凝固延缓。粗糙面、纱布及升温均加速凝血。"},{"q":"下列哪种情况尿量的减少与肾小球滤过率降低无密切关系","o":["入球小动脉阻塞时","大失血时","肾小囊内压升高时","大量出汗时","输尿管堵塞时"],"a":3,"e":"大量出汗丢失的是低渗液体，主要引起血浆晶体渗透压升高和循环血量减少，通过渗透压感受器和容量感受器使抗利尿激素释放增多，尿量减少，与肾小球滤过率降低无密切关系。入球小动脉阻塞、大失血、囊内压升高、输尿管堵塞均直接或间接使有效滤过压下降、滤过率降低。"},{"q":"体液中最活跃的部分是","o":["细胞内液","组织液","血浆","淋巴","脑脊液"],"a":2,"e":"血浆与组织液之间通过毛细血管壁不断进行物质交换，是体液中最活跃的部分。血浆中电解质含量与组织液基本相同，可反映组织液情况；细胞内液、淋巴和脑脊液交换较慢。"},{"q":"离体肾动脉灌流实验发现，当动脉灌注压在80～160mmHg范围内变动时，肾血流量可保持相对稳定。其原因是","o":["肾脏血管无神经支配","肾脏血管无激素调节","肾动脉血流量与全身血压高低无关","肾血流量有自身调节作用","灌注压高低对肾血流量无任何作用"],"a":3,"e":"肾血流量在动脉灌注压70～180mmHg范围内保持相对稳定，属肾血流量的自身调节，可用肌源学说和管-球反馈学说解释。肾脏血管受神经和激素调节，灌注压超出该范围时肾血流量随之改变。"},{"q":"血管平滑肌细胞膜表面，能与普萘洛尔发生特异性结合的是","o":["α受体","β1受体","β2受体","M受体","N受体"],"a":2,"e":"普萘洛尔是非选择性β受体阻断剂，可阻断β1和β2受体，血管平滑肌细胞膜表面存在β2受体，故能与之特异性结合。α受体、M受体和N受体均非普萘洛尔的结合靶点。"},{"q":"属于局部电位的是","o":["终板电位","神经纤维动作电位","窦房结P细胞动作电位","锋电位","后电位"],"a":0,"e":"终板电位是骨骼肌终板膜上ACh使Na+内流产生的去极化电位，不能向远距离传播，属于局部电位。神经纤维动作电位、窦房结P细胞动作电位和锋电位均为可传播的动作电位，后电位是动作电位后的恢复过程。"},{"q":"在心动周期中，主动脉瓣关闭始于","o":["快速射血期初","减慢射血期初","等容舒张期初","快速充盈期初","减慢充盈期初"],"a":2,"e":"等容舒张期初，心室开始舒张、室内压下降，主动脉内血液反流推动半月瓣关闭，此时房室瓣仍关闭，心室成为封闭腔。快速射血期和减慢射血期半月瓣开放，快速充盈期和减慢充盈期房室瓣开放。"},{"q":"在肠道中，与葡萄糖实现联合转运的离子是","o":["Na+","K+","Ca2+","Cl-","H+"],"a":0,"e":"小肠黏膜上皮细胞刷状缘膜的SGLT-1使2个Na+与1分子葡萄糖同向转运入胞，属继发性主动转运，其能量来自钠泵造成的Na+浓度梯度。K+、Ca2+、Cl-和H+均不参与葡萄糖的联合转运。"},{"q":"下列关于胰腺分泌HCO3-的叙述，正确的是","o":["迷走神经兴奋可引起HCO3-大量分泌","缩胆囊素可引起HCO3-大量分泌","HCO3-由胰腺内腺泡细胞分泌","可防止胃酸对十二指肠黏膜的侵蚀","生长抑素可促进HCO3-分泌"],"a":3,"e":"胰液中的HCO3-由胰腺小导管上皮细胞分泌，主要作用是中和进入十二指肠的胃酸，保护肠黏膜并提供小肠消化酶的最适pH环境。迷走神经和缩胆囊素主要促进胰酶分泌，生长抑素抑制胰液分泌。"},{"q":"下列哪一项是缩宫素的主要生理作用","o":["刺激输卵管收缩","抑制乳汁分泌","促进子宫平滑肌收缩","促进非孕子宫舒张","发动分娩子宫收缩的决定因素"],"a":2,"e":"缩宫素的主要生理作用是促进子宫平滑肌收缩，分娩时引发子宫强烈收缩，哺乳期促进乳腺排乳。其对妊娠末期子宫作用强，低剂量引起节律性收缩，高剂量导致强直性收缩。"},{"q":"与血液凝固密切相关的血浆成分是","o":["氯化钠","葡萄糖","白蛋白","球蛋白","纤维蛋白原"],"a":4,"e":"血液凝固的实质是血浆中可溶性纤维蛋白原转变为不溶性纤维蛋白，交织成网形成血凝块。纤维蛋白原是凝血过程的核心底物，故与血液凝固密切相关。"},{"q":"以下关于1，25-二羟维生素D3的描述中，哪一项是正确的","o":["作用靶点在骨、肾和大肠","主要在肝脏由7-脱氢胆固醇转化生成","在血浆中以游离状态存在","促进小肠黏膜对钙的吸收，抑制小肠对磷的吸收","促进肾小管对钙、磷的重吸收"],"a":4,"e":"1，25-二羟维生素D3能协同PTH促进肾小管重吸收钙，并拮抗PTH对肾小管重吸收磷的抑制作用，使钙、磷从尿中排泄减少。其靶点不包括大肠，主要在肝外生成且需转运蛋白。"},{"q":"人唾液中除含有唾液淀粉酶外，还含有下列哪种酶","o":["蛋白水解酶","肽酶","溶菌酶","脂肪酶","麦芽糖酶"],"a":2,"e":"唾液中含有唾液淀粉酶和溶菌酶，后者与免疫球蛋白共同具有杀菌和杀病毒作用，保护清洁口腔。唾液淀粉酶水解淀粉为麦芽糖，并非麦芽糖酶。"},{"q":"脊髓前角运动神经元轴突末梢释放的递质是","o":["５－羟色胺","去甲肾上腺素","乙酰胆碱","多巴胺","γ-氨基丁酸"],"a":2,"e":"脊髓前角运动神经元属胆碱能神经元，其轴突末梢释放乙酰胆碱，作用于骨骼肌终板膜N2型乙酰胆碱受体引起肌肉收缩。去甲肾上腺素为交感神经末梢递质。"},{"q":"关于卵巢功能的调节，下列哪一项描述是错误的","o":["受下丘脑-腺垂体-卵巢轴的影响","下丘脑分泌促性腺激素释放激素刺激腺垂体分泌促卵泡激素和黄体生成素","促卵泡激素和黄体生成素刺激卵巢分泌雌激素和孕激素","雌激素和孕激素对下丘脑和腺垂体都只有负反馈的调节作用","卵巢功能活动的周期性变化包括卵子的生成和激素水平两个方面"],"a":3,"e":"雌激素和孕激素对下丘脑及腺垂体以负反馈调节为主，但排卵期高浓度雌激素对下丘脑及腺垂体起正反馈调节作用，故“只有负反馈”的描述错误。"},{"q":"接受同一人的血液，第二次输血时才出现输血反应见于","o":["A型或B型","O型或AB型","Rh阴性血型","Rh阳性血型","A型的不同亚型之间"],"a":2,"e":"Rh阴性者血清中不存在抗Rh天然抗体，首次接受Rh阳性血液后经免疫产生抗Rh抗体，再次输入Rh阳性血才发生溶血性输血反应。ABO血型天然抗体首次输血即可反应。"},{"q":"心室肌细胞动作电位的膜电位接近与Na+平衡电位，是下列哪一时相","o":["阈电位","极化倒转最大值","动作电位1期","动作电位平台期","最大复极电位"],"a":1,"e":"心室肌细胞动作电位0期去极化由Na+内流形成，膜电位快速上升直至接近Na+平衡电位，即极化倒转最大值。平台期由Ca2+内流与K+外流共同形成。"},{"q":"身处海拔3000米的高原，自觉呼吸困难，这主要是由于","o":["血氧容量下降","Hb含量减少","血氧饱和度下降","血液供应不足","动脉血氧分压升高"],"a":2,"e":"高原吸入气PO2降低使动脉血PO2下降，Hb氧饱和度随之降低，血液携氧减少而出现呼吸困难。教材指出PO2降至60mmHg时Hb氧饱和度约90%，低于此值则明显下降。血氧容量取决于Hb含量，并非首要改变。"},{"q":"中枢温度敏感神经元分布最多的部位在","o":["延髓","脊髓","大脑皮层运动区","脑干网状结构","下丘脑"],"a":4,"e":"视前区-下丘脑前部（PO/AH）是体温调节的基本中枢，此处温度敏感神经元分布最集中，其中热敏神经元居多。下丘脑、脑干网状结构和脊髓虽也含温度敏感神经元，但数量较少。"},{"q":"支配肌梭的神经纤维属于","o":["Aα纤维","Aβ纤维","Aγ纤维","Aδ纤维","B类纤维"],"a":2,"e":"肌梭的传出神经纤维为γ运动神经元发出的Aγ纤维，支配梭内肌纤维收缩成分，调节肌梭敏感性；其传入纤维为Ⅰa和Ⅱ类纤维。α运动神经元发出的Aα纤维支配梭外肌。"},{"q":"肾小管重吸收葡萄糖的部位在","o":["髓袢降支","髓袢升支","近端小管","远端小管","集合管"],"a":2,"e":"葡萄糖重吸收全部发生在近端小管，尤其前半段，经SGLT与Na+耦联转运，超过肾糖阈时出现尿糖。髓袢、远端小管和集合管不重吸收葡萄糖。"},{"q":"人体生理学的任务是阐明","o":["细胞的生命现象","器官的功能活动","人体与环境相互关系","正常生命活动及规律","生物的生命现象"],"a":3,"e":"人体生理学是研究人体功能活动及其规律的科学，其任务是阐明正常生命活动现象、规律及内在机制。细胞、器官功能活动只是其研究层面之一，不能概括整体任务。"},{"q":"大多数可兴奋细胞接受刺激发生反应的共有表现是产生","o":["神经冲动","收缩","分泌","动作电位","局部电位"],"a":3,"e":"现代生理学将神经细胞、肌细胞和腺细胞等可兴奋细胞接受刺激后产生动作电位的现象称为兴奋，动作电位是各类可兴奋细胞共同的反应表现。神经冲动、收缩、分泌分别是神经、肌、腺细胞的特殊表现。"},{"q":"以每平方米体表面积的产热量来衡量，下述哪项不是影响能量代谢的因素","o":["体重","环境温度","肌肉运动","精神紧张程度","食物"],"a":0,"e":"能量代谢率与体表面积成正比，故以单位体表面积产热量衡量时个体间差异很小，体重不成为影响因素。环境温度、肌肉运动、精神紧张和食物特殊动力效应均影响能量代谢。"},{"q":"下列由小肠腺分泌的酶是","o":["肠淀粉酶","肠脂肪酶","肠激酶","胆固醇酯酶","核糖核酸酶"],"a":2,"e":"小肠腺分泌肠激酶，可特异性激活胰液中的胰蛋白酶原，使之转变为有活性的胰蛋白酶。肠淀粉酶、肠脂肪酶及胆固醇酯酶、核糖核酸酶均非小肠腺分泌。"},{"q":"肺活量是指","o":["自然呼吸时，一次呼出或吸入的气量","尽力吸气后能尽力呼出的气量","每分钟吸入或呼出的气量","平静呼气后再尽力呼出的气量","平静吸气后再尽力吸入的气量"],"a":1,"e":"肺活量是尽力吸气后从肺内所能呼出的最大气体量，反映一次呼吸的最大通气能力。平静呼气后再尽力呼出为补呼气量，平静吸气后再尽力吸入为补吸气量。"},{"q":"以下跨膜信号转导途径中，信号传递速度最快的是","o":["G蛋白偶联受体","酪氨酸激酶受体","酪氨酸激酶结合型受体","鸟苷酸环化酶受体","离子通道型受体"],"a":4,"e":"离子通道型受体被配体激活后通道开放，从递质结合到产生电位变化仅需0.5毫秒，路径简单、速度快，适于神经电信号快速传递。G蛋白耦联受体等需经级联反应，速度较慢。"},{"q":"测定基础代谢率时的基础状态不包括下列哪一项","o":["空腹","无体力活动和精神紧张","环境温度20～25℃","清醒","深睡状态"],"a":4,"e":"基础状态要求清醒、空腹、无肌肉活动和精神紧张，环境温度20～25℃。熟睡时能量代谢率进一步降低，不属于基础状态。"},{"q":"EPSP的产生是由于突触后膜提高了下列哪些离子的通透性","o":["Ca2+、Na+，尤其是Ca2+","K+、Na+，尤其是K+","Na+、K+，尤其是Na+","Na+、Cl-、，尤其是Na+","Na+、Cl-，尤其是Cl-"],"a":2,"e":"EPSP由突触后膜对Na+、K+通透性增加引起，静息时Na+内向驱动力大于K+外向驱动力，故以Na+内流为主，产生去极化。"},{"q":"下列关于胃酸分泌的描述，错误的是","o":["分泌过程是耗能过程","质子泵在H+分泌中起关键作用","壁细胞分泌盐酸增多时，血浆pH值将下降","H+的分泌与K+的细胞内转运相偶联","由壁细胞分泌"],"a":2,"e":"壁细胞分泌H+入胃腔的同时，HCO3-进入血液，故大量泌酸时血浆HCO3-升高、pH不下降，此描述错误。泌酸依靠质子泵耗能主动转运，H+与K+转运偶联。"},{"q":"胃内含有消化蛋白质的胃蛋白酶，且处于一个强酸的环境，而胃不会被自身消化。这种胃黏膜自我保护机制与下列哪一个屏障作用有关","o":["碳酸氢盐屏障","凝胶保护层","细胞屏障","黏液-碳酸氢盐屏障","黏液屏障"],"a":3,"e":"胃黏膜非泌酸细胞分泌的HCO3-与表面黏液联合形成黏液-碳酸氢盐屏障，保护胃黏膜免受盐酸和胃蛋白酶损伤。"},{"q":"下列关于神经纤维轴浆运输的描述，错误的是","o":["平时不断进行","有顺向和逆向运输","有快速和慢速运输","不直接消耗ATP","为神经元活动和存活所必需"],"a":3,"e":"轴浆运输是轴突内物质的转运过程，快速轴浆运输需消耗ATP，并非不耗能。轴浆运输平时不断进行，有顺向和逆向、快速和慢速之分，为神经元活动和存活所必需。"},{"q":"贫血时血氧指标的变化是","o":["血氧容量不变，血氧饱和度下降","血氧容量和血氧含量均下降","血氧容量不变，血氧含量下降","动脉血氧分压下降","动脉血氧分压升高"],"a":1,"e":"血氧容量取决于Hb浓度，贫血时Hb减少使血氧容量和血氧含量均下降。动脉血氧分压反映吸入气与肺换气，贫血时正常；血氧饱和度主要取决于PO2。"},{"q":"提高自律细胞自律性的因素是","o":["最大复极电位绝对值减小","阈电位水平上移","4期自动去极化速度增快","最大复极电位水平下降","0期去极化速度增快"],"a":2,"e":"4期自动去极化速度是决定自律性最重要的因素，速度增快使达到阈电位所需时间缩短，自律性升高。最大复极电位绝对值减小或阈电位上移均使二者差距缩小，自律性升高，但非最主要因素。"},{"q":"交感缩血管神经过度兴奋时，对下列哪一器官的血管收缩作用最强","o":["骨骼肌","皮肤","心脏","脑","肝脏"],"a":1,"e":"交感缩血管纤维分布密度以皮肤血管最大，其次为骨骼肌和内脏，冠状血管和脑血管最小，故过度兴奋时皮肤血管收缩作用最强。"},{"q":"用毒毛花苷G抑制钠泵活动后，细胞功能发生的变化有","o":["静息电位绝对值增大","动作电位幅度降低","Na+-Ca2+交换增加","细胞质渗透压降低","动作电位幅度增大"],"a":1,"e":"毒毛花苷G抑制钠泵使细胞内Na+增多、膜内外Na+浓度差减小，动作电位0期Na+内流减少，幅度降低。钠泵受抑使生电作用减弱，静息电位绝对值减小而非增大。"},{"q":"关于钠泵的表述，错误的是","o":["具有ATP酶活性","能帮助Na+从细胞膜外进入膜内","属于二聚体蛋白质","对细胞生物电的产生具有重要意义","参与细胞正常体积的维持"],"a":1,"e":"钠泵每分解一分子ATP将3个Na+移出胞外、2个K+移入胞内，故其作用是逆浓度差将Na+排出细胞，而非帮助Na+从膜外进入膜内。钠泵属二聚体蛋白质，具ATP酶活性，参与生物电产生和细胞体积维持。"},{"q":"慢性肾功能衰竭大多数患者有轻度、中度贫血，其原因与肾脏哪种激素分泌有关","o":["肾素","血管紧张素Ⅱ","醛固酮","前列腺素","促红细胞生成素"],"a":4,"e":"肾脏合成和释放促红细胞生成素，刺激红细胞生成；慢性肾衰竭时EPO生成减少，导致贫血。肾素、血管紧张素Ⅱ和醛固酮主要参与血压调节。"},{"q":"促进女性青春期乳腺发育的最主要的激素是下列哪一种","o":["生长激素","催乳素","雌激素","催产素","甲状腺激素"],"a":2,"e":"青春期女性乳腺发育主要依赖生长激素对乳腺间质和脂肪组织的作用，雌激素与孕激素在青春期起基础促进作用。催乳素主要作用于妊娠期乳腺腺泡发育及泌乳。"},{"q":"气体扩散速率与下列因素的关系是","o":["分压差小则扩散快","与各气体分子量的平方根成正比","与扩散面积成反比","与温度成反比","与溶解度成正比"],"a":4,"e":"气体扩散速率与气体在溶液中的溶解度成正比，与分压差、温度、扩散面积成正比，与扩散距离和分子量平方根成反比。"},{"q":"肺功能衰竭患者往往缺O2显著，CO2潴留不明显，其原因是","o":["CO2的分子量比O2的分子量大","肺泡毛细血管血液与肺泡之间的O2分压差大于CO2分压差","O2的溶解度大于CO2的溶解度","肺泡毛细血管血液与肺泡之间的CO2分压差大于O2分压差","CO2的扩散系数是O2的20倍"],"a":4,"e":"CO2在血浆中的溶解度约为O2的24倍，其扩散系数约为O2的20倍，故CO2扩散比O2快，不易潴留，患者缺氧显著而CO2潴留不明显。"},{"q":"引起伤害性感受器兴奋的致痛物质是","o":["Na+、Cl-","二氧化碳","乙酰胆碱","缓激肽","一氧化氮"],"a":3,"e":"缓激肽是损伤区经激肽释放酶作用生成的致痛物质，可直接激活伤害性感受器或降低其激活阈值。Na+、Cl-为离子，二氧化碳、乙酰胆碱、一氧化氮均非教材所列致痛物质。"},{"q":"B型血中的红细胞与A型血的血清相混，将发生的现象是","o":["红细胞聚集","红细胞凝集","红细胞叠连","血液凝固","红细胞吞噬"],"a":1,"e":"B型红细胞含B凝集原，A型血清含抗B凝集素，两者相遇发生抗原-抗体反应，红细胞凝集成簇，即红细胞凝集。红细胞叠连是红细胞沉降的机制，与凝集本质不同。"},{"q":"能将蛋白质分子有选择性地转运到细胞内的物质转运方式是","o":["载体介导的易化扩散","原发性主动转运","继发性主动转运","液相入胞","受体介导入胞"],"a":4,"e":"受体介导入胞是被转运物与膜受体特异性结合后选择性进入细胞的方式，转铁蛋白、LDL等大分子蛋白质即以此方式转运。液相入胞对底物无选择性，载体介导易化扩散和主动转运主要转运小分子或离子。"},{"q":"下列生理或病理过程属于正反馈的是","o":["体位由平卧转变为直立时，通过压力感受性反射使血压回升","激素水平降低时，其与相应受体的亲和力及受体的表达数量均增加","大失血使血压降低，心脏血供不足，心输出量减少而进一步降低血压","应激反应中，血中ACTH和肾上腺糖皮质激素水平持续升高","有关寒冷信息通过视、听等感觉传入中枢即引起产热增加"],"a":3,"e":"应激时下丘脑CRH分泌增加，促进腺垂体释放ACTH，ACTH再促进肾上腺皮质分泌糖皮质激素，使血中ACTH和糖皮质激素水平持续升高，属正反馈。压力感受性反射使血压回升属负反馈。"},{"q":"胃酸分泌过多可导致胃溃疡，引起胃疼痛，服用雷尼替丁后可以缓解。其机制是下列的哪一项","o":["阻断M受体，使胃酸分泌减少","使胃平滑肌舒张","阻断H2受体，使胃酸分泌减少","阻断氢泵的作用，使胃酸分泌减少","使生长抑素分泌增多"],"a":2,"e":"雷尼替丁为H2受体阻断剂，阻断组胺与壁细胞H2受体结合，减少胃酸分泌，从而缓解溃疡疼痛。奥美拉唑才是抑制质子泵的药物。"},{"q":"关于神经纤维动作电位产生机制的叙述，错误的是","o":["加大细胞外Na+浓度，动作电位幅度会减小","其去极过程是由于Na+内流形成的","其复极过程是由于K+外流形成的","膜电位去极到阈电位时Na+通道迅速大量开放","该动作电位的形成与Ca2+无关"],"a":0,"e":"动作电位幅度取决于Na+内流，细胞外Na+浓度加大时Na+内流增多，动作电位幅度增大而非减小。去极由Na+内流形成，复极由K+外流形成，去极达阈电位时Na+通道大量开放。"},{"q":"在兴奋收缩耦联过程中起主要媒介作用的离子是","o":["Na+","K+","Cl-","Ca2+","Mg2+"],"a":3,"e":"兴奋-收缩耦联中Ca2+是起主要媒介作用的离子，胞质Ca2+浓度升高触发肌丝滑行引起收缩。心肌细胞兴奋时细胞外Ca2+内流并触发肌质网释放Ca2+，即钙致Ca2+释放。"},{"q":"心电图中代表两心室去极化和复极化的时间是","o":["P-P间期","S-T段","P-R间期","Q-T间期","R-R间期"],"a":3,"e":"QT间期从QRS波起点到T波终点，代表心室开始去极化到完全复极化所经历的时间。P波反映心房去极化，PR间期反映心房去极至心室开始去极的时间。"},{"q":"下述关于浦肯野细胞起搏离子流If的描述，哪一项是错误的","o":["由于超极化而激活","阈电位约为-50mV","充分激活的膜电位为-100mV","可被铯所阻断","是钙离子流"],"a":4,"e":"If为超极化激活的内向离子流，主要由Na+负载，而非钙离子流。其充分激活电位约-100mV，可被铯阻断，阈电位约-50mV。"},{"q":"渗透性利尿的直接机制是","o":["血浆晶体渗透压升高","肾小球滤过率增加","血浆胶体渗透压升高","肾小管和集合管对水的通透性降低","肾小管和集合管内小管液溶质浓度增加"],"a":4,"e":"小管液中溶质未被重吸收使小管液溶质浓度升高，渗透压增大，水重吸收减少而尿量增多，即渗透性利尿。其直接机制是小管液溶质浓度增加产生的渗透作用。"},{"q":"兴奋性突触后电位属于","o":["静息电位","去极化性电紧张电位","动作电位","阈电位","超极化性电紧张电位"],"a":1,"e":"兴奋性突触后电位是递质使后膜对Na+等通透性增大而产生的去极化电位，属局部电位，具有电紧张电位性质，为去极化性电紧张电位。"},{"q":"肾脏不能分泌的激素是","o":["血管紧张素Ⅱ","促红细胞生成素","肾素","羟化维生素D3","前列腺素"],"a":0,"e":"血管紧张素Ⅱ由血管紧张素Ⅰ在血管紧张素转换酶作用下生成，肾脏可分泌肾素、促红细胞生成素、前列腺素并羟化维生素D3，但不分泌血管紧张素Ⅱ。"},{"q":"心交感神经调节心脏活动时，跨膜信号转导过程中数量增多的第二信使是","o":["cAPM","cGMP","IP3","DG","Ca2+"],"a":0,"e":"心交感神经末梢释放去甲肾上腺素，作用于心肌β1受体，经G蛋白激活腺苷酸环化酶使cAMP生成增多，cAMP作为第二信使发挥调节作用。"},{"q":"在各段肾小管中，重吸收量占首位的部位是","o":["髓袢升支粗段","髓袢升支细段","近端小管","远曲小管","集合管"],"a":2,"e":"近端小管是Na+、Cl-和水重吸收的主要部位，约65%～70%的Na+、Cl-和水在此被重吸收，重吸收量居各段肾小管之首。"},{"q":"下列物质中与肾外髓部高渗梯度形成有关的是","o":["氯化钠","氯化钾","尿素","葡萄糖","肌酐"],"a":0,"e":"髓袢升支粗段主动重吸收NaCl而对水不通透，增加外髓部组织间液渗透压，是形成外髓部高渗梯度的主要物质和起始动力。"},{"q":"关于G蛋白耦联受体的叙述，错误的是","o":["本身不具备酶的活性","是膜受体中最大的家族","可直接激活腺苷酸环化酶","是一种7次跨膜受体","本身不具备通道结构，但可通过第二信使调控离子通道的活动"],"a":2,"e":"G蛋白耦联受体本身无酶活性，通过活化G蛋白再激活腺苷酸环化酶生成cAMP，属7次跨膜受体，可经第二信使调控离子通道。"},{"q":"甲状腺滤泡上皮细胞的聚碘作用是通过继发性主动转运实现的，抑制下列哪项功能活动可以导致甲状腺的聚碘障碍","o":["I-通道","钠泵","钠-碘交换体","钠-钙交换体","质子泵"],"a":1,"e":"碘捕获由基底膜钠碘同向转运体介导，属继发性主动转运，其能量来自钠泵活动建立的Na+电化学梯度。哇巴因抑制钠泵后，NIS活动减弱，聚碘障碍。"},{"q":"肾脏维持水平衡的功能主要靠调节下列哪项活动来实现","o":["肾小球滤过量","肾小管的分泌功能","近曲小管的重吸收水量","远曲小管与髓袢的重吸收水量","远曲小管与集合管的重吸收水量"],"a":4,"e":"远曲小管和集合管对水的重吸收受抗利尿激素调节，可根据机体水盐平衡状况改变，是维持水平衡的主要调节部位。近端小管重吸收水量呈等渗性重吸收，不受调节。"},{"q":"临床上，采用质子泵抑制剂治疗急性胰腺炎的主要机制是","o":["减少促胰液素的分泌","增加缩胆囊素的分泌","减少生长抑素的分泌","兴奋迷走神经","兴奋交感神经"],"a":0,"e":"质子泵抑制剂抑制胃酸分泌，使十二指肠黏膜释放促胰液素减少，从而减少胰液分泌，减轻胰腺自身消化。促胰液素主要促进胰腺分泌水和HCO3-。"},{"q":"生理情况下，肾小球的滤过分数约为","o":["10%","20%","30%","40%","50%"],"a":1,"e":"滤过分数为肾小球滤过率与肾血浆流量之比，正常约为125/660，即约20%。"},{"q":"以下哪种肌肉肌细胞间存在的缝隙连接最少","o":["膀胱","消化道","睫状肌","小血管平滑肌","子宫平滑肌"],"a":2,"e":"睫状肌属多个单位平滑肌，肌细胞间几乎不含缝隙连接，以单个肌细胞为单位活动。膀胱、消化道、子宫及小血管平滑肌多为单个单位平滑肌，缝隙连接丰富。"},{"q":"属于负反馈调节的生理过程有","o":["分娩过程","排尿反射","减压反射","血液凝固","射乳反射"],"a":2,"e":"减压反射即压力感受性反射，属典型负反馈调节，对动脉血压短期稳定有重要意义。分娩、排尿、射乳及血液凝固均为正反馈。"},{"q":"副交感神经节后纤维释放的递质是","o":["ACh","NE","5-HT","ACh和NE","NE和5-HT"],"a":0,"e":"副交感神经节后纤维主要释放乙酰胆碱，作用于M受体；少数肽能纤维释放血管活性肠肽等肽类递质。去甲肾上腺素为交感神经节后纤维递质。"},{"q":"关于胃排空的叙述，下列哪一项不正确","o":["混合性食物在进餐后4～6小时完全排空","糖类食物排空最快，蛋白质最慢","胃的蠕动是胃排空的动力","迷走神经兴奋促进胃排空","液体食物排空速度快于固体食物"],"a":1,"e":"三大营养物质中糖类排空最快，蛋白质次之，脂肪最慢，故“蛋白质最慢”表述错误。混合性食物完全排空约需4～6小时，胃蠕动为排空动力，迷走神经兴奋促进排空。"},{"q":"动物实验中，在气管插管外口连接一根1、0m长的橡皮管，观察到动物呼吸加深加快，其主要原因是","o":["肺牵张反射增强","动脉血中PO2升高","动脉血中pH值升高","气道阻力增加","动脉血中PCO2升高"],"a":4,"e":"正确答案是动脉血中PCO2升高。气管插管外口连接1.0m长橡皮管使气道阻力增大、肺泡通气量减少，CO2排出受阻而蓄积，动脉血PCO2升高，经中枢和外周化学感受器使呼吸加深加快。"},{"q":"关于致密斑的描述正确的是","o":["位于近端小管的起始部","是感受Na+含量变化的感受器","是肾素的分泌细胞","可调节血管升压素的释放","是晶体渗透压感受器"],"a":1,"e":"正确答案是感受Na+含量变化的感受器。致密斑位于远曲小管起始部，能感受流经该处小管液的NaCl量，是肾内机制的感受器之一。肾素由球旁细胞分泌，致密斑并非分泌细胞。"},{"q":"一般血型抗原都是红细胞膜上的","o":["糖原","蛋白质","磷脂","脂蛋白","糖脂或糖蛋白"],"a":4,"e":"正确答案是糖脂或糖蛋白。ABO血型抗原的特异性决定于红细胞膜上糖蛋白或糖脂所含的糖链，糖链中一个糖基的差别即可决定A型与B型抗原的不同。"},{"q":"可以被兴奋性G蛋白（Gs）激活的是","o":["磷酸二酯酶","腺苷酸环化酶","鸟苷酸环化酶","磷脂酶C","蛋白激酶A"],"a":1,"e":"正确答案是腺苷酸环化酶。激素作为第一信使与膜受体结合后，通过活化的Gs蛋白激活腺苷酸环化酶，催化ATP生成cAMP。蛋白激酶A是cAMP的下游效应酶，并非Gs直接激活的酶。"},{"q":"心输出量是指","o":["每搏输出量","左右心室输出的总血液量","每分钟左心室所泵出的血量","心房进入心室的血量","每分钟两心房进入心室的血量"],"a":2,"e":"正确答案是每分钟左心室所泵出的血量。心输出量指一侧心室每分钟射出的血液量，等于心率与搏出量的乘积，左右心室心输出量基本相等。"},{"q":"肾小管中，重吸收Na+最多的部位是","o":["近端小管","髓袢降支","髓袢升支","远端小管","集合管"],"a":0,"e":"正确答案是近端小管。小管液中65%～70%的Na+、Cl-和水在近端小管被重吸收，近端小管是Na+、Cl-和水重吸收的主要部位。"},{"q":"对于氧解离曲线的描述，正确的是","o":["氧解离曲线的纵轴可以用血液中氧气的浓度来表示","曲线上段和中段主要反映Hb与O2的结合","曲线下段反映Hb与O2的解离","PO2逐渐升高，血氧含量也直线增加","氧解离曲线受多种因素的影响可以发生上移或下移的变化"],"a":2,"e":"正确答案是曲线下段反映Hb与O2的解离。下段相当于PO2 15～40mmHg，曲线最陡直，PO2稍降即引起Hb氧饱和度明显下降，反映血液供O2的储备。曲线上段平坦，PO2升高时血氧含量并非直线增加。"},{"q":"下列关于心率的描述，错误的是","o":["正常人安静时为60～100次/分","新生儿心率较成年人慢","女性心率比男性稍快","运动员平时心率较慢","妊娠、甲亢病人心率较快"],"a":1,"e":"正确答案是新生儿心率较成年人慢。新生儿心率较快，随年龄增长逐渐减慢，至青春期接近成年人水平。成年人安静时心率60～100次/分，女性稍快于男性，运动员平时心率较慢。"},{"q":"内源性凝血与外源性凝血的主要区别在于","o":["有无血小板参与","有无Ca2＋参与","凝血酶原激活过程","纤维蛋白形成过程","凝血因子Ⅹ的激活过程"],"a":4,"e":"凝血因子Ⅹ的激活过程是两条途径的主要区别：内源性途径由血液与带负电荷异物表面接触启动，经FⅫ、Ⅺ、Ⅸ、Ⅷ激活FⅩ；外源性途径由组织因子与FⅦ结合激活FⅩ。生成FⅩa后到纤维蛋白形成的过程为共同途径，故纤维蛋白形成过程并非区别点。"},{"q":"推测膜蛋白肽链中可能存在的跨膜α螺旋数目，其主要依据是肽链中所含有的","o":["氨基酸总数目","疏水性氨基酸数目","亲水性氨基酸数目","疏水性氨基酸片段数目","亲水性氨基酸片段数目"],"a":3,"e":"跨膜α螺旋由疏水性氨基酸残基组成，其数目取决于肽链中疏水性氨基酸片段的数目，每个疏水片段对应一个跨膜螺旋。视蛋白含7个螺旋区穿过膜盘膜结构即为依据。"},{"q":"骨骼肌发生等张收缩时，长度不发生改变的结构是","o":["肌原纤维","肌小节","H带","暗带","明带"],"a":3,"e":"肌丝滑行学说指出，收缩时粗肌丝和细肌丝本身长度不变，暗带宽度不变，只有明带和H带相应变窄。故长度不发生改变的结构是暗带。"},{"q":"下列关于冠脉循环解剖特点的叙述，正确的是","o":["冠脉开口于肺动脉根部","冠脉小分支以垂直方向穿入心肌","冠脉易在心肌舒张时被压迫","心肌毛细血管网分布较少","冠脉侧支血流量丰富"],"a":1,"e":"冠脉小分支常以垂直于心脏表面的方向穿入心肌，故心肌收缩时易受压迫。冠脉开口于升主动脉根部，心肌毛细血管密度高，毛细血管数与心肌纤维数之比可达1∶1。"},{"q":"能阻断终板膜上胆碱能受体的是","o":["有机磷","筒箭毒","普萘洛尔","氯吡格雷","河豚毒素"],"a":1,"e":"筒箭毒碱可特异性阻断终板膜上的N2型乙酰胆碱受体阳离子通道，使骨骼肌松弛。有机磷抑制胆碱酯酶，河豚毒素阻断钠通道，均非受体阻断剂。"},{"q":"凝血酶的主要作用是","o":["加速凝血因子Ⅶ复合物的形成","加速凝血酶原酶复合物的形成","激活凝血因子Ⅰ","激活凝血因子Ⅻ","促进血小板聚集"],"a":2,"e":"凝血酶的主要作用是使纤维蛋白原（凝血因子Ⅰ）转变为纤维蛋白，并参与血小板聚集。凝血酶原酶复合物生成凝血酶，而非凝血酶加速其形成。"},{"q":"以下属于单个单位平滑肌的是","o":["竖毛肌","睫状肌","输尿管","虹膜肌","大血管平滑肌"],"a":2,"e":"单个单位平滑肌细胞间存在大量缝隙连接，全部肌细胞作为功能合胞体活动，输尿管、消化道、子宫等属此类。竖毛肌、睫状肌、虹膜肌及大血管平滑肌为多单位平滑肌。"},{"q":"女性月经周期中，体温最低的时间是","o":["月经期","排卵前","排卵后","排卵日","增殖期"],"a":3,"e":"育龄期女性基础体温在卵泡期较低，排卵日最低，排卵后升高0.3～0.6℃，故体温最低的时间为排卵日。"},{"q":"副交感神经对代谢的影响是","o":["促进甲状旁腺素分泌","促进胰高血糖素分泌","促进糖原分解","促进胰岛素分泌","促进甲状腺激素的释放"],"a":3,"e":"副交感神经兴奋时释放乙酰胆碱，作用于胰岛β细胞膜M受体，直接促进胰岛素分泌。迷走神经还可通过刺激胃肠激素分泌间接促进胰岛素分泌。"},{"q":"肾小球有效滤过压等于","o":["肾小囊内压-（肾小球毛细血管血压+血浆胶体渗透压）","肾小囊内压-（肾小球毛细血管血压-血浆胶体渗透压）","血浆胶体渗透压-（肾小球毛细血管血压+肾小囊内压）","肾小球毛细血管血压-（肾小囊内压+血浆胶体渗透压）","肾小球毛细血管血压-肾小囊内压+血浆胶体渗透压"],"a":3,"e":"肾小球有效滤过压是滤过力与重吸收力之差，即肾小球毛细血管血压减去肾小囊内压与血浆胶体渗透压之和。肾小囊内液胶体渗透压接近于0，可忽略不计。"},{"q":"静息电位的数值（绝对值）变大称作","o":["极化","去极化","复极化","超极化","反极化"],"a":3,"e":"膜电位负值增大、极化状态增强的过程称为超极化。去极化是膜电位负值减小，复极化是去极化后向静息电位恢复的过程。"},{"q":"可使心室肌兴奋性增高的因素是","o":["Na+通道少量失活","静息电位绝对值加大","阈电位下移","细胞外液Ca2+浓度增加","Na+通道处于备用状态"],"a":2,"e":"阈电位下移使其与静息电位差距缩短，引起兴奋所需刺激减小，心室肌兴奋性增高。静息电位绝对值加大则差距增大，兴奋性降低。"},{"q":"可兴奋细胞包括","o":["神经元、骨骼肌细胞、角质上皮细胞","肌细胞、腺细胞、角质上皮细胞","神经元、腺细胞、骨细胞","神经元、骨骼肌细胞、心肌细胞","神经元、骨骼肌细胞、骨细胞"],"a":3,"e":"可兴奋细胞指受刺激后能产生动作电位的细胞，包括神经元、骨骼肌细胞和心肌细胞。腺细胞主要产生分泌活动，角质上皮细胞和骨细胞不能产生动作电位。"},{"q":"肾交感神经兴奋时，下列说法正确的是","o":["入球小动脉收缩幅度小于出球小动脉的收缩幅度","可减弱近端小管对水和氯化钠的通透性","可使有效滤过压增加","引起球旁细胞分泌肾素","对肾血流量无影响"],"a":3,"e":"肾交感神经兴奋时末梢释放去甲肾上腺素，作用于球旁细胞膜β受体，直接刺激肾素释放。交感兴奋还使入球小动脉收缩更明显，肾血流量减少。"},{"q":"交叉配血试验的次侧是指","o":["供血者的红细胞与受血者的红细胞进行配血","供血者的红细胞与受血者的血浆进行配血","供血者的血浆与受血者的红细胞进行配血","供血者的血浆与受血者的血浆进行配血","供血者的红细胞与受血者的骨髓造血细胞进行配血"],"a":2,"e":"交叉配血次侧是用受血者的红细胞与供血者的血清（血浆）做配合试验，检测供血者体内是否存在针对受血者红细胞的抗体。主侧则为供血者红细胞与受血者血清配合。"},{"q":"最理想的血管内抗凝剂是","o":["肝素","柠檬酸钠","草酸钠","氯化钙","氯化钠"],"a":0,"e":"肝素主要由肥大细胞产生，通过增强抗凝血酶对凝血酶的灭活而发挥强大抗凝作用，是理想的体内抗凝剂。柠檬酸钠和草酸钠通过螯合钙离子抗凝，主要用于体外。"},{"q":"自身调节指组织、细胞在不依赖于神经、体液调节的情况下对刺激所产生的","o":["适应性反应","旁分泌反应","稳态反应","非自控调节","前馈调节"],"a":0,"e":"自身调节是指细胞或组织器官不依赖神经和体液调节，凭借本身内在特性对内环境变化产生特定适应性反应。肾入球小动脉牵张性收缩维持肾血流量稳定即属此类。"},{"q":"下列哪个物质可激活胃蛋白酶原","o":["Cl-","Na+","Ca2+","盐酸","内因子"],"a":3,"e":"盐酸可激活胃蛋白酶原，并为其提供适宜的酸性环境，使蛋白质变性利于水解。Cl⁻、Na⁺、Ca²⁺无此作用，内因子仅促进维生素B₁₂吸收。"},{"q":"关于睾酮刺激男性副性征的叙述，下列哪项是错误的","o":["体毛发达","头发生长茂盛","皮脂腺分泌旺盛","肌肉发达","声调低沉"],"a":1,"e":"雄激素使男性出现骨骼粗壮、肌肉发达、胡须和阴毛生长、喉结突出、声调低沉及皮脂腺分泌旺盛等第二性征。头发生长茂盛并非睾酮刺激男性副性征的表现。"},{"q":"正常情况下，肺泡气PO2发生较大变化时，组织PO2只发生很小变化，这主要是因为","o":["体内氧储备多","组织血流量代偿性增加","Hb具有氧缓冲功能","组织耗氧量可随肺泡气PO2变化而变化","呼吸运动增强，摄氧增多"],"a":2,"e":"Hb与O₂结合呈氧解离曲线，肺泡PO₂大幅波动时Hb氧饱和度变化较小，起氧缓冲作用，使组织PO₂保持相对稳定。体内氧储备少，组织耗氧量不随肺泡PO₂改变。"},{"q":"让受试者先用力作深吸气，然后以最快的速度尽力呼出气体，分别测量第1、2、3秒末的呼出气量，计算其占肺活量的百分数，分别称为第1、2、3秒的","o":["通气储量百分比","最大随意通气量","肺泡通气量","深吸气量","时间肺活量"],"a":4,"e":"一次最大吸气后尽力尽快呼气，测第1、2、3秒末呼出气量占FVC的百分数，即用力呼气量，又称时间肺活量，用于反映肺弹性状态和气道通畅程度。"},{"q":"视网膜中存在着感光的视杆细胞和视锥细胞，其中视觉最敏感的部位在","o":["视盘周边部","视网膜周边部","黄斑","中央凹","视神经乳头"],"a":3,"e":"中央凹处视锥细胞密度最高，且与双极细胞、神经节细胞呈一对一单线联系，故视敏度最高，是视觉最敏感部位。视神经乳头无感光细胞。"},{"q":"管球反馈是指","o":["肾小球滤过率增大，近端小管重吸收率增加","肾小球滤过率减少，近端小管重吸收率减少","肾小球滤过率增大或减少，近端小管的重吸收率始终占肾小球滤过率的65%～70%。","近端小管重吸收率减少，肾小球滤过率减少","近端小管重吸收率增加，肾小球滤过率增大"],"a":2,"e":"近端小管对Na⁺和水的重吸收率始终占肾小球滤过率的65%～70%，即定比重吸收，称为球-管平衡，其意义在于保持尿量和尿Na⁺相对稳定。"},{"q":"正常情况下看近物时，动眼神经兴奋使睫状肌收缩，从而悬韧带松弛，可使眼调节表现为","o":["晶状体曲度增大","晶状体曲度减小","瞳孔缩小","角膜曲度增大","角膜曲度减小"],"a":0,"e":"视近物时睫状肌收缩、悬韧带松弛，晶状体因自身弹性变凸，表面曲率增加、折光力增强，使物像前移至视网膜。瞳孔缩小是同时出现的瞳孔近反射。"},{"q":"关于大脑初级运动皮层的特征，错误的是","o":["对躯体运动的交叉性支配","功能代表区的大小与运动的精细程度有关","运动区定位的总体安排是倒置的","接受来自皮肤的浅感觉传入","接受来自关节肌腱等深部的感觉冲动"],"a":3,"e":"初级运动皮层接受来自关节、肌腱等深部感觉冲动，皮肤浅感觉主要投射至中央后回。运动代表区大小取决于运动精细程度，总体呈倒置安排并对躯体运动呈交叉性支配。"},{"q":"对于O2在血液中的结合运输的叙述，正确的是","o":["混合静脉血流经肺泡时，由于肺泡PO2高，Hb与O2迅速解离","动脉血流经组织时，由于组织细胞PO2低，HbO2迅速解离","动脉血流经肺泡时，由于肺泡PO2高，Hb与O2迅速结合","静脉血流经组织时，由于组织细胞PO2低，HbO2迅速解离","静脉血流经组织时，由于组织细胞PO2高，Hb与O2迅速结合"],"a":1,"e":"动脉血流经组织时组织PO2低，HbO2迅速解离释出O2供组织利用。Hb与O2结合和解离迅速且可逆，不需酶催化，主要受PO2影响。"},{"q":"下列因素均可引起抗利尿激素的分泌，其中最为敏感的因素是","o":["循环血量减少","血浆晶体渗透压升高","动脉血压下降","寒冷刺激","精神紧张"],"a":1,"e":"血浆晶体渗透压是调节抗利尿激素分泌最重要的因素，升高1%～2%即可引起反应。渗透压感受器对Na+、Cl-形成的渗透压变化最敏感，循环血量改变通过影响其敏感度起作用。"},{"q":"下列关于能量代谢影响因素的描述，错误的是","o":["肌肉运动是影响能量代谢最显著的因素","环境温度在30～35℃时，能量代谢最稳定","情绪激动、烦恼、愤怒、恐惧及焦虑等，能量代谢可显著增高","环境温度＜10℃时，能量代谢明显增加是由于寒战和肌肉张力增高所致","进食全蛋白质食物，可使机体额外增加30%的热量"],"a":1,"e":"安静状态下环境温度20～30℃时能量代谢最稳定，超过30℃或低于20℃代谢率均增加。肌肉运动是影响能量代谢最显著的因素，寒冷时肌紧张增强和战栗使代谢增加。"},{"q":"胆碱能Ｎ型受体的阻断剂是","o":["筒箭毒","普萘洛尔","酚妥拉明","河豚毒素","阿托品"],"a":0,"e":"筒箭毒碱可特异性阻断突触后膜N2型ACh受体通道，使骨骼肌松弛。阿托品阻断M受体，酚妥拉明阻断α受体，普萘洛尔阻断β受体。"},{"q":"下列血液检查正常参考值中不正确的是","o":["男性血细胞比容为40%～50%","出血时间为<9min","白细胞数目为（4、0～10、0）×109/L","正常成年人血小板数目为（100～300）×109/L","正常成年男性红细胞沉降率正常值0～20mm/h"],"a":4,"e":"正常成年男性红细胞沉降率为0～15mm/h，女性为0～20mm/h。男性血细胞比容40%～50%、白细胞（4.0～10.0）×10⁹/L、血小板（100～300）×10⁹/L均正确。"},{"q":"下丘脑渗透压感受器最敏感的刺激是","o":["血压升高","血浆胶体渗透压升高","肾小球毛细血管血压升高","血浆晶体渗透压升高","循环血量增多"],"a":3,"e":"下丘脑渗透压感受器对血浆晶体渗透压变化最敏感，升高1%～2%即可引起抗利尿激素分泌增加。其对Na+、Cl-形成的渗透压最敏感，对葡萄糖、尿素敏感性弱。"},{"q":"骨骼肌收缩过程中肌张力增加的原因是","o":["最适初长度不断变大","横桥结合数目增多","肌肉收缩速度增加","前负荷不断增加","接受的刺激强度增加"],"a":1,"e":"肌张力大小取决于活化横桥数目，Ca2+与TnC结合后暴露肌动蛋白结合位点，参与结合的横桥增多则张力增加。最适初长度时粗细肌丝重叠最佳，横桥结合数目最多。"},{"q":"心室肌动作电位3期复极是由于膜对哪种离子通透性增高所致","o":["K+","Na+","Cl-","Ca2+","Mg2+"],"a":0,"e":"心室肌动作电位3期快速复极由K+外流增强所致，膜对K+通透性增高使膜电位迅速恢复至静息水平。2期平台期后复极加快即进入3期。"},{"q":"在牛蛙脊髓反射的实验中，反射时间的长短主要取决于","o":["刺激强度的高低","刺激持续时间的长短","中枢突触的多少","神经纤维传导速度的快慢","传入与传出纤维的长度"],"a":2,"e":"反射时由感受器电位、突触延搁、神经纤维传导等组成，其中兴奋经中枢多级突触接替耗时最多，故反射时间长短主要取决于中枢突触的多少。"},{"q":"实验过程中心室肌对刺激不产生反应，在下列可能的原因中，哪一项是错误的","o":["刺激强度太弱","电刺激的波宽太窄","心肌处在不应期中","Na+通道处在备用状态","心肌细胞除极到-50mV"],"a":3,"e":"Na+通道处于备用状态是心肌细胞具有兴奋性的前提，此时给予适宜刺激可产生动作电位。刺激过弱、波宽过窄、处于不应期或除极至-50mV均使钠通道失活或不能激活而致无反应。"},{"q":"当血钾逐步升高时，心肌的兴奋性","o":["逐步升高","逐步降低","先降低后升高","先升高后降低","基本不变"],"a":3,"e":"血钾轻度升高使膜电位轻度去极化，与阈电位靠近，兴奋性升高；血钾明显升高时膜电位显著减小，钠通道部分或完全失活，兴奋性降低或丧失。"},{"q":"视杆细胞的视紫红质属于","o":["G蛋白偶联受体","酪氨酸激酶受体","鸟苷酸环化酶受体","化学门控通道","电压门控通道"],"a":0,"e":"视紫红质由视蛋白和视黄醛组成，视蛋白属G蛋白耦联受体，为7次跨膜蛋白，经G蛋白激活下游效应酶诱发感受器电位。"},{"q":"损毁家兔下丘脑室上核，将出现下列哪种变化","o":["尿量不变，尿液浓度没有变化","尿量增加，尿液浓缩","尿量增加，尿液稀释","尿量减少，尿液浓缩","尿量减少，尿液稀释"],"a":2,"e":"下丘脑视上核合成血管升压素（抗利尿激素），损毁后其释放减少，集合管对水通透性降低，水重吸收减少，尿量增加且尿液稀释。"},{"q":"属于中枢抑制性递质的是","o":["γ－氨基丁酸、甘氨酸","乙酰胆碱","谷氨酸、门冬氨酸","多巴胺、５－羟色胺","肾上腺素、去甲肾上腺素"],"a":0,"e":"γ-氨基丁酸和甘氨酸属抑制性氨基酸类递质，作用于中枢引起抑制。谷氨酸、天冬氨酸为兴奋性氨基酸递质。"},{"q":"红细胞悬浮稳定性差会导致","o":["溶血","凝集","凝固","血沉加快","出血时延长"],"a":3,"e":"红细胞悬浮稳定性以血沉表示，沉降率越快表示悬浮稳定性越小，故悬浮稳定性差时血沉加快。其与双凹圆碟形表面积与体积之比有关。"},{"q":"下列因素中可影响肌肉收缩能力的是","o":["前负荷","后负荷","ATP酶活性","初长度","被动张力"],"a":2,"e":"ATP酶活性属于肌肉收缩能力的内在决定因素，可影响横桥周期与肌丝滑行效率。前负荷、后负荷和初长度通过改变肌肉初长度或张力影响收缩，不属于收缩能力本身。"},{"q":"关于微循环直捷通路的叙述，正确的是","o":["血流速度较慢","经常处于开放状态","是血液和组织细胞之间进行物质交换的主要部位","在骨骼肌组织中较少见","可以调节体温"],"a":1,"e":"直捷通路相对短而直，血流阻力小、流速快，经常处于开放状态，主要保证静脉回心血量。物质交换的主要部位是迂回通路，故其余描述不符。"},{"q":"下列关于大脑皮层对呼吸运动调节的叙述，错误的是","o":["对呼吸运动的随意控制必须依赖于大脑皮层","大脑皮层通过控制低位脑干呼吸神经元调节呼吸","在建立与呼吸有关的条件反射的过程中，大脑皮层起重要作用","在人类平时生活中，呼吸对环境的适应并不需要大脑皮层参与","言语与唱歌反映了大脑皮层对呼吸的控制作用"],"a":3,"e":"呼吸的随意控制依赖大脑皮层，皮层通过低位脑干呼吸神经元调节呼吸，并参与呼吸条件反射。日常呼吸对环境的适应仍需皮层参与，故该说法错误。"},{"q":"波尔效应是指","o":["PCO2升高使Hb与O2的亲和力下降，氧解离曲线右移","PCO2升高使Hb与O2的亲和力加强，氧解离曲线左移","O2与Hb的结合可促使CO2的结合","O2与Hb的结合可促使CO2的释放","O2与Hb的解离可促使CO2的释放"],"a":0,"e":"波尔效应指PCO2升高或pH降低使Hb对O2亲和力下降、氧解离曲线右移，促进O2释放。P50增大即反映亲和力降低、曲线右移。"},{"q":"在周围神经系统中，属于肾上腺素能神经纤维的是","o":["躯体运动神经纤维","绝大部分交感神经的节后纤维","交感神经节前纤维","副交感神经节后纤维","副交感神经的节前纤维"],"a":1,"e":"交感神经节后纤维释放去甲肾上腺素，属肾上腺素能纤维，绝大部分交感节后纤维符合此特征。副交感节后纤维释放乙酰胆碱，躯体运动神经纤维也释放乙酰胆碱。"},{"q":"衡量心肌细胞自律性高低的最主要指标是","o":["阈电位水平","动作电位0期去极速率","最大舒张电位水平","动作电位4期自动去极速率","2期平台期持续的时间"],"a":3,"e":"自律性高低主要取决于4期自动去极化速度，速度越快达阈电位所需时间越短，自律性越高。最大复极电位和阈电位水平也影响自律性，但以4期去极速度最为重要。"},{"q":"机体处于急性大失血状态时，最早出现的代偿反应是","o":["迷走神经兴奋","交感神经兴奋","组织液回流增加","血管紧张素系统作用加强","血浆蛋白和红细胞的恢复"],"a":1,"e":"急性大失血时交感神经兴奋最早出现，引起心率加快、血管收缩等代偿反应。组织液回流增加、血管紧张素系统激活及血浆蛋白红细胞恢复均出现较晚。"},{"q":"关于雄激素的作用的叙述，下列哪一项是错误的","o":["刺激雄性附性器官发育并维持成熟状态","刺激红细胞生成","促进肌肉与骨骼生长","分泌过盛可使男子身高超出常人","维持正常的性欲"],"a":3,"e":"雄激素分泌过盛可促使骨骺过早闭合，反而使身高低于常人，故该说法错误。雄激素可刺激附性器官发育、促进肌肉骨骼生长、刺激红细胞生成并维持性欲。"},{"q":"骨骼肌细胞膜中横管的主要作用是","o":["储存Ca2+","释放乙酰胆碱","传导动作电位","降解乙酰胆碱","产生终板电位"],"a":2,"e":"横管由肌膜向细胞内凹陷形成，可将肌膜上的动作电位传入细胞内部，故主要作用是传导动作电位。储存Ca2+的是纵管（肌质网），释放乙酰胆碱和产生终板电位均发生于神经-肌接头。"},{"q":"关于胃酸的生理作用，下列哪项是错误的","o":["能激活胃蛋白酶原，供给胃蛋白酶所需的酸性环境","可使食物中的蛋白质变性易于分解","可杀死随食物进入胃内的细菌","可促进维生素B12的吸收","盐酸进入小肠后，可促进胆汁、胰液、小肠液的分泌"],"a":3,"e":"促进维生素B12吸收的是胃壁细胞分泌的内因子，它与维生素B12结合后经回肠黏膜受体介导吸收，胃酸无此作用。盐酸能激活胃蛋白酶原、使蛋白质变性、杀灭细菌，并进入小肠促进胆汁、胰液和小肠液分泌。"},{"q":"血浆与组织液各种成分浓度的主要区别是","o":["Na+","K+","蛋白质","有机酸","尿素"],"a":2,"e":"血浆与组织液的主要差别是蛋白质含量，血浆蛋白分子大，不易透过毛细血管壁，故组织液中蛋白甚少。两者离子成分基本相同，Na+、K+、有机酸、尿素浓度无显著差异。"},{"q":"在近端小管，全部被重吸收的物质是","o":["Na+","肌酐","尿素","葡萄糖","氨"],"a":3,"e":"滤过的葡萄糖全部在近端小管（尤其前半段）经Na+-葡萄糖耦联转运体重吸收。Na+、尿素仅部分重吸收，肌酐则被分泌排出，均非全部重吸收。"},{"q":"关于钠泵生理作用的表述，错误的是","o":["每个活动周期能将3个Na+离子移出膜外","每个活动周期能将2个K+离子移出膜外","从膜内移出Na+，可防止水分子进入细胞内","钠泵的活动造成细胞内高K+，使许多代谢得以进行","钠泵的活动可造成膜两侧的离子势能储备"],"a":1,"e":"钠泵每分解一分子ATP将3个Na+移出膜外、2个K+移入膜内，故“将2个K+移出膜外”错误。其生电效应使膜内负值增大，并维持细胞内高K+和膜两侧离子势能储备。"},{"q":"能反映右心室功能的指标是","o":["心输出量","动脉压","中心静脉压","脉压","平均动脉压"],"a":2,"e":"中心静脉压取决于心脏射血能力与静脉回心血量的关系，心脏射血能力减弱时中心静脉压升高，故可反映右心室功能。心输出量、动脉压、脉压和平均动脉压主要反映左心射血及外周阻力。"},{"q":"有机磷中毒的主要原因是","o":["乙酰胆碱水解加速","乙酰胆碱受体功能障碍","乙酰胆碱释放量增加","乙酰胆碱与其受体亲和力增高","胆碱酯酶活性降低"],"a":4,"e":"有机磷农药不可逆抑制胆碱酯酶，使乙酰胆碱不能被水解而大量蓄积，引起中毒。新斯的明等可逆性胆碱酯酶抑制剂即通过抑制该酶发挥作用。"},{"q":"激活胰蛋白酶原的物质主要是","o":["盐酸","碳酸氢盐","胰脂肪酶","糜蛋白酶","肠激酶"],"a":4,"e":"肠液中的肠激酶是激活胰蛋白酶原的特异性酶，使其转变为有活性的胰蛋白酶，后者还可正反馈激活胰蛋白酶原。盐酸虽可激活胃蛋白酶原，但对胰蛋白酶原无此作用。"},{"q":"睾酮属于下列哪一类激素","o":["类固醇激素","含氮类激素","肽类激素","蛋白质类激素","胺类激素"],"a":0,"e":"睾酮由睾丸间质细胞合成，其共同前体为胆固醇，属于类固醇激素。类固醇激素分子量小、亲脂，可穿越胞膜释放入血并与运载蛋白结合运输。"},{"q":"下列有关H+与NH3的分泌，正确的是","o":["H+与NH3的分泌存在相互竞争","H+与NH3的分泌存在相互促进","H+与NH3的分泌无关系","泌NH3有利于排碱保酸","泌H+抑制HCO3-的重吸收"],"a":1,"e":"肾小管分泌的NH3与H+结合生成NH4+，降低小管液H+浓度，使泌H+持续进行，故两者分泌相互促进。泌NH3促进HCO3-重吸收，有利于排酸保碱。"},{"q":"关于睾丸的功能的叙述，下列哪一项是错误的","o":["睾丸的生精功能与内分泌功能互不影响","精原细胞产生精子","具有产生精子与雄激素的双重功能","间质细胞产生睾酮","支持细胞对精子起营养作用"],"a":0,"e":"睾丸的生精功能受雄激素等内分泌调节，内分泌功能亦受生精细胞产物影响，二者相互影响。间质细胞分泌睾酮，支持细胞营养生精细胞，精原细胞经分裂产生精子。"},{"q":"在等容收缩期，压力梯度正确的是","o":["房内压>室内压>主动脉压","房内压<室内压>主动脉压","房内压=室内压>主动脉压","房内压<室内压<主动脉压","房内压>室内压<主动脉压"],"a":3,"e":"等容收缩期房室瓣已关闭、半月瓣尚未开放，室内压高于房内压而低于主动脉压，即房内压<室内压<主动脉压。"},{"q":"关于心电图波形与心肌动作电位关系的描述，正确的是","o":["P波反映心房肌动作电位的全过程","QRS波群反映心室肌动作电位的全过程","T段反映静息期膜内外离子分布恢复的过程","心电图一个周期等于心房、心室肌细胞动作电位时程之和","心电图反映无数心肌细胞动作电位效应的总和"],"a":4,"e":"心电图记录整个心脏兴奋过程中无数心肌细胞电变化在体表的综合效应，而非单个细胞动作电位。P波反映心房去极化，QRS波群对应心室肌0期去极化。"},{"q":"下列可作为心室收缩期开始标志的心音是","o":["第一心音","第二心音","第三心音","第四心音","主动脉瓣关闭音"],"a":0,"e":"第一心音由房室瓣突然关闭引起心室血液和室壁振动产生，标志心室收缩开始，在心尖搏动处听诊最清楚。第二心音标志心室舒张开始。"},{"q":"易化扩散不同于单纯扩散的是","o":["需要ATP供能","借助于膜蛋白的帮助","顺浓度差转运","逆浓度差转运","转运对象是蛋白质"],"a":1,"e":"易化扩散需借助通道蛋白或载体蛋白，属被动转运，不耗能，顺浓度梯度和/或电位梯度进行。单纯扩散直接通过脂质双层，不需膜蛋白。"},{"q":"内分泌细胞分泌激素到组织液的过程属于","o":["载体介导易化扩散","原发性主动转运","继发性主动转运","出胞","通道介导易化扩散"],"a":3,"e":"内分泌细胞分泌激素以大分子物质经分泌囊泡排出细胞，属出胞过程，需消耗能量并伴细胞膜面积增加。"},{"q":"进入肺泡内的气体，可因血液在肺内分布不均而未全部与血液进行气体交换。没有发生气体交换的这部分肺泡容量，称为","o":["解剖无效腔","生理无效腔","肺泡无效腔","气道无效腔","无效腔"],"a":2,"e":"正确答案为肺泡无效腔。肺泡有通气但无血流、未能进行气体交换的肺泡容积即肺泡无效腔，正常人接近于零。生理无效腔是肺泡无效腔与解剖无效腔之和。"},{"q":"神经冲动传递至接头前膜后引起递质释放是因为","o":["Na+通道关闭","Ca2+通道开放","K+通道开发","Cl-通道开放","水通道开放"],"a":1,"e":"正确答案为Ca2+通道开放。接头前膜动作电位激活电压门控钙通道，Ca2+内流触发囊泡出胞释放ACh，递质释放具Ca2+依赖性。"},{"q":"细胞膜在静息情况下，对下列哪种离子通透性最大","o":["K+","Na+","Cl-","Ca2+","Mg2+"],"a":0,"e":"正确答案为K+。静息时细胞膜对K+通透性最大，K+顺浓度差外流形成静息电位的主要成分；Na+通透性很小，钠泵生电效应贡献不超过5%。"},{"q":"关于微循环直捷通路的叙述，错误的是","o":["回流速度快","经常处于开放状态","是血液和组织液进行物质交换的部位","管经比真毛细血管稍粗","骨骼肌组织中较常见"],"a":2,"e":"正确答案为“是血液和组织液进行物质交换的部位”。直捷通路经常开放、血流较快、管径稍粗，主要使血液迅速回心；物质交换的主要场所是迂回通路的真毛细血管网。"},{"q":"腱器官是一种","o":["张力感受器","长度感受器","压力感受器","温度感受器","化学感受器"],"a":0,"e":"正确答案为张力感受器。腱器官位于肌腱胶原纤维之间，感受骨骼肌张力变化，对过度牵张起保护作用；肌梭才是感受肌肉长度的感受器。"},{"q":"下列生理过程与Ca2+内流无关的是","o":["快反应细胞动作电位的2期复极化","慢反应细胞动作电位的0期去极化","慢反应细胞动作电位的4期自动去极化","快反应细胞动作电位的1期复极化","快反应细胞动作电位的平台期"],"a":3,"e":"正确答案为快反应细胞动作电位的1期复极化。1期由瞬时外向钾流Ito介导，与Ca2+内流无关；2期平台期由Ca2+内流与K+外流共同形成，慢反应细胞0期和4期均依赖Ca2+内流。"},{"q":"关于睾丸功能调节的叙述，下列哪一项是错误的","o":["促卵泡激素对生精过程有刺激作用","黄体生成素刺激间质细胞分泌睾酮","促卵泡激素对生精有始动作用","睾酮与雄激素结合球蛋白结合，促进精母细胞减数分裂","睾酮对腺垂体促卵泡激素的分泌起负反馈抑制作用"],"a":4,"e":"正确答案为“睾酮对腺垂体促卵泡激素的分泌起负反馈抑制作用”。睾酮主要负反馈抑制腺垂体LH分泌，对FSH的抑制较弱；FSH刺激生精并具始动作用，LH刺激间质细胞分泌睾酮。"},{"q":"下列关于Hb与O2结合的叙述正确的是","o":["1分子Hb可以结合1分子O2","Hb与O2在氧化酶的作用下结合生成HbO2","Hb的4个亚单位间有协同效应","Hb与O2的结合曲线呈线性，而解离曲线呈S形","O2与Hb结合时将其分子中的Fe2+氧化成了Fe3+"],"a":2,"e":"正确答案为Hb的4个亚单位间有协同效应。1个亚单位结合O2后经变构效应使其他亚单位更易结合O2，故氧解离曲线呈S形；Hb与O2结合是氧合而非氧化，Fe2+不变价。"},{"q":"中心静脉压的最佳测定部位是","o":["左心房","右心房","肘静脉","右心室","左心室"],"a":1,"e":"中心静脉压指右心房和胸腔内大静脉的血压，故最佳测定部位为右心房。其数值取决于心脏射血能力与静脉回心血量的相互关系，正常波动于4～12cmH2O。"},{"q":"下述哪种情况会导致肾小球滤过率减少","o":["血浆胶体渗透压降低","血浆胶体渗透压增高","血浆晶体渗透压升高","血浆晶体渗透压降低","血浆蛋白质含量降低"],"a":1,"e":"血浆胶体渗透压增高使有效滤过压降低，肾小球滤过率减少。血浆胶体渗透压降低或血浆蛋白减少则使有效滤过压增大、滤过率增加。"},{"q":"卡巴胆碱（胆碱能受体激动剂）作用于窦房结细胞产生超极化，其机制是","o":["是由于Na+-K+泵活动增强引起的","是由于Na+内流引起的","是由于K+外流引起的","是由于Ca2+外流引起的","是由于Cl-外流引起的"],"a":2,"e":"卡巴胆碱激动窦房结P细胞M受体，使K+外流增加，引起膜超极化，自律性降低。ACh经M受体激活IK-ACh通道，K+外流增多是超极化的机制。"},{"q":"神经调节的特点是","o":["作用迅速、精确、短暂","作用缓慢、广泛、持久","非自动控制","有生物节律","局部、稳定"],"a":0,"e":"神经调节经反射弧完成，具有反应迅速、持续时间短、调节精确的特点。体液调节则作用缓慢、广泛而持久。"},{"q":"神经肌肉接头前膜释放的Ach与终板膜上的受体结合，可使终板膜","o":["对Na+、K+通透性增加，发生超极化","仅对Ca2+通透性增加，发生去极化","仅对K+通透性增加，发生超极化","对Na+、K+通透性增加，发生去极化","对ACh通透性增加，发生去极化"],"a":3,"e":"ACh与终板膜N2型受体结合，通道主要对Na+、K+通透，以Na+内流为主，产生去极化型终板电位。"},{"q":"非条件反射的特点有","o":["先天遗传获得","有固定的反射弧","中枢在皮质下结构","数量十分有限","以上都是正确的"],"a":4,"e":"非条件反射是先天遗传获得、反射弧固定、中枢位于皮层下结构、数量有限的反射，故以上均正确。条件反射则需后天学习建立。"},{"q":"神经中枢内，通常兴奋通过一个突触所需要的时间为","o":["2、0～3、0ms","1、0～2、0ms","0、5～1、0ms","0、3～0、5ms","0、1～0、2ms"],"a":3,"e":"兴奋通过一个化学突触需0.3～0.5ms，中枢延搁主要由此决定。膝反射中枢延搁0.6～0.9ms，符合单突触反射。"},{"q":"下列关于睾丸功能调节的描述，哪一项是错误的","o":["受下丘脑-腺垂体-睾丸轴调节","促性腺激素释放激素是以脉冲形式分泌的","促卵泡激素和黄体生成素对生精过程均有调节作用","雄激素、抑制素可反馈调节下丘脑、腺垂体有关激素分泌","睾酮可启动生精过程、促卵泡激素维持生精过程"],"a":4,"e":"FSH对生精过程有启动作用，LH通过促进睾酮合成对生精过程有维持效应。睾酮作用于精原细胞促进精子生成，并非启动生精过程。"},{"q":"下列哪一项是醛固酮的主要作用","o":["增加肾近曲小管保钠排钾","增加肾近曲小管排钠排钾","增加肾髓袢排钠排钾","增加肾近曲小管和集合管排钠排钾","增加肾远曲小管和集合管保钠排钾"],"a":4,"e":"醛固酮主要作用于肾远曲小管和集合管上皮细胞，促进Na+重吸收和K+分泌，即保Na+排K+。近曲小管和髓袢不是醛固酮的靶部位。"},{"q":"在一个心动周期中，主动脉血压达到的最低值称为","o":["收缩压","舒张压","脉压","平均动脉压","循环系统平均充盈压"],"a":1,"e":"舒张压是一个心动周期中因心室停止射血而使动脉压降到的最低值。收缩压为心室射血时动脉压的最高值，脉压为两者差值。"},{"q":"不存在于血浆中的凝血因子是","o":["因子Ⅲ","因子Ⅴ","因子Ⅶ","因子Ⅸ","因子Ⅻ"],"a":0,"e":"除FⅢ（组织因子）外，其他凝血因子均存在于新鲜血浆中，FⅢ存在于组织中。"},{"q":"血液的组成是","o":["血浆和红细胞","血浆和白细胞","血浆和血小板","血浆和血细胞","血浆、红细胞和白细胞"],"a":3,"e":"血液由血浆和悬浮于其中的血细胞组成，红细胞、白细胞和血小板均属血细胞。"},{"q":"关于雌激素的生理作用的描述，下列哪一项是错误的","o":["使输卵管平滑肌活动增强","卵泡期子宫内膜增生变厚，腺体分泌","促进肾小管对钠、水的重吸收","与促卵泡激素配合促进卵泡增生","促进蛋白质合成，有利于生长发育"],"a":1,"e":"雌激素使子宫内膜增生变厚，腺体增多，但腺体分泌黏液是孕激素的作用。雌激素可增强输卵管平滑肌活动、促进肾小管重吸收钠水、促进蛋白质合成。"},{"q":"肾小球滤过的直接动力是","o":["肾小球有效滤过压","肾小囊内压","血浆胶体渗透压","集合管内压","组织液的静水压"],"a":0,"e":"肾小球有效滤过压是促进超滤的动力与对抗超滤的阻力之间的差值，为肾小球滤过的直接动力。"},{"q":"将肌细胞膜上动作电位传导至肌细胞内部肌原纤维的结构是","o":["连接肌质网","横管","纵行肌质网","终池","横桥"],"a":1,"e":"横管由肌膜内陷形成，肌膜动作电位沿横管传至肌细胞内部，激活L型钙通道引发兴奋-收缩耦联。"},{"q":"下列关于电突触的叙述，错误的是","o":["结构基础为缝隙链接","单向传递","电阻低","没有潜伏期","传递速度快"],"a":1,"e":"电突触以缝隙连接为结构基础，电导大、电阻低，传递具有双向性和快速性，几乎无潜伏期。单向传递是化学突触传递的特征。"},{"q":"在一个心动周期中，冠脉血流量急剧减少的时期是","o":["等容收缩期","快速射血期","减慢射血期","舒张期","心房收缩期"],"a":0,"e":"等容收缩期心室壁张力急剧升高，压迫肌纤维间小血管，使冠脉血流明显减少甚至断流。快速射血期冠脉压随主动脉压升高，血流量增加。"},{"q":"消化道平滑肌细胞动作电位产生的离子基础是下列哪一项","o":["K+内流","Na+内流","Ca2+内流","Ca2+与K+内流","Na+与K+内流"],"a":2,"e":"消化道平滑肌细胞动作电位去极化主要依赖Ca2+内流，锋电位上升慢、持续时间长。复极化由K+外流所致。"},{"q":"分布于横管膜上，与兴奋收缩耦联最为相关的离子通道是","o":["T型钙通道","R型钙通道","L型钙通道","受体门控钙通道","机械门控式钙通道"],"a":2,"e":"横管膜和肌膜中的L型钙通道在动作电位传导时被激活，内流的Ca2+触发肌质网释放大量Ca2+，即钙致钙释放。"},{"q":"视前区-下丘脑前部是","o":["控制产热活动的中枢部位","控制散热活动的中枢部位","体温调节中枢整合部位","只存在热敏神经元而不存在冷敏神经元","冷敏神经元较多"],"a":2,"e":"视前区-下丘脑前部（PO/AH）是体温调节的基本中枢，存在温度敏感神经元，起整合作用。"},{"q":"有关发绀的叙述，正确的是","o":["出现发绀一定标志着组织缺氧","CO中毒时出现发绀","严重贫血可出现发绀","高原性红细胞增多症可出现发绀","缺氧一定会出现发绀"],"a":3,"e":"发绀指血液中Hb含量达5g/100ml以上时皮肤黏膜呈暗紫色。高原性红细胞增多症者Hb浓度异常增高，可出现发绀但并不一定缺氧。"},{"q":"血液中生物活性最强的甲状腺激素是","o":["一碘甲腺原氨酸","二碘甲腺原氨酸","三碘甲腺原氨酸","四碘甲腺原氨酸","逆-三碘甲腺原氨酸"],"a":2,"e":"T3的生物活性最强，约为T4的5倍，虽分泌量少但活性高。T4需在外周组织脱碘转化为T3后发挥主要作用。"},{"q":"交叉配血试验的主侧是指","o":["供血者的红细胞与受血者的红细胞进行配血","供血者的红细胞与受血者的血浆进行配血","供血者的血浆与受血者的红细胞进行配血","供血者的血浆与受血者的血浆进行配血","以上均不是"],"a":1,"e":"交叉配血主侧为供血者红细胞与受血者血清（血浆）配合，检测受血者体内是否存在针对供血者红细胞的抗体。"},{"q":"可用来反映心脏射血前负荷的指标是","o":["心室收缩末期容积","心室舒张末期容积","心室等容舒张期容积","等容收缩期心室内压","快速射血期心室内压"],"a":1,"e":"前负荷指心室舒张末期容积，因测量方便，实验中常用心室舒张末期压或心房内压反映前负荷。"},{"q":"正常情况下，维持呼吸中枢兴奋的有效刺激是","o":["一定程度的缺氧","高浓度的CO2","一定浓度的CO2","肺牵张感受器的传入冲动","一定浓度的H+"],"a":2,"e":"一定浓度的CO2是维持呼吸中枢正常兴奋性的生理性刺激，动脉血PCO2需保持一定水平，其兴奋呼吸的阈值约为40mmHg。CO2是调节呼吸最重要的生理性化学因素，过度通气使PCO2降低可致呼吸暂停。"},{"q":"动脉血压突然升高时，将引起","o":["左室射血速度增快","心输出量增加","左室收缩末期容积增加","左室射血时达到最高室压的时间缩短","左室射血时的最高室内压下降"],"a":2,"e":"大动脉血压是心室收缩的后负荷，动脉压突然升高使射血阻力增大、搏出量暂时减少，射血后心室内剩余血量增多，收缩末期容积增大。"},{"q":"下列物质中，收缩血管作用最强的是","o":["肾上腺素","肾素","血管紧张素Ⅱ","内皮素","去甲肾上腺素"],"a":3,"e":"内皮素是内皮细胞合成释放的21肽，具有强烈而持久的缩血管效应，对体内各脏器血管几乎都有收缩作用，为已知缩血管作用最强者。"},{"q":"神经肌肉接头处前膜释放的递质是","o":["肾上腺素","多巴胺","乙酰胆碱","5-羟色胺","去甲肾上腺素"],"a":2,"e":"骨骼肌神经肌肉接头的兴奋传递中，接头前膜Ca2+依赖性突触囊泡出胞，释放乙酰胆碱至接头间隙，作用于终板膜N2型ACh受体阳离子通道。"},{"q":"心室肌细胞0期去极化时，钠通道在膜去极化到一定程度时，便迅速失活而关闭，钠通道完全关闭是在","o":["膜电位在-50mV水平时","膜电位在-30mV水平时","膜电位在0mV水平时","膜电位极化倒转达最大值时","膜电位复极化到平台水平时"],"a":3,"e":"心室肌细胞0期去极的钠通道激活快、失活也快，膜去极化到0mV左右开始失活关闭，至去极化达Na+平衡电位即极化倒转最大值时钠通道完全关闭。"},{"q":"与IP3和DG生成有直接关系的G蛋白效应器是","o":["腺苷酸环化酶","鸟苷酸环化酶","蛋白激酶A","蛋白激酶C","磷脂酶C"],"a":4,"e":"磷脂酶C是G蛋白效应器酶，激活后水解膜磷脂生成IP3和DG，二者分别触发钙库释放Ca2+和激活蛋白激酶C。"},{"q":"心肌细胞超常期内兴奋性高于正常，此期","o":["兴奋传导速度高于正常","动作电位幅度大于正常","0期除极速率高于正常","刺激阈值低于正常","自动节律性高于正常"],"a":3,"e":"超常期膜电位接近阈电位，引起兴奋所需刺激小于原阈值，即刺激阈值低于正常，故兴奋性高于正常；此期0期去极速度和幅度均低于正常。"},{"q":"心室肌细胞不具有的生理特性是","o":["兴奋性","自律性","传导性","收缩性","自律性和收缩性"],"a":1,"e":"心室肌细胞属工作细胞，具有兴奋性、传导性和收缩性，无自律性；自律性为窦房结等自律细胞所具有。"},{"q":"生成组织液的有效滤过压等于","o":["（组织液胶体渗透压＋组织液静水压）－（毛细血管血压＋血浆胶体渗透压）","（血浆胶体渗透压＋组织液静水压）－（毛细血管血压＋组织液胶体渗透压）","（毛细血管血压＋血浆胶体渗透压）－（组织液胶体渗透压＋组织液静水压）","（毛细血管血压＋组织液静水压）－（血浆胶体渗透压＋组织液胶体渗透压）","（毛细血管血压＋组织液胶体渗透压）－（血浆胶体渗透压＋组织液静水压）"],"a":4,"e":"组织液生成的有效滤过压为（毛细血管血压＋组织液胶体渗透压）－（血浆胶体渗透压＋组织液静水压）。毛细血管血压和组织液胶体渗透压是促使液体滤过的力量，血浆胶体渗透压和组织液静水压是促使重吸收的力量。"},{"q":"可抑制血小板聚集的物质是","o":["ADP","TXA2","PGI2","胶原","凝血酶"],"a":2,"e":"PGI2由血管内皮细胞产生，可提高血小板内cAMP含量，具有较强抑制血小板聚集和舒张血管的作用。TXA2则降低血小板内cAMP而促进聚集，两者作用相反。"},{"q":"缺氧对呼吸中枢的直接作用是","o":["抑制","兴奋","抑制大于兴奋","抑制与兴奋相等","兴奋大于抑制"],"a":0,"e":"低O2对呼吸中枢的直接作用是抑制。低O2主要通过兴奋外周化学感受器反射性兴奋呼吸中枢，可对抗其对中枢的直接抑制；严重缺O2时反射效应不足以克服抑制，呼吸运动减弱。"},{"q":"近髓肾单位的主要功能是","o":["分泌醛固酮","释放抗利尿激素","释放肾素","生成尿液","浓缩和稀释尿液"],"a":4,"e":"近髓肾单位的髓袢长，深入肾髓质，与肾髓质高渗梯度的形成及逆流倍增机制密切相关，主要参与尿液的浓缩和稀释。肾素由球旁细胞释放，醛固酮由肾上腺皮质分泌。"},{"q":"献血者为A型血，经交叉配血试验，主侧不凝集而次侧凝集，受血者的血型为","o":["A型","B型","AB型","O型","B型或AB型"],"a":2,"e":"主侧不凝集说明受血者血清中无抗A抗体，次侧凝集说明受血者红细胞含A抗原，故受血者为AB型。O型血输给其他血型者时也可出现主侧不凝集而次侧凝集。"},{"q":"食物特殊动力效应最强的食物是","o":["蛋白质","糖类","脂肪","矿物质","无机盐"],"a":0,"e":"进食蛋白质产生的特殊动力效应最显著，约为30%，即摄入提供100kJ能量的蛋白质可产生约30kJ额外耗能，糖类和脂肪的特殊动力效应明显低于蛋白质。"},{"q":"硫氧嘧啶类药物可治疗甲状腺功能亢进，其机制是","o":["抑制T3、T4的释放","抑制碘的摄取","抑制过氧化物酶的活性，使T3、T4合成减少","使T3、T4的破坏增多","阻止T3、T4进入细胞"],"a":2,"e":"硫氧嘧啶类药物通过抑制甲状腺过氧化物酶（TPO）活性而抑制甲状腺激素的合成，TPO是TH合成的关键酶，故临床用于治疗甲状腺功能亢进。"},{"q":"关于传导散热的叙述，不正确的是","o":["以直接传导的方式散热","皮肤的热量传给衣服","与皮肤温度有关","脂肪的热导率很高","与接触物的热导率有关"],"a":3,"e":"脂肪组织导热性能差，热导率低，故肥胖者身体深部热量不易传向表层。传导散热取决于皮肤与接触物的温差、接触面积及接触物导热性能，热量以直接传导方式传给温度较低的接触物。"},{"q":"心室肌细胞具有兴奋性的前提是Na+通道处于下列哪种状态","o":["启动","备用","激活","失活","开放"],"a":1,"e":"正确答案是备用。钠通道处于静息（备用）状态是心肌细胞具有兴奋性的前提，只有膜电位恢复至静息电位水平时钠通道才全部恢复为备用状态。失活状态下钠通道不能再次开放，故落在有效不应期内的刺激不能引起有效兴奋。"},{"q":"关于钠泵生理作用的描述，错误的是","o":["钠泵能逆着浓度差将进入细胞内的Na+移出胞外","钠泵能顺着浓度差使细胞外的K+移入胞内","由于从膜内移出Na+，可防止水分子进入细胞内","钠泵的活动造成细胞内高钾，是许多反应得以进行","钠泵的活动可造成膜两侧的离子势能储备"],"a":1,"e":"正确答案是“顺着浓度差使细胞外的K+移入胞内”。钠泵每分解一分子ATP，逆浓度差将3个Na+移出胞外、2个K+移入胞内，K+移入是逆浓度梯度进行的主动转运，并非顺浓度差。"},{"q":"当脊髓前角γ-运动神经元的传出冲动增加时，可引起","o":["肌梭传入冲动增加","梭外肌收缩减弱","梭内肌收缩减弱","α-运动神经元的传出冲动减少","α-运动神经元的传出冲动不变"],"a":0,"e":"正确答案是肌梭传入冲动增加。γ运动神经元传出纤维支配梭内肌纤维的收缩成分，其活动增强使梭内肌收缩、肌梭敏感性提高，Ⅰa类传入冲动增多，进而兴奋α运动神经元使梭外肌收缩。"},{"q":"交感神经兴奋可引起","o":["瞳孔缩小","逼尿肌收缩","肠蠕动增强","心率加快","支气管平滑肌收缩"],"a":3,"e":"正确答案是心率加快。心交感神经兴奋通过去甲肾上腺素与β1受体结合，使窦房结自律性增高、心率加快，同时心肌收缩力增强。瞳孔缩小、逼尿肌收缩、肠蠕动增强及支气管平滑肌收缩均为副交感神经兴奋的表现。"},{"q":"关于通气/血流比值的描述，错误的是","o":["安静时正常值是0、84，即V/Q=0、84","通气/血流比值减少，反映功能性动静脉短路","通气/血流比值增大，反映肺泡无效腔增大","肺尖部的通气/血流比值增大","肺动脉栓塞时，比值减小"],"a":4,"e":"正确答案是“肺动脉栓塞时，比值减小”。肺动脉栓塞使肺血流量减少，通气/血流比值增大，反映肺泡无效腔增大；比值减小则反映功能性动静脉短路。"},{"q":"心动周期中，占时间最长的是","o":["心房收缩期","等容收缩期","快速射血期","等容舒张期","心室充盈期"],"a":4,"e":"正确答案是心室充盈期。心室充盈期包括快速充盈期、减慢充盈期和心房收缩期，在心动周期各时相中持续时间最长，心率增快时舒张期缩短主要缩短的是充盈时间。"},{"q":"下列属于条件反射的是","o":["吸吮反射","眨眼反射","屈肌反射","窦弓反射","看到食物引起唾液分泌增加"],"a":4,"e":"正确答案是看到食物引起唾液分泌增加。食物的颜色、性状等信号引起的唾液分泌是经后天学习建立的条件反射；吸吮反射、眨眼反射、屈肌反射和窦弓反射均为生来具有的非条件反射。"},{"q":"纤溶酶的主要作用是水解","o":["凝血因子Ⅴ","凝血因子Ⅱa","凝血因子Ⅻ","凝血因子Ⅰ、Ⅰa","凝血因子Ⅳ"],"a":3,"e":"正确答案是凝血因子Ⅰ、Ⅰa。纤溶酶是血浆中活性最强的蛋白酶，主要水解纤维蛋白（FⅠa）和纤维蛋白原（FⅠ），使血栓溶解；对凝血因子Ⅴ、Ⅷ等也有降解作用，但主要底物是纤维蛋白和纤维蛋白原。"},{"q":"下列哪种跨膜物质转运的方式无饱和现象","o":["单纯扩散","载体介导的易化扩散","质子泵","Na+-H+交换","受体介导的入胞"],"a":0,"e":"单纯扩散属被动转运，无生物学转运机制参与，扩散速率随浓度差增大而升高，无饱和现象。经载体易化扩散因载体数量有限而出现饱和，最大扩散速率为Vmax。"},{"q":"心肌组织中，兴奋传导速度最快的是","o":["浦肯野纤维","结间束","心房肌","心室肌","希氏束"],"a":0,"e":"浦肯野纤维十分粗大且细胞间缝隙连接数量多，兴奋传导速度在心内传导系统中最快，可达4m/s左右。房室交界结区传导最慢，形成房室延搁。"},{"q":"血浆蛋白减少可引起组织水肿，其主要原因是","o":["淋巴液回流减少","毛细血管通透性增加","毛细血管血压升高","血浆胶体渗透压降低","毛细血管血压降低"],"a":3,"e":"血浆胶体渗透压主要取决于血浆蛋白尤其是白蛋白浓度，血浆蛋白减少使血浆胶体渗透压降低，有效滤过压增大，组织液生成增多而出现水肿。"},{"q":"切除肾上腺会导致动物死亡，其原因是由于缺乏下列哪种激素","o":["脱氢异雄酮","肾上腺素","雌二醇","糖皮质激素","醛固酮"],"a":3,"e":"切除双侧肾上腺后动物因缺乏糖皮质激素导致糖、蛋白质和脂肪代谢紊乱，机体对伤害性刺激的耐受力严重降低而死亡。缺乏醛固酮虽致水盐代谢紊乱，但致死主要归因于糖皮质激素缺乏。"},{"q":"脊髓腰骶段受到损伤时，排尿反射的障碍主要表现为","o":["少尿","多尿","尿失禁","尿潴留","尿频"],"a":3,"e":"支配膀胱的盆神经或骶段脊髓受损时排尿反射不能发生，膀胱松弛扩张，大量尿液滞留，导致尿潴留。尿失禁见于高位脊髓受损后骶部排尿中枢失去高位中枢控制。"},{"q":"下列关于等张收缩的描述错误的是","o":["等张收缩过程发生肌纤维的缩短","消耗能量主要用于肌肉缩短和移动负荷","收缩过程张力始终不变","肌肉开始缩短前，先表现出等张收缩，后表现出等长收缩","肌肉收缩产生的张力大于或等于阻力负荷，肌肉发生等张收缩"],"a":3,"e":"肌肉收缩最常见的形式是先等长收缩后等张收缩，即张力增至与后负荷相等后才开始缩短，故“先等张后等长”的描述错误。等张收缩时张力不变而肌纤维缩短并移动负荷。"},{"q":"心肌细胞兴奋后，其兴奋性发生周期变化的顺序是","o":["绝对不应期—相对不应期—局部反应期—超常期","绝对不应期—相对不应期—超常期—局部反应期","绝对不应期—超常期—局部反应期—相对不应期","绝对不应期—局部反应期—相对不应期—超常期","绝对不应期—相对不应期—超常期—低常期"],"a":3,"e":"心肌细胞兴奋后兴奋性依次经历绝对不应期、局部反应期、相对不应期和超常期。有效不应期特别长，保证心肌不发生完全强直收缩。"},{"q":"关于胃的蠕动，下列哪一项是正确的","o":["空腹时基本不发生","发生频率约为12次/分","一个蠕动彼消失后才产生另一个蠕动","蠕动波向胃底和幽门两个方向传播","起始于胃底部"],"a":0,"e":"胃的蠕动在食物入胃后约5分钟开始，空腹时基本不发生。蠕动始于胃中部向幽门推进，频率约每分钟3次，且一波未平一波又起。"},{"q":"关于肾小球滤过液中葡萄糖重吸收的描述错误的是","o":["只有近端小管可以重吸收","与Na+重吸收相偶联","正常情况下有部分葡萄糖在近端小管不能被重吸收","是一种主动转运的过程","肾小管重吸收葡萄糖的能力有一定限度"],"a":2,"e":"肾糖阈以内滤过的葡萄糖全部在近端小管被重吸收，尿中不出现葡萄糖，故“正常情况下有部分葡萄糖不能被重吸收”错误。葡萄糖重吸收由SGLT2/SGLT1继发性主动转运完成，与Na+重吸收偶联，且近端小管重吸收能力有极限。"},{"q":"下列哪种激素分泌不足可引起呆小病的发生","o":["生长激素","甲状旁腺激素","维生素D3","肾上腺糖皮质激素","甲状腺激素"],"a":4,"e":"甲状腺激素是维持正常生长发育不可缺少的激素，分泌不足时婴幼儿骨骼和脑发育障碍，引起呆小病。生长激素不足引起侏儒症而非呆小病。"},{"q":"肾脏的排泄具有维持机体水平衡的功能，水的重吸收过程取决于小管内外的渗透压和不同管段管壁对水的通透性。维持水平衡重吸收的部位是","o":["近端小管","髓袢降支细段","髓袢升支细段","髓袢升支粗段","远曲小管和集合管"],"a":4,"e":"远曲小管和集合管对Na+、Cl-和水的重吸收可根据机体水和盐平衡状况进行调节，是维持水平衡的主要部位。集合管主细胞顶端膜含AQP2，其水通透性受抗利尿激素调节。"},{"q":"决定微循环中真毛细血管网开放与否的因素是","o":["动脉血压","静脉血压","脉压","微动脉和后微动脉的舒缩状态","毛细血管前括约肌的舒缩状态"],"a":4,"e":"真毛细血管起始端的毛细血管前括约肌收缩和舒张控制毛细血管的开放与关闭，在微循环中起“分闸门”作用。其舒缩活动主要与局部组织代谢活动有关。"},{"q":"正常成人总的呼吸膜面积约有","o":["30m2","70m2","120m2","150m2","300m2"],"a":1,"e":"正常成人两肺的总扩散面积约70m2，安静时用于气体扩散的呼吸膜面积约40m2，储备面积大。气体扩散速率与扩散面积成正比。"},{"q":"去大脑动物仰卧时伸肌紧张性最高，俯卧时则伸肌紧张性最低，这一现象称为","o":["翻正反射","探究反射","颈紧张反射","迷路紧张反射","腱反射"],"a":3,"e":"去大脑动物仰卧时伸肌紧张性最高、俯卧时最低，这一随头位改变而变化的肌紧张现象称迷路紧张反射，由前庭器官传入冲动引起。颈紧张反射则源于颈部肌肉本体感受器的传入。"},{"q":"巨幼红细胞性贫血是由于缺少","o":["亚铁离子","蛋白质","维生素B12和叶酸","促红细胞生成素","维生素D3"],"a":2,"e":"叶酸和维生素B12是合成DNA所需的重要辅酶，缺乏时红细胞核发育障碍，引起巨幼红细胞性贫血。铁和蛋白质缺乏则引起缺铁性贫血。"},{"q":"慢性肾衰竭患者常出现的电解质紊乱是","o":["低磷血症","低钙血症","代谢性碱中毒","低钾血症","低镁血症"],"a":1,"e":"慢性肾衰竭时肾小球滤过磷减少致血磷升高，血钙相应降低，并因肾脏1α-羟化酶不足使活性维生素D3生成减少，故常出现低钙血症。"},{"q":"下列选项中不是血浆蛋白功能的是","o":["运输物质","参与机体的免疫","缓冲pH值","维持血浆晶体渗透压","参与凝血和抗凝血作用"],"a":3,"e":"血浆蛋白不能自由通过毛细血管壁，主要维持血浆胶体渗透压；晶体渗透压由Na+、Cl-等晶体物质形成，与血浆蛋白无关。白蛋白、球蛋白等可运输物质、参与免疫、缓冲pH及凝血与抗凝。"},{"q":"不属于含氮激素的是","o":["生长激素","生长抑素","促卵泡激素","肾上腺糖皮质激素","催乳素"],"a":3,"e":"肾上腺糖皮质激素属类固醇激素，由胆固醇合成，并非含氮激素。生长激素、生长抑素、促卵泡激素和催乳素均为肽类或蛋白质激素，属含氮激素。"},{"q":"关于糖皮质激素生理作用，下列哪一项是错误的","o":["升高血糖","使肝外全身细胞内蛋白质减少","加强心肌收缩力、维持动脉血压","增加肩背部、腹部脂肪的合成","减少淋巴细胞数量"],"a":2,"e":"糖皮质激素通过允许作用提高心肌和血管平滑肌对儿茶酚胺的敏感性，从而加强心肌收缩力、维持血压，此为正性作用而非错误项。糖皮质激素促进糖异生升高血糖、促进肝外蛋白分解、减少淋巴细胞。"},{"q":"体内二氧化碳分压最高的是","o":["静脉血液","毛细血管血液","动脉血液","组织液","细胞内液"],"a":4,"e":"组织细胞有氧代谢不断消耗O2并产生CO2，CO2由细胞内液向组织液和血液扩散，故细胞内液CO2分压最高，可达50mmHg以上，高于组织液、静脉血和动脉血。"},{"q":"在甲状腺手术中误伤甲状旁腺时，下列哪项变化会出现","o":["血磷升高","血钙降低","血钙升高","血钙降低、血磷升高","血钙升高、血磷降低"],"a":3,"e":"甲状旁腺激素总效应为升高血钙、降低血磷。甲状腺手术误伤甲状旁腺致PTH缺乏，则升钙降磷作用丧失，出现血钙降低、血磷升高，神经肌肉兴奋性增高可致手足搐搦。"},{"q":"迷走神经末梢释放乙酰胆碱可引起心率减慢主要是由于","o":["窦房结细胞对K+通透性降低","窦房结细胞对K+通透性增加","窦房结细胞对Ca2+通透性增加","窦房结细胞对Na+通透性增加","窦房结细胞对Cl-通透性增加"],"a":1,"e":"迷走神经末梢释放ACh作用于窦房结P细胞M受体，使细胞膜对K+通透性增加，最大复极电位增大，与阈电位差距加大，4期自动去极化减慢，自律性降低、心率减慢。"},{"q":"刺激的阈强度是指","o":["用最小刺激强度，刚刚引起组织的最短作用时间","保持一定的刺激强不变，能引起组织兴奋的最适作用时间","保持一定的刺激时间不变，引起组织发生兴奋的最小刺激强度","刺激时间不限，能引起组织兴奋的最适刺激强度","刺激时间不限，能引起组织最大兴奋的最小刺激强度"],"a":2,"e":"阈强度是在固定刺激作用时间和强度-时间变化率的条件下，能引起活组织细胞产生反应的最小刺激强度，是衡量组织兴奋性高低的指标。"},{"q":"关于月经出血的描述，下列哪一项是错误的","o":["黄体期后期，促卵泡激素和黄体生成素分泌减少","黄体退化，雌激素和孕激素分泌减少","前列腺素F2α释放，子宫内膜血管痉挛","溶酶体释出蛋白水解酶，使组织溶解，内膜剥脱，形成出血","出血期中由于雌激素和孕激素的正反馈，促卵泡激素和黄体生成素又开始加强分泌"],"a":4,"e":"月经出血期雌、孕激素分泌减少，解除了对下丘脑和腺垂体的负反馈抑制，FSH和LH分泌增加而非减少，故“正反馈使FSH、LH加强分泌”的表述错误。黄体退化、前列腺素F2α致血管痉挛及溶酶体酶溶解内膜均为出血期机制。"},{"q":"当达到K+平衡电位时","o":["膜两侧K+浓度梯度为零","膜外K+浓度大于膜内","膜两侧电位梯度为零","膜内电位较膜外电位相对较正","膜内侧K+的净外流为零"],"a":4,"e":"K+平衡电位是K+电-化学驱动力为零时的膜电位，此时K+的净外流为零。静息时膜对K+通透性高，K+顺浓度差外流达平衡，膜内负电荷形成的电场力与浓度差驱动力相等。"},{"q":"下列关于大肠内消化的叙述，正确的是","o":["大肠液的pH为7","大肠运动强而快","大肠内细菌对糖和脂肪有发酵作用","大肠对刺激反应较敏感","大肠液内不含任何消化酶"],"a":2,"e":"大肠内细菌含分解食物残渣的酶，对糖及脂肪的分解称为发酵，产物有乳酸、乙酸、CO2等。大肠液pH呈弱碱性而非中性，大肠运动缓慢，对刺激反应不敏感。"},{"q":"吸收后以淋巴管为主要转运途径的物质是","o":["葡萄糖","氨基酸","乳糜微粒","中链脂肪酸","无机盐"],"a":2,"e":"长链脂肪酸及一酰甘油在肠上皮细胞内重新合成甘油三酯，与载脂蛋白组装成乳糜微粒，经出胞进入淋巴循环。葡萄糖、氨基酸和无机盐主要经血液转运。"},{"q":"IPSP的产生是由于突触后膜提高了下列哪些离子的通透性","o":["Cl-、K+，尤其是Cl-","K+、Na+，尤其是K+","K+、Ca2+，尤其是Ca2+","K+、HCO3-，尤其是HCO3-","Na+、Cl-，尤其是Na+"],"a":0,"e":"IPSP由抑制性递质使突触后膜氯通道开放、Cl-内流产生，GABAB受体激活还可增加K+外流，均致后膜超极化，其中以Cl-通透性升高为主。"},{"q":"下列哪种疾病会使基础代谢率明显升高","o":["肢端肥大症","甲状腺功能亢进","糖尿病","呆小病","肾上腺皮质功能亢进"],"a":1,"e":"甲状腺功能亢进时甲状腺激素分泌过多，基础代谢率可比正常值高25%～80%，是使BMR明显升高的典型疾病。呆小病为甲状腺功能减退，BMR降低。"},{"q":"下列关于CO2解离曲线的叙述，正确的是","o":["表示Hb结合CO2的量与PCO2的关系","有饱和点","呈S形","PO2的变化可使之移位","纵坐标可用饱和度表示"],"a":3,"e":"CO2解离曲线表示血液CO2含量与PCO2的关系，接近线性、无饱和点，纵坐标用浓度表示；PO2变化可通过何尔登效应影响CO2含量而使曲线移位。"},{"q":"远曲小管和集合管对Na+的重吸收主要受下列哪种激素调节","o":["抗利尿激素","醛固酮","肾上腺素","肾素","缓激肽"],"a":1,"e":"醛固酮主要作用于肾远曲小管和集合管上皮细胞，促进Na+重吸收和K+分泌，即保Na+排K+。抗利尿激素主要调节水的重吸收。"},{"q":"游离神经末梢作为一种痛觉感受器，依其所接受刺激的性质可归属于","o":["温度感受器","机械感受器","触压感受器","牵张感受器","化学感受器"],"a":4,"e":"游离神经末梢是痛觉感受器，感受伤害性化学刺激，依刺激性质归属化学感受器。机械感受器包括触-压觉、牵张和压力感受器等。"},{"q":"下列物质中，可直接引起冠脉舒张，血流量增加的是","o":["血管紧张素Ⅱ","去甲肾上腺素","甲状腺激素","腺苷","内皮素"],"a":3,"e":"腺苷由冠脉周围间质细胞中的5′-核苷酸酶分解AMP产生，具有强烈舒张小动脉作用，使冠脉血流量增加。血管紧张素Ⅱ和内皮素均为缩血管物质。"},{"q":"生理条件下，调节冠脉血流量的最重要因素是","o":["心交感神经","心迷走神经","腺苷","血氧水平","血二氧化碳水平"],"a":2,"e":"腺苷能舒张心脏冠状小动脉，是心、脑血流自身调节中的主要介质，为调节冠脉血流量最重要的因素。心肌代谢产物中腺苷的舒血管作用最强。"},{"q":"安静时，微循环中真毛细血管网的状态是","o":["经常关闭","经常开放","交替开放","受交感神经调节","突然开放或关闭"],"a":2,"e":"安静时同一器官不同部位的真毛细血管轮流开放，同一毛细血管也开放与关闭交替进行，由毛细血管前括约肌的收缩和舒张控制，属代谢性自身调节。"},{"q":"月经血不会发生凝固是由于以下哪个原因","o":["雌激素阻止血液凝固","孕激素阻止血液凝固","子宫分泌前列腺素阻止血液凝固","子宫内有丰富的纤溶酶原激活物","子宫内有大量肝素"],"a":3,"e":"子宫内膜组织含丰富的纤溶酶原激活物，可激活纤溶酶，将凝结的纤维蛋白降解为可溶性产物，故月经血不凝固。"},{"q":"临床上常可以通过牵涉痛来初步判断内脏疾病部位，如心肌缺血患者，常主诉","o":["右肩、右上臂、心前区疼痛","右肩、右上臂、上腹部疼痛","左肩、左上臂、上腹部疼痛","左肩、左上臂、心前区疼痛","左肩、左上臂、肩胛区疼痛"],"a":3,"e":"心肌缺血时酸性代谢产物刺激心交感传入纤维，牵涉痛常表现在心前区、左肩和左上臂。胆囊炎牵涉至右肩胛区。"},{"q":"下列生物活性物质中，哪一种不属于内分泌激素","o":["肾上腺素","胰岛素","甲状腺素","前列腺素","内因子"],"a":4,"e":"内因子是胃壁细胞分泌的糖蛋白，与维生素B12结合促进其在回肠吸收，属消化液成分而非内分泌激素。前列腺素为局部激素。"},{"q":"心迷走神经分布数量较少的心肌组织是","o":["窦房结","心室肌","心房肌","房室交界","房室束"],"a":1,"e":"心迷走神经节后纤维主要支配窦房结、心房肌、房室交界和房室束，对心室肌支配很少，故刺激迷走神经时心房肌收缩力减弱比心室肌明显。"},{"q":"心室肌细胞动作电位0期形成的离子流是","o":["K＋外流","K＋内流","Na＋内流","Ca2＋内流","Cl-内流"],"a":2,"e":"心室肌细胞0期去极化由快钠通道开放、Na+快速内流引起，膜电位迅速上升至+30mV左右。Ca2+内流构成平台期。"},{"q":"血液与组织液之间物质交换的最主要形式是","o":["吞饮","滤过","扩散","滤过和重吸收","重吸收"],"a":2,"e":"扩散是血液与组织液之间进行物质交换最重要的方式，滤过和重吸收仅占很小部分。组织液与血液间物质交换通过毛细血管壁以单纯扩散完成。"},{"q":"发热开始前，先出现寒战的原因是","o":["身体特别虚弱","体温调节中枢功能障碍","机体过度散热","机体产热量不足","体温调定点上移"],"a":4,"e":"发热由致热原使体温调定点上移引起，此时体温低于调定点，中枢促使产热加强、散热减弱，故先出现畏寒、寒战。中暑属散热不足或中枢功能障碍的非调节性体温升高。"},{"q":"肺泡表面张力来自","o":["肺泡表面活性物质","肺泡上皮","基膜层","肺泡内液-气分子间的吸引力","肺泡表面活性物质与液体分子之间的吸引力"],"a":3,"e":"肺泡表面张力源于肺泡内液-气界面上液体分子间的相互吸引力，使液体表面积趋于缩小。肺表面活性物质的作用是降低该表面张力。"},{"q":"下列哪项活动属于条件反射","o":["看到酸梅时引起唾液分泌","食物进入口腔引起胃腺分泌","大量饮水后尿量增加","寒冷环境下皮肤血管收缩","炎热环境下出汗"],"a":0,"e":"看到酸梅引起唾液分泌是食物性状、颜色等信号经条件反射引起的唾液分泌，属条件反射。食物入口刺激黏膜引起的唾液分泌为非条件反射。"},{"q":"在刺激作用时间无限长的情况下，引起细胞产生动作电位的最小刺激强度是","o":["阈强度","基强度","时值","阈刺激","阈下刺激"],"a":1,"e":"刺激作用时间无限长时，引起细胞产生动作电位的最小刺激强度称为基强度。阈强度是固定作用时间下的最小刺激强度，时值则是二倍基强度对应的作用时间。"},{"q":"红细胞的主要功能为","o":["吞噬细菌","参与凝集","参与特异性免疫","运输氧气和二氧化碳","缓冲pH值"],"a":3,"e":"红细胞内富含血红蛋白，主要功能是运输O2和CO2。吞噬细菌由吞噬细胞完成，参与特异性免疫的是淋巴细胞。"},{"q":"由于突触前膜的活动发生改变而形成突触前抑制，这个活动是","o":["突触前膜释放兴奋性神经递质减少","突触前膜发生超极化","突触前膜释放抑制性神经递质","突触前神经元末梢内流的Ca2+增多","突触前神经元末梢对Na+通透性增大"],"a":0,"e":"突触前抑制通过使突触前末梢释放兴奋性递质减少，降低突触后神经元EPSP幅度而实现。突触前膜去极化使Ca2+内流增多时递质释放增加，属突触前易化。"},{"q":"下列哪一项描述符合Wolff-Chaikoff效应","o":["腺垂体分泌促甲状腺激素调节甲状腺激素的分泌","下丘脑对腺垂体促甲状腺激素分泌的调节","甲状腺激素反馈调节促甲状腺激素分泌","自主神经对甲状腺功能的调节","过量碘产生的抗甲状腺聚碘作用"],"a":4,"e":"过量碘抑制甲状腺过氧化物酶活性及碘的活化、碘化酪氨酸缩合，从而抑制甲状腺激素合成，称碘阻滞效应（Wolff-Chaikoff效应）。该效应为甲状腺的保护性反应。"},{"q":"关于钙的吸收，正确的叙述是","o":["钙吸收的主要部位是回肠","离子状态的钙最易吸收","胃酸抑制钙的吸收","维生素E促进钙的吸收","钙吸收为被动过程"],"a":1,"e":"离子状态的钙最易吸收。肠内容物pH约为3时钙呈离子化状态，吸收最好；钙吸收主要部位是小肠上段，胃酸促进钙溶解吸收，维生素D而非维生素E促进钙吸收，钙吸收以主动转运为主。"},{"q":"肾小管中H+的分泌主要位于","o":["近端小管","髓袢升支粗段","髓袢降支细段","髓袢升支细段","远曲小管"],"a":0,"e":"近端小管是分泌H+的主要部位，以Na+-H+交换方式为主。髓袢升支粗段主要重吸收HCO3-，远曲小管和集合管虽可泌H+但非主要部位。"},{"q":"下列哪项不是调节甲状旁腺激素的因素","o":["血钙浓度","血糖","血磷浓度","血镁浓度","前列腺素F2"],"a":1,"e":"甲状旁腺激素分泌主要受血钙浓度负反馈调控，血磷、血镁及前列腺素F2也影响其分泌。血糖是调节胰岛素和胰高血糖素分泌的最重要因素，不调节甲状旁腺激素。"},{"q":"控制四肢远端肌肉精细运动的传导通路是","o":["皮质脊髓束","顶盖脊髓束","网状脊髓束","皮质脑干束","前庭脊髓束"],"a":0,"e":"皮层脊髓束经内囊、脑干下行至脊髓前角外侧部运动神经元，控制四肢远端肌肉的精细、技巧性运动。皮质脑干束止于脑神经运动神经元，顶盖脊髓束、网状脊髓束和前庭脊髓束主要与姿势平衡有关。"},{"q":"人类新小脑损伤的特有表现有","o":["意向性震颤","静止性震颤","肌张力增强","偏瘫","平衡失调"],"a":4,"e":"新小脑即脊髓小脑，损伤后表现为意向性震颤、拮抗肌轮替快复动作障碍等小脑性共济失调，静止时无异常。静止性震颤见于帕金森病，肌张力增强和偏瘫属锥体系或锥体外系病变。"},{"q":"突触传递中，影响突触前神经末梢递质释放量的关键因素是","o":["神经末梢膜Na+通道密度","进入神经末梢的Ca2+量","神经末梢内囊泡数量","囊泡内递质含量","活化区面积大小"],"a":1,"e":"递质释放量主要决定于进入突触前末梢的Ca2+量，凡促进Ca2+内流的因素均增加递质释放。囊泡数量、递质含量和活化区面积不决定单次释放量。"},{"q":"丘脑特异投射系统的结构特点是","o":["主要接受来自脑干网状上行激动系统的传入纤维","起始核团是髓板内核群","所有特定感觉的传入纤维都要到丘脑换元","弥散投射到大脑皮质广泛区域","点对点投射到大脑皮质特定区域"],"a":4,"e":"特异性投射系统由丘脑特异感觉接替核和联络核发出，以点对点方式投射到大脑皮层特定区域，引起特定感觉。非特异投射系统起自髓板内核群，弥散投射到皮层广泛区域。"},{"q":"可阻断浦肯野纤维细胞0期去极化的药物是","o":["普萘洛尔","河豚毒素","阿托品","维拉帕米","四乙铵"],"a":1,"e":"浦肯野细胞0期去极化由快钠通道介导，可被河豚毒素阻断。维拉帕米阻断L型钙通道，主要影响窦房结等慢反应细胞；四乙铵阻断钾通道；普萘洛尔和阿托品作用于受体。"},{"q":"下列关于小肠上皮细胞吸收糖的叙述，正确的是","o":["吸收速率为葡萄糖>甘露糖>果糖>半乳糖","单糖通过腔面膜属于主动过程，而通过基侧膜属于被动过程","腔面膜上2分子单糖与1个Na+同向转运","戊糖吸收不依赖Na+转运","与氨基酸竞争转运体"],"a":1,"e":"单糖经刷状缘SGLT-1与Na+同向转运入细胞属继发性主动转运，而经基底侧膜转出为顺浓度差的被动过程。SGLT-1是2个Na+与1分子葡萄糖或半乳糖结合，并非2分子单糖与1个Na+。"},{"q":"在心动周期中，心室内压上升速率最快的时期是","o":["心房收缩期","等容收缩期","快速射血期","减慢射血期","快速充盈期"],"a":1,"e":"等容收缩期房室瓣与半月瓣均关闭，心室继续收缩使室内压急剧升高，上升速率最快。快速射血期半月瓣已开放，室内压上升减慢。"},{"q":"调节体温的基本中枢位于","o":["下丘脑","脑桥","延髓","脊髓","大脑皮质"],"a":0,"e":"脑分段横断实验表明，保持下丘脑及以下结构完整即可维持体温相对稳定，视前区-下丘脑前部是体温调节的基本中枢。"},{"q":"抗凝血酶Ⅲ的作用机制是","o":["除掉血浆中游离的钙离子","使血浆中的纤维蛋白原降解","抑制凝血因子Ⅻ不被激活","封闭了某些凝血因子的丝氨酸残基","抑制凝血因子Ⅲ激活"],"a":3,"e":"抗凝血酶是最重要的丝氨酸蛋白酶抑制物，通过与凝血因子活性中心的丝氨酸残基结合而灭活之，可灭活60%～70%的凝血酶。"},{"q":"根据王田的BMR检测结果(252、5kJ/m2·h)，下列哪项是正确的（正常BMR参考值146、9kJ/m2·h）","o":["甲状腺功能亢进","BMR在正常范围","提示有肾上腺皮质功能低下","提示有垂体性肥胖","甲状腺功能低下"],"a":0,"e":"实测BMR为252.5kJ/(m²·h)，较正常值146.9kJ/(m²·h)升高约72%，落在甲亢时BMR升高25%～80%的范围内。"},{"q":"如果人为地保持脑脊液pH值不变，用含高浓度CO2的人工脑脊液灌流脑室不再引起通气加强，此情况表明","o":["CO2可直接兴奋呼吸中枢","CO2可直接兴奋中枢化学总受器","CO2通过改变脑脊液H+浓度而兴奋呼吸中枢","CO2通过改变脑脊液H+浓度而兴奋中枢化学感受器","脑脊液中的H+可直接兴奋呼吸中枢"],"a":3,"e":"中枢化学感受器的生理性刺激是脑脊液和局部细胞外液中的H+而非CO2；CO2需先与水生成H+才能兴奋中枢化学感受器，故保持脑脊液pH不变时高CO2不再引起通气加强。"},{"q":"关于心动周期的叙述，错误的是","o":["心房开始收缩，作为一个心动周期的开始","通常心动周期是指心室的活动周期","舒张期大于收缩期","心房和心室有共同收缩的时期","心动周期持续的时间与心率有关"],"a":3,"e":"心房收缩时心室处于舒张状态，心房收缩结束后心室才开始收缩，二者不存在共同收缩的时期。心动周期通常指心室活动周期，且舒张期长于收缩期。"},{"q":"下列关于N型受体的叙述，错误的是","o":["属于胆碱能受体","存在于副交感神经节内神经元的突触后膜上","存在于交感神经节内神经元的突触后膜上","能与毒蕈碱发生特异性结合","其阻断剂为筒箭毒"],"a":3,"e":"N型受体属胆碱能受体，分布于交感和副交感神经节神经元的突触后膜，阻断剂为筒箭毒。毒蕈碱是M型受体的特异性激动剂，不与N型受体结合。"},{"q":"影响外周阻力最主要的因素是","o":["血液黏滞性","血管长度","小动脉、微动脉的口径","血流速度","血管弹性"],"a":2,"e":"小动脉和微动脉口径是影响外周阻力最主要的因素。依据泊肃叶定律，血流阻力与血管半径的四次方成反比，微动脉处血流阻力最大、血压降幅最显著。血液黏滞性和血管长度在生理条件下相对稳定。"},{"q":"下列哪一种因素可抑制胃排空","o":["食物对胃的扩张刺激","肠-胃反射增强","迷走神经兴奋释放乙酰胆碱","迷走-迷走反射增强","G细胞释放促胃液素增多"],"a":1,"e":"肠-胃反射增强可抑制胃运动，使胃排空减慢。食糜中的酸、脂肪和高渗性及机械扩张刺激十二指肠感受器，通过肠-胃反射抑制胃排空。食物扩张胃、迷走反射及促胃液素均促进胃排空。"},{"q":"促胃液素由下列哪一种消化道细胞分泌","o":["I细胞","S细胞","G细胞","D细胞","PP细胞"],"a":2,"e":"促胃液素由胃窦及十二指肠、空肠上段黏膜的G细胞分泌。G细胞分泌促胃液素和ACTH样物质，促胃液素经CCKB受体通路强烈刺激壁细胞分泌胃酸。"},{"q":"下列哪一项不是调节胃排空速度的因素","o":["胃内容物中碳水化合物","胃黏膜G细胞的分泌物","十二指肠的扩张刺激","十二指肠内容物的渗透压","进入十二指肠的食糜的酸度"],"a":0,"e":"胃排空主要受胃内因素和十二指肠内因素调控，后者包括酸、脂肪、高渗性及机械扩张。胃内容物中的碳水化合物不是调节胃排空速度的因素。"},{"q":"关于O2在血液中的运输，描述正确的是","o":["物理溶解的O2量占98、5%","化学结合的O2量占1、5%","与红细胞内的Hb结合运输","与血浆蛋白质结合运输","与血浆中的铁结合在一起运输"],"a":2,"e":"血液中98.5%的O2与红细胞内血红蛋白结合成氧合血红蛋白运输。物理溶解的O2仅占极少部分，主要起桥梁作用；O2不与血浆蛋白或血浆铁结合运输。"},{"q":"促进胰酶分泌作用最强的是","o":["生长抑素","缩胆囊素","胰岛素","促胃液素","促胰液素"],"a":1,"e":"缩胆囊素促进胰液中各种酶的分泌，故又称促胰酶素。引起其释放的因素由强至弱为蛋白质分解产物、脂酸钠、盐酸、脂肪，糖类无刺激作用。"},{"q":"女性的基础体温随月经周期而变动，这可能与下列哪种激素有关","o":["甲状腺激素","肾上腺激素","雌激素","孕激素","促肾上腺皮质激素"],"a":3,"e":"孕激素可作用于下丘脑体温调节中枢，使体温调定点水平提高，排卵后孕激素分泌增加使基础体温升高0.2～0.5℃。基础体温的双相变化是判断排卵的标志之一。"},{"q":"对体温调节起关键作用的中枢部位是","o":["脊髓灰质侧角","脑干网状结构","视前区-下丘脑前部","下丘脑后部","中脑中央灰质"],"a":2,"e":"视前区-下丘脑前部（PO/AH）是体温调节的基本中枢，此处热敏神经元居多，能整合温度信息并调节体温。"},{"q":"下列关于生理性止血描述，错误的是","o":["包括血管收缩、血小板血栓形成和血液凝固三个过程","血小板与止血栓的形成有关","首先表现为受损血管局部和附近的小血管收缩，使局部血流减少","一期止血主要依赖于血管收缩及血小板止血栓的形成","血小板减少时，凝血时间明显延长"],"a":4,"e":"血小板减少或功能降低时出血时间延长，而凝血时间反映凝血因子参与的血液凝固过程，血小板数量减少并不使其明显延长。血小板与止血栓形成及一期止血有关，凝血时间取决于凝血因子。"},{"q":"生长因子进行信号转导的方式是","o":["酪氨酸激酶受体介导的信号转导通路","酪氨酸激酶结合型受体介导的信号转导通路","鸟苷酸环化酶受体介导的信号转导通路","G蛋白偶联受体介导的信号转导通路","离子通道型受体介导的信号转导通路"],"a":0,"e":"生长因子和肽类激素的受体属酪氨酸激酶型受体，配体结合后激活受体酪氨酸激酶，经相对简捷的通路调控细胞代谢、生长、增殖和分化。"},{"q":"骨骼肌收缩过程中，后负荷改变可以影响肌肉的","o":["兴奋性","初长度","最适初长度","收缩速度","收缩能力"],"a":3,"e":"后负荷增大时横桥周期延长、摆动速度减慢，肌肉缩短速度降低；后负荷为零时缩短速度最大。前负荷决定初长度，收缩能力是与负荷无关的内在特性。"},{"q":"去甲肾上腺素和α受体结合后产生的效应，错误的是","o":["血管收缩","瞳孔扩大","小肠平滑肌收缩","妊娠子宫收缩","竖毛肌收缩"],"a":2,"e":"去甲肾上腺素与α受体结合主要引起血管、子宫、虹膜开大肌和竖毛肌等收缩；与β2受体结合则使小肠平滑肌舒张，故小肠平滑肌收缩不是α受体效应。"},{"q":"可引起射血分数增大的因素是","o":["心室舒张末期容积增大","动脉血压升高","心率减慢","心肌收缩能力增强","快速射血期缩短"],"a":3,"e":"心肌收缩能力增强使每搏量增加而心室舒张末期容积不变或减小，射血分数增大。动脉血压升高增加后负荷，使射血分数减小。"},{"q":"在动物实验中，将蛋白质的中间消化产物(如蛋白胨)通过肠瘘直接注入十二指肠中，其引起胰液分泌的主要机制是","o":["交感神经兴奋","食物引起促胰液素和缩胆囊素的分泌","食物引起降钙素基因相关肽的分泌","食物引起生长抑素的分泌","食物引起胰多肽的分泌"],"a":1,"e":"蛋白质消化产物注入十二指肠可刺激小肠黏膜释放促胰液素和缩胆囊素，二者协同促进胰液分泌，前者以cAMP、后者以磷脂酰肌醇系统为第二信使。"},{"q":"肺的通气/血流比值反映肺部气体交换的气泵与血泵的匹配情况。如果通气/血流比值增大，表明该受试者肺内出现","o":["解剖无效腔增大","肺泡无效腔增大","解剖动-静脉短路","功能性动-静脉短路","气体交换效率提高"],"a":1,"e":"通气/血流比值增大表示通气过度和/或血流不足，部分肺泡气体未能与血液充分交换，相当于肺泡无效腔增大。比值减小则形成功能性动-静脉短路。"},{"q":"电击头部或脑震荡可能导致","o":["逆行性遗忘症","顺行性遗忘症","近期记忆受损","远期记忆受损","近期和远期记忆障碍"],"a":0,"e":"电击头部或脑震荡引起逆行性遗忘症，即不能回忆记忆障碍之前一段时间的经历，但仍可形成新的记忆；顺行性遗忘症多见于海马和颞叶皮层损伤等。"},{"q":"腱反射属于","o":["屈肌反射","防御反射","肌牵张反射","条件反射","发汗反射"],"a":2,"e":"腱反射是牵张反射的一种类型，指快速牵拉肌腱时引起的同一肌肉收缩。牵张反射的感受器为肌梭，其反射弧简单，属于肌牵张反射。"},{"q":"去甲肾上腺素和β受体结合后产生的效应，错误的是","o":["血管平滑肌舒张","子宫平滑肌舒张","小肠平滑肌舒张","支气管平滑肌舒张","心脏活动减弱"],"a":4,"e":"去甲肾上腺素与β受体结合后，对血管、子宫、小肠、支气管平滑肌均产生舒张效应；与心肌β1受体结合则产生兴奋效应，使心脏活动增强而非减弱。"},{"q":"迷走神经对冠状动脉的直接作用表现是","o":["兴奋血管平滑肌α受体","冠脉舒张","冠脉收缩","冠脉循环阻力增加","血流量减少"],"a":1,"e":"迷走神经兴奋时释放ACh，激活冠脉平滑肌M受体使冠状动脉舒张。交感神经才通过α受体使冠脉收缩。"},{"q":"神经细胞在产生动作电位时，去极相的变化方向是朝向下列哪种电位的变化方向","o":["K+的平衡电位","Na+的平衡电位","Ca2+的平衡电位","Cl-的平衡电位","有机负离子的平衡电位"],"a":1,"e":"动作电位去极相由Na+内流引起，膜电位向Na+平衡电位方向变化，达到顶点时接近ENa（约+60mV）。"},{"q":"使用冰袋给高热患者降温是","o":["增加辐射散热","增加传导散热","增加蒸发散热","增加对流散热","增加环境湿度"],"a":1,"e":"传导散热是机体热量直接传给温度较低接触物的散热方式。冰袋温度低、导热性能好，通过传导增加散热，常用于高热患者降温。"},{"q":"关于胰高血糖素的生理作用，下列哪一项是正确的","o":["促进糖原分解","抑制糖异生","抑制脂肪分解","促进胆汁和胃液分泌","抑制胰岛素分泌"],"a":0,"e":"胰高血糖素的主要靶器官是肝脏，可激活糖原磷酸化酶促进肝糖原分解，从而升高血糖；它同时增强糖异生、促进脂肪分解。"},{"q":"神经肌肉接头传递中，使乙酰胆碱降解的酶是","o":["磷酸二酯酶","腺苷酸环化酶","胆碱酯酶","ATP酶","胆碱乙酰化酶"],"a":2,"e":"接头后膜间隙面分布的乙酰胆碱酯酶能将ACh迅速水解为胆碱和乙酸，使递质失活，终止神经肌肉接头的兴奋传递。"},{"q":"循环系统平均充盈压的高低取决于","o":["动脉血压与外周阻力的关系","心输出量与外周阻力的关系","中心静脉压的高低","心输出量与心脏射血能力之间的关系","循环血量与血管容量之间的关系"],"a":4,"e":"循环系统平均充盈压取决于血量与循环系统容积的相对关系：血量增多或血管容积变小则充盈压增高，反之降低。"},{"q":"正常成人白细胞总数是","o":["（3、0～5、0）×1012/L","（3、0～8、0）×1011/L","（4、0～10、0）×109∕L","（5、0～10、0）×108/L","（5、0～10、0）×1012∕L"],"a":2,"e":"正常成人白细胞总数为（4.0～10.0）×10⁹/L，教材给出的参考范围为（3.5～9.5）×10⁹/L，数量级为10⁹/L。红细胞数量级为10¹²/L，血小板为10⁹/L量级但正常值为（100～300）×10⁹/L。"},{"q":"平静呼吸过程中，胸膜腔负压最大值(绝对值)出现在","o":["呼气末","呼气中","吸气中","吸气末","吸气初"],"a":3,"e":"平静吸气末胸膜腔内压约为-6mmHg，呼气末约为-2.5mmHg，吸气时胸膜腔负压绝对值增大，故负压绝对值最大出现在吸气末。胸膜腔内压=-肺弹性回缩压，吸气末肺扩张程度最大，回缩压最大。"},{"q":"平滑肌细胞中不含以下哪种结构","o":["肌球蛋白","肌动蛋白","原肌球蛋白","致密体","肌钙蛋白"],"a":4,"e":"平滑肌细胞内不含肌钙蛋白，而有钙调蛋白，Ca²⁺通过Ca²⁺-CaM通路活化肌球蛋白轻链激酶引起收缩。骨骼肌和心肌的细肌丝才由肌动蛋白、原肌球蛋白和肌钙蛋白组成。"},{"q":"给狗制备“食管瘘”进行胃液分泌的研究是","o":["混合实验法","慢性在体实验法","急性在体实验法","急性离体实验法","慢性离体实验法"],"a":1,"e":"食管瘘需先手术造瘘，待动物康复后在清醒状态下进行观察，属于慢性在体实验。急性在体实验指麻醉或清醒动物上的即刻观察，离体实验则需将器官或细胞从体内分离。"},{"q":"有关平静呼吸的叙述，错误的是","o":["吸气时肋间外肌收缩","吸气时膈肌收缩","呼气时肋间内肌收缩","呼气时胸廓自然回位","吸气是主动的过程"],"a":2,"e":"平静呼气时呼气肌不参与，仅由膈肌和肋间外肌舒张、胸廓弹性回位所致，是被动过程；肋间内肌收缩只出现在用力呼气时。平静吸气则为主动过程，膈肌和肋间外肌收缩。"},{"q":"下列哪一种原因导致月经出血的发生","o":["雌激素急剧减少","孕激素急剧减少","雌激素与孕激素都急剧减少","前列腺素F2α减少","缩宫素急剧减少"],"a":2,"e":"排卵后未受精则黄体退化，雌激素与孕激素分泌均急剧减少，子宫内膜失去激素支持而坏死脱落出血，形成月经。孕激素单独下降不足以解释，需两者共同撤退。"},{"q":"下列哪一项因素会影响醛固酮的分泌","o":["血Ca2+浓度降低","血Ca2+浓度升高","血K+浓度升高","血Cl-浓度降低","血Cl-浓度升高"],"a":2,"e":"血K⁺浓度升高可直接刺激肾上腺皮质球状带分泌醛固酮，且醛固酮分泌对血K⁺变化更为敏感，通过保Na⁺排K⁺维持血K⁺稳定。血Na⁺浓度降低也刺激醛固酮分泌，而Ca²⁺、Cl⁻浓度变化不是主要调节因素。"},{"q":"临床上常选择一种能充分反映肺组织的弹性状态和气道通畅程度的通气功能状况的指标是","o":["肺活量","肺总容量","深吸气量","时间肺活量","通气血流比值"],"a":3,"e":"时间肺活量（用力呼气量）限制呼气时间，能充分反映肺组织弹性状态和气道通畅程度，肺活量不限制呼气时间，在弹性降低或气道狭窄时仍可正常。"},{"q":"下列关于近端小管重吸收的叙述正确的是","o":["Cl-为主动重吸收","K+为被动重吸收","Na+为主动或被动重吸收","HCO3-为主动重吸收","水不被重吸收"],"a":2,"e":"近端小管对Na+的重吸收既存在主动转运（基侧膜钠泵驱动），也存在细胞旁途径的被动重吸收，故Na+为主动或被动重吸收。Cl-主要经细胞旁途径被动重吸收，水经AQP1大量重吸收。"},{"q":"关于抑制性突触后电位的产生，正确的叙述是","o":["突触前轴突末梢超极化","对Ca2+、K+通透性增大","突触后膜出现超极化","突触后膜去极化","突触后膜出现复极化"],"a":2,"e":"抑制性突触后电位是抑制性递质使突触后膜氯通道开放、Cl-内流，引起突触后膜超极化。其本质为突触后膜出现超极化，而非突触前末梢变化。"},{"q":"巴比妥类催眠药、全身麻醉药乙醚对机体发挥作用的机制，可能是阻断","o":["丘脑特异投射系统","脑干网状结构上行激动系统","边缘系统与大脑皮质之间的联系","脊髓丘脑侧束","脊髓丘脑前束"],"a":1,"e":"巴比妥类及乙醚等全身麻醉药通过阻断脑干网状结构上行激动系统，削弱其对大脑皮层的唤醒作用而产生麻醉效应。网状结构上行激动系统维持觉醒状态。"},{"q":"肺牵张反射的传入神经是","o":["舌咽神经","迷走神经","舌下神经","交感神经","窦神经"],"a":1,"e":"肺牵张反射的感受器位于呼吸道平滑肌，冲动经迷走神经传入延髓呼吸中枢，加速吸气向呼气转换。切断两侧迷走神经后呼吸变深变慢。"},{"q":"平均动脉压的粗略计算公式为","o":["收缩压+1/3脉压","收缩压－1/3脉压","舒张压＋2/3脉压","舒张压＋1/3脉压","(收缩压+舒张压）÷2"],"a":3,"e":"平均动脉压为一个心动周期中动脉血压的平均值，因舒张期较长而更接近舒张压，粗略估算约等于舒张压加1/3脉压。"},{"q":"血液循环流经肾小球时，血浆中的水分和小分子溶质可经滤过膜进入肾小囊，但滤液中几乎没有蛋白质。其原因是","o":["血浆蛋白分子较大，不能通过滤过膜上的孔","滤过膜上有带负电荷的成分，可以排斥血浆蛋白","滤过膜上孔的大小和带负电荷的蛋白两个因素共同作用","肾小球滤过的蛋白质可在肾小管主动重吸收","滤过膜中的内皮细胞层和基膜层有相同大小的网孔"],"a":2,"e":"滤过膜通透性既取决于各层筛孔的大小，也取决于其带负电荷的糖蛋白对带负电血浆蛋白的排斥，两因素共同限制蛋白质滤过。"},{"q":"阻力血管主要是指","o":["大动脉","小动脉和微动脉","大静脉","小动脉","毛细血管"],"a":1,"e":"外周阻力主要来自小动脉和微动脉，二者管径细、对血流阻力大，合称毛细血管前阻力血管，是产生外周阻力的主要部位。"},{"q":"当下丘脑温度升高时，热敏神经元放电频率的变化是","o":["减少","不变","增加","先增加后减少","先减少后增加"],"a":2,"e":"热敏神经元发放冲动的频率随局部组织温度升高而增加，视前区-下丘脑前部以热敏神经元居多，参与体温调定点的设定。"},{"q":"临床上，胆道瘘管长期引流及胆汁缺乏的患者应用胆酸钠（利胆剂）治疗的主要机制是","o":["促进促胃液素的分泌","促进促胰液素的分泌","兴奋迷走神经","促进胆盐的肠肝循环","兴奋交感神经"],"a":3,"e":"胆盐经肠肝循环返回肝脏后可直接刺激肝细胞分泌胆汁，即胆盐的利胆作用。胆酸钠作为利胆剂，其治疗机制即通过补充胆盐、促进肠肝循环而刺激肝胆汁分泌。"},{"q":"下列哪一个激素不属于胃肠激素","o":["促胃液素","促胰液素","肾上腺素","缩胆囊素","生长抑素"],"a":2,"e":"胃肠激素是由胃肠道内分泌细胞分泌的肽类激素，包括促胃液素、促胰液素、缩胆囊素和生长抑素等。肾上腺素由肾上腺髓质嗜铬细胞分泌，属儿茶酚胺类，不属于胃肠激素。"},{"q":"贫血和CO中毒时，可携带O2的Hb减少，但并不引起呼吸加强，这是因为","o":["颈动脉体血流量代偿性增加","动脉血Hb氧饱和度正常","颈动脉体化学感受器发生适应","动脉血PO2正常","动脉血氧含量正常"],"a":3,"e":"外周化学感受器对动脉血PO2下降敏感，而对血O2含量降低不敏感。贫血和CO中毒时血氧含量下降但动脉血PO2仍正常，故化学感受器传入冲动不增加，不引起呼吸加强。"},{"q":"机体的内环境通常是指","o":["体腔内空间","组织间隙","细胞外液","细胞内液","血液"],"a":2,"e":"生理学中把体内细胞直接接触和生存的细胞外液称为内环境。胃内、肠道内、汗腺管内等与外环境连通的液体不属于内环境。"},{"q":"调节红细胞生成的最重要的体液因素是","o":["雄激素","雌激素","甲状腺激素","促红细胞生成素","生长激素"],"a":3,"e":"EPO是调节红细胞生成最重要的体液因素，CFU-E是其作用的主要靶细胞，其存活完全依赖EPO。雄激素、甲状腺激素等可间接影响红细胞生成，但作用远弱于EPO。"},{"q":"血型抗体主要是","o":["IgG与IgA","IgG与IgD","IgG与IgM","IgD与IgM","IgG与IgE"],"a":2,"e":"ABO血型系统的天然抗体多属IgM，免疫性抗体属IgG；Rh系统抗体主要为IgG。故血型抗体主要是IgG与IgM。"},{"q":"醛固酮分泌减少可导致","o":["低血钾","高血钾","细胞外液量增多","血压升高","高血钠"],"a":1,"e":"醛固酮促进肾远曲小管和集合管保Na+排K+。醛固酮分泌减少时排K+减少，导致高血钾，同时Na+和水排出增多，出现低血钠和细胞外液量减少。"},{"q":"老年人大动脉硬化时，动脉血压的变化主要是","o":["收缩压降低","舒张压升高","收缩压升高，舒张压降低","收缩压降低，舒张压升高","收缩压和舒张压均升高，且升高幅度相同"],"a":2,"e":"大动脉弹性贮器作用减弱时，心室收缩期血管不能有效扩张缓冲，收缩压升高；舒张期血管回缩力减弱，舒张压降低，故脉压增大。"},{"q":"心室肌细胞膜反应曲线反映的是","o":["静息电位和不应期的关系","动作电位和不应期的关系","静息电位和心肌兴奋性的关系","动作电位和心肌传导性的关系","静息电位和动作电位最大去极化速率的关系"],"a":4,"e":"膜反应曲线描述的是兴奋前膜电位水平与0期最大去极化速度之间的关系。膜电位减小时Na+通道开放效率降低，最大去极化速度下降，故该曲线反映静息电位与动作电位最大去极化速率的关系。"},{"q":"一次进食后的食物残渣全部从大肠排出约需","o":["6～8h","8～12h","12～18h","18～24h","24h以上"],"a":4,"e":"食物残渣在大肠内停留时间较长，一次进食后的食物残渣全部从大肠排出约需24h以上。大肠主要吸收水分和无机盐并暂时储存残渣，无重要消化活动。"},{"q":"当肾动脉血压在一定范围内波动时，肾血流量相对稳定的调节方式属于","o":["免疫调节","体液调节","神经调节","神经-内分泌调节","自身调节"],"a":4,"e":"当肾动脉灌注压在70～180mmHg范围内变动时，肾血流量通过自身调节保持相对稳定。该调节不依赖外来神经和体液因素，由肌源学说和管-球反馈学说解释。"},{"q":"新生儿溶血性贫血可能发生在","o":["Rh阳性母亲所生Rh阳性婴儿","Rh阳性母亲所生Rh阴性婴儿","Rh阴性母亲所生Rh阳性婴儿","Rh阴性母亲所生Rh阴性婴儿","B或C均可发生"],"a":2,"e":"Rh阴性母亲怀Rh阳性胎儿时，胎儿红细胞可进入母体使其产生IgG类抗D抗体，再次妊娠时抗体经胎盘进入胎儿血循环，引起红细胞溶血。第一胎较少发生，故新生儿溶血性贫血见于Rh阴性母亲所生Rh阳性婴儿。"},{"q":"维持胸内负压的必要条件是","o":["呼吸道存在一定阻力","胸膜腔密闭","呼气肌收缩","吸气肌收缩","肺内压低于大气压"],"a":1,"e":"胸膜腔的密闭状态是形成胸膜腔内负压的重要前提。胸膜腔一旦与大气相通即形成气胸，负压减小或消失，肺依自身弹性回缩力而塌陷。"},{"q":"交感神经活动增强时，下列哪项不会出现","o":["肠蠕动抑制","肾素分泌","胰岛素分泌","瞳孔开大肌收缩","支气管平滑肌舒张"],"a":2,"e":"交感神经兴奋释放去甲肾上腺素，主要经β细胞膜α受体抑制胰岛素分泌。交感兴奋还可抑制肠蠕动、促进肾素分泌、使瞳孔开大肌收缩、支气管平滑肌舒张，故不会出现的是胰岛素分泌。"},{"q":"阈电位是指","o":["造成膜对K+通透性突然增大的临界膜电位","造成膜对K+通透性突然减小的临界膜电位","超极化到刚能引起动作电位时的膜电位","造成膜对Na+通透性突然增大的临界膜电位","造成膜对Na+通透性突然减小的临界膜电位"],"a":3,"e":"阈电位是能引起Na+通道大量开放、触发动作电位的临界膜电位，即造成膜对Na+通透性突然增大的临界膜电位。去极化达此水平时Na+内流与去极化形成正反馈。"},{"q":"下列哪些临床表现不会见于甲状腺功能亢进病人","o":["病人体重明显减轻","喜热畏寒","突眼","甲状腺功能检查游离T3、T4升高","双侧甲状腺Ⅰ度大"],"a":1,"e":"甲状腺功能亢进时产热量增加，患者喜凉怕热、多汗、体重下降，故喜热畏寒不会出现。甲亢还可见突眼、游离T3和T4升高及甲状腺肿大。"},{"q":"下列关于甲状腺激素的作用机制的描述，哪一项是正确的","o":["与核受体结合刺激mRNA生成","与核受体结合促进Ca2+释放","与核受体结合抑制Ca2+释放","与核受体结合促进cAMP生成","与膜受体结合抑制cAMP生成"],"a":0,"e":"甲状腺激素属脂溶性激素，进入胞内与核受体结合形成复合物，转位至核内与靶基因HRE结合，促进mRNA生成及特定蛋白质表达。"},{"q":"可以较迅速地反映内环境变化状况的体液是","o":["脑脊液","血液","尿液","细胞内液","淋巴液"],"a":1,"e":"血液在心血管内循环流动，能迅速反映内环境变化并参与维持稳态。脑脊液、尿液、细胞内液和淋巴液均不具备这一快速反映能力。"},{"q":"关于头期胃液分泌的叙述，下列哪一项是正确的","o":["只有食物直接刺激口腔才能引起","只有神经调节","不包括条件反射","传出神经是迷走神经","酸度高、消化力弱"],"a":3,"e":"头期胃液分泌由食物刺激头面部感受器引起，包括条件反射和非条件反射，传出神经均为迷走神经。其酸度高、消化力强，并非仅由神经调节。"},{"q":"节后纤维兴奋可导致自律细胞动作电位4期内向电流If增强的是","o":["心交感神经","心迷走神经","交感缩血管神经","A和C都符合","A、B、C都符合"],"a":0,"e":"心交感神经节后纤维释放去甲肾上腺素，与β1受体结合使自律细胞4期If内向电流增强，自动去极化加速。心迷走神经兴奋则使4期K+外流增加、If减弱。"},{"q":"血浆中某物质能被肾小球滤过，同时肾小管对其有吸收作用，该物质的血浆清除率和菊粉的血浆清除率相比较正确的说法是","o":["一定相等","不能肯定，应当考虑肾小管该物质的分泌情况","一定少于菊粉的血浆清除率","一定大于菊粉的血浆清除率","不能肯定，应当考虑集合管该物质的分泌情况"],"a":1,"e":"该物质清除率小于菊粉清除率提示被重吸收，但若同时存在肾小管分泌且分泌量较大，清除率可改变，故不能肯定，须考虑肾小管分泌情况。"},{"q":"射血分数是指","o":["每搏输出量/心室舒张末期容积","心输出量/体表面积","心室收缩末期容积/心室舒张末期容积","心输出量/心室舒张末期容积","心室舒张末期容积/体表面积"],"a":0,"e":"射血分数定义为每搏输出量占心室舒张末期容积的百分比，健康成人55%～65%。心输出量/体表面积是心指数。"},{"q":"EPSP发生时，突触后膜电位的状态是","o":["超射","超极化","反极化","复极化","去极化"],"a":4,"e":"兴奋性突触后电位是兴奋性递质使突触后膜Na+内流为主引起的去极化电位，去极化达阈电位即可爆发动作电位。"}];
